  // examples/button_examples.dart
  'button_states':
      'class ButtonStatesExample extends StatefulWidget {\n'
      '  const ButtonStatesExample({super.key});\n'
      '\n'
      '  @override\n'
      '  State<ButtonStatesExample> createState() => _ButtonStatesExampleState();\n'
      '}\n'
      '\n'
      'class _ButtonStatesExampleState extends State<ButtonStatesExample> {\n'
      '  bool _saving = false;\n'
      '\n'
      '  Future<void> _save() async {\n'
      '    setState(() => _saving = true);\n'
      '    await Future<void>.delayed(const Duration(seconds: 2));\n'
      '    if (mounted) setState(() => _saving = false);\n'
      '  }\n'
      '\n'
      '  @override\n'
      '  Widget build(BuildContext context) {\n'
      '    return AstryxHStack(\n'
      '      gap: AstryxSpacingToken.spacing3,\n'
      '      wrap: true,\n'
      '      children: <Widget>[\n'
      '        // `loading` keeps the callback and the width — the layout cannot jump,\n'
      '        // and the button reports itself as disabled while the work is in\n'
      '        // flight.\n'
      '        AstryxButton(\n'
      '          label: \'Save\',\n'
      '          variant: AstryxButtonVariant.primary,\n'
      '          loading: _saving,\n'
      '          onPressed: _save,\n'
      '        ),\n'
      '        const AstryxButton(label: \'Inert\'),\n'
      '        AstryxButton(label: \'Disabled\', enabled: false, onPressed: () {}),\n'
      '      ],\n'
      '    );\n'
      '  }\n'
      '}\n',
