  'button_group_segmented':
      'class ButtonGroupSegmentedExample extends StatefulWidget {\n'
      '  const ButtonGroupSegmentedExample({super.key});\n'
      '\n'
      '  @override\n'
      '  State<ButtonGroupSegmentedExample> createState() =>\n'
      '      _ButtonGroupSegmentedExampleState();\n'
      '}\n'
      '\n'
      'class _ButtonGroupSegmentedExampleState\n'
      '    extends State<ButtonGroupSegmentedExample> {\n'
      '  String _range = \'Week\';\n'
      '\n'
      '  @override\n'
      '  Widget build(BuildContext context) {\n'
      '    // The group carries no selection of its own. A segmented control is a\n'
      '    // group whose selected child takes a louder variant — which keeps the\n'
      '    // selection where the application already holds it.\n'
      '    return AstryxButtonGroup(\n'
      '      children: <Widget>[\n'
      '        for (final range in const <String>[\'Day\', \'Week\', \'Month\'])\n'
      '          AstryxButton(\n'
      '            label: range,\n'
      '            variant: range == _range\n'
      '                ? AstryxButtonVariant.primary\n'
      '                : AstryxButtonVariant.secondary,\n'
      '            onPressed: () => setState(() => _range = range),\n'
      '          ),\n'
      '      ],\n'
      '    );\n'
      '  }\n'
      '}\n',
