      'class _CalendarDemoExampleState extends State<CalendarDemoExample> {\n'
      '  DateTime? _day;\n'
      '\n'
      '  @override\n'
      '  Widget build(BuildContext context) {\n'
      '    // The grid is one tab stop: Tab lands on it, the arrow keys move within it,\n'
      '    // and Enter picks. Nothing is selected until Enter or a press says so.\n'
      '    return AstryxVStack(\n'
      '      gap: AstryxSpacingToken.spacing3,\n'
      '      children: <Widget>[\n'
      '        AstryxCalendar(\n'
      '          selected: _day,\n'
      '          onChanged: (day) => setState(() => _day = day),\n'
      '        ),\n'
      '        AstryxText(\n'
      '          _day == null ? \'Nothing picked\' : \'Picked \${_day!.day}/\${_day!.month}\',\n'
      '          type: AstryxTextType.supporting,\n'
      '          color: AstryxTextColor.secondary,\n'
      '        ),\n'
      '      ],\n'
      '    );\n'
      '  }\n'
      '}\n',
