  // examples/calendar_examples.dart
  'calendar_bounds':
      'class CalendarBoundsExample extends StatefulWidget {\n'
      '  const CalendarBoundsExample({super.key});\n'
      '\n'
      '  @override\n'
      '  State<CalendarBoundsExample> createState() => _CalendarBoundsExampleState();\n'
      '}\n'
      '\n'
      'class _CalendarBoundsExampleState extends State<CalendarBoundsExample> {\n'
      '  DateTime? _day;\n'
      '\n'
      '  @override\n'
      '  Widget build(BuildContext context) {\n'
      '    final today = DateTime.now();\n'
      '\n'
      '    // Days outside the bounds, and weekends inside them, are dimmed rather than\n'
      '    // hidden: the grid keeps its shape, and a user can see why a date is out of\n'
      '    // reach instead of wondering where it went.\n'
      '    return AstryxCalendar(\n'
      '      selected: _day,\n'
      '      firstDate: today,\n'
      '      lastDate: DateTime(today.year, today.month + 2, today.day),\n'
      '      selectableDayPredicate: (day) =>\n'
      '          day.weekday != DateTime.saturday && day.weekday != DateTime.sunday,\n'
      '      onChanged: (day) => setState(() => _day = day),\n'
      '    );\n'
      '  }\n'
      '}\n',
