  // examples/chat_examples.dart
  'chat_layout_demo':
      'class ChatLayoutDemoExample extends StatefulWidget {\n'
      '  const ChatLayoutDemoExample({super.key});\n'
      '\n'
      '  @override\n'
      '  State<ChatLayoutDemoExample> createState() => _ChatLayoutDemoExampleState();\n'
      '}\n'
      '\n'
      'class _ChatLayoutDemoExampleState extends State<ChatLayoutDemoExample> {\n'
      '  final TextEditingController _draft = TextEditingController();\n'
      '  final List<({AstryxChatRole role, String text})> _turns =\n'
      '      <({AstryxChatRole role, String text})>[\n'
      '        (role: AstryxChatRole.user, text: \'Why did the 14:02 deploy fail?\'),\n'
      '        (\n'
      '          role: AstryxChatRole.assistant,\n'
      '          text:\n'
      '              \'The health check timed out. The scheduler took 41 seconds to \'\n'
      '              \'bind its port, and the check gives up at 30.\',\n'
      '        ),\n'
      '        (role: AstryxChatRole.user, text: \'Can we raise the timeout?\'),\n'
      '        (\n'
      '          role: AstryxChatRole.assistant,\n'
      '          text:\n'
      '              \'You can, but the bind is the real problem — it used to take \'\n'
      '              \'four seconds. I would look at the migration that ships with \'\n'
      '              \'this release first.\',\n'
      '        ),\n'
      '      ];\n'
      '\n'
      '  @override\n'
      '  void dispose() {\n'
      '    _draft.dispose();\n'
      '    super.dispose();\n'
      '  }\n'
      '\n'
      '  void _send(String text) {\n'
      '    setState(() {\n'
      '      _turns\n'
      '        ..add((role: AstryxChatRole.user, text: text))\n'
      '        ..add((\n'
      '          role: AstryxChatRole.assistant,\n'
      '          text: \'Noted. (This example does not actually answer.)\',\n'
      '        ));\n'
      '      _draft.clear();\n'
      '    });\n'
      '  }\n'
      '\n'
      '  @override\n'
      '  Widget build(BuildContext context) {\n'
      '    // The layout owns the scrolling: it opens on the newest turn, stays put as\n'
      '    // turns arrive, and offers a jump-to-latest button once you scroll back.\n'
      '    return AstryxCard(\n'
      '      padding: AstryxSpacingToken.spacing0,\n'
      '      // Bounded inside the card: a card lays its body out in a column, and a\n'
      '      // column hands its child unbounded height — which the layout needs to\n'
      '      // divide between the transcript and the composer.\n'
      '      child: SizedBox(\n'
      '        height: 420,\n'
      '        child: AstryxChatLayout(\n'
      '          messages: <Widget>[\n'
      '            for (final turn in _turns)\n'
      '              AstryxChatMessage(\n'
      '                role: turn.role,\n'
      '                author: turn.role == AstryxChatRole.user\n'
      '                    ? \'You\'\n'
      '                    : \'Assistant\',\n'
      '                child: AstryxText(turn.text),\n'
      '              ),\n'
      '          ],\n'
      '          composer: AstryxChatComposer(\n'
      '            controller: _draft,\n'
      '            onSubmit: _send,\n'
      '          ),\n'
      '        ),\n'
      '      ),\n'
      '    );\n'
      '  }\n'
      '}\n',
