  // examples/chat_examples.dart
  'chat_message_streaming':
      'class ChatMessageStreamingExample extends StatefulWidget {\n'
      '  const ChatMessageStreamingExample({super.key});\n'
      '\n'
      '  @override\n'
      '  State<ChatMessageStreamingExample> createState() =>\n'
      '      _ChatMessageStreamingExampleState();\n'
      '}\n'
      '\n'
      'class _ChatMessageStreamingExampleState\n'
      '    extends State<ChatMessageStreamingExample> {\n'
      '  static const String _answer =\n'
      '      \'Three services restarted and the health check passed on the first \'\n'
      '      \'attempt. Total time was 41 seconds, most of it waiting on the port \'\n'
      '      \'bind.\';\n'
      '\n'
      '  String _shown = \'\';\n'
      '\n'
      '  void _stream() => setState(() => _shown = _answer);\n'
      '\n'
      '  @override\n'
      '  Widget build(BuildContext context) {\n'
      '    // A turn whose content is `AstryxStreamingText`: the transcript does not\n'
      '    // move as it types, because the layout keeps the newest turn at offset 0.\n'
      '    return AstryxVStack(\n'
      '      gap: AstryxSpacingToken.spacing3,\n'
      '      align: AstryxStackAlign.stretch,\n'
      '      children: <Widget>[\n'
      '        AstryxChatMessage(\n'
      '          author: \'Assistant\',\n'
      '          child: _shown.isEmpty\n'
      '              ? const AstryxSpinner(label: \'Thinking\')\n'
      '              : AstryxStreamingText(\n'
      '                  _shown,\n'
      '                  streaming: false,\n'
      '                  charactersPerSecond: 45,\n'
      '                ),\n'
      '        ),\n'
      '        AstryxButton(\n'
      '          label: _shown.isEmpty ? \'Stream the answer\' : \'Reset\',\n'
      '          onPressed: () => _shown.isEmpty\n'
      '              ? _stream()\n'
      '              : setState(() => _shown = \'\'),\n'
      '        ),\n'
      '      ],\n'
      '    );\n'
      '  }\n'
      '}\n',
  // examples/chat_examples.dart
  'chat_composer_demo':
      'class ChatComposerDemoExample extends StatefulWidget {\n'
      '  const ChatComposerDemoExample({super.key});\n'
      '\n'
      '  @override\n'
      '  State<ChatComposerDemoExample> createState() =>\n'
      '      _ChatComposerDemoExampleState();\n'
      '}\n'
      '\n'
      'class _ChatComposerDemoExampleState extends State<ChatComposerDemoExample> {\n'
      '  final TextEditingController _draft = TextEditingController();\n'
      '  final List<String> _sent = <String>[];\n'
      '\n'
      '  bool _generating = false;\n'
      '\n'
      '  @override\n'
      '  void dispose() {\n'
      '    _draft.dispose();\n'
      '    super.dispose();\n'
      '  }\n'
      '\n'
      '  void _send(String text) {\n'
      '    setState(() {\n'
      '      _sent.insert(0, text);\n'
      '      _draft.clear();\n'
      '      _generating = true;\n'
      '    });\n'
      '  }\n'
      '\n'
      '  @override\n'
      '  Widget build(BuildContext context) {\n'
      '    // Enter sends, Shift+Enter starts a line, and the send button is disabled\n'
      '    // until there is something to send. While generating it becomes stop.\n'
      '    return AstryxVStack(\n'
      '      gap: AstryxSpacingToken.spacing3,\n'
      '      align: AstryxStackAlign.stretch,\n'
      '      children: <Widget>[\n'
      '        AstryxChatComposer(\n'
      '          controller: _draft,\n'
      '          generating: _generating,\n'
      '          onSubmit: _send,\n'
      '          onStop: () => setState(() => _generating = false),\n'
      '          leading: <Widget>[\n'
      '            AstryxIconButton(\n'
      '              icon: AstryxIconName.wrench,\n'
      '              label: \'Tools\',\n'
      '              variant: AstryxButtonVariant.ghost,\n'
      '              onPressed: () {},\n'
      '            ),\n'
      '          ],\n'
      '          trailing: <Widget>[\n'
      '            AstryxIconButton(\n'
      '              icon: AstryxIconName.microphone,\n'
      '              label: \'Dictate\',\n'
      '              variant: AstryxButtonVariant.ghost,\n'
      '              onPressed: () {},\n'
      '            ),\n'
      '          ],\n'
      '          footer: const AstryxText(\n'
      '            \'Enter sends · Shift+Enter starts a line\',\n'
      '            type: AstryxTextType.supporting,\n'
      '            color: AstryxTextColor.secondary,\n'
      '          ),\n'
      '        ),\n'
      '        if (_sent.isNotEmpty)\n'
      '          AstryxText(\n'
      '            \'Sent: \${_sent.first}\',\n'
      '            type: AstryxTextType.supporting,\n'
      '            color: AstryxTextColor.secondary,\n'
      '          ),\n'
      '      ],\n'
      '    );\n'
      '  }\n'
      '}\n',
  // examples/chat_examples.dart
  'chat_composer_drawer':
      'class ChatComposerDrawerExample extends StatefulWidget {\n'
      '  const ChatComposerDrawerExample({super.key});\n'
      '\n'
      '  @override\n'
      '  State<ChatComposerDrawerExample> createState() =>\n'
      '      _ChatComposerDrawerExampleState();\n'
      '}\n'
      '\n'
      'class _ChatComposerDrawerExampleState extends State<ChatComposerDrawerExample> {\n'
      '  final TextEditingController _draft = TextEditingController();\n'
      '  final List<String> _attached = <String>[\'deploy-log-14-02.txt\'];\n'
      '\n'
      '  @override\n'
      '  void dispose() {\n'
      '    _draft.dispose();\n'
      '    super.dispose();\n'
      '  }\n'
      '\n'
      '  @override\n'
      '  Widget build(BuildContext context) {\n'
      '    // The drawer is part of the composer\'s surface rather than floating above\n'
      '    // it, so what is about to be sent is unmistakable.\n'
      '    return AstryxChatComposer(\n'
      '      controller: _draft,\n'
      '      onSubmit: (_) => setState(_draft.clear),\n'
      '      drawer: _attached.isEmpty\n'
      '          ? null\n'
      '          : AstryxHStack(\n'
      '              gap: AstryxSpacingToken.spacing2,\n'
      '              wrap: true,\n'
      '              runGap: AstryxSpacingToken.spacing2,\n'
      '              children: <Widget>[\n'
      '                for (final file in _attached)\n'
      '                  AstryxBadge(file),\n'
      '                AstryxButton(\n'
      '                  label: \'Remove all\',\n'
      '                  variant: AstryxButtonVariant.ghost,\n'
      '                  size: AstryxButtonSize.sm,\n'
      '                  onPressed: () => setState(_attached.clear),\n'
      '                ),\n'
      '              ],\n'
      '            ),\n'
      '      leading: <Widget>[\n'
      '        AstryxIconButton(\n'
      '          icon: AstryxIconName.copy,\n'
      '          label: \'Attach a file\',\n'
      '          variant: AstryxButtonVariant.ghost,\n'
      '          onPressed: () => setState(() => _attached.add(\'metrics.csv\')),\n'
      '        ),\n'
      '      ],\n'
      '    );\n'
      '  }\n'
      '}\n',
