  // examples/chat_examples.dart
  'chat_composer_token':
      'class ChatComposerTokenExample extends StatefulWidget {\n'
      '  const ChatComposerTokenExample({super.key});\n'
      '\n'
      '  @override\n'
      '  State<ChatComposerTokenExample> createState() =>\n'
      '      _ChatComposerTokenExampleState();\n'
      '}\n'
      '\n'
      'class _ChatComposerTokenExampleState extends State<ChatComposerTokenExample> {\n'
      '  final AstryxTokenTextController _draft = AstryxTokenTextController(\n'
      '    tokens: const <String, AstryxTextToken>{\n'
      '      \'@ada\': AstryxTextToken(),\n'
      '      \'@grace\': AstryxTextToken(),\n'
      '      \'deploy-log.txt\': AstryxTextToken(),\n'
      '    },\n'
      '    text: \'Ask @ada about deploy-log.txt\',\n'
      '  );\n'
      '\n'
      '  List<String> _mentioned = <String>[];\n'
      '\n'
      '  @override\n'
      '  void initState() {\n'
      '    super.initState();\n'
      '    _draft.addListener(_track);\n'
      '    _mentioned = _draft.present;\n'
      '  }\n'
      '\n'
      '  void _track() => setState(() => _mentioned = _draft.present);\n'
      '\n'
      '  @override\n'
      '  void dispose() {\n'
      '    _draft\n'
      '      ..removeListener(_track)\n'
      '      ..dispose();\n'
      '    super.dispose();\n'
      '  }\n'
      '\n'
      '  @override\n'
      '  Widget build(BuildContext context) {\n'
      '    // The tokens are *styled text*, not widgets: edit around them and the\n'
      '    // caret, selection and backspace behave exactly as they do anywhere else.\n'
      '    return AstryxVStack(\n'
      '      gap: AstryxSpacingToken.spacing3,\n'
      '      align: AstryxStackAlign.stretch,\n'
      '      children: <Widget>[\n'
      '        AstryxChatComposer(controller: _draft, onSubmit: (_) {}),\n'
      '        AstryxText(\n'
      '          _mentioned.isEmpty\n'
      '              ? \'Nothing mentioned\'\n'
      '              : \'Mentioned: \${_mentioned.join(\', \')}\',\n'
      '          type: AstryxTextType.supporting,\n'
      '          color: AstryxTextColor.secondary,\n'
      '        ),\n'
      '      ],\n'
      '    );\n'
      '  }\n'
      '}\n',
