  // examples/code_examples.dart
  'code_span':
      'class CodeSpanExample extends StatelessWidget {\n'
      '  const CodeSpanExample({super.key});\n'
      '\n'
      '  @override\n'
      '  Widget build(BuildContext context) {\n'
      '    // Flutter has no inline element, so a widget cannot sit inside a string.\n'
      '    // `AstryxCode.span` is the bridge: a `WidgetSpan` that lines up with the\n'
      '    // sentence around it.\n'
      '    return Text.rich(\n'
      '      TextSpan(\n'
      '        style: AstryxTheme.of(context).textStyle(AstryxTypeRole.body),\n'
      '        children: <InlineSpan>[\n'
