      '            exclusive: true,\n'
      '            initialIndex: 0,\n'
      '            onChanged: (index) => setState(() => _open = index),\n'
      '            children: const <AstryxCollapsible>[\n'
      '              AstryxCollapsible(\n'
      '                title: \'Shipping address\',\n'
      '                child: AstryxText(\'12 Hanover Square, London\'),\n'
