  // examples/color_examples.dart
  'color_roles':
      'class ColorRolesExample extends StatelessWidget {\n'
      '  const ColorRolesExample({super.key});\n'
      '\n'
      '  /// The semantic tokens, grouped by the job they do rather than by hue.\n'
      '  ///\n'
      '  /// A token is chosen by what it is *for* — the surface a card sits on, the\n'
      '  /// line that bounds a control — which is why none of them is named after a\n'
      '  /// colour.\n'
      '  static const List<(String, List<AstryxColorToken>)> _groups =\n'
      '      <(String, List<AstryxColorToken>)>[\n'
      '        (\n'
      '          \'Surfaces\',\n'
      '          <AstryxColorToken>[\n'
      '            AstryxColorToken.backgroundBody,\n'
      '            AstryxColorToken.backgroundSurface,\n'
      '            AstryxColorToken.backgroundCard,\n'
      '            AstryxColorToken.backgroundMuted,\n'
      '            AstryxColorToken.backgroundInverted,\n'
      '          ],\n'
      '        ),\n'
      '        (\n'
      '          \'Text and icon\',\n'
      '          <AstryxColorToken>[\n'
      '            AstryxColorToken.textPrimary,\n'
      '            AstryxColorToken.textSecondary,\n'
      '            AstryxColorToken.textDisabled,\n'
      '            AstryxColorToken.textAccent,\n'
      '            AstryxColorToken.iconSecondary,\n'
      '          ],\n'
      '        ),\n'
      '        (\n'
      '          \'Lines and fills\',\n'
      '          <AstryxColorToken>[\n'
      '            AstryxColorToken.border,\n'
      '            AstryxColorToken.borderEmphasized,\n'
      '            AstryxColorToken.skeleton,\n'
      '            AstryxColorToken.track,\n'
      '            AstryxColorToken.tintHover,\n'
      '          ],\n'
      '        ),\n'
      '        (\n'
      '          \'Sentiment\',\n'
      '          <AstryxColorToken>[\n'
      '            AstryxColorToken.accent,\n'
      '            AstryxColorToken.success,\n'
      '            AstryxColorToken.warning,\n'
      '            AstryxColorToken.error,\n'
      '            AstryxColorToken.errorMuted,\n'
      '          ],\n'
      '        ),\n'
      '      ];\n'
      '\n'
      '  @override\n'
      '  Widget build(BuildContext context) {\n'
      '    final theme = AstryxTheme.of(context);\n'
      '\n'
      '    return AstryxGrid(\n'
      '      minWidth: 210,\n'
      '      gap: AstryxSpacingToken.spacing3,\n'
      '      children: <Widget>[\n'
      '        for (final (title, tokens) in _groups)\n'
      '          AstryxCard(\n'
      '            padding: AstryxSpacingToken.spacing3,\n'
      '            child: AstryxVStack(\n'
      '              gap: AstryxSpacingToken.spacing2,\n'
      '              align: AstryxStackAlign.stretch,\n'
      '              children: <Widget>[\n'
      '                AstryxText(title, type: AstryxTextType.label),\n'
      '                for (final token in tokens)\n'
      '                  AstryxHStack(\n'
      '                    gap: AstryxSpacingToken.spacing2,\n'
      '                    children: <Widget>[\n'
      '                      DecoratedBox(\n'
      '                        decoration: BoxDecoration(\n'
      '                          color: theme.color(token),\n'
      '                          borderRadius: theme.borderRadius(\n'
      '                            AstryxRadiusToken.inner,\n'
      '                          ),\n'
      '                          border: Border.all(\n'
      '                            color: theme.color(AstryxColorToken.border),\n'
      '                          ),\n'
      '                        ),\n'
      '                        child: const SizedBox(width: 20, height: 20),\n'
      '                      ),\n'
      '                      Flexible(\n'
      '                        child: AstryxText(\n'
      '                          token.name,\n'
      '                          type: AstryxTextType.supporting,\n'
      '                          color: AstryxTextColor.secondary,\n'
      '                          maxLines: 1,\n'
      '                        ),\n'
      '                      ),\n'
      '                    ],\n'
      '                  ),\n'
      '              ],\n'
      '            ),\n'
      '          ),\n'
      '      ],\n'
      '    );\n'
      '  }\n'
      '}\n',
  // examples/color_examples.dart
  'color_on_pairs':
      'class ColorOnPairsExample extends StatelessWidget {\n'
      '  const ColorOnPairsExample({super.key});\n'
      '\n'
      '  /// Each fill and the foreground that is guaranteed to read on it.\n'
      '  static const List<(AstryxColorToken, AstryxColorToken)> _pairs =\n'
      '      <(AstryxColorToken, AstryxColorToken)>[\n'
      '        (AstryxColorToken.accent, AstryxColorToken.onAccent),\n'
      '        (AstryxColorToken.success, AstryxColorToken.onSuccess),\n'
      '        (AstryxColorToken.warning, AstryxColorToken.onWarning),\n'
      '        (AstryxColorToken.error, AstryxColorToken.onError),\n'
      '      ];\n'
      '\n'
      '  @override\n'
      '  Widget build(BuildContext context) {\n'
      '    final theme = AstryxTheme.of(context);\n'
      '\n'
      '    // Never choose the foreground yourself. Each `--color-on-*` token is\n'
      '    // derived from its fill, so it stays legible when the accent changes.\n'
      '    return AstryxHStack(\n'
      '      gap: AstryxSpacingToken.spacing2,\n'
      '      wrap: true,\n'
      '      runGap: AstryxSpacingToken.spacing2,\n'
      '      children: <Widget>[\n'
      '        for (final (fill, on) in _pairs)\n'
      '          DecoratedBox(\n'
      '            decoration: BoxDecoration(\n'
      '              color: theme.color(fill),\n'
      '              borderRadius: theme.borderRadius(AstryxRadiusToken.element),\n'
      '            ),\n'
      '            child: Padding(\n'
      '              padding: EdgeInsets.symmetric(\n'
      '                horizontal: theme.spacing(AstryxSpacingToken.spacing3),\n'
      '                vertical: theme.spacing(AstryxSpacingToken.spacing2),\n'
      '              ),\n'
      '              child: Text(\n'
      '                on.name,\n'
      '                style: theme\n'
      '                    .textStyle(AstryxTypeRole.label)\n'
      '                    .copyWith(color: theme.color(on)),\n'
      '              ),\n'
      '            ),\n'
      '          ),\n'
      '      ],\n'
      '    );\n'
      '  }\n'
      '}\n',
