  // examples/core_examples.dart
  'core_pipeline':
      '/// A definition: one seed accent, and one token set by hand.\n'
      'final AstryxDefinedTheme _demoTheme = defineTheme(\n'
      '  const AstryxDefineThemeInput(\n'
      '    name: \'engine-demo\',\n'
      '    color: AstryxColorScaleConfig(accent: \'#B3261E\'),\n'
      '    tokens: <String, AstryxTokenValue>{\n'
      '      \'--radius-element\': AstryxTokenValue(\'2px\'),\n'
      '    },\n'
      '  ),\n'
      ');\n'
      '\n'
      '/// The engine\'s output: every token, concrete, in both modes.\n'
      '///\n'
      '/// Resolved once, at the top level — not per build. A theme is read far more\n'
      '/// often than it changes.\n'
      'final AstryxResolvedTokenSet _resolved = AstryxResolvedTokenSet.resolve(\n'
      '  _demoTheme,\n'
      ');\n'
      '\n'
      'class CorePipelineExample extends StatelessWidget {\n'
      '  const CorePipelineExample({super.key});\n'
      '\n'
      '  static const List<AstryxToken> _shown = <AstryxToken>[\n'
      '    // Generated from the seed.\n'
      '    AstryxColorToken.accent,\n'
      '    // Emitted as `var(--color-accent)`, followed by the resolver.\n'
      '    AstryxColorToken.textAccent,\n'
      '    // A `light-dark()` pair: one token, two halves.\n'
      '    AstryxColorToken.backgroundCard,\n'
      '    // Overridden by hand, beating the generated value.\n'
      '    AstryxRadiusToken.element,\n'
      '    // Untouched by the definition, so the token default stands.\n'
      '    AstryxDurationToken.fast,\n'
      '  ];\n'
      '\n'
      '  @override\n'
      '  Widget build(BuildContext context) {\n'
      '    return AstryxVStack(\n'
      '      gap: AstryxSpacingToken.spacing2,\n'
      '      align: AstryxStackAlign.stretch,\n'
      '      children: <Widget>[\n'
      '        const _Row(cells: <String>[\'token\', \'light\', \'dark\'], header: true),\n'
      '        for (final token in _shown)\n'
      '          _Row(\n'
      '            cells: <String>[\n'
      '              token.cssName,\n'
      '              _resolved.value(token, AstryxThemeMode.light),\n'
      '              _resolved.value(token, AstryxThemeMode.dark),\n'
      '            ],\n'
      '          ),\n'
      '      ],\n'
      '    );\n'
      '  }\n'
      '}\n'
      '\n'
      'class _Row extends StatelessWidget {\n'
      '  const _Row({required this.cells, this.header = false});\n'
      '\n'
      '  final List<String> cells;\n'
      '  final bool header;\n'
      '\n'
      '  @override\n'
      '  Widget build(BuildContext context) {\n'
