      '    return SizedBox(\n'
      '      width: 260,\n'
      '      child: AstryxDateInput(\n'
      '        label: \'Start date\',\n'
      '        value: _start,\n'
      '        required: true,\n'
      '        firstDate: today,\n'
      '        lastDate: DateTime(today.year + 1, today.month, today.day),\n'
      '        selectableDayPredicate: (day) =>\n'
      '            day.weekday != DateTime.saturday && day.weekday != DateTime.sunday,\n'
      '        onChanged: (date) => setState(() => _start = date),\n'
      '      ),\n'
