      'class _DateTimeInputDemoExampleState extends State<DateTimeInputDemoExample> {\n'
      '  DateTime? _publishAt;\n'
      '\n'
      '  @override\n'
      '  Widget build(BuildContext context) {\n'
      '    // A date on its own is still an answer: picking a day with the time left\n'
      '    // alone commits `defaultTime` — 09:00 here. A time on its own commits\n'
      '    // nothing, because there is no instant to report.\n'
      '    return AstryxVStack(\n'
      '      gap: AstryxSpacingToken.spacing3,\n'
      '      align: AstryxStackAlign.stretch,\n'
      '      children: <Widget>[\n'
      '        SizedBox(\n'
      '          width: 340,\n'
      '          child: AstryxDateTimeInput(\n'
      '            label: \'Publish at\',\n'
      '            value: _publishAt,\n'
      '            defaultTime: const AstryxTime(hour: 9, minute: 0),\n'
      '            stepMinutes: 15,\n'
      '            onChanged: (at) => setState(() => _publishAt = at),\n'
      '          ),\n'
      '        ),\n'
      '        AstryxText(\n'
      '          _publishAt == null ? \'Not scheduled\' : _publishAt!.toIso8601String(),\n'
      '          type: AstryxTextType.supporting,\n'
      '          color: AstryxTextColor.secondary,\n'
      '        ),\n'
      '      ],\n'
      '    );\n'
      '  }\n'
      '}\n',
