  // examples/divider_examples.dart
  'divider_vertical':
      'class DividerVerticalExample extends StatelessWidget {\n'
      '  const DividerVerticalExample({super.key});\n'
      '\n'
      '  @override\n'
      '  Widget build(BuildContext context) {\n'
      '    // A vertical rule needs a bounded height. `align: stretch` inside a row of\n'
      '    // known height gives it one; an `IntrinsicHeight` also works.\n'
      '    return const SizedBox(\n'
      '      height: 24,\n'
