  // examples/dropdown_menu_examples.dart
  'dropdown_menu_placement':
      'class DropdownMenuPlacementExample extends StatelessWidget {\n'
      '  const DropdownMenuPlacementExample({super.key});\n'
      '\n'
      '  @override\n'
      '  Widget build(BuildContext context) {\n'
