      '          AstryxMenuItem(label: \'Newest first\', onSelected: () {}),\n'
      '          AstryxMenuItem(label: \'Oldest first\', onSelected: () {}),\n'
      '          AstryxMenuItem(label: \'Most requests\', onSelected: () {}),\n'
      '        ],\n'
      '        triggerBuilder: (context, controller) => AstryxButton(\n'
      '          label: \'Sort\',\n'
      '          width: double.infinity,\n'
      '          trailing: const AstryxIcon(AstryxIconName.chevronDown),\n'
