  // examples/elevation_examples.dart
  'elevation_shadows':
      'class ElevationShadowsExample extends StatelessWidget {\n'
      '  const ElevationShadowsExample({super.key});\n'
      '\n'
      '  /// The three drop shadows, and what sits at each.\n'
      '  static const List<(AstryxShadowToken, String)> _steps =\n'
      '      <(AstryxShadowToken, String)>[\n'
      '        (AstryxShadowToken.low, \'popover, tooltip, menu\'),\n'
      '        (AstryxShadowToken.med, \'toast, selector list\'),\n'
      '        (AstryxShadowToken.high, \'dialog\'),\n'
      '      ];\n'
      '\n'
      '  @override\n'
      '  Widget build(BuildContext context) {\n'
      '    final theme = AstryxTheme.of(context);\n'
      '\n'
      '    return AstryxGrid(\n'
      '      minWidth: 190,\n'
      '      gap: AstryxSpacingToken.spacing6,\n'
      '      children: <Widget>[\n'
      '        for (final (token, uses) in _steps)\n'
      '          DecoratedBox(\n'
      '            decoration: BoxDecoration(\n'
      '              color: theme.color(AstryxColorToken.backgroundPopover),\n'
      '              borderRadius: theme.borderRadius(AstryxRadiusToken.container),\n'
      '              boxShadow: theme.boxShadows(token),\n'
      '            ),\n'
      '            child: Padding(\n'
      '              padding: EdgeInsets.all(\n'
      '                theme.spacing(AstryxSpacingToken.spacing4),\n'
      '              ),\n'
      '              child: AstryxVStack(\n'
      '                gap: AstryxSpacingToken.spacing1,\n'
      '                align: AstryxStackAlign.stretch,\n'
      '                children: <Widget>[\n'
      '                  AstryxText(token.name, type: AstryxTextType.label),\n'
      '                  AstryxText(\n'
      '                    uses,\n'
      '                    type: AstryxTextType.supporting,\n'
      '                    color: AstryxTextColor.secondary,\n'
      '                  ),\n'
      '                ],\n'
      '              ),\n'
      '            ),\n'
      '          ),\n'
      '      ],\n'
      '    );\n'
      '  }\n'
      '}\n',
  // examples/elevation_examples.dart
  'elevation_button':
      'class ElevationButtonExample extends StatelessWidget {\n'
      '  const ElevationButtonExample({super.key});\n'
