  // examples/field_examples.dart
  'field_demo':
      'class FieldDemoExample extends StatefulWidget {\n'
      '  const FieldDemoExample({super.key});\n'
      '\n'
      '  @override\n'
      '  State<FieldDemoExample> createState() => _FieldDemoExampleState();\n'
      '}\n'
      '\n'
      'class _FieldDemoExampleState extends State<FieldDemoExample> {\n'
      '  double _budget = 40;\n'
      '\n'
      '  @override\n'
      '  Widget build(BuildContext context) {\n'
      '    // `AstryxField` gives a label, description, required marker and status\n'
      '    // message to a control that has none of its own — here a plain Flutter\n'
      '    // slider. The field publishes all of that to its child through\n'
      '    // `AstryxFieldScope`, so the control does not have to take the props.\n'
      '    return SizedBox(\n'
      '      width: 320,\n'
      '      child: AstryxField(\n'
      '        label: \'Monthly budget\',\n'
      '        description: \'Alerts fire at 80% of this.\',\n'
      '        required: true,\n'
      '        status: _budget > 80\n'
      '            ? const AstryxFieldStatus.warning(\'Above your usual spend\')\n'
      '            : null,\n'
      '        child: AstryxHStack(\n'
      '          gap: AstryxSpacingToken.spacing3,\n'
      '          mainAxisSize: MainAxisSize.max,\n'
      '          children: <Widget>[\n'
      '            Expanded(\n'
      '              child: _Slider(\n'
      '                value: _budget,\n'
      '                onChanged: (value) => setState(() => _budget = value),\n'
      '              ),\n'
      '            ),\n'
      '            AstryxText(\n'
      '              \'\\\$\${_budget.round()}\',\n'
      '              tabularNumbers: true,\n'
      '            ),\n'
      '          ],\n'
      '        ),\n'
      '      ),\n'
      '    );\n'
      '  }\n'
      '}\n',
  // examples/field_examples.dart
  'field_scope':
      'class FieldScopeExample extends StatelessWidget {\n'
      '  const FieldScopeExample({super.key});\n'
      '\n'
      '  @override\n'
      '  Widget build(BuildContext context) {\n'
      '    // Controls that *do* have their own label read the scope instead of\n'
      '    // repeating it: `enabled` and `status` cascade down from the field.\n'
      '    return SizedBox(\n'
      '      width: 320,\n'
      '      child: AstryxField(\n'
      '        label: \'Region\',\n'
      '        description: \'Both controls inherit the field being disabled.\',\n'
      '        enabled: false,\n'
      '        child: AstryxVStack(\n'
      '          gap: AstryxSpacingToken.spacing2,\n'
      '          align: AstryxStackAlign.stretch,\n'
      '          children: <Widget>[\n'
      '            const AstryxTextInput(label: \'Region\', labelHidden: true),\n'
      '            AstryxCheckbox(\n'
      '              label: \'Replicate to a second region\',\n'
      '              value: false,\n'
      '            ),\n'
      '          ],\n'
      '        ),\n'
