  // examples/forms_advanced_examples.dart
  'input_group_status':
      'class InputGroupStatusExample extends StatelessWidget {\n'
      '  const InputGroupStatusExample({super.key});\n'
      '\n'
      '  @override\n'
      '  Widget build(BuildContext context) {\n'
      '    // The status belongs to the group, so the whole joined border carries it\n'
      '    // rather than one child of it turning red on its own.\n'
      '    return AstryxInputGroup(\n'
      '      label: \'Amount\',\n'
      '      status: const AstryxFieldStatus.error(\'Enter an amount above zero.\'),\n'
      '      children: <Widget>[\n'
      '        const AstryxInputGroupText(r\'\$\'),\n'
      '        Expanded(\n'
      '          child: AstryxTextInput(\n'
      '            label: \'Amount\',\n'
      '            labelHidden: true,\n'
      '            placeholder: \'0.00\',\n'
      '            onChanged: (_) {},\n'
      '          ),\n'
      '        ),\n'
      '        const AstryxInputGroupText(\'USD\'),\n'
