  // examples/forms_group_examples.dart
  'number_input_range':
      'class NumberInputRangeExample extends StatefulWidget {\n'
      '  const NumberInputRangeExample({super.key});\n'
      '\n'
      '  @override\n'
      '  State<NumberInputRangeExample> createState() =>\n'
      '      _NumberInputRangeExampleState();\n'
      '}\n'
      '\n'
      'class _NumberInputRangeExampleState extends State<NumberInputRangeExample> {\n'
      '  num? _timeout = 2.5;\n'
      '  num? _year = 1999;\n'
      '\n'
      '  @override\n'
      '  Widget build(BuildContext context) {\n'
      '    return AstryxVStack(\n'
      '      gap: AstryxSpacingToken.spacing4,\n'
      '      children: <Widget>[\n'
      '        // A fractional step and a unit. Typing 99 here is refused rather than\n'
      '        // pulled down to 10 — the value stays what it was, and the rejection is\n'
      '        // announced.\n'
      '        AstryxNumberInput(\n'
      '          label: \'Timeout\',\n'
      '          value: _timeout,\n'
      '          min: 0.5,\n'
      '          max: 10,\n'
      '          step: 0.5,\n'
      '          units: \'seconds\',\n'
      '          width: 260,\n'
      '          onChanged: (value) => setState(() => _timeout = value),\n'
      '        ),\n'
      '        // No steppers: nobody increments a year one at a time.\n'
      '        AstryxNumberInput(\n'
      '          label: \'Year\',\n'
      '          value: _year,\n'
      '          min: 1900,\n'
      '          max: 2100,\n'
      '          integerOnly: true,\n'
      '          steppers: false,\n'
      '          showClear: true,\n'
      '          width: 260,\n'
      '          onChanged: (value) => setState(() => _year = value),\n'
      '        ),\n'
      '      ],\n'
      '    );\n'
      '  }\n'
      '}\n',
