      'class GridResponsiveExample extends StatelessWidget {\n'
      '  const GridResponsiveExample({super.key});\n'
      '\n'
      '  @override\n'
      '  Widget build(BuildContext context) {\n'
      '    // No breakpoints. The column count falls out of the width available, the\n'
      '    // way `repeat(auto-fit, minmax(180px, 1fr))` does upstream. Resize the\n'
      '    // window to watch it re-flow.\n'
      '    return const AstryxGrid(\n'
      '      minWidth: 180,\n'
      '      maxColumns: 4,\n'
      '      gap: AstryxSpacingToken.spacing3,\n'
      '      children: <Widget>[\n'
      '        _Metric(\'Requests\', \'4,201\'),\n'
      '        _Metric(\'Errors\', \'12\'),\n'
      '        _Metric(\'p95\', \'318 ms\'),\n'
