  // examples/hooks_examples.dart
  'hook_theme':
      'class HookThemeExample extends StatelessWidget {\n'
      '  const HookThemeExample({super.key});\n'
      '\n'
      '  @override\n'
      '  Widget build(BuildContext context) {\n'
      '    // `AstryxTheme.of(context)` is the whole of `useTheme`: a lookup up the\n'
      '    // tree, and a subscription to it — this widget rebuilds when the theme\n'
      '    // changes, with nothing wired up to make that happen.\n'
      '    final theme = AstryxTheme.of(context);\n'
      '\n'
      '    return AstryxMetadataList(\n'
      '      items: <AstryxMetadataItem>[\n'
      '        AstryxMetadataItem.text(label: \'Mode\', value: theme.mode.name),\n'
      '        AstryxMetadataItem.text(\n'
      '          label: \'Platform\',\n'
      '          value: theme.platform.name,\n'
      '        ),\n'
      '        AstryxMetadataItem.text(\n'
      '          label: \'Density\',\n'
      '          value: AstryxTheme.densityOf(context).name,\n'
      '        ),\n'
      '        AstryxMetadataItem(\n'
      '          label: \'accent\',\n'
      '          value: AstryxHStack(\n'
      '            gap: AstryxSpacingToken.spacing2,\n'
      '            children: <Widget>[\n'
      '              Container(\n'
      '                width: 16,\n'
      '                height: 16,\n'
      '                decoration: BoxDecoration(\n'
      '                  color: theme.color(AstryxColorToken.accent),\n'
      '                  borderRadius: theme.borderRadius(AstryxRadiusToken.inner),\n'
      '                ),\n'
      '              ),\n'
      '              AstryxCode(\n'
      '                \'spacing3 = \${theme.spacing(AstryxSpacingToken.spacing3)}\',\n'
      '              ),\n'
      '            ],\n'
      '          ),\n'
      '        ),\n'
      '      ],\n'
      '    );\n'
      '  }\n'
      '}\n',
  // examples/hooks_examples.dart
  'hook_media_query':
      'class HookMediaQueryExample extends StatelessWidget {\n'
      '  const HookMediaQueryExample({super.key});\n'
      '\n'
      '  @override\n'
      '  Widget build(BuildContext context) {\n'
      '    // `LayoutBuilder` answers "how much room do *I* have" — the question a\n'
      '    // component actually has. `MediaQuery` answers "how big is the window",\n'
      '    // which is a different one, and the wrong one inside a panel.\n'
      '    return LayoutBuilder(\n'
      '      builder: (context, constraints) {\n'
      '        final narrow = constraints.maxWidth < 420;\n'
      '\n'
      '        return AstryxVStack(\n'
      '          gap: AstryxSpacingToken.spacing3,\n'
      '          align: AstryxStackAlign.stretch,\n'
      '          children: <Widget>[\n'
      '            AstryxBanner(\n'
      '              status: narrow\n'
      '                  ? AstryxBannerStatus.warning\n'
      '                  : AstryxBannerStatus.info,\n'
      '              title: narrow\n'
      '                  ? \'Narrow: \${constraints.maxWidth.round()}px\'\n'
      '                  : \'Wide: \${constraints.maxWidth.round()}px\',\n'
      '              description:\n'
      '                  \'Drag the window. The threshold is a number this example \'\n'
      '                  \'chose, not an entry in a breakpoint table.\',\n'
      '            ),\n'
      '            if (narrow)\n'
      '              const AstryxText(\'Stacked, because there is no room beside.\')\n'
      '            else\n'
      '              const AstryxHStack(\n'
      '                gap: AstryxSpacingToken.spacing3,\n'
      '                children: <Widget>[\n'
      '                  AstryxBadge(\'Side by side\'),\n'
      '                  AstryxBadge(\'While it fits\'),\n'
      '                ],\n'
      '              ),\n'
      '          ],\n'
      '        );\n'
      '      },\n'
      '    );\n'
      '  }\n'
      '}\n',
  // examples/hooks_examples.dart
  'hook_hotkeys':
      'class HookHotkeysExample extends StatefulWidget {\n'
      '  const HookHotkeysExample({super.key});\n'
      '\n'
      '  @override\n'
      '  State<HookHotkeysExample> createState() => _HookHotkeysExampleState();\n'
      '}\n'
      '\n'
      'class _HookHotkeysExampleState extends State<HookHotkeysExample> {\n'
      '  static const AstryxHotkey _save = AstryxHotkey.mod(LogicalKeyboardKey.keyS);\n'
      '  static const AstryxHotkey _palette = AstryxHotkey.mod(\n'
      '    LogicalKeyboardKey.keyK,\n'
      '  );\n'
      '\n'
      '  final List<String> _log = <String>[];\n'
      '\n'
      '  void _record(String what) => setState(() {\n'
      '    _log.insert(0, what);\n'
      '    if (_log.length > 3) _log.removeLast();\n'
      '  });\n'
      '\n'
      '  @override\n'
      '  Widget build(BuildContext context) {\n'
      '    // One definition per shortcut: bound here, and drawn by `AstryxKbd.hotkey`\n'
      '    // below from the same object — so the hint can never describe a key that is\n'
      '    // not the one bound. `mod` is ⌘ on a Mac and Ctrl elsewhere.\n'
      '    return AstryxHotkeys(\n'
      '      autofocus: true,\n'
      '      bindings: <AstryxHotkey, VoidCallback>{\n'
      '        _save: () => _record(\'Saved\'),\n'
      '        _palette: () => _record(\'Opened the palette\'),\n'
      '      },\n'
      '      child: AstryxCard(\n'
      '        child: AstryxVStack(\n'
      '          gap: AstryxSpacingToken.spacing3,\n'
      '          align: AstryxStackAlign.stretch,\n'
      '          children: <Widget>[\n'
      '            const AstryxList(\n'
      '              children: <Widget>[\n'
      '                AstryxItem(\n'
      '                  label: \'Save\',\n'
      '                  trailing: AstryxKbd.hotkey(_save),\n'
      '                ),\n'
      '                AstryxItem(\n'
      '                  label: \'Command palette\',\n'
      '                  trailing: AstryxKbd.hotkey(_palette),\n'
      '                ),\n'
      '              ],\n'
      '            ),\n'
      '            AstryxText(\n'
      '              _log.isEmpty ? \'Press one of them\' : _log.join(\' · \'),\n'
      '              type: AstryxTextType.supporting,\n'
      '              color: AstryxTextColor.secondary,\n'
      '            ),\n'
      '          ],\n'
      '        ),\n'
      '      ),\n'
      '    );\n'
      '  }\n'
      '}\n',
  // examples/hooks_examples.dart
  'hook_focus_trap':
      'class HookFocusTrapExample extends StatefulWidget {\n'
      '  const HookFocusTrapExample({super.key});\n'
      '\n'
      '  @override\n'
      '  State<HookFocusTrapExample> createState() => _HookFocusTrapExampleState();\n'
      '}\n'
      '\n'
      'class _HookFocusTrapExampleState extends State<HookFocusTrapExample> {\n'
      '  bool _trapped = true;\n'
      '\n'
      '  @override\n'
      '  Widget build(BuildContext context) {\n'
      '    // Tab round the three buttons inside the panel. Trapped, focus loops inside\n'
      '    // it; untrapped, it escapes to the switch above and onto the page. Every\n'
      '    // Astryx overlay uses this — reach for it directly only for a layer you are\n'
      '    // building yourself.\n'
      '    return AstryxVStack(\n'
      '      gap: AstryxSpacingToken.spacing3,\n'
      '      align: AstryxStackAlign.stretch,\n'
      '      children: <Widget>[\n'
      '        AstryxSwitch(\n'
      '          label: \'Trap focus\',\n'
      '          value: _trapped,\n'
      '          onChanged: (value) => setState(() => _trapped = value),\n'
      '        ),\n'
      '        AstryxFocusTrap(\n'
      '          enabled: _trapped,\n'
      '          // Nothing is stealing focus on the way in here: the panel is already\n'
      '          // on the page, unlike an overlay that has just opened.\n'
      '          autofocus: false,\n'
      '          child: AstryxCard(\n'
      '            child: AstryxHStack(\n'
      '              gap: AstryxSpacingToken.spacing2,\n'
      '              children: <Widget>[\n'
      '                AstryxButton(label: \'First\', onPressed: () {}),\n'
      '                AstryxButton(label: \'Second\', onPressed: () {}),\n'
      '                AstryxButton(label: \'Third\', onPressed: () {}),\n'
      '              ],\n'
      '            ),\n'
      '          ),\n'
      '        ),\n'
      '      ],\n'
      '    );\n'
      '  }\n'
      '}\n',
  // examples/hooks_examples.dart
  'hook_scroll_lock':
      'class HookScrollLockExample extends StatefulWidget {\n'
      '  const HookScrollLockExample({super.key});\n'
      '\n'
      '  @override\n'
      '  State<HookScrollLockExample> createState() => _HookScrollLockExampleState();\n'
      '}\n'
      '\n'
      'class _HookScrollLockExampleState extends State<HookScrollLockExample> {\n'
      '  final AstryxOverlayController _modal = AstryxOverlayController();\n'
      '\n'
      '  @override\n'
      '  void dispose() {\n'
      '    _modal.dispose();\n'
      '    super.dispose();\n'
      '  }\n'
      '\n'
      '  @override\n'
      '  Widget build(BuildContext context) {\n'
      '    // Open the panel, then try to scroll the list behind it. Locked, it does\n'
      '    // not move — a scrim blocks presses, and a wheel is not a press.\n'
      '    return AstryxVStack(\n'
      '      gap: AstryxSpacingToken.spacing3,\n'
      '      align: AstryxStackAlign.stretch,\n'
      '      children: <Widget>[\n'
      '        AstryxButton(label: \'Open the panel\', onPressed: _modal.show),\n'
      '        AstryxOverlay(\n'
      '          controller: _modal,\n'
      '          label: \'Panel\',\n'
      '          child: AstryxCard(\n'
      '            width: 280,\n'
      '            child: AstryxVStack(\n'
      '              gap: AstryxSpacingToken.spacing3,\n'
      '              children: <Widget>[\n'
      '                const AstryxText(\'Now try to scroll the list behind this.\'),\n'
      '                AstryxButton(label: \'Close\', onPressed: _modal.hide),\n'
      '              ],\n'
      '            ),\n'
      '          ),\n'
      '        ),\n'
      '        AstryxScrollLock.whileModalIsOpen(\n'
      '          child: AstryxCard(\n'
      '            padding: AstryxSpacingToken.spacing0,\n'
      '            // Bounded here rather than around the card: a card lays its body\n'
      '            // out in a column, and a column hands its child unbounded height.\n'
      '            child: SizedBox(\n'
      '              height: 160,\n'
      '              child: ListView(\n'
      '                padding: EdgeInsets.zero,\n'
      '                children: <Widget>[\n'
      '                  for (var i = 1; i <= 20; i++) AstryxItem(label: \'Row \$i\'),\n'
      '                ],\n'
      '              ),\n'
      '            ),\n'
      '          ),\n'
      '        ),\n'
      '      ],\n'
      '    );\n'
      '  }\n'
      '}\n',
  // examples/hooks_examples.dart
  'hook_scroll_overflow':
      'class HookScrollOverflowExample extends StatefulWidget {\n'
      '  const HookScrollOverflowExample({super.key});\n'
      '\n'
      '  @override\n'
      '  State<HookScrollOverflowExample> createState() =>\n'
      '      _HookScrollOverflowExampleState();\n'
      '}\n'
      '\n'
      'class _HookScrollOverflowExampleState extends State<HookScrollOverflowExample> {\n'
      '  AstryxScrollEdges _edges = AstryxScrollEdges.none;\n'
      '\n'
      '  @override\n'
      '  Widget build(BuildContext context) {\n'
      '    // Scroll the strip. The fade appears only on the side that has more, so it\n'
      '    // is information rather than decoration — and it is never hit-testable, so\n'
      '    // a chip underneath it stays pressable.\n'
      '    return AstryxVStack(\n'
      '      gap: AstryxSpacingToken.spacing2,\n'
      '      align: AstryxStackAlign.stretch,\n'
      '      children: <Widget>[\n'
      '        AstryxScrollOverflow(\n'
      '          onChanged: (edges) => setState(() => _edges = edges),\n'
      '          child: SingleChildScrollView(\n'
      '            scrollDirection: Axis.horizontal,\n'
      '            child: AstryxHStack(\n'
      '              gap: AstryxSpacingToken.spacing2,\n'
      '              children: <Widget>[\n'
      '                for (final region in <String>[\n'
      '                  \'us-east-1\',\n'
      '                  \'us-west-2\',\n'
      '                  \'eu-west-1\',\n'
      '                  \'eu-central-1\',\n'
      '                  \'ap-south-1\',\n'
      '                  \'ap-northeast-1\',\n'
      '                  \'sa-east-1\',\n'
      '                ])\n'
      '                  AstryxBadge(region),\n'
      '              ],\n'
      '            ),\n'
      '          ),\n'
      '        ),\n'
      '        AstryxText(\n'
      '          _edges.overflows\n'
      '              ? \'More at the start: \${_edges.hasMoreAtStart} · \'\n'
      '                    \'more at the end: \${_edges.hasMoreAtEnd}\'\n'
      '              : \'Everything fits\',\n'
      '          type: AstryxTextType.supporting,\n'
      '          color: AstryxTextColor.secondary,\n'
      '        ),\n'
      '      ],\n'
      '    );\n'
      '  }\n'
      '}\n',
  // examples/hooks_examples.dart
  'hook_list_focus':
      'class HookListFocusExample extends StatefulWidget {\n'
      '  const HookListFocusExample({super.key});\n'
      '\n'
      '  @override\n'
      '  State<HookListFocusExample> createState() => _HookListFocusExampleState();\n'
      '}\n'
      '\n'
      'class _HookListFocusExampleState extends State<HookListFocusExample> {\n'
      '  static const List<String> _filters = <String>[\n'
      '    \'Open\',\n'
      '    \'Merged\',\n'
      '    \'Closed\',\n'
      '    \'Draft\',\n'
      '  ];\n'
      '\n'
      '  final Set<int> _on = <int>{0};\n'
      '\n'
      '  @override\n'
      '  Widget build(BuildContext context) {\n'
      '    final theme = AstryxTheme.of(context);\n'
      '\n'
      '    // Tab onto the strip, then use the arrows — one tab stop for four chips.\n'
      '    // `Draft` is disabled, and movement skips it rather than landing on it.\n'
      '    return AstryxVStack(\n'
      '      gap: AstryxSpacingToken.spacing2,\n'
      '      align: AstryxStackAlign.stretch,\n'
      '      children: <Widget>[\n'
      '        AstryxRovingFocus.list(\n'
      '          length: _filters.length,\n'
      '          label: \'Filters\',\n'
      '          gap: AstryxSpacingToken.spacing2,\n'
      '          isEnabled: (index) => _filters[index] != \'Draft\',\n'
      '          onActivate: (index) => setState(() {\n'
      '            _on.contains(index) ? _on.remove(index) : _on.add(index);\n'
      '          }),\n'
      '          itemBuilder: (context, item) {\n'
      '            final selected = _on.contains(item.index);\n'
      '            final enabled = _filters[item.index] != \'Draft\';\n'
      '\n'
      '            return Semantics(\n'
      '              // The items are announced individually even though only the group\n'
      '              // takes focus: `explicitChildNodes` on the group keeps them.\n'
      '              inMutuallyExclusiveGroup: false,\n'
      '              checked: selected,\n'
      '              enabled: enabled,\n'
      '              label: _filters[item.index],\n'
      '              child: ExcludeSemantics(\n'
      '                child: AstryxFocusRing(\n'
      '                  focused: item.showsFocusRing,\n'
      '                  borderRadius: theme.borderRadius(AstryxRadiusToken.full),\n'
      '                  child: AstryxBadge(\n'
      '                    _filters[item.index],\n'
      '                    variant: selected\n'
      '                        ? AstryxBadgeVariant.info\n'
      '                        : AstryxBadgeVariant.neutral,\n'
      '                  ),\n'
      '                ),\n'
      '              ),\n'
      '            );\n'
      '          },\n'
      '        ),\n'
      '        AstryxText(\n'
      '          \'Enter or Space toggles. Selected: \'\n'
      '          \'\${_on.map((i) => _filters[i]).join(\', \')}\',\n'
      '          type: AstryxTextType.supporting,\n'
      '          color: AstryxTextColor.secondary,\n'
      '        ),\n'
      '      ],\n'
      '    );\n'
      '  }\n'
      '}\n',
  // examples/hooks_examples.dart
  'hook_grid_focus':
      'class HookGridFocusExample extends StatefulWidget {\n'
      '  const HookGridFocusExample({super.key});\n'
      '\n'
      '  @override\n'
      '  State<HookGridFocusExample> createState() => _HookGridFocusExampleState();\n'
      '}\n'
      '\n'
      'class _HookGridFocusExampleState extends State<HookGridFocusExample> {\n'
      '  static const List<AstryxPalette> _palettes = AstryxPalette.values;\n'
      '\n'
      '  AstryxPalette? _picked;\n'
      '\n'
      '  @override\n'
      '  Widget build(BuildContext context) {\n'
      '    final theme = AstryxTheme.of(context);\n'
      '\n'
      '    // The inline arrows move within a row, the block arrows between rows, and\n'
      '    // Home and End reach the ends of *that row* rather than of the grid. It\n'
      '    // does not wrap: stepping off a row\'s end would silently change rows.\n'
      '    return AstryxVStack(\n'
      '      gap: AstryxSpacingToken.spacing2,\n'
      '      align: AstryxStackAlign.stretch,\n'
      '      children: <Widget>[\n'
      '        AstryxRovingFocus.grid(\n'
      '          length: _palettes.length,\n'
      '          columns: 3,\n'
      '          label: \'Team colour\',\n'
      '          gap: AstryxSpacingToken.spacing2,\n'
      '          onActivate: (index) => setState(() => _picked = _palettes[index]),\n'
      '          itemBuilder: (context, item) {\n'
      '            final palette = _palettes[item.index];\n'
      '\n'
      '            return Semantics(\n'
      '              button: true,\n'
      '              selected: palette == _picked,\n'
      '              label: palette.name,\n'
      '              child: ExcludeSemantics(\n'
      '                child: AstryxFocusRing(\n'
      '                  focused: item.showsFocusRing,\n'
      '                  borderRadius: theme.borderRadius(AstryxRadiusToken.element),\n'
      '                  child: Container(\n'
      '                    width: 56,\n'
      '                    height: 32,\n'
      '                    decoration: BoxDecoration(\n'
      '                      color: theme.color(palette.background),\n'
      '                      borderRadius: theme.borderRadius(\n'
      '                        AstryxRadiusToken.element,\n'
      '                      ),\n'
      '                      border: Border.all(\n'
      '                        color: theme.color(\n'
      '                          palette == _picked\n'
      '                              ? AstryxColorToken.accent\n'
      '                              : palette.border,\n'
      '                        ),\n'
      '                        width:\n'
      '                            theme.borderWidth() * (palette == _picked ? 2 : 1),\n'
      '                      ),\n'
      '                    ),\n'
      '                  ),\n'
      '                ),\n'
      '              ),\n'
      '            );\n'
      '          },\n'
      '        ),\n'
      '        AstryxText(\n'
      '          _picked == null ? \'Nothing picked\' : \'Picked \${_picked!.name}\',\n'
      '          type: AstryxTextType.supporting,\n'
      '          color: AstryxTextColor.secondary,\n'
      '        ),\n'
      '      ],\n'
      '    );\n'
      '  }\n'
      '}\n',
  // examples/hooks_examples.dart
  'hook_clickable_container':
      'class HookClickableContainerExample extends StatefulWidget {\n'
      '  const HookClickableContainerExample({super.key});\n'
      '\n'
      '  @override\n'
      '  State<HookClickableContainerExample> createState() =>\n'
      '      _HookClickableContainerExampleState();\n'
      '}\n'
      '\n'
      'class _HookClickableContainerExampleState\n'
      '    extends State<HookClickableContainerExample> {\n'
      '  String _last = \'Nothing pressed\';\n'
      '\n'
      '  @override\n'
      '  Widget build(BuildContext context) {\n'
      '    // A non-null `onPressed` makes the whole card one button: hover, press, a\n'
      '    // focus ring, `Semantics(button: true)` and the tap-target guarantee. What\n'
      '    // it must *not* contain is another control — a button inside a button is a\n'
      '    // node a screen reader cannot describe and a keyboard cannot reach twice.\n'
      '    return AstryxVStack(\n'
      '      gap: AstryxSpacingToken.spacing3,\n'
      '      align: AstryxStackAlign.stretch,\n'
      '      children: <Widget>[\n'
      '        AstryxCard(\n'
      '          semanticsLabel: \'Atlas scheduler\',\n'
      '          onPressed: () => setState(() => _last = \'Opened Atlas scheduler\'),\n'
      '          child: const AstryxVStack(\n'
      '            gap: AstryxSpacingToken.spacing1,\n'
      '            children: <Widget>[\n'
      '              AstryxHeading(\n'
      '                \'Atlas scheduler\',\n'
      '                type: AstryxHeadingType.display3,\n'
      '              ),\n'
      '              AstryxText(\'Runs every fifteen minutes\'),\n'
      '            ],\n'
      '          ),\n'
      '        ),\n'
      '        AstryxList(\n'
      '          children: <Widget>[\n'
      '            AstryxItem(\n'
      '              label: \'Deploy log\',\n'
      '              description: \'The row is the control, not a link inside it\',\n'
      '              onPressed: () => setState(() => _last = \'Opened the deploy log\'),\n'
      '            ),\n'
      '          ],\n'
      '        ),\n'
      '        AstryxText(\n'
      '          _last,\n'
      '          type: AstryxTextType.supporting,\n'
      '          color: AstryxTextColor.secondary,\n'
      '        ),\n'
      '      ],\n'
      '    );\n'
      '  }\n'
      '}\n',
  // examples/hooks_examples.dart
  'hook_entry_animation':
      'class HookEntryAnimationExample extends StatefulWidget {\n'
      '  const HookEntryAnimationExample({super.key});\n'
      '\n'
      '  @override\n'
      '  State<HookEntryAnimationExample> createState() =>\n'
      '      _HookEntryAnimationExampleState();\n'
      '}\n'
      '\n'
      'class _HookEntryAnimationExampleState extends State<HookEntryAnimationExample> {\n'
      '  int _generation = 0;\n'
      '  AstryxEntryTransition _transition = AstryxEntryTransition.fadeUp;\n'
      '\n'
      '  @override\n'
      '  Widget build(BuildContext context) {\n'
      '    // It runs once per element. Replaying it is a *key* change, not a flag: a\n'
      '    // new key tells Flutter this is new content rather than the old content\n'
      '    // updated, which is the same thing the animation is trying to say.\n'
      '    return AstryxVStack(\n'
      '      gap: AstryxSpacingToken.spacing3,\n'
      '      align: AstryxStackAlign.stretch,\n'
      '      children: <Widget>[\n'
      '        AstryxHStack(\n'
      '          gap: AstryxSpacingToken.spacing2,\n'
      '          children: <Widget>[\n'
      '            AstryxSegmentedControl<AstryxEntryTransition>(\n'
      '              label: \'Transition\',\n'
      '              value: _transition,\n'
      '              segments: const <AstryxSegment<AstryxEntryTransition>>[\n'
      '                AstryxSegment(\n'
      '                  value: AstryxEntryTransition.fade,\n'
      '                  label: \'Fade\',\n'
      '                ),\n'
      '                AstryxSegment(\n'
      '                  value: AstryxEntryTransition.fadeUp,\n'
      '                  label: \'Up\',\n'
      '                ),\n'
      '                AstryxSegment(\n'
      '                  value: AstryxEntryTransition.fadeScale,\n'
      '                  label: \'Scale\',\n'
      '                ),\n'
      '              ],\n'
      '              onChanged: (value) => setState(() {\n'
      '                _transition = value;\n'
      '                _generation++;\n'
      '              }),\n'
      '            ),\n'
      '            AstryxButton(\n'
      '              label: \'Replay\',\n'
      '              onPressed: () => setState(() => _generation++),\n'
      '            ),\n'
      '          ],\n'
      '        ),\n'
      '        AstryxVStack(\n'
      '          gap: AstryxSpacingToken.spacing2,\n'
      '          align: AstryxStackAlign.stretch,\n'
      '          children: <Widget>[\n'
      '            for (var i = 0; i < 3; i++)\n'
      '              AstryxEntryAnimation(\n'
      '                key: ValueKey<String>(\'\$_generation.\$i\'),\n'
      '                transition: _transition,\n'
      '                // A stagger, kept short: one a user has to wait out has become\n'
      '                // a loading state.\n'
      '                delay: Duration(milliseconds: 60 * i),\n'
      '                child: AstryxCard(\n'
      '                  child: AstryxText(\'Row \${i + 1}\'),\n'
      '                ),\n'
      '              ),\n'
      '          ],\n'
      '        ),\n'
      '      ],\n'
      '    );\n'
      '  }\n'
      '}\n',
  // examples/hooks_examples.dart
  'hook_container_reveal':
      'class HookContainerRevealExample extends StatelessWidget {\n'
      '  const HookContainerRevealExample({super.key});\n'
      '\n'
      '  @override\n'
      '  Widget build(BuildContext context) {\n'
      '    // Scroll the panel. Each card is laid out from the start — so the scrollbar\n'
      '    // does not lie about the length — and painted as it comes into view.\n'
      '    return AstryxCard(\n'
      '      padding: AstryxSpacingToken.spacing0,\n'
      '      // Bounded inside the card: a card lays its body out in a column, and a\n'
      '      // column hands its child unbounded height — which a scroller reads as\n'
      '      // "no need to scroll".\n'
      '      child: SizedBox(\n'
      '        height: 220,\n'
      '        child: SingleChildScrollView(\n'
      '          padding: const EdgeInsets.all(12),\n'
      '          child: AstryxVStack(\n'
      '            gap: AstryxSpacingToken.spacing3,\n'
      '            align: AstryxStackAlign.stretch,\n'
      '            children: <Widget>[\n'
      '              for (var i = 1; i <= 8; i++)\n'
      '                AstryxContainerReveal(\n'
      '                  child: AstryxCard(\n'
      '                    child: AstryxHStack(\n'
      '                      gap: AstryxSpacingToken.spacing2,\n'
      '                      children: <Widget>[\n'
      '                        AstryxBadge(\'\$i\'),\n'
      '                        const AstryxText(\'Revealed on the way in\'),\n'
      '                      ],\n'
      '                    ),\n'
      '                  ),\n'
      '                ),\n'
      '            ],\n'
      '          ),\n'
      '        ),\n'
      '      ),\n'
      '    );\n'
      '  }\n'
      '}\n',
  // examples/hooks_examples.dart
  'hook_keyboard_hint':
      'class HookKeyboardHintExample extends StatelessWidget {\n'
      '  const HookKeyboardHintExample({super.key});\n'
      '\n'
      '  @override\n'
      '  Widget build(BuildContext context) {\n'
      '    // Press a key, then move the mouse: the hints follow the same last-input\n'
      '    // signal as the focus ring, so a hint and a ring never disagree about which\n'
      '    // mode the user is in. They keep their space either way.\n'
      '    return AstryxList(\n'
      '      children: <Widget>[\n'
      '        AstryxItem(\n'
      '          label: \'Command palette\',\n'
      '          onPressed: () {},\n'
      '          trailing: const AstryxKeyboardHint(\n'
      '            child: AstryxKbd.hotkey(\n'
      '              AstryxHotkey.mod(LogicalKeyboardKey.keyK),\n'
      '            ),\n'
      '          ),\n'
      '        ),\n'
      '        AstryxItem(\n'
      '          label: \'Save\',\n'
      '          onPressed: () {},\n'
      '          trailing: const AstryxKeyboardHint(\n'
      '            child: AstryxKbd.hotkey(\n'
      '              AstryxHotkey.mod(LogicalKeyboardKey.keyS),\n'
      '            ),\n'
      '          ),\n'
      '        ),\n'
      '        AstryxItem(\n'
      '          label: \'Deploy log\',\n'
      '          onPressed: () {},\n'
      '          // Nothing to hint, so the slot says something else on a pointer.\n'
      '          trailing: const AstryxKeyboardHint(\n'
      '            otherwise: AstryxText(\n'
      '              \'2 minutes ago\',\n'
      '              type: AstryxTextType.supporting,\n'
      '              color: AstryxTextColor.secondary,\n'
      '            ),\n'
      '            child: AstryxKbd.chord(<String>[\'G\', \'L\']),\n'
      '          ),\n'
      '        ),\n'
      '      ],\n'
      '    );\n'
      '  }\n'
      '}\n',
  // examples/hooks_examples.dart
  'hook_streaming_text':
      'class HookStreamingTextExample extends StatefulWidget {\n'
      '  const HookStreamingTextExample({super.key});\n'
      '\n'
      '  @override\n'
      '  State<HookStreamingTextExample> createState() =>\n'
      '      _HookStreamingTextExampleState();\n'
      '}\n'
      '\n'
      'class _HookStreamingTextExampleState extends State<HookStreamingTextExample> {\n'
      '  static const List<String> _chunks = <String>[\n'
      '    \'The deploy finished in 41 seconds. \',\n'
      '    \'Three services restarted, \',\n'
      '    \'and the health check passed on the first attempt.\',\n'
      '  ];\n'
      '\n'
      '  String _text = \'\';\n'
      '  int _next = 0;\n'
      '\n'
      '  bool get _streaming => _next < _chunks.length;\n'
      '\n'
      '  void _send() {\n'
      '    if (!_streaming) {\n'
      '      setState(() {\n'
      '        _text = \'\';\n'
      '        _next = 0;\n'
      '      });\n'
      '      return;\n'
      '    }\n'
      '    setState(() {\n'
      '      _text += _chunks[_next];\n'
      '      _next++;\n'
      '    });\n'
      '  }\n'
      '\n'
      '  @override\n'
      '  Widget build(BuildContext context) {\n'
      '    // Press "Send a chunk" a few times. Text arrives in bursts and is revealed\n'
      '    // at a steady rate, so it reads as typing rather than twitching — and the\n'
      '    // caret says more is coming.\n'
      '    return AstryxVStack(\n'
      '      gap: AstryxSpacingToken.spacing3,\n'
      '      align: AstryxStackAlign.stretch,\n'
      '      children: <Widget>[\n'
      '        AstryxCard(\n'
      '          child: _text.isEmpty\n'
      '              ? const AstryxText(\n'
      '                  \'Nothing yet\',\n'
      '                  color: AstryxTextColor.secondary,\n'
      '                )\n'
      '              : AstryxStreamingText(\n'
      '                  _text,\n'
      '                  streaming: _streaming,\n'
      '                  charactersPerSecond: 40,\n'
      '                ),\n'
      '        ),\n'
      '        AstryxButton(\n'
      '          label: _streaming ? \'Send a chunk\' : \'Start again\',\n'
      '          onPressed: _send,\n'
      '        ),\n'
      '      ],\n'
      '    );\n'
      '  }\n'
      '}\n',
  // examples/hooks_examples.dart
  'hook_image_mode':
      'class HookImageModeExample extends StatelessWidget {\n'
      '  const HookImageModeExample({super.key});\n'
      '\n'
      '  @override\n'
      '  Widget build(BuildContext context) {\n'
      '    final theme = AstryxTheme.of(context);\n'
      '    final dark = theme.mode == AstryxThemeMode.dark;\n'
      '\n'
      '    // One line, and it subscribes: switch the docs between light and dark and\n'
      '    // this swaps with it, with nothing else wired up. Stand-ins for two real\n'
      '    // assets — `Image.asset(dark ? \'logo_dark.png\' : \'logo_light.png\')`.\n'
      '    return AstryxVStack(\n'
      '      gap: AstryxSpacingToken.spacing3,\n'
      '      children: <Widget>[\n'
      '        Container(\n'
      '          width: 200,\n'
      '          height: 72,\n'
      '          alignment: Alignment.center,\n'
      '          decoration: BoxDecoration(\n'
      '            color: theme.color(\n'
      '              dark\n'
      '                  ? AstryxColorToken.backgroundInverted\n'
      '                  : AstryxColorToken.backgroundMuted,\n'
      '            ),\n'
      '            borderRadius: theme.borderRadius(AstryxRadiusToken.container),\n'
      '            border: Border.all(\n'
      '              color: theme.color(AstryxColorToken.border),\n'
      '              width: theme.borderWidth(),\n'
      '            ),\n'
      '          ),\n'
      '          child: AstryxText(\n'
      '            dark ? \'the dark lockup\' : \'the light lockup\',\n'
      '            color: AstryxTextColor.inherit,\n'
      '            style: TextStyle(\n'
      '              color: theme.color(\n'
      '                dark ? AstryxColorToken.onDark : AstryxColorToken.textPrimary,\n'
      '              ),\n'
      '            ),\n'
      '          ),\n'
      '        ),\n'
      '        const AstryxText(\n'
      '          \'Both variants take the same semantic label: they are the same \'\n'
      '          \'picture.\',\n'
      '          type: AstryxTextType.supporting,\n'
      '          color: AstryxTextColor.secondary,\n'
      '        ),\n'
      '      ],\n'
      '    );\n'
      '  }\n'
      '}\n',
  // examples/hooks_examples.dart
  'hook_translator':
      'class HookTranslatorExample extends StatelessWidget {\n'
      '  const HookTranslatorExample({super.key});\n'
      '\n'
      '  @override\n'
      '  Widget build(BuildContext context) {\n'
      '    // Getters and methods on a class, not keys in a map: a missing string is a\n'
      '    // compile error, and a method keeps word order in the translator\'s hands.\n'
      '    final l10n = AstryxLocalizations.of(context);\n'
      '\n'
      '    return AstryxVStack(\n'
      '      gap: AstryxSpacingToken.spacing3,\n'
      '      align: AstryxStackAlign.stretch,\n'
      '      children: <Widget>[\n'
      '        AstryxMetadataList(\n'
      '          items: <AstryxMetadataItem>[\n'
      '            AstryxMetadataItem.text(\n'
      '              label: \'fieldRequired\',\n'
      '              value: l10n.fieldRequired,\n'
      '            ),\n'
      '            AstryxMetadataItem.text(\n'
      '              label: \'clearField(…)\',\n'
      '              value: l10n.clearField(\'Email\'),\n'
      '            ),\n'
      '            AstryxMetadataItem.text(\n'
      '              label: \'paginationPage(…)\',\n'
      '              value: l10n.paginationPage(3, 20),\n'
      '            ),\n'
      '          ],\n'
      '        ),\n'
      '        const AstryxDivider(label: \'Overridden for the subtree below\'),\n'
      '        AstryxLocalizationsScope(\n'
      '          localizations: const TerseLocalizations(),\n'
      '          child: Builder(\n'
      '            builder: (context) {\n'
      '              final terse = AstryxLocalizations.of(context);\n'
      '\n'
      '              return AstryxMetadataList(\n'
      '                items: <AstryxMetadataItem>[\n'
      '                  AstryxMetadataItem.text(\n'
      '                    label: \'fieldRequired\',\n'
      '                    value: terse.fieldRequired,\n'
      '                  ),\n'
      '                  AstryxMetadataItem.text(\n'
      '                    label: \'clearField(…)\',\n'
      '                    value: terse.clearField(\'Email\'),\n'
      '                  ),\n'
      '                  AstryxMetadataItem.text(\n'
      '                    label: \'paginationPage(…)\',\n'
      '                    // Not overridden, so the English default still answers.\n'
      '                    value: terse.paginationPage(3, 20),\n'
      '                  ),\n'
      '                ],\n'
      '              );\n'
      '            },\n'
      '          ),\n'
      '        ),\n'
      '      ],\n'
      '    );\n'
      '  }\n'
      '}\n',
