  // examples/hover_card_examples.dart
  'hover_card_timing':
      'class HoverCardTimingExample extends StatelessWidget {\n'
      '  const HoverCardTimingExample({super.key});\n'
      '\n'
      '  @override\n'
      '  Widget build(BuildContext context) {\n'
      '    // The wait filters a mouse on its way somewhere else; the exit duration is\n'
      '    // the grace period for crossing the gap onto the card. Zero exit makes the\n'
      '    // card unreachable, which is why it is not the default.\n'
      '    return const AstryxHStack(\n'
      '      gap: AstryxSpacingToken.spacing5,\n'
      '      children: <Widget>[\n'
      '        AstryxHoverCard(\n'
      '          waitDuration: Duration.zero,\n'
      '          content: AstryxText(\'No wait at all.\'),\n'
      '          child: AstryxText(\'Instant\', color: AstryxTextColor.accent),\n'
      '        ),\n'
      '        AstryxHoverCard(\n'
      '          waitDuration: Duration(milliseconds: 700),\n'
      '          content: AstryxText(\'Opens only for a pointer that settles.\'),\n'
      '          child: AstryxText(\'Patient\', color: AstryxTextColor.accent),\n'
      '        ),\n'
      '      ],\n'
      '    );\n'
      '  }\n'
      '}\n',
