      '        for (final name in AstryxIconName.values)\n'
      '          AstryxHStack(\n'
      '            gap: AstryxSpacingToken.spacing2,\n'
      '            children: <Widget>[\n'
      '              AstryxIcon(name, size: AstryxIconSize.sm),\n'
      '              Flexible(\n'
      '                child: AstryxText(\n'
      '                  name.name,\n'
      '                  type: AstryxTextType.supporting,\n'
      '                  color: AstryxTextColor.secondary,\n'
      '                  maxLines: 1,\n'
