      '            AstryxIcon(AstryxIconName.clock),\n'
      '            AstryxText(\'Pending review\'),\n'
      '          ],\n'
      '        ),\n'
      '        // Meaningful on its own: it needs a name, because nothing else in the\n'
      '        // row says what it means.\n'
      '        AstryxIcon(\n'
      '          AstryxIconName.warning,\n'
