  // examples/icons_examples.dart
  'icons_registry_swap':
      'class IconsRegistrySwapExample extends StatelessWidget {\n'
      '  const IconsRegistrySwapExample({super.key});\n'
      '\n'
      '  /// Built from the defaults, so the 25 names not listed still resolve.\n'
      '  static final AstryxIconRegistry _custom = AstryxIconRegistry.defaults\n'
      '      .copyWith(const <AstryxIconName, IconData>{\n'
      '        AstryxIconName.close: LucideIcons.circleX,\n'
      '        AstryxIconName.check: LucideIcons.badgeCheck,\n'
      '        AstryxIconName.chevronRight: LucideIcons.arrowRight,\n'
      '      });\n'
      '\n'
      '  static const List<AstryxIconName> _shown = <AstryxIconName>[\n'
      '    AstryxIconName.close,\n'
      '    AstryxIconName.check,\n'
      '    AstryxIconName.chevronRight,\n'
      '  ];\n'
      '\n'
      '  @override\n'
      '  Widget build(BuildContext context) {\n'
      '    return AstryxGrid(\n'
      '      minWidth: 220,\n'
      '      gap: AstryxSpacingToken.spacing3,\n'
      '      children: <Widget>[\n'
      '        for (final (title, registry) in <(String, AstryxIconRegistry)>[\n'
      '          (\'AstryxIconRegistry.defaults\', AstryxIconRegistry.defaults),\n'
      '          (\'defaults.copyWith(…)\', _custom),\n'
      '        ])\n'
      '          // `AstryxTheme` rather than a nested provider: this swaps the\n'
      '          // registry and inherits everything else, so the theme and density\n'
      '          // pickers above still reach the icons below.\n'
      '          AstryxTheme(\n'
      '            data: AstryxTheme.of(context),\n'
      '            density: AstryxTheme.densityOf(context),\n'
      '            icons: registry,\n'
      '            child: AstryxCard(\n'
      '              padding: AstryxSpacingToken.spacing3,\n'
      '              child: AstryxVStack(\n'
      '                gap: AstryxSpacingToken.spacing3,\n'
      '                align: AstryxStackAlign.stretch,\n'
      '                children: <Widget>[\n'
      '                  AstryxText(\n'
      '                    title,\n'
      '                    type: AstryxTextType.code,\n'
      '                    color: AstryxTextColor.secondary,\n'
      '                    maxLines: 1,\n'
      '                  ),\n'
      '                  AstryxHStack(\n'
      '                    gap: AstryxSpacingToken.spacing4,\n'
      '                    children: <Widget>[\n'
      '                      for (final name in _shown)\n'
      '                        AstryxIcon(name, size: AstryxIconSize.lg),\n'
      '                    ],\n'
      '                  ),\n'
      '                ],\n'
      '              ),\n'
      '            ),\n'
      '          ),\n'
      '      ],\n'
      '    );\n'
      '  }\n'
      '}\n',
  // examples/icons_examples.dart
  'icons_mirroring':
      'class IconsMirroringExample extends StatelessWidget {\n'
      '  const IconsMirroringExample({super.key});\n'
      '\n'
      '  /// Two that mirror, and two that deliberately do not.\n'
      '  static const List<(AstryxIconName, String)> _cases =\n'
      '      <(AstryxIconName, String)>[\n'
      '        (AstryxIconName.chevronRight, \'mirrors\'),\n'
      '        (AstryxIconName.externalLink, \'mirrors\'),\n'
      '        (AstryxIconName.arrowUp, \'block axis — never flips\'),\n'
      '        (AstryxIconName.clock, \'an object — never flips\'),\n'
      '      ];\n'
      '\n'
      '  @override\n'
      '  Widget build(BuildContext context) {\n'
      '    return AstryxGrid(\n'
      '      minWidth: 190,\n'
      '      gap: AstryxSpacingToken.spacing3,\n'
      '      children: <Widget>[\n'
      '        for (final (name, note) in _cases)\n'
      '          AstryxCard(\n'
      '            padding: AstryxSpacingToken.spacing3,\n'
      '            child: AstryxVStack(\n'
      '              gap: AstryxSpacingToken.spacing2,\n'
      '              align: AstryxStackAlign.stretch,\n'
      '              children: <Widget>[\n'
      '                AstryxText(name.name, type: AstryxTextType.code, maxLines: 1),\n'
      '                AstryxHStack(\n'
      '                  gap: AstryxSpacingToken.spacing4,\n'
      '                  children: <Widget>[\n'
      '                    for (final direction in TextDirection.values)\n'
      '                      AstryxHStack(\n'
      '                        gap: AstryxSpacingToken.spacing1,\n'
      '                        children: <Widget>[\n'
      '                          AstryxText(\n'
      '                            direction.name,\n'
      '                            type: AstryxTextType.supporting,\n'
      '                            color: AstryxTextColor.secondary,\n'
      '                          ),\n'
      '                          Directionality(\n'
      '                            textDirection: direction,\n'
      '                            child: AstryxIcon(name),\n'
      '                          ),\n'
      '                        ],\n'
      '                      ),\n'
      '                  ],\n'
      '                ),\n'
      '                AstryxText(\n'
      '                  note,\n'
      '                  type: AstryxTextType.supporting,\n'
      '                  color: AstryxTextColor.secondary,\n'
      '                ),\n'
      '              ],\n'
      '            ),\n'
      '          ),\n'
      '      ],\n'
      '    );\n'
      '  }\n'
      '}\n',
