  // examples/item_examples.dart
  'item_states':
      'class ItemStatesExample extends StatefulWidget {\n'
      '  const ItemStatesExample({super.key});\n'
      '\n'
      '  @override\n'
      '  State<ItemStatesExample> createState() => _ItemStatesExampleState();\n'
      '}\n'
      '\n'
      'class _ItemStatesExampleState extends State<ItemStatesExample> {\n'
      '  String _selected = \'Alan Turing\';\n'
      '\n'
      '  @override\n'
      '  Widget build(BuildContext context) {\n'
      '    // A press and a selection are different things: the press state goes when\n'
      '    // the pointer leaves, the selection stays until something else is chosen.\n'
      '    return AstryxVStack(\n'
      '      gap: AstryxSpacingToken.spacing1,\n'
      '      align: AstryxStackAlign.stretch,\n'
      '      children: <Widget>[\n'
      '        for (final name in const <String>[\'Ada Lovelace\', \'Alan Turing\'])\n'
      '          AstryxItem(\n'
      '            label: name,\n'
      '            selected: _selected == name,\n'
      '            onPressed: () => setState(() => _selected = name),\n'
      '          ),\n'
      '        const AstryxItem(\n'
      '          label: \'Grace Hopper\',\n'
      '          description: \'Shown, but not yours to open\',\n'
      '        ),\n'
      '        AstryxItem(\n'
      '          label: \'Katherine Johnson\',\n'
      '          description: \'Unavailable\',\n'
      '          enabled: false,\n'
      '          onPressed: () {},\n'
      '        ),\n'
      '      ],\n'
      '    );\n'
      '  }\n'
      '}\n',
  // examples/layout_examples.dart
  'layout_page':
      'class LayoutPageExample extends StatelessWidget {\n'
      '  const LayoutPageExample({super.key});\n'
      '\n'
      '  @override\n'
      '  Widget build(BuildContext context) {\n'
      '    // A screen is a measure, a column of sections, and a grid inside one of\n'
      '    // them. There is no page widget to learn: the same four layout primitives\n'
      '    // that build a card build the page around it.\n'
      '    return AstryxCenter(\n'
      '      axis: AstryxCenterAxis.horizontal,\n'
      '      maxWidth: 760,\n'
      '      paddingBlock: AstryxSpacingToken.spacing6,\n'
      '      child: AstryxVStack(\n'
      '        gap: AstryxSpacingToken.spacing6,\n'
      '        align: AstryxStackAlign.stretch,\n'
      '        children: <Widget>[\n'
      '          AstryxHStack(\n'
      '            mainAxisSize: MainAxisSize.max,\n'
      '            justify: AstryxStackJustify.between,\n'
      '            gap: AstryxSpacingToken.spacing3,\n'
      '            children: <Widget>[\n'
      '              const Flexible(\n'
      '                child: AstryxHeading(\'Environments\', level: 1),\n'
      '              ),\n'
      '              AstryxButton(\n'
      '                label: \'New environment\',\n'
      '                variant: AstryxButtonVariant.primary,\n'
      '                onPressed: () {},\n'
      '              ),\n'
      '            ],\n'
      '          ),\n'
      '          const AstryxDivider(),\n'
      '          AstryxGrid(\n'
      '            minWidth: 200,\n'
      '            gap: AstryxSpacingToken.spacing3,\n'
      '            children: <Widget>[\n'
      '              for (final (name, status) in const <(String, String)>[\n'
      '                (\'production\', \'healthy\'),\n'
      '                (\'staging\', \'degraded\'),\n'
      '                (\'preview\', \'healthy\'),\n'
      '              ])\n'
      '                AstryxCard(\n'
      '                  child: AstryxVStack(\n'
      '                    gap: AstryxSpacingToken.spacing2,\n'
      '                    children: <Widget>[\n'
      '                      AstryxText(name, type: AstryxTextType.label),\n'
      '                      AstryxBadge(\n'
      '                        status,\n'
      '                        variant: status == \'healthy\'\n'
      '                            ? AstryxBadgeVariant.success\n'
      '                            : AstryxBadgeVariant.warning,\n'
      '                      ),\n'
      '                    ],\n'
      '                  ),\n'
      '                ),\n'
      '            ],\n'
      '          ),\n'
      '        ],\n'
      '      ),\n'
      '    );\n'
      '  }\n'
      '}\n',
