  // examples/list_examples.dart
  'list_density':
      'class ListDensityExample extends StatelessWidget {\n'
      '  const ListDensityExample({super.key});\n'
      '\n'
      '  @override\n'
      '  Widget build(BuildContext context) {\n'
      '    // The list sets the rhythm once; no row repeats it, and no row can\n'
      '    // disagree with its neighbours by accident.\n'
      '    return AstryxHStack(\n'
      '      gap: AstryxSpacingToken.spacing6,\n'
      '      align: AstryxStackAlign.start,\n'
      '      children: <Widget>[\n'
      '        for (final density in AstryxItemDensity.values)\n'
      '          Flexible(\n'
      '            child: AstryxList(\n'
      '              label: density.name,\n'
      '              density: density,\n'
      '              children: <Widget>[\n'
      '                for (final name in const <String>[\'Ada\', \'Alan\', \'Grace\'])\n'
      '                  AstryxItem(label: name),\n'
      '              ],\n'
      '            ),\n'
      '          ),\n'
      '      ],\n'
      '    );\n'
      '  }\n'
      '}\n',
  // examples/list_examples.dart
  'list_empty':
      'class ListEmptyExample extends StatefulWidget {\n'
      '  const ListEmptyExample({super.key});\n'
      '\n'
      '  @override\n'
      '  State<ListEmptyExample> createState() => _ListEmptyExampleState();\n'
      '}\n'
      '\n'
      'class _ListEmptyExampleState extends State<ListEmptyExample> {\n'
      '  final List<String> _keys = <String>[];\n'
      '\n'
      '  @override\n'
      '  Widget build(BuildContext context) {\n'
      '    // `empty` is the list\'s answer to having nothing to show. Without it a\n'
      '    // list with no rows renders nothing at all, which reads as a bug.\n'
      '    return AstryxList(\n'
      '      label: \'API keys\',\n'
      '      showDividers: true,\n'
      '      empty: AstryxEmptyState(\n'
      '        size: AstryxEmptyStateSize.compact,\n'
      '        icon: const AstryxIcon(AstryxIconName.search),\n'
      '        title: \'No API keys\',\n'
      '        description: \'Keys you create will be listed here.\',\n'
      '        actions: <Widget>[\n'
      '          AstryxButton(\n'
      '            label: \'Create a key\',\n'
      '            variant: AstryxButtonVariant.primary,\n'
      '            onPressed: () => setState(() => _keys.add(\'key_live_1\')),\n'
      '          ),\n'
      '        ],\n'
      '      ),\n'
      '      children: <Widget>[\n'
      '        for (final key in _keys)\n'
      '          AstryxItem(\n'
      '            label: key,\n'
      '            description: \'Created just now\',\n'
      '            trailing: AstryxButton(\n'
      '              label: \'Revoke\',\n'
      '              size: AstryxButtonSize.sm,\n'
      '              variant: AstryxButtonVariant.ghost,\n'
      '              onPressed: () => setState(() => _keys.remove(key)),\n'
      '            ),\n'
      '          ),\n'
      '      ],\n'
      '    );\n'
      '  }\n'
      '}\n',
