      'class _AvatarGroupDemoExampleState extends State<AvatarGroupDemoExample> {\n'
      '  bool _all = false;\n'
      '\n'
      '  @override\n'
      '  Widget build(BuildContext context) {\n'
      '    // "+3" is the only thing saying the row is a sample rather than the whole\n'
      '    // set, so it is pressable and the names behind it are reachable.\n'
      '    return AstryxVStack(\n'
      '      gap: AstryxSpacingToken.spacing3,\n'
      '      children: <Widget>[\n'
      '        AstryxAvatarGroup(\n'
      '          label: \'Reviewers\',\n'
      '          max: _all ? _people.length : 3,\n'
      '          onOverflowPressed: () => setState(() => _all = true),\n'
      '          avatars: <AstryxAvatar>[\n'
      '            for (final person in _people)\n'
      '              AstryxAvatar(\n'
      '                name: person.name,\n'
      '                status: person.status,\n'
      '                statusLabel: person.state,\n'
      '              ),\n'
      '          ],\n'
      '        ),\n'
      '        if (_all)\n'
      '          AstryxButton(\n'
      '            label: \'Collapse\',\n'
      '            variant: AstryxButtonVariant.ghost,\n'
      '            size: AstryxButtonSize.sm,\n'
      '            onPressed: () => setState(() => _all = false),\n'
      '          ),\n'
      '      ],\n'
      '    );\n'
      '  }\n'
