  // examples/media_examples.dart
  'aspect_ratio_demo':
      'class AspectRatioDemoExample extends StatelessWidget {\n'
      '  const AspectRatioDemoExample({super.key});\n'
      '\n'
      '  @override\n'
      '  Widget build(BuildContext context) {\n'
      '    // With nothing in it the box is a placeholder: the right shape in the\n'
      '    // right colour reads as the picture arriving, where a hole reads as a bug.\n'
      '    return AstryxGrid(\n'
      '      minWidth: 160,\n'
      '      gap: AstryxSpacingToken.spacing3,\n'
      '      children: <Widget>[\n'
      '        for (final entry in <({String label, double ratio})>[\n'
      '          (label: \'16 / 9\', ratio: 16 / 9),\n'
      '          (label: \'1\', ratio: 1),\n'
      '          (label: \'4 / 3\', ratio: 4 / 3),\n'
      '        ])\n'
      '          AstryxVStack(\n'
      '            gap: AstryxSpacingToken.spacing1,\n'
      '            align: AstryxStackAlign.stretch,\n'
      '            children: <Widget>[\n'
      '              AstryxAspectRatio(ratio: entry.ratio, showBorder: true),\n'
      '              AstryxText(\n'
      '                entry.label,\n'
      '                type: AstryxTextType.supporting,\n'
      '                color: AstryxTextColor.secondary,\n'
      '              ),\n'
      '            ],\n'
      '          ),\n'
      '      ],\n'
