  // examples/media_examples.dart
  'thumbnail_demo':
      'class ThumbnailDemoExample extends StatefulWidget {\n'
      '  const ThumbnailDemoExample({super.key});\n'
      '\n'
      '  @override\n'
      '  State<ThumbnailDemoExample> createState() => _ThumbnailDemoExampleState();\n'
      '}\n'
      '\n'
      'class _ThumbnailDemoExampleState extends State<ThumbnailDemoExample> {\n'
      '  static const List<({String label, AstryxIconName icon})> _files =\n'
      '      <({String label, AstryxIconName icon})>[\n'
      '        (label: \'atlas-scheduler.png\', icon: AstryxIconName.copy),\n'
      '        (label: \'deploy-log.txt\', icon: AstryxIconName.copy),\n'
      '        (label: \'metrics.csv\', icon: AstryxIconName.viewColumns),\n'
      '        (label: \'runbook.md\', icon: AstryxIconName.copy),\n'
      '      ];\n'
      '\n'
      '  int _selected = 0;\n'
      '\n'
      '  @override\n'
      '  Widget build(BuildContext context) {\n'
      '    // Nothing here can be previewed, so every tile falls back to a glyph and\n'
      '    // leans on its name — which is why the name is required.\n'
      '    return AstryxHStack(\n'
      '      gap: AstryxSpacingToken.spacing3,\n'
      '      wrap: true,\n'
      '      runGap: AstryxSpacingToken.spacing3,\n'
      '      align: AstryxStackAlign.start,\n'
      '      children: <Widget>[\n'
      '        for (var i = 0; i < _files.length; i++)\n'
      '          AstryxThumbnail(\n'
      '            label: _files[i].label,\n'
      '            icon: _files[i].icon,\n'
      '            showCaption: true,\n'
      '            selected: i == _selected,\n'
      '            onPressed: () => setState(() => _selected = i),\n'
      '          ),\n'
      '      ],\n'
      '    );\n'
      '  }\n'
      '}\n',
  // examples/media_examples.dart
  'carousel_demo':
