  // examples/media_examples.dart
  'lightbox_demo':
      'class LightboxDemoExample extends StatefulWidget {\n'
      '  const LightboxDemoExample({super.key});\n'
      '\n'
      '  @override\n'
      '  State<LightboxDemoExample> createState() => _LightboxDemoExampleState();\n'
      '}\n'
      '\n'
      'class _LightboxDemoExampleState extends State<LightboxDemoExample> {\n'
      '  final AstryxOverlayController _viewer = AstryxOverlayController();\n'
      '  int _opened = 0;\n'
      '\n'
      '  @override\n'
      '  void dispose() {\n'
      '    _viewer.dispose();\n'
      '    super.dispose();\n'
      '  }\n'
      '\n'
      '  void _open(int index) {\n'
      '    setState(() => _opened = index);\n'
      '    _viewer.show();\n'
      '  }\n'
      '\n'
      '  @override\n'
      '  Widget build(BuildContext context) {\n'
      '    final theme = AstryxTheme.of(context);\n'
      '\n'
      '    // Press a thumbnail. The viewer opens on *that* one, pages with the arrow\n'
      '    // keys, and closes on Escape.\n'
      '    return AstryxVStack(\n'
      '      gap: AstryxSpacingToken.spacing3,\n'
      '      children: <Widget>[\n'
      '        AstryxHStack(\n'
      '          gap: AstryxSpacingToken.spacing3,\n'
      '          children: <Widget>[\n'
      '            for (var i = 0; i < 3; i++)\n'
      '              AstryxThumbnail(\n'
      '                label: \'Screenshot \${i + 1}\',\n'
      '                width: 80,\n'
      '                onPressed: () => _open(i),\n'
      '              ),\n'
      '          ],\n'
      '        ),\n'
      '        AstryxLightbox(\n'
      '          controller: _viewer,\n'
      '          initialIndex: _opened,\n'
      '          items: <AstryxLightboxItem>[\n'
      '            for (var i = 1; i <= 3; i++)\n'
      '              AstryxLightboxItem(\n'
      '                label: \'Screenshot \$i\',\n'
      '                caption: \'Screenshot \$i — the deploy at 14:0\$i\',\n'
      '                child: SizedBox(\n'
      '                  width: 420,\n'
      '                  child: AstryxAspectRatio(\n'
      '                    ratio: 16 / 9,\n'
      '                    background: AstryxColorToken.backgroundCard,\n'
      '                    child: Center(\n'
      '                      child: AstryxText(\n'
      '                        \'Screenshot \$i\',\n'
      '                        color: AstryxTextColor.secondary,\n'
      '                      ),\n'
      '                    ),\n'
      '                  ),\n'
      '                ),\n'
      '              ),\n'
      '          ],\n'
      '        ),\n'
      '        AstryxText(\n'
      '          \'Opens on the thumbnail that was pressed — currently \'\n'
      '          \'\${_opened + 1}. Radius token: \'\n'
      '          \'\${theme.radius(AstryxRadiusToken.container)}px.\',\n'
      '          type: AstryxTextType.supporting,\n'
      '          color: AstryxTextColor.secondary,\n'
      '        ),\n'
      '      ],\n'
      '    );\n'
      '  }\n'
      '}\n',
  // examples/media_examples.dart
  'media_theme_demo':
      'class MediaThemeDemoExample extends StatelessWidget {\n'
      '  const MediaThemeDemoExample({super.key});\n'
      '\n'
      '  @override\n'
      '  Widget build(BuildContext context) {\n'
      '    final theme = AstryxTheme.of(context);\n'
      '\n'
      '    // A caption over a picture cannot use the page\'s text colour: the picture\n'
      '    // is whatever colour it is. `AstryxMediaTheme` forces the on-dark tokens\n'
      '    // and puts a scrim behind them.\n'
      '    return SizedBox(\n'
      '      height: 200,\n'
      '      child: ClipRRect(\n'
      '        borderRadius: theme.borderRadius(AstryxRadiusToken.container),\n'
      '        child: Stack(\n'
      '          fit: StackFit.expand,\n'
      '          children: <Widget>[\n'
      '            // Stands in for a photograph.\n'
      '            DecoratedBox(\n'
      '              decoration: BoxDecoration(\n'
      '                color: theme.color(AstryxColorToken.backgroundInverted),\n'
      '              ),\n'
      '            ),\n'
      '            Align(\n'
      '              alignment: Alignment.topCenter,\n'
      '              child: AstryxMediaTheme(\n'
      '                scrim: AstryxMediaScrim.top,\n'
      '                child: AstryxHStack(\n'
      '                  gap: AstryxSpacingToken.spacing2,\n'
      '                  mainAxisSize: MainAxisSize.max,\n'
      '                  justify: AstryxStackJustify.between,\n'
      '                  children: <Widget>[\n'
      '                    const AstryxText(\n'
      '                      \'2 of 8\',\n'
      '                      type: AstryxTextType.supporting,\n'
      '                      color: AstryxTextColor.inherit,\n'
      '                    ),\n'
      '                    AstryxIconButton(\n'
      '                      icon: AstryxIconName.close,\n'
      '                      label: \'Close\',\n'
      '                      variant: AstryxButtonVariant.ghost,\n'
      '                      onPressed: () {},\n'
      '                    ),\n'
      '                  ],\n'
      '                ),\n'
      '              ),\n'
      '            ),\n'
      '            const Align(\n'
      '              alignment: Alignment.bottomCenter,\n'
      '              child: AstryxMediaTheme(\n'
      '                child: AstryxVStack(\n'
      '                  gap: AstryxSpacingToken.spacing1,\n'
      '                  children: <Widget>[\n'
      '                    AstryxText(\n'
      '                      \'atlas-scheduler.png\',\n'
      '                      color: AstryxTextColor.inherit,\n'
      '                    ),\n'
      '                    AstryxText(\n'
      '                      \'Captured at 14:02, three seconds before the timeout\',\n'
      '                      type: AstryxTextType.supporting,\n'
      '                      color: AstryxTextColor.inherit,\n'
      '                    ),\n'
      '                  ],\n'
      '                ),\n'
      '              ),\n'
      '            ),\n'
      '          ],\n'
      '        ),\n'
      '      ),\n'
      '    );\n'
      '  }\n'
      '}\n',
