  'metadata_list_inline':
      'class MetadataListInlineExample extends StatelessWidget {\n'
      '  const MetadataListInlineExample({super.key});\n'
      '\n'
      '  @override\n'
      '  Widget build(BuildContext context) {\n'
      '    // Inline reads faster when the values are short and there are many of\n'
      '    // them; stacked survives a narrow column, which inline does not.\n'
      '    return const AstryxMetadataList(\n'
      '      direction: AstryxMetadataListDirection.inline,\n'
      '      labelWidth: 120,\n'
      '      items: <AstryxMetadataItem>[\n'
      '        AstryxMetadataItem(\n'
      '          label: \'Region\',\n'
      '          icon: AstryxIcon(AstryxIconName.info),\n'
      '          value: AstryxText(\'us-east-1\'),\n'
      '          semanticsValue: \'us-east-1\',\n'
      '        ),\n'
      '        AstryxMetadataItem(\n'
      '          label: \'Instance\',\n'
      '          value: AstryxText(\'c6g.2xlarge\'),\n'
      '          semanticsValue: \'c6g.2xlarge\',\n'
      '        ),\n'
      '        AstryxMetadataItem(\n'
      '          label: \'Uptime\',\n'
