  // examples/motion_examples.dart
  'motion_durations':
      'class MotionDurationsExample extends StatefulWidget {\n'
      '  const MotionDurationsExample({super.key});\n'
      '\n'
      '  @override\n'
      '  State<MotionDurationsExample> createState() => _MotionDurationsExampleState();\n'
      '}\n'
      '\n'
      'class _MotionDurationsExampleState extends State<MotionDurationsExample> {\n'
      '  /// The three bases. Each has a `-min` and a `-max` variant beside it.\n'
      '  static const List<AstryxDurationToken> _bases = <AstryxDurationToken>[\n'
      '    AstryxDurationToken.fast,\n'
      '    AstryxDurationToken.medium,\n'
      '    AstryxDurationToken.slow,\n'
      '  ];\n'
      '\n'
      '  bool _moved = false;\n'
      '\n'
      '  @override\n'
      '  Widget build(BuildContext context) {\n'
      '    final theme = AstryxTheme.of(context);\n'
      '\n'
      '    // Durations come from `AstryxMotion`, never from the theme directly: it is\n'
      '    // the layer that returns zero when the platform asks for reduced motion.\n'
      '    final motion = AstryxMotion.of(context);\n'
      '\n'
      '    return AstryxVStack(\n'
      '      gap: AstryxSpacingToken.spacing3,\n'
      '      align: AstryxStackAlign.stretch,\n'
      '      children: <Widget>[\n'
      '        for (final token in _bases)\n'
      '          AstryxVStack(\n'
      '            gap: AstryxSpacingToken.spacing1,\n'
      '            align: AstryxStackAlign.stretch,\n'
      '            children: <Widget>[\n'
      '              AstryxText(\n'
      '                \'\${token.name} · \${motion.duration(token).inMilliseconds}ms\',\n'
      '                type: AstryxTextType.code,\n'
      '              ),\n'
      '              DecoratedBox(\n'
      '                decoration: BoxDecoration(\n'
      '                  color: theme.color(AstryxColorToken.backgroundMuted),\n'
      '                  borderRadius: theme.borderRadius(AstryxRadiusToken.full),\n'
      '                ),\n'
      '                child: SizedBox(\n'
      '                  height: 28,\n'
      '                  child: AnimatedAlign(\n'
      '                    duration: motion.duration(token),\n'
      '                    curve: motion.curve(),\n'
      '                    alignment: _moved\n'
      '                        ? AlignmentDirectional.centerEnd\n'
      '                        : AlignmentDirectional.centerStart,\n'
      '                    child: Padding(\n'
      '                      padding: EdgeInsets.symmetric(\n'
      '                        horizontal: theme.spacing(AstryxSpacingToken.spacing1),\n'
      '                      ),\n'
      '                      child: DecoratedBox(\n'
      '                        decoration: BoxDecoration(\n'
      '                          color: theme.color(AstryxColorToken.accent),\n'
      '                          borderRadius: theme.borderRadius(\n'
      '                            AstryxRadiusToken.full,\n'
      '                          ),\n'
      '                        ),\n'
      '                        child: const SizedBox(width: 20, height: 20),\n'
      '                      ),\n'
      '                    ),\n'
      '                  ),\n'
      '                ),\n'
      '              ),\n'
      '            ],\n'
      '          ),\n'
      '        AstryxHStack(\n'
      '          gap: AstryxSpacingToken.spacing2,\n'
      '          children: <Widget>[\n'
      '            AstryxButton(\n'
      '              label: _moved ? \'Send back\' : \'Send across\',\n'
      '              onPressed: () => setState(() => _moved = !_moved),\n'
      '            ),\n'
      '          ],\n'
      '        ),\n'
      '      ],\n'
      '    );\n'
      '  }\n'
      '}\n',
  // examples/navigation_controls_examples.dart
  'link_demo':
      'class LinkDemoExample extends StatelessWidget {\n'
      '  const LinkDemoExample({super.key});\n'
      '\n'
      '  @override\n'
      '  Widget build(BuildContext context) {\n'
      '    // Flutter has no inline element, so `AstryxLink.span` is how one sits in a\n'
      '    // sentence. An external link says so in its accessible name as well as in\n'
      '    // its glyph: the user who cannot see the glyph is the one most disrupted\n'
      '    // by a window they did not expect.\n'
      '    return AstryxVStack(\n'
      '      gap: AstryxSpacingToken.spacing3,\n'
      '      children: <Widget>[\n'
      '        Text.rich(\n'
      '          TextSpan(\n'
      '            style: AstryxTheme.of(context).textStyle(AstryxTypeRole.body),\n'
      '            children: <InlineSpan>[\n'
      '              const TextSpan(text: \'Start with the \'),\n'
      '              AstryxLink.span(\'installation guide\', onPressed: () {}),\n'
      '              const TextSpan(text: \', then read about \'),\n'
      '              AstryxLink.span(\'theming\', onPressed: () {}),\n'
      '              const TextSpan(text: \'.\'),\n'
      '            ],\n'
      '          ),\n'
      '        ),\n'
      '        AstryxLink(\'The Flutter docs\', external: true, onPressed: () {}),\n'
      '        AstryxLink(\'Already read\', visited: true, onPressed: () {}),\n'
      '        const AstryxLink(\'Unavailable\', enabled: false),\n'
      '      ],\n'
      '    );\n'
      '  }\n'
      '}\n',
  // examples/navigation_controls_examples.dart
  'segmented_control_demo':
      'class SegmentedControlDemoExample extends StatefulWidget {\n'
      '  const SegmentedControlDemoExample({super.key});\n'
      '\n'
      '  @override\n'
      '  State<SegmentedControlDemoExample> createState() =>\n'
      '      _SegmentedControlDemoExampleState();\n'
      '}\n'
      '\n'
      'class _SegmentedControlDemoExampleState\n'
      '    extends State<SegmentedControlDemoExample> {\n'
      '  String _range = \'week\';\n'
      '  String _density = \'balanced\';\n'
      '\n'
      '  @override\n'
      '  Widget build(BuildContext context) {\n'
      '    // One tab stop; the arrows move *and* choose, and wrap at both ends. It\n'
      '    // announces itself as a radio group, which is what it is.\n'
      '    return AstryxVStack(\n'
      '      gap: AstryxSpacingToken.spacing4,\n'
      '      children: <Widget>[\n'
      '        AstryxSegmentedControl<String>(\n'
      '          label: \'Range\',\n'
      '          value: _range,\n'
      '          onChanged: (value) => setState(() => _range = value),\n'
      '          segments: const <AstryxSegment<String>>[\n'
      '            AstryxSegment(value: \'day\', label: \'Day\'),\n'
      '            AstryxSegment(value: \'week\', label: \'Week\'),\n'
      '            AstryxSegment(value: \'month\', label: \'Month\'),\n'
      '            AstryxSegment(value: \'year\', label: \'Year\', enabled: false),\n'
      '          ],\n'
      '        ),\n'
      '        AstryxSegmentedControl<String>(\n'
      '          label: \'Density\',\n'
      '          value: _density,\n'
      '          onChanged: (value) => setState(() => _density = value),\n'
      '          segments: const <AstryxSegment<String>>[\n'
      '            AstryxSegment(\n'
      '              value: \'compact\',\n'
      '              label: \'Compact\',\n'
      '              labelHidden: true,\n'
      '              icon: AstryxIcon(AstryxIconName.menu),\n'
      '            ),\n'
      '            AstryxSegment(\n'
      '              value: \'balanced\',\n'
      '              label: \'Balanced\',\n'
      '              labelHidden: true,\n'
      '              icon: AstryxIcon(AstryxIconName.viewColumns),\n'
      '            ),\n'
      '          ],\n'
      '        ),\n'
      '        AstryxText(\n'
      '          \'Showing \$_range, \$_density\',\n'
      '          type: AstryxTextType.supporting,\n'
      '          color: AstryxTextColor.secondary,\n'
      '        ),\n'
      '      ],\n'
      '    );\n'
      '  }\n'
      '}\n',
  // examples/navigation_controls_examples.dart
  'toolbar_demo':
      'class ToolbarDemoExample extends StatefulWidget {\n'
      '  const ToolbarDemoExample({super.key});\n'
      '\n'
      '  @override\n'
      '  State<ToolbarDemoExample> createState() => _ToolbarDemoExampleState();\n'
      '}\n'
      '\n'
      'class _ToolbarDemoExampleState extends State<ToolbarDemoExample> {\n'
      '  final Set<String> _marks = <String>{\'bold\'};\n'
      '\n'
      '  @override\n'
      '  Widget build(BuildContext context) {\n'
      '    // Tab reaches the band once and leaves it once, however many controls sit\n'
      '    // between; the arrows move inside it. A formatting bar of twelve buttons\n'
      '    // is twelve presses to walk past otherwise.\n'
      '    return AstryxCard(\n'
      '      padding: AstryxSpacingToken.spacing1,\n'
      '      child: AstryxToolbar(\n'
      '        label: \'Formatting\',\n'
      '        children: <Widget>[\n'
      '          for (final mark in const <List<String>>[\n'
      '            <String>[\'bold\', \'Bold\'],\n'
      '            <String>[\'italic\', \'Italic\'],\n'
      '            <String>[\'code\', \'Code\'],\n'
      '          ])\n'
      '            AstryxToggleButton(\n'
      '              label: mark[1],\n'
      '              pressed: _marks.contains(mark[0]),\n'
      '              size: AstryxButtonSize.sm,\n'
      '              onChanged: (on) => setState(() {\n'
      '                on ? _marks.add(mark[0]) : _marks.remove(mark[0]);\n'
      '              }),\n'
      '            ),\n'
      '          const AstryxToolbarDivider(),\n'
      '          AstryxMoreMenu(\n'
      '            label: \'More formatting\',\n'
      '            entries: <AstryxMenuEntry>[\n'
      '              AstryxMenuItem(label: \'Strikethrough\', onSelected: () {}),\n'
      '              AstryxMenuItem(label: \'Superscript\', onSelected: () {}),\n'
      '              const AstryxMenuDivider(),\n'
      '              AstryxMenuItem(\n'
      '                label: \'Clear formatting\',\n'
      '                destructive: true,\n'
      '                onSelected: () => setState(_marks.clear),\n'
      '              ),\n'
      '            ],\n'
      '          ),\n'
      '        ],\n'
      '      ),\n'
      '    );\n'
      '  }\n'
      '}\n',
  // examples/navigation_controls_examples.dart
  'tab_menu_demo':
      'class TabMenuDemoExample extends StatefulWidget {\n'
      '  const TabMenuDemoExample({super.key});\n'
      '\n'
      '  @override\n'
      '  State<TabMenuDemoExample> createState() => _TabMenuDemoExampleState();\n'
      '}\n'
      '\n'
      'class _TabMenuDemoExampleState extends State<TabMenuDemoExample> {\n'
      '  String _view = \'overview\';\n'
      '\n'
      '  static const Set<String> _reports = <String>{\'usage\', \'billing\'};\n'
      '\n'
      '  @override\n'
      '  Widget build(BuildContext context) {\n'
      '    // Most tabs are views; this one is a *set* of them. It is drawn as a tab so\n'
      '    // it reads as one, and announced as a menu button so nobody is told it is\n'
      '    // a tab and then handed a menu.\n'
      '    return AstryxVStack(\n'
      '      gap: AstryxSpacingToken.spacing3,\n'
      '      children: <Widget>[\n'
      '        AstryxHStack(\n'
      '          children: <Widget>[\n'
      '            AstryxTabList<String>(\n'
      '              label: \'Views\',\n'
      '              value: _reports.contains(_view) ? null : _view,\n'
      '              onChanged: (value) => setState(() => _view = value),\n'
      '              tabs: const <AstryxTab<String>>[\n'
      '                AstryxTab(value: \'overview\', label: \'Overview\'),\n'
      '                AstryxTab(value: \'activity\', label: \'Activity\'),\n'
      '              ],\n'
      '            ),\n'
      '            AstryxTabMenu(\n'
      '              label: \'Reports\',\n'
      '              selected: _reports.contains(_view),\n'
      '              entries: <AstryxMenuEntry>[\n'
      '                for (final report in _reports)\n'
      '                  AstryxMenuItem(\n'
      '                    label: report,\n'
      '                    onSelected: () => setState(() => _view = report),\n'
      '                  ),\n'
      '              ],\n'
      '            ),\n'
      '          ],\n'
      '        ),\n'
      '        AstryxText(\'Showing \$_view\'),\n'
      '      ],\n'
      '    );\n'
      '  }\n'
      '}\n',
  // examples/navigation_controls_examples.dart
  'pagination_demo':
      'class PaginationDemoExample extends StatefulWidget {\n'
      '  const PaginationDemoExample({super.key});\n'
      '\n'
      '  @override\n'
      '  State<PaginationDemoExample> createState() => _PaginationDemoExampleState();\n'
      '}\n'
      '\n'
      'class _PaginationDemoExampleState extends State<PaginationDemoExample> {\n'
      '  int _page = 1;\n'
      '\n'
      '  @override\n'
      '  Widget build(BuildContext context) {\n'
      '    // Pages are one-based, as they are to the person reading them. The ends\n'
      '    // are always shown, the middle gaps, and the arrows disable rather than\n'
      '    // disappear — a control that vanishes moves everything beside it.\n'
      '    return AstryxVStack(\n'
      '      gap: AstryxSpacingToken.spacing3,\n'
      '      children: <Widget>[\n'
      '        AstryxPagination(\n'
      '          page: _page,\n'
      '          pageCount: 20,\n'
      '          onPageChanged: (page) => setState(() => _page = page),\n'
      '        ),\n'
      '        AstryxText(\n'
      '          \'Page \$_page of 20\',\n'
      '          type: AstryxTextType.supporting,\n'
      '          color: AstryxTextColor.secondary,\n'
      '        ),\n'
      '      ],\n'
      '    );\n'
      '  }\n'
      '}\n',
  // examples/navigation_examples.dart
  'side_nav_demo':
      'class SideNavDemoExample extends StatefulWidget {\n'
      '  const SideNavDemoExample({super.key});\n'
      '\n'
      '  @override\n'
      '  State<SideNavDemoExample> createState() => _SideNavDemoExampleState();\n'
      '}\n'
      '\n'
      'class _SideNavDemoExampleState extends State<SideNavDemoExample> {\n'
      '  String _section = \'deploys\';\n'
      '  bool _collapsed = false;\n'
      '\n'
      '  @override\n'
      '  Widget build(BuildContext context) {\n'
      '    // Collapse it and the labels leave the screen but not the semantics tree:\n'
      '    // each row keeps its name and gains a tooltip that shows on focus as well\n'
      '    // as hover, so a keyboard user gets what a mouse user gets.\n'
      '    return SizedBox(\n'
      '      height: 420,\n'
      '      child: Row(\n'
      '        crossAxisAlignment: CrossAxisAlignment.stretch,\n'
      '        children: <Widget>[\n'
      '          SizedBox(\n'
      '            width: _collapsed ? 64 : 240,\n'
      '            child: AstryxSideNav(\n'
      '              label: \'Sections\',\n'
      '              entries: _entries,\n'
      '              selectedId: _section,\n'
      '              onSelected: (id) => setState(() => _section = id),\n'
      '              collapsed: _collapsed,\n'
      '              onCollapsedChanged: (value) => setState(() => _collapsed = value),\n'
      '              header: AstryxNavHeadingMenu(\n'
      '                label: \'Acme Corp\',\n'
      '                description: \'Production\',\n'
      '                collapsed: _collapsed,\n'
      '                leading: const AstryxNavIcon(\n'
      '                  AstryxIcon(AstryxIconName.viewColumns),\n'
      '                ),\n'
      '                entries: <AstryxMenuEntry>[\n'
      '                  AstryxMenuItem(label: \'Acme Corp\', onSelected: () {}),\n'
      '                  AstryxMenuItem(label: \'Globex\', onSelected: () {}),\n'
      '                  const AstryxMenuDivider(),\n'
      '                  AstryxMenuItem(label: \'New workspace\', onSelected: () {}),\n'
      '                ],\n'
      '              ),\n'
      '            ),\n'
      '          ),\n'
      '          const AstryxDivider(axis: Axis.vertical),\n'
      '          Expanded(\n'
      '            child: AstryxCenter(child: AstryxHeading(_section)),\n'
      '          ),\n'
      '        ],\n'
      '      ),\n'
      '    );\n'
      '  }\n'
      '}\n',
  // examples/navigation_examples.dart
  'top_nav_demo':
      'class TopNavDemoExample extends StatefulWidget {\n'
      '  const TopNavDemoExample({super.key});\n'
      '\n'
      '  @override\n'
      '  State<TopNavDemoExample> createState() => _TopNavDemoExampleState();\n'
      '}\n'
      '\n'
      'class _TopNavDemoExampleState extends State<TopNavDemoExample> {\n'
      '  String _section = \'deploys\';\n'
      '\n'
      '  @override\n'
      '  Widget build(BuildContext context) {\n'
      '    // The same entries as the rail, laid along a row. A section becomes a menu\n'
      '    // — a bar has no room for a heading over a group, but a menu is exactly\n'
      '    // what holds one — and an item with a `panel` opens the mega menu.\n'
      '    return AstryxVStack(\n'
      '      gap: AstryxSpacingToken.spacing0,\n'
      '      align: AstryxStackAlign.stretch,\n'
      '      children: <Widget>[\n'
      '        AstryxTopNav(\n'
      '          leading: const AstryxText(\'Acme\', type: AstryxTextType.label),\n'
      '          entries: <AstryxNavEntry>[\n'
      '            ..._entries,\n'
      '            AstryxNavItem(\n'
      '              id: \'docs\',\n'
      '              label: \'Docs\',\n'
      '              panel: AstryxCard(\n'
      '                child: AstryxVStack(\n'
      '                  gap: AstryxSpacingToken.spacing2,\n'
      '                  align: AstryxStackAlign.stretch,\n'
      '                  children: <Widget>[\n'
      '                    const AstryxHeading(\'Guides\', level: 3),\n'
      '                    AstryxItem(label: \'Getting started\', onPressed: () {}),\n'
      '                    AstryxItem(label: \'Theming\', onPressed: () {}),\n'
      '                  ],\n'
      '                ),\n'
      '              ),\n'
      '            ),\n'
      '          ],\n'
      '          selectedId: _section,\n'
      '          onSelected: (id) => setState(() => _section = id),\n'
      '          actions: <Widget>[\n'
      '            AstryxIconButton(\n'
      '              icon: AstryxIconName.search,\n'
      '              label: \'Search\',\n'
      '              variant: AstryxButtonVariant.ghost,\n'
      '              size: AstryxButtonSize.sm,\n'
      '              onPressed: () {},\n'
      '            ),\n'
      '            AstryxButton(\n'
      '              label: \'Account\',\n'
      '              size: AstryxButtonSize.sm,\n'
      '              onPressed: () {},\n'
      '            ),\n'
      '          ],\n'
      '        ),\n'
      '        const AstryxDivider(),\n'
      '        Padding(\n'
      '          padding: const EdgeInsets.all(16),\n'
      '          child: AstryxText(\'Showing \$_section\'),\n'
      '        ),\n'
      '      ],\n'
      '    );\n'
      '  }\n'
      '}\n',
  // examples/navigation_examples.dart
  'mobile_nav_demo':
      'class MobileNavDemoExample extends StatefulWidget {\n'
      '  const MobileNavDemoExample({super.key});\n'
      '\n'
      '  @override\n'
      '  State<MobileNavDemoExample> createState() => _MobileNavDemoExampleState();\n'
      '}\n'
      '\n'
      'class _MobileNavDemoExampleState extends State<MobileNavDemoExample> {\n'
      '  final AstryxOverlayController _nav = AstryxOverlayController();\n'
      '  String _section = \'deploys\';\n'
      '\n'
      '  @override\n'
      '  void dispose() {\n'
      '    _nav.dispose();\n'
      '    super.dispose();\n'
      '  }\n'
      '\n'
      '  @override\n'
      '  Widget build(BuildContext context) {\n'
      '    // The drawer is a real overlay: it traps focus, closes on Escape or a\n'
      '    // press on the scrim, and hands focus back to the button that opened it.\n'
      '    // Closing it after a choice is the caller\'s, which is why `onSelected`\n'
      '    // hides it here.\n'
      '    return SizedBox(\n'
      '      height: 260,\n'
      '      child: AstryxVStack(\n'
      '        gap: AstryxSpacingToken.spacing3,\n'
      '        align: AstryxStackAlign.stretch,\n'
      '        children: <Widget>[\n'
      '          AstryxHStack(\n'
      '            gap: AstryxSpacingToken.spacing2,\n'
      '            children: <Widget>[\n'
      '              AstryxMobileNavToggle(\n'
      '                controller: _nav,\n'
      '                size: AstryxButtonSize.sm,\n'
      '              ),\n'
      '              AstryxText(\'Showing \$_section\'),\n'
      '            ],\n'
      '          ),\n'
      '          AstryxMobileNav(\n'
      '            controller: _nav,\n'
      '            entries: _entries,\n'
      '            selectedId: _section,\n'
      '            onSelected: (id) {\n'
      '              setState(() => _section = id);\n'
      '              _nav.hide();\n'
      '            },\n'
      '          ),\n'
      '        ],\n'
      '      ),\n'
      '    );\n'
      '  }\n'
      '}\n',
  // examples/navigation_examples.dart
  'breadcrumbs_demo':
      'class BreadcrumbsDemoExample extends StatelessWidget {\n'
      '  const BreadcrumbsDemoExample({super.key});\n'
      '\n'
      '  @override\n'
      '  Widget build(BuildContext context) {\n'
      '    final trail = <AstryxBreadcrumb>[\n'
      '      AstryxBreadcrumb(label: \'Projects\', onPressed: () {}),\n'
      '      AstryxBreadcrumb(label: \'astryx_ui\', onPressed: () {}),\n'
      '      AstryxBreadcrumb(label: \'Environments\', onPressed: () {}),\n'
      '      AstryxBreadcrumb(label: \'production\', onPressed: () {}),\n'
      '      const AstryxBreadcrumb(label: \'Deploy #412\'),\n'
      '    ];\n'
      '\n'
      '    // The same trail at three widths. It collapses in the middle, never at the\n'
      '    // ends: the first step is the way out to the top and the last is where the\n'
      '    // reader is.\n'
      '    return AstryxVStack(\n'
      '      gap: AstryxSpacingToken.spacing4,\n'
      '      children: <Widget>[\n'
      '        for (final width in const <double>[560, 380, 240])\n'
      '          AstryxVStack(\n'
      '            gap: AstryxSpacingToken.spacing1,\n'
      '            children: <Widget>[\n'
      '              AstryxText(\n'
      '                \'\${width.toInt()} px\',\n'
      '                type: AstryxTextType.supporting,\n'
      '                color: AstryxTextColor.secondary,\n'
      '              ),\n'
      '              SizedBox(\n'
      '                width: width,\n'
      '                child: AstryxBreadcrumbs(items: trail),\n'
      '              ),\n'
      '            ],\n'
      '          ),\n'
      '      ],\n'
      '    );\n'
      '  }\n'
      '}\n',
  // examples/overflow_list_examples.dart
  'overflow_list_demo':
      'class OverflowListDemoExample extends StatefulWidget {\n'
      '  const OverflowListDemoExample({super.key});\n'
      '\n'
      '  @override\n'
      '  State<OverflowListDemoExample> createState() =>\n'
      '      _OverflowListDemoExampleState();\n'
      '}\n'
      '\n'
      'class _OverflowListDemoExampleState extends State<OverflowListDemoExample> {\n'
      '  static const List<String> _tags = <String>[\n'
      '    \'billing\',\n'
      '    \'infra\',\n'
      '    \'urgent\',\n'
      '    \'customer-reported\',\n'
      '    \'regression\',\n'
      '    \'needs-repro\',\n'
      '  ];\n'
      '\n'
      '  String? _chosen;\n'
      '\n'
      '  @override\n'
      '  Widget build(BuildContext context) {\n'
      '    // Narrow the window and the tail moves into the menu; widen it and the\n'
      '    // items come back. Nothing is ever unreachable — what does not fit is a\n'
      '    // real menu row, not a clipped one.\n'
      '    return AstryxVStack(\n'
      '      gap: AstryxSpacingToken.spacing3,\n'
      '      align: AstryxStackAlign.stretch,\n'
      '      children: <Widget>[\n'
      '        AstryxOverflowList(\n'
      '          menuLabel: \'More tags\',\n'
      '          items: <AstryxOverflowItem>[\n'
      '            for (final tag in _tags)\n'
      '              AstryxOverflowItem(\n'
      '                label: tag,\n'
      '                onSelected: () => setState(() => _chosen = tag),\n'
      '                child: AstryxBadge(tag),\n'
      '              ),\n'
      '          ],\n'
      '        ),\n'
      '        AstryxText(\n'
      '          _chosen == null ? \'Nothing chosen yet\' : \'Chose \$_chosen\',\n'
      '          type: AstryxTextType.supporting,\n'
      '          color: AstryxTextColor.secondary,\n'
      '        ),\n'
      '      ],\n'
      '    );\n'
      '  }\n'
      '}\n',
