  // examples/popover_examples.dart
  'popover_controlled':
      'class PopoverControlledExample extends StatefulWidget {\n'
      '  const PopoverControlledExample({super.key});\n'
      '\n'
      '  @override\n'
      '  State<PopoverControlledExample> createState() =>\n'
      '      _PopoverControlledExampleState();\n'
      '}\n'
      '\n'
      'class _PopoverControlledExampleState extends State<PopoverControlledExample> {\n'
      '  final AstryxOverlayController _controller = AstryxOverlayController();\n'
      '  bool _open = false;\n'
      '\n'
      '  @override\n'
      '  void initState() {\n'
      '    super.initState();\n'
      '    _controller.addListener(() => setState(() => _open = _controller.isOpen));\n'
      '  }\n'
      '\n'
      '  @override\n'
      '  void dispose() {\n'
      '    _controller.dispose();\n'
      '    super.dispose();\n'
      '  }\n'
      '\n'
      '  @override\n'
      '  Widget build(BuildContext context) {\n'
      '    // Passing a controller makes the popover *controlled*: the open state lives\n'
      '    // wherever the application already keeps state, and anything can drive it.\n'
      '    return AstryxHStack(\n'
      '      gap: AstryxSpacingToken.spacing3,\n'
      '      children: <Widget>[\n'
      '        AstryxPopover(\n'
      '          controller: _controller,\n'
      '          label: \'Details\',\n'
      '          width: 220,\n'
      '          content: const AstryxText(\'Focus is trapped in here.\'),\n'
      '          triggerBuilder: (context, controller) =>\n'
      '              AstryxButton(label: \'Details\', onPressed: controller.toggle),\n'
      '        ),\n'
      '        AstryxButton(\n'
      '          label: _open ? \'Close from outside\' : \'Open from outside\',\n'
      '          variant: AstryxButtonVariant.ghost,\n'
      '          onPressed: _controller.toggle,\n'
      '        ),\n'
      '      ],\n'
      '    );\n'
      '  }\n'
      '}\n',
