  // examples/progress_bar_examples.dart
  'progress_live':
      'class ProgressLiveExample extends StatefulWidget {\n'
      '  const ProgressLiveExample({super.key});\n'
      '\n'
      '  @override\n'
      '  State<ProgressLiveExample> createState() => _ProgressLiveExampleState();\n'
      '}\n'
      '\n'
      'class _ProgressLiveExampleState extends State<ProgressLiveExample> {\n'
      '  double _value = 0.15;\n'
      '  Timer? _ticker;\n'
      '\n'
      '  @override\n'
      '  void dispose() {\n'
      '    _ticker?.cancel();\n'
      '    super.dispose();\n'
      '  }\n'
      '\n'
      '  void _run() {\n'
      '    _ticker?.cancel();\n'
      '    setState(() => _value = 0);\n'
      '    _ticker = Timer.periodic(const Duration(milliseconds: 320), (timer) {\n'
      '      if (!mounted) return timer.cancel();\n'
      '      setState(() => _value = (_value + 0.12).clamp(0.0, 1.0));\n'
      '      if (_value >= 1) timer.cancel();\n'
      '    });\n'
      '  }\n'
      '\n'
      '  @override\n'
      '  Widget build(BuildContext context) {\n'
      '    return SizedBox(\n'
      '      width: 320,\n'
      '      child: AstryxVStack(\n'
      '        gap: AstryxSpacingToken.spacing3,\n'
      '        align: AstryxStackAlign.stretch,\n'
      '        children: <Widget>[\n'
      '          AstryxProgressBar(\n'
      '            label: \'Importing 240 rows\',\n'
      '            value: _value,\n'
      '            showValueLabel: true,\n'
      '            variant: _value >= 1\n'
      '                ? AstryxProgressVariant.success\n'
      '                : AstryxProgressVariant.accent,\n'
      '          ),\n'
      '          AstryxButton(\n'
      '            label: _value >= 1 ? \'Run again\' : \'Run\',\n'
      '            size: AstryxButtonSize.sm,\n'
      '            onPressed: _run,\n'
      '          ),\n'
      '        ],\n'
      '      ),\n'
      '    );\n'
      '  }\n'
      '}\n',
  // examples/provider_examples.dart
  'provider_theme':
      'class ProviderThemeExample extends StatefulWidget {\n'
      '  const ProviderThemeExample({super.key});\n'
      '\n'
      '  @override\n'
      '  State<ProviderThemeExample> createState() => _ProviderThemeExampleState();\n'
      '}\n'
      '\n'
      'class _ProviderThemeExampleState extends State<ProviderThemeExample> {\n'
      '  AstryxDefinedTheme _theme = butterTheme;\n'
      '  AstryxColorMode _mode = AstryxColorMode.light;\n'
      '\n'
      '  @override\n'
      '  Widget build(BuildContext context) {\n'
      '    // A provider can be nested: this one re-themes its own subtree and leaves\n'
      '    // the page around it alone. Everything below it — including any overlay it\n'
      '    // opens — resolves the theme installed here.\n'
      '    return AstryxVStack(\n'
      '      gap: AstryxSpacingToken.spacing3,\n'
      '      align: AstryxStackAlign.stretch,\n'
      '      children: <Widget>[\n'
      '        AstryxHStack(\n'
      '          gap: AstryxSpacingToken.spacing2,\n'
      '          children: <Widget>[\n'
      '            AstryxSegmentedControl<AstryxDefinedTheme>(\n'
      '              label: \'Theme\',\n'
      '              value: _theme,\n'
      '              segments: <AstryxSegment<AstryxDefinedTheme>>[\n'
      '                AstryxSegment(value: butterTheme, label: \'Butter\'),\n'
      '                AstryxSegment(value: matchaTheme, label: \'Matcha\'),\n'
      '                AstryxSegment(value: gothicTheme, label: \'Gothic\'),\n'
      '              ],\n'
      '              onChanged: (theme) => setState(() => _theme = theme),\n'
      '            ),\n'
      '            AstryxSegmentedControl<AstryxColorMode>(\n'
      '              label: \'Mode\',\n'
      '              value: _mode,\n'
      '              segments: const <AstryxSegment<AstryxColorMode>>[\n'
      '                AstryxSegment(value: AstryxColorMode.light, label: \'Light\'),\n'
      '                AstryxSegment(value: AstryxColorMode.dark, label: \'Dark\'),\n'
      '              ],\n'
      '              onChanged: (mode) => setState(() => _mode = mode),\n'
      '            ),\n'
      '          ],\n'
      '        ),\n'
      '        AstryxThemeProvider(\n'
      '          theme: _theme,\n'
      '          mode: _mode,\n'
      '          child: AstryxCard(\n'
      '            child: AstryxVStack(\n'
      '              gap: AstryxSpacingToken.spacing3,\n'
      '              children: <Widget>[\n'
      '                const AstryxHeading(\n'
      '                  \'Inside the provider\',\n'
      '                  type: AstryxHeadingType.display3,\n'
      '                ),\n'
      '                const AstryxText(\n'
      '                  \'Colour, radius, type and motion all come from the theme \'\n'
      '                  \'installed here — no widget below reads a raw value.\',\n'
      '                ),\n'
      '                AstryxHStack(\n'
      '                  gap: AstryxSpacingToken.spacing2,\n'
      '                  children: <Widget>[\n'
      '                    AstryxButton(label: \'Primary\', onPressed: () {}),\n'
      '                    const AstryxBadge(\'Badge\'),\n'
      '                  ],\n'
      '                ),\n'
      '              ],\n'
      '            ),\n'
      '          ),\n'
      '        ),\n'
      '      ],\n'
      '    );\n'
      '  }\n'
      '}\n',
