  // examples/provider_examples.dart
  'provider_link':
      'class ProviderLinkExample extends StatefulWidget {\n'
      '  const ProviderLinkExample({super.key});\n'
      '\n'
      '  @override\n'
      '  State<ProviderLinkExample> createState() => _ProviderLinkExampleState();\n'
      '}\n'
      '\n'
      'class _ProviderLinkExampleState extends State<ProviderLinkExample> {\n'
      '  Uri? _followed;\n'
      '\n'
      '  @override\n'
      '  Widget build(BuildContext context) {\n'
      '    // The delegate stands in for your router. This one records where a link\n'
      '    // wanted to go; a real one would call `GoRouter.of(context).go(...)` or\n'
      '    // `launchUrl`. The package never decides what following means.\n'
      '    return AstryxLinkScope(\n'
      '      delegate: AstryxLinkDelegate.fromCallback((uri, {target}) {\n'
      '        setState(() => _followed = uri);\n'
      '      }),\n'
      '      child: AstryxVStack(\n'
      '        gap: AstryxSpacingToken.spacing2,\n'
      '        children: <Widget>[\n'
      '          AstryxLink(\'Billing settings\', href: Uri.parse(\'/settings/billing\')),\n'
      '          AstryxLink(\n'
      '            \'Status page\',\n'
      '            href: Uri.parse(\'https://status.example.com\'),\n'
      '            external: true,\n'
      '          ),\n'
      '          AstryxText(\n'
      '            _followed == null\n'
      '                ? \'Nothing followed yet\'\n'
      '                : \'The delegate was handed \$_followed\',\n'
      '            type: AstryxTextType.supporting,\n'
      '            color: AstryxTextColor.secondary,\n'
      '          ),\n'
      '        ],\n'
      '      ),\n'
      '    );\n'
      '  }\n'
      '}\n',
  // examples/provider_examples.dart
  'provider_localizations':
      'class ProviderLocalizationsExample extends StatefulWidget {\n'
      '  const ProviderLocalizationsExample({super.key});\n'
      '\n'
      '  @override\n'
      '  State<ProviderLocalizationsExample> createState() =>\n'
      '      _ProviderLocalizationsExampleState();\n'
      '}\n'
      '\n'
      'class _ProviderLocalizationsExampleState\n'
      '    extends State<ProviderLocalizationsExample> {\n'
      '  bool _rtl = false;\n'
      '  DateTime? _day;\n'
      '\n'
      '  @override\n'
      '  Widget build(BuildContext context) {\n'
      '    // Two halves, and they are independent. The strings come from a\n'
      '    // localisations subclass; the direction comes from `Directionality`, which\n'
      '    // is Flutter\'s own and needs nothing from this package.\n'
      '    return AstryxVStack(\n'
      '      gap: AstryxSpacingToken.spacing3,\n'
      '      align: AstryxStackAlign.stretch,\n'
      '      children: <Widget>[\n'
      '        AstryxSwitch(\n'
      '          label: \'Right to left\',\n'
      '          value: _rtl,\n'
      '          onChanged: (value) => setState(() => _rtl = value),\n'
      '        ),\n'
      '        AstryxLocalizationsScope(\n'
      '          localizations: const FrenchLocalizations(),\n'
      '          child: Directionality(\n'
      '            textDirection: _rtl ? TextDirection.rtl : TextDirection.ltr,\n'
      '            child: AstryxCard(\n'
      '              child: AstryxCalendar(\n'
      '                selected: _day,\n'
      '                today: DateTime(2026, 8, 4),\n'
      '                onChanged: (day) => setState(() => _day = day),\n'
      '              ),\n'
      '            ),\n'
      '          ),\n'
      '        ),\n'
      '      ],\n'
      '    );\n'
      '  }\n'
      '}\n',
  // examples/provider_examples.dart
  'provider_syntax':
      'class ProviderSyntaxExample extends StatelessWidget {\n'
      '  const ProviderSyntaxExample({super.key});\n'
      '\n'
      '  @override\n'
      '  Widget build(BuildContext context) {\n'
      '    final theme = AstryxTheme.of(context);\n'
      '    final palette = theme.syntaxPalette;\n'
      '\n'
      '    // The palette a theme carries, read back as `Color`s. Nothing in the\n'
      '    // package paints with them — this is the seam for a highlighter you wire\n'
      '    // yourself, so its colours come from the theme rather than from a list of\n'
      '    // hex values beside it.\n'
      '    if (palette.isEmpty) {\n'
      '      return const AstryxEmptyState(\n'
      '        title: \'This theme carries no syntax palette\',\n'
      '        description: \'The prebuilt themes all do.\',\n'
      '      );\n'
      '    }\n'
      '\n'
      '    return AstryxVStack(\n'
      '      gap: AstryxSpacingToken.spacing3,\n'
      '      align: AstryxStackAlign.stretch,\n'
      '      children: <Widget>[\n'
      '        AstryxGrid(\n'
      '          minWidth: 140,\n'
      '          gap: AstryxSpacingToken.spacing2,\n'
      '          children: <Widget>[\n'
      '            for (final entry in palette.entries)\n'
      '              AstryxHStack(\n'
      '                gap: AstryxSpacingToken.spacing2,\n'
      '                children: <Widget>[\n'
      '                  Container(\n'
      '                    width: 16,\n'
      '                    height: 16,\n'
      '                    decoration: BoxDecoration(\n'
      '                      color: entry.value,\n'
      '                      borderRadius: theme.borderRadius(\n'
      '                        AstryxRadiusToken.inner,\n'
      '                      ),\n'
      '                    ),\n'
      '                  ),\n'
      '                  Flexible(\n'
      '                    child: AstryxText(\n'
      '                      entry.key.key,\n'
      '                      type: AstryxTextType.supporting,\n'
      '                      maxLines: 1,\n'
      '                    ),\n'
      '                  ),\n'
      '                ],\n'
      '              ),\n'
      '          ],\n'
      '        ),\n'
      '        const AstryxCodeBlock(\n'
      '          \'\'\'\n'
      'Color? keyword(BuildContext context) =>\n'
      '    AstryxTheme.of(context).syntaxColor(AstryxSyntaxToken.keyword);\'\'\',\n'
      '          language: \'dart\',\n'
      '        ),\n'
      '      ],\n'
      '    );\n'
      '  }\n'
      '}\n',
  // examples/radio_list_examples.dart
  'radio_list_demo':
      'class RadioListDemoExample extends StatefulWidget {\n'
