  // examples/search_examples.dart
  'typeahead_demo':
      'class TypeaheadDemoExample extends StatefulWidget {\n'
      '  const TypeaheadDemoExample({super.key});\n'
      '\n'
      '  @override\n'
      '  State<TypeaheadDemoExample> createState() => _TypeaheadDemoExampleState();\n'
      '}\n'
      '\n'
      'class _TypeaheadDemoExampleState extends State<TypeaheadDemoExample> {\n'
      '  final TextEditingController _query = TextEditingController();\n'
      '  String? _picked;\n'
      '\n'
      '  @override\n'
      '  void dispose() {\n'
      '    _query.dispose();\n'
      '    super.dispose();\n'
      '  }\n'
      '\n'
      '  @override\n'
      '  Widget build(BuildContext context) {\n'
      '    // Type "a". The field keeps focus while the arrows move a highlighted row,\n'
      '    // so typing, correcting and choosing are one gesture.\n'
      '    return AstryxVStack(\n'
      '      gap: AstryxSpacingToken.spacing3,\n'
      '      align: AstryxStackAlign.stretch,\n'
      '      children: <Widget>[\n'
      '        AstryxTypeahead<String>(\n'
      '          label: \'Project\',\n'
      '          description: \'Arrow keys move; Enter chooses; Escape closes.\',\n'
      '          controller: _query,\n'
      '          onSelected: (name) => setState(() => _picked = name),\n'
      '          source: (text) async {\n'
      '            // A real source is a request. This one is a list and a small delay,\n'
      '            // so the spinner and the debounce are visible.\n'
      '            await Future<void>.delayed(const Duration(milliseconds: 180));\n'
      '            return <AstryxTypeaheadItem<String>>[\n'
      '              for (final project in _projects)\n'
      '                if (project.name.toLowerCase().contains(text.toLowerCase()))\n'
      '                  AstryxTypeaheadItem(\n'
      '                    value: project.name,\n'
      '                    label: project.name,\n'
      '                    description: \'\${project.kind} · \${project.owner}\',\n'
      '                  ),\n'
      '            ];\n'
      '          },\n'
      '        ),\n'
      '        AstryxText(\n'
      '          _picked == null ? \'Nothing chosen\' : \'Chose \$_picked\',\n'
      '          type: AstryxTextType.supporting,\n'
      '          color: AstryxTextColor.secondary,\n'
      '        ),\n'
      '      ],\n'
      '    );\n'
      '  }\n'
      '}\n',
  // examples/search_examples.dart
  'base_typeahead_demo':
      'class BaseTypeaheadDemoExample extends StatefulWidget {\n'
      '  const BaseTypeaheadDemoExample({super.key});\n'
      '\n'
      '  @override\n'
      '  State<BaseTypeaheadDemoExample> createState() =>\n'
      '      _BaseTypeaheadDemoExampleState();\n'
      '}\n'
      '\n'
      'class _BaseTypeaheadDemoExampleState extends State<BaseTypeaheadDemoExample> {\n'
      '  final TextEditingController _query = TextEditingController();\n'
      '\n'
      '  @override\n'
      '  void dispose() {\n'
      '    _query.dispose();\n'
      '    super.dispose();\n'
      '  }\n'
      '\n'
      '  @override\n'
      '  Widget build(BuildContext context) {\n'
      '    final theme = AstryxTheme.of(context);\n'
      '\n'
      '    // The engine with a field and rows of the caller\'s own: a token chip per\n'
      '    // suggestion rather than a list row, which the styled one cannot draw.\n'
      '    return AstryxBaseTypeahead<String>(\n'
      '      controller: _query,\n'
      '      minQueryLength: 0,\n'
      '      openOnFocus: true,\n'
      '      onSelected: (owner) => _query.clear(),\n'
      '      source: (text) async => <String>[\n'
      '        for (final owner in <String>{\n'
      '          for (final project in _projects) project.owner,\n'
      '        })\n'
      '          if (owner.contains(text.toLowerCase())) owner,\n'
      '      ],\n'
      '      headerBuilder: (context, state) => Padding(\n'
      '        padding: EdgeInsets.all(theme.spacing(AstryxSpacingToken.spacing2)),\n'
      '        child: AstryxText(\n'
      '          state.suggestions.isEmpty ? \'No owners\' : \'Owners\',\n'
      '          type: AstryxTextType.supporting,\n'
      '          color: AstryxTextColor.secondary,\n'
      '        ),\n'
      '      ),\n'
      '      fieldBuilder: (context, state) => AstryxTextInput(\n'
      '        label: \'Owner\',\n'
      '        controller: state.controller,\n'
      '        focusNode: state.focusNode,\n'
      '        placeholder: \'Focus me\',\n'
      '        leading: const AstryxIcon(\n'
      '          AstryxIconName.search,\n'
      '          size: AstryxIconSize.sm,\n'
      '          color: AstryxIconColor.secondary,\n'
      '        ),\n'
      '      ),\n'
      '      itemBuilder: (context, owner, state) {\n'
      '        final active = state.isActive(state.suggestions.indexOf(owner));\n'
      '\n'
      '        return Padding(\n'
      '          padding: EdgeInsets.all(theme.spacing(AstryxSpacingToken.spacing1)),\n'
      '          child: AstryxFocusRing(\n'
      '            focused: active,\n'
      '            borderRadius: theme.borderRadius(AstryxRadiusToken.full),\n'
      '            child: AstryxTokenChip(owner, onPressed: () => state.select(owner)),\n'
      '          ),\n'
      '        );\n'
      '      },\n'
      '    );\n'
      '  }\n'
      '}\n',
  // examples/search_examples.dart
  'command_palette_demo':
      'class CommandPaletteDemoExample extends StatefulWidget {\n'
      '  const CommandPaletteDemoExample({super.key});\n'
      '\n'
      '  @override\n'
      '  State<CommandPaletteDemoExample> createState() =>\n'
      '      _CommandPaletteDemoExampleState();\n'
      '}\n'
      '\n'
      'class _CommandPaletteDemoExampleState extends State<CommandPaletteDemoExample> {\n'
      '  static const AstryxHotkey _open = AstryxHotkey.mod(LogicalKeyboardKey.keyK);\n'
      '\n'
      '  final AstryxOverlayController _palette = AstryxOverlayController();\n'
      '  String _last = \'Nothing run yet\';\n'
      '\n'
      '  @override\n'
      '  void dispose() {\n'
      '    _palette.dispose();\n'
      '    super.dispose();\n'
      '  }\n'
      '\n'
      '  void _run(String what) => setState(() => _last = what);\n'
      '\n'
      '  @override\n'
      '  Widget build(BuildContext context) {\n'
      '    // Press the button, or ⌘K / Ctrl+K. The shortcut on each row is drawn from\n'
      '    // the hotkey that is bound, so the palette cannot teach a stale chord.\n'
      '    return AstryxHotkeys(\n'
      '      autofocus: true,\n'
      '      bindings: <AstryxHotkey, VoidCallback>{_open: _palette.show},\n'
      '      child: AstryxVStack(\n'
      '        gap: AstryxSpacingToken.spacing3,\n'
      '        align: AstryxStackAlign.stretch,\n'
      '        children: <Widget>[\n'
      '          AstryxHStack(\n'
      '            gap: AstryxSpacingToken.spacing2,\n'
      '            children: <Widget>[\n'
      '              AstryxButton(\n'
      '                label: \'Open the palette\',\n'
      '                trailing: const AstryxKbd.hotkey(_open),\n'
      '                onPressed: _palette.show,\n'
      '              ),\n'
      '            ],\n'
      '          ),\n'
      '          AstryxText(\n'
      '            _last,\n'
      '            type: AstryxTextType.supporting,\n'
      '            color: AstryxTextColor.secondary,\n'
      '          ),\n'
      '          AstryxCommandPalette(\n'
      '            controller: _palette,\n'
      '            groups: <AstryxCommandGroup>[\n'
      '              AstryxCommandGroup(\n'
      '                label: \'Navigate\',\n'
      '                items: <AstryxCommandItem>[\n'
      '                  AstryxCommandItem(\n'
      '                    label: \'Go to deploys\',\n'
      '                    icon: AstryxIconName.arrowUp,\n'
      '                    hotkey: const AstryxHotkey.mod(LogicalKeyboardKey.keyD),\n'
      '                    onSelected: () => _run(\'Went to deploys\'),\n'
      '                  ),\n'
      '                  AstryxCommandItem(\n'
      '                    label: \'Go to settings\',\n'
      '                    icon: AstryxIconName.wrench,\n'
      '                    keywords: const <String>[\'preferences\', \'config\'],\n'
      '                    onSelected: () => _run(\'Went to settings\'),\n'
      '                  ),\n'
      '                ],\n'
      '              ),\n'
      '              AstryxCommandGroup(\n'
      '                label: \'Deploy\',\n'
      '                items: <AstryxCommandItem>[\n'
      '                  AstryxCommandItem(\n'
      '                    label: \'Roll back the last deploy\',\n'
      '                    icon: AstryxIconName.arrowDown,\n'
      '                    description: \'Reverts to 13:41\',\n'
      '                    onSelected: () => _run(\'Rolled back\'),\n'
      '                  ),\n'
      '                  const AstryxCommandItem(\n'
      '                    label: \'Promote to production\',\n'
      '                    enabled: false,\n'
      '                    description: \'Needs an approval first\',\n'
      '                    onSelected: _noop,\n'
      '                  ),\n'
      '                ],\n'
      '              ),\n'
      '            ],\n'
      '          ),\n'
      '        ],\n'
      '      ),\n'
      '    );\n'
      '  }\n'
      '\n'
      '  static void _noop() {}\n'
      '}\n',
  // examples/search_examples.dart
  'power_search_demo':
      'class PowerSearchDemoExample extends StatefulWidget {\n'
      '  const PowerSearchDemoExample({super.key});\n'
      '\n'
      '  @override\n'
      '  State<PowerSearchDemoExample> createState() => _PowerSearchDemoExampleState();\n'
      '}\n'
      '\n'
      'class _PowerSearchDemoExampleState extends State<PowerSearchDemoExample> {\n'
      '  AstryxSearchQuery _query = const AstryxSearchQuery();\n'
      '\n'
      '  Iterable<({String name, String kind, String owner})> get _results =>\n'
      '      _projects.where((project) {\n'
      '        final text = _query.text.trim().toLowerCase();\n'
      '        if (text.isNotEmpty && !project.name.toLowerCase().contains(text)) {\n'
      '          return false;\n'
      '        }\n'
      '        return _query.filters.every((filter) => switch (filter.field) {\n'
      '          \'kind\' => project.kind == filter.value,\n'
      '          \'owner\' => project.owner == filter.value,\n'
      '          _ => true,\n'
      '        });\n'
      '      });\n'
      '\n'
      '  @override\n'
      '  Widget build(BuildContext context) {\n'
      '    // Filters are chips beside the text, not syntax inside it: nothing to\n'
      '    // learn, nothing to mistype, and no error message to write.\n'
      '    return AstryxVStack(\n'
      '      gap: AstryxSpacingToken.spacing3,\n'
      '      align: AstryxStackAlign.stretch,\n'
      '      children: <Widget>[\n'
      '        AstryxPowerSearch(\n'
      '          query: _query,\n'
      '          options: const <AstryxSearchFilterOption>[\n'
      '            AstryxSearchFilterOption(\n'
      '              field: \'kind\',\n'
      '              label: \'Kind\',\n'
      '              values: <String>[\'Service\', \'Job\', \'Doc\'],\n'
      '            ),\n'
      '            AstryxSearchFilterOption(\n'
      '              field: \'owner\',\n'
      '              label: \'Owner\',\n'
      '              values: <String>[\'ada\', \'grace\', \'linus\'],\n'
      '            ),\n'
      '          ],\n'
      '          onChanged: (query) => setState(() => _query = query),\n'
      '        ),\n'
      '        AstryxList(\n'
      '          children: <Widget>[\n'
      '            for (final project in _results)\n'
      '              AstryxItem(\n'
      '                label: project.name,\n'
      '                description: \'\${project.kind} · \${project.owner}\',\n'
      '              ),\n'
      '          ],\n'
      '        ),\n'
      '        if (_results.isEmpty)\n'
      '          const AstryxEmptyState(\n'
      '            title: \'Nothing matches\',\n'
      '            description: \'Remove a filter, or search for something else.\',\n'
      '          ),\n'
      '      ],\n'
      '    );\n'
      '  }\n'
      '}\n',
