  'section_nesting':
      'class SectionNestingExample extends StatelessWidget {\n'
      '  const SectionNestingExample({super.key});\n'
      '\n'
      '  @override\n'
      '  Widget build(BuildContext context) {\n'
      '    // No section here is told its level. A page assembled from parts nobody\n'
      '    // wrote together still produces an outline a screen reader can navigate —\n'
      '    // which is the fault this exists to prevent, and one nobody can see by\n'
      '    // looking at the screen.\n'
      '    return const AstryxSection(\n'
      '      title: \'Environments\',\n'
      '      child: AstryxSection(\n'
      '        title: \'Production\',\n'
      '        description: \'Heading level 3, without being told.\',\n'
      '        child: AstryxSection(\n'
      '          title: \'Regions\',\n'
      '          description: \'And 4 here.\',\n'
      '          child: AstryxText(\'us-east-1, eu-central-1\'),\n'
      '        ),\n'
      '      ),\n'
      '    );\n'
      '  }\n'
      '}\n',
