  // examples/section_examples.dart
  'outline_demo':
      'class OutlineDemoExample extends StatefulWidget {\n'
      '  const OutlineDemoExample({super.key});\n'
      '\n'
      '  @override\n'
      '  State<OutlineDemoExample> createState() => _OutlineDemoExampleState();\n'
      '}\n'
      '\n'
      'class _OutlineDemoExampleState extends State<OutlineDemoExample> {\n'
      '  final ScrollController _scroll = ScrollController();\n'
      '  final Map<String, GlobalKey> _anchors = <String, GlobalKey>{\n'
      '    \'setup\': GlobalKey(),\n'
      '    \'usage\': GlobalKey(),\n'
      '    \'tokens\': GlobalKey(),\n'
      '  };\n'
      '\n'
      '  @override\n'
      '  void dispose() {\n'
      '    _scroll.dispose();\n'
      '    super.dispose();\n'
      '  }\n'
      '\n'
      '  @override\n'
      '  Widget build(BuildContext context) {\n'
      '    // Scroll the page, and the outline follows: what it tracks is where the\n'
      '    // headings are, not what the scroll offset says.\n'
      '    return SizedBox(\n'
      '      height: 260,\n'
      '      child: Row(\n'
      '        crossAxisAlignment: CrossAxisAlignment.stretch,\n'
      '        children: <Widget>[\n'
      '          Expanded(\n'
      '            child: SingleChildScrollView(\n'
      '              controller: _scroll,\n'
      '              child: AstryxVStack(\n'
      '                gap: AstryxSpacingToken.spacing4,\n'
      '                align: AstryxStackAlign.stretch,\n'
      '                children: <Widget>[\n'
      '                  for (final section in const <List<String>>[\n'
      '                    <String>[\'setup\', \'Setup\'],\n'
      '                    <String>[\'usage\', \'Usage\'],\n'
      '                    <String>[\'tokens\', \'Tokens\'],\n'
      '                  ])\n'
      '                    AstryxSection(\n'
      '                      title: section[1],\n'
      '                      headerKey: _anchors[section[0]],\n'
      '                      child: const AstryxText(\n'
      '                        \'Enough copy to push the next heading past the top of \'\n'
      '                        \'the viewport, which is the event the outline is \'\n'
      '                        \'listening for.\\n\\n\'\n'
      '                        \'Scroll on, and the entry beside this one takes the \'\n'
      '                        \'accent rule.\',\n'
      '                      ),\n'
      '                    ),\n'
      '                ],\n'
      '              ),\n'
      '            ),\n'
      '          ),\n'
