  // examples/selectable_card_examples.dart
  'selectable_card_demo':
      'class SelectableCardDemoExample extends StatefulWidget {\n'
      '  const SelectableCardDemoExample({super.key});\n'
      '\n'
      '  @override\n'
      '  State<SelectableCardDemoExample> createState() =>\n'
      '      _SelectableCardDemoExampleState();\n'
      '}\n'
      '\n'
      'class _SelectableCardDemoExampleState extends State<SelectableCardDemoExample> {\n'
      '  String _plan = \'pro\';\n'
      '\n'
      '  @override\n'
      '  Widget build(BuildContext context) {\n'
      '    // One choice out of three, where each option carries a price and a line of\n'
      '    // detail — more than a radio row can hold, which is the whole reason to\n'
      '    // reach for a card here.\n'
      '    return AstryxVStack(\n'
      '      gap: AstryxSpacingToken.spacing3,\n'
      '      align: AstryxStackAlign.stretch,\n'
      '      children: <Widget>[\n'
      '        for (final plan in const <List<String>>[\n'
      '          <String>[\'starter\', \'Starter\', r\'\$0\', \'One project, one seat\'],\n'
      '          <String>[\'pro\', \'Pro\', r\'\$20\', \'Unlimited projects, five seats\'],\n'
      '          <String>[\'scale\', \'Scale\', r\'\$80\', \'Unlimited seats, SSO, audit log\'],\n'
      '        ])\n'
      '          AstryxSelectableCard(\n'
      '            label: \'\${plan[1]} plan\',\n'
      '            semanticsHint: \'\${plan[2]} per month. \${plan[3]}\',\n'
      '            control: AstryxSelectableCardControl.radio,\n'
      '            selected: _plan == plan[0],\n'
      '            onSelectedChanged: (_) => setState(() => _plan = plan[0]),\n'
      '            child: AstryxVStack(\n'
      '              gap: AstryxSpacingToken.spacing1,\n'
      '              align: AstryxStackAlign.stretch,\n'
      '              children: <Widget>[\n'
      '                AstryxHStack(\n'
      '                  justify: AstryxStackJustify.between,\n'
      '                  mainAxisSize: MainAxisSize.max,\n'
      '                  children: <Widget>[\n'
      '                    Flexible(\n'
      '                      child: AstryxText(plan[1], type: AstryxTextType.large),\n'
      '                    ),\n'
      '                    AstryxText(\'\${plan[2]}/mo\'),\n'
      '                  ],\n'
      '                ),\n'
      '                AstryxText(\n'
      '                  plan[3],\n'
      '                  type: AstryxTextType.supporting,\n'
      '                  color: AstryxTextColor.secondary,\n'
      '                ),\n'
      '              ],\n'
      '            ),\n'
      '          ),\n'
      '      ],\n'
      '    );\n'
      '  }\n'
      '}\n',
  // examples/selectable_card_examples.dart
  'selectable_card_controls':
      'class SelectableCardControlsExample extends StatefulWidget {\n'
      '  const SelectableCardControlsExample({super.key});\n'
      '\n'
      '  @override\n'
      '  State<SelectableCardControlsExample> createState() =>\n'
      '      _SelectableCardControlsExampleState();\n'
      '}\n'
      '\n'
      'class _SelectableCardControlsExampleState\n'
      '    extends State<SelectableCardControlsExample> {\n'
      '  final Set<String> _regions = <String>{\'iad\'};\n'
      '\n'
      '  @override\n'
      '  Widget build(BuildContext context) {\n'
      '    // A checkbox card is an independent choice, so any number of these can be\n'
      '    // on at once — the same distinction as `AstryxCheckbox` against\n'
      '    // `AstryxRadioList`, moved onto a card.\n'
      '    return AstryxGrid(\n'
      '      minWidth: 200,\n'
      '      gap: AstryxSpacingToken.spacing3,\n'
      '      children: <Widget>[\n'
      '        for (final region in const <List<String>>[\n'
      '          <String>[\'iad\', \'us-east\', \'12 ms\'],\n'
      '          <String>[\'fra\', \'eu-central\', \'86 ms\'],\n'
      '          <String>[\'bom\', \'ap-south\', \'148 ms\'],\n'
      '        ])\n'
      '          AstryxSelectableCard(\n'
      '            label: \'\${region[1]} region\',\n'
      '            selected: _regions.contains(region[0]),\n'
      '            onSelectedChanged: (selected) => setState(() {\n'
      '              if (selected) {\n'
      '                _regions.add(region[0]);\n'
      '              } else {\n'
      '                _regions.remove(region[0]);\n'
      '              }\n'
      '            }),\n'
      '            child: AstryxVStack(\n'
      '              gap: AstryxSpacingToken.spacing1,\n'
      '              align: AstryxStackAlign.stretch,\n'
      '              children: <Widget>[\n'
      '                AstryxText(region[1]),\n'
      '                AstryxText(\n'
      '                  \'\${region[2]} from here\',\n'
      '                  type: AstryxTextType.supporting,\n'
      '                  color: AstryxTextColor.secondary,\n'
      '                ),\n'
      '              ],\n'
      '            ),\n'
      '          ),\n'
      '      ],\n'
      '    );\n'
      '  }\n'
      '}\n',
  // examples/selectable_card_examples.dart
  'selectable_card_states':
      'class SelectableCardStatesExample extends StatelessWidget {\n'
      '  const SelectableCardStatesExample({super.key});\n'
      '\n'
      '  @override\n'
      '  Widget build(BuildContext context) {\n'
      '    // The three ways a card stops being an ordinary control, side by side. Note\n'
      '    // that the last two still fill the box: a card the user cannot change is\n'
      '    // still visibly the selected one, even though the accent border and the\n'
      '    // tint — which read as an affordance — are gone.\n'
      '    return AstryxVStack(\n'
      '      gap: AstryxSpacingToken.spacing3,\n'
      '      align: AstryxStackAlign.stretch,\n'
      '      children: <Widget>[\n'
      '        AstryxSelectableCard(\n'
      '          label: \'Selected\',\n'
      '          selected: true,\n'
      '          onSelectedChanged: (_) {},\n'
      '          child: const AstryxText(\'Selected, and yours to change\'),\n'
      '        ),\n'
      '        const AstryxSelectableCard(\n'
      '          label: \'Shown elsewhere\',\n'
      '          selected: true,\n'
      '          child: AstryxText(\'A null callback: inert, but not dimmed\'),\n'
      '        ),\n'
      '        AstryxSelectableCard(\n'
      '          label: \'Unavailable\',\n'
      '          selected: true,\n'
      '          enabled: false,\n'
      '          onSelectedChanged: (_) {},\n'
      '          child: const AstryxText(\'Disabled: dimmed, and skipped by Tab\'),\n'
      '        ),\n'
      '      ],\n'
      '    );\n'
      '  }\n'
      '}\n',
  // examples/selectable_card_examples.dart
  'selectable_card_compact':
      'class SelectableCardCompactExample extends StatefulWidget {\n'
      '  const SelectableCardCompactExample({super.key});\n'
      '\n'
      '  @override\n'
      '  State<SelectableCardCompactExample> createState() =>\n'
      '      _SelectableCardCompactExampleState();\n'
      '}\n'
      '\n'
      'class _SelectableCardCompactExampleState\n'
      '    extends State<SelectableCardCompactExample> {\n'
      '  String _speed = \'balanced\';\n'
      '\n'
      '  @override\n'
      '  Widget build(BuildContext context) {\n'
      '    // `controlSize` sizes the control, not the card. At `sm`, with the padding\n'
      '    // one step down, a card holding a single line stops being mostly box.\n'
      '    return AstryxGrid(\n'
      '      minWidth: 150,\n'
      '      gap: AstryxSpacingToken.spacing2,\n'
      '      children: <Widget>[\n'
      '        for (final speed in const <String>[\'fast\', \'balanced\', \'thorough\'])\n'
      '          AstryxSelectableCard(\n'
      '            label: speed,\n'
      '            control: AstryxSelectableCardControl.radio,\n'
      '            controlSize: AstryxToggleSize.sm,\n'
      '            padding: AstryxSpacingToken.spacing3,\n'
      '            selected: _speed == speed,\n'
      '            onSelectedChanged: (_) => setState(() => _speed = speed),\n'
      '            child: AstryxText(speed),\n'
      '          ),\n'
      '      ],\n'
      '    );\n'
      '  }\n'
      '}\n',
