  // examples/shape_examples.dart
  'shape_scale':
      'class ShapeScaleExample extends StatelessWidget {\n'
      '  const ShapeScaleExample({super.key});\n'
      '\n'
      '  @override\n'
      '  Widget build(BuildContext context) {\n'
      '    final theme = AstryxTheme.of(context);\n'
      '\n'
      '    return AstryxGrid(\n'
      '      minWidth: 130,\n'
      '      gap: AstryxSpacingToken.spacing3,\n'
      '      children: <Widget>[\n'
      '        for (final token in AstryxRadiusToken.values)\n'
      '          AstryxVStack(\n'
      '            gap: AstryxSpacingToken.spacing2,\n'
      '            align: AstryxStackAlign.stretch,\n'
      '            children: <Widget>[\n'
      '              DecoratedBox(\n'
      '                decoration: BoxDecoration(\n'
      '                  color: theme.color(AstryxColorToken.backgroundMuted),\n'
      '                  borderRadius: theme.borderRadius(token),\n'
      '                  border: Border.all(\n'
      '                    color: theme.color(AstryxColorToken.border),\n'
      '                  ),\n'
      '                ),\n'
      '                child: const SizedBox(height: 56),\n'
      '              ),\n'
      '              AstryxText(\n'
      '                \'\${token.name} · \${theme.radius(token).round()}px\',\n'
      '                type: AstryxTextType.supporting,\n'
      '                color: AstryxTextColor.secondary,\n'
      '                maxLines: 1,\n'
      '              ),\n'
      '            ],\n'
      '          ),\n'
      '      ],\n'
      '    );\n'
      '  }\n'
      '}\n',
  // examples/shape_examples.dart
  'shape_nesting':
      'class ShapeNestingExample extends StatelessWidget {\n'
      '  const ShapeNestingExample({super.key});\n'
      '\n'
      '  @override\n'
      '  Widget build(BuildContext context) {\n'
      '    final theme = AstryxTheme.of(context);\n'
      '\n'
      '    // Three steps of the scale, nested in the order they are meant to nest:\n'
      '    // container outside, element inside it, inner innermost. Each step is one\n'
      '    // notch tighter than the one around it, so the curves stay concentric.\n'
      '    return AstryxCard(\n'
      '      padding: AstryxSpacingToken.spacing3,\n'
      '      child: AstryxVStack(\n'
      '        gap: AstryxSpacingToken.spacing2,\n'
      '        align: AstryxStackAlign.stretch,\n'
      '        children: <Widget>[\n'
      '          const AstryxText(\'container · card\', type: AstryxTextType.label),\n'
      '          DecoratedBox(\n'
      '            decoration: BoxDecoration(\n'
      '              color: theme.color(AstryxColorToken.backgroundMuted),\n'
      '              borderRadius: theme.borderRadius(AstryxRadiusToken.element),\n'
      '              border: Border.all(color: theme.color(AstryxColorToken.border)),\n'
      '            ),\n'
      '            child: Padding(\n'
      '              padding: EdgeInsets.all(\n'
      '                theme.spacing(AstryxSpacingToken.spacing2),\n'
      '              ),\n'
      '              child: AstryxVStack(\n'
      '                gap: AstryxSpacingToken.spacing2,\n'
      '                align: AstryxStackAlign.stretch,\n'
      '                children: <Widget>[\n'
      '                  const AstryxText(\n'
      '                    \'element · button, input\',\n'
      '                    type: AstryxTextType.supporting,\n'
      '                  ),\n'
      '                  DecoratedBox(\n'
      '                    decoration: BoxDecoration(\n'
      '                      color: theme.color(AstryxColorToken.backgroundCard),\n'
      '                      borderRadius: theme.borderRadius(\n'
      '                        AstryxRadiusToken.inner,\n'
      '                      ),\n'
      '                      border: Border.all(\n'
      '                        color: theme.color(AstryxColorToken.border),\n'
      '                      ),\n'
      '                    ),\n'
      '                    child: Padding(\n'
      '                      padding: EdgeInsets.all(\n'
      '                        theme.spacing(AstryxSpacingToken.spacing2),\n'
      '                      ),\n'
      '                      child: const AstryxText(\n'
      '                        \'inner · a chip inside it\',\n'
      '                        type: AstryxTextType.supporting,\n'
      '                        color: AstryxTextColor.secondary,\n'
      '                      ),\n'
      '                    ),\n'
      '                  ),\n'
      '                ],\n'
      '              ),\n'
      '            ),\n'
      '          ),\n'
      '        ],\n'
      '      ),\n'
      '    );\n'
      '  }\n'
      '}\n',
