  // examples/skeleton_examples.dart
  'skeleton_delay':
      'class SkeletonDelayExample extends StatefulWidget {\n'
      '  const SkeletonDelayExample({super.key});\n'
      '\n'
      '  @override\n'
      '  State<SkeletonDelayExample> createState() => _SkeletonDelayExampleState();\n'
      '}\n'
      '\n'
      'class _SkeletonDelayExampleState extends State<SkeletonDelayExample> {\n'
      '  int _run = 0;\n'
      '\n'
      '  @override\n'
      '  Widget build(BuildContext context) {\n'
      '    // The block appears at once; only the pulse waits. Content that arrives\n'
      '    // quickly should not flash an animation on its way past.\n'
      '    return AstryxVStack(\n'
      '      gap: AstryxSpacingToken.spacing3,\n'
      '      align: AstryxStackAlign.stretch,\n'
      '      children: <Widget>[\n'
      '        SizedBox(\n'
      '          width: 280,\n'
      '          child: AstryxVStack(\n'
      '            key: ValueKey<int>(_run),\n'
      '            gap: AstryxSpacingToken.spacing2,\n'
      '            align: AstryxStackAlign.stretch,\n'
      '            children: const <Widget>[\n'
      '              AstryxSkeleton.text(delay: Duration.zero),\n'
      '              AstryxSkeleton.text(delay: Duration(milliseconds: 600)),\n'
      '              AstryxSkeleton.text(delay: Duration(seconds: 1)),\n'
      '            ],\n'
      '          ),\n'
      '        ),\n'
      '        AstryxButton(\n'
      '          label: \'Restart\',\n'
      '          size: AstryxButtonSize.sm,\n'
      '          onPressed: () => setState(() => _run++),\n'
      '        ),\n'
      '      ],\n'
      '    );\n'
      '  }\n'
      '}\n',
  // examples/spacing_examples.dart
  'spacing_gap':
      'class SpacingGapExample extends StatelessWidget {\n'
      '  const SpacingGapExample({super.key});\n'
      '\n'
      '  /// Three steps of the scale, applied to the same layout.\n'
      '  static const List<AstryxSpacingToken> _steps = <AstryxSpacingToken>[\n'
      '    AstryxSpacingToken.spacing1,\n'
      '    AstryxSpacingToken.spacing3,\n'
      '    AstryxSpacingToken.spacing6,\n'
      '  ];\n'
      '\n'
      '  @override\n'
      '  Widget build(BuildContext context) {\n'
      '    // One token drives the padding *and* the gap, which is what keeps the\n'
      '    // rhythm of a screen consistent — two numbers cannot drift apart.\n'
      '    return AstryxVStack(\n'
      '      gap: AstryxSpacingToken.spacing3,\n'
      '      align: AstryxStackAlign.stretch,\n'
      '      children: <Widget>[\n'
      '        for (final step in _steps)\n'
      '          AstryxVStack(\n'
      '            gap: AstryxSpacingToken.spacing1,\n'
      '            align: AstryxStackAlign.stretch,\n'
      '            children: <Widget>[\n'
      '              AstryxText(step.name, type: AstryxTextType.code),\n'
      '              AstryxCard(\n'
      '                padding: step,\n'
      '                child: AstryxHStack(\n'
      '                  gap: step,\n'
      '                  wrap: true,\n'
      '                  runGap: step,\n'
      '                  children: const <Widget>[\n'
      '                    AstryxBadge(\'build\'),\n'
      '                    AstryxBadge(\'test\'),\n'
      '                    AstryxBadge(\'deploy\'),\n'
      '                  ],\n'
      '                ),\n'
      '              ),\n'
      '            ],\n'
      '          ),\n'
      '      ],\n'
      '    );\n'
      '  }\n'
      '}\n',
