  // examples/spinner_examples.dart
  'spinner_shades':
      'class SpinnerShadesExample extends StatelessWidget {\n'
      '  const SpinnerShadesExample({super.key});\n'
      '\n'
      '  @override\n'
      '  Widget build(BuildContext context) {\n'
      '    final theme = AstryxTheme.of(context);\n'
      '\n'
      '    return AstryxHStack(\n'
      '      gap: AstryxSpacingToken.spacing4,\n'
      '      children: <Widget>[\n'
      '        for (final shade in AstryxSpinnerShade.values)\n'
      '          // `onMedia` only reads on an inverted surface, so it gets one.\n'
      '          ColoredBox(\n'
      '            color: shade == AstryxSpinnerShade.onMedia\n'
      '                ? theme.color(AstryxColorToken.backgroundInverted)\n'
      '                : const Color(0x00000000),\n'
      '            child: Padding(\n'
      '              padding: EdgeInsets.all(\n'
      '                theme.spacing(AstryxSpacingToken.spacing2),\n'
      '              ),\n'
      '              child: AstryxSpinner(shade: shade, label: \'Loading\'),\n'
      '            ),\n'
      '          ),\n'
      '      ],\n'
      '    );\n'
      '  }\n'
      '}\n',
