      '      gap: AstryxSpacingToken.spacing3,\n'
      '      align: AstryxStackAlign.stretch,\n'
      '      children: <Widget>[\n'
      '        for (final justify in AstryxStackJustify.values)\n'
      '          AstryxVStack(\n'
      '            gap: AstryxSpacingToken.spacing1,\n'
      '            align: AstryxStackAlign.stretch,\n'
      '            children: <Widget>[\n'
      '              AstryxText(justify.name, type: AstryxTextType.label),\n'
      '              AstryxHStack(\n'
      '                gap: AstryxSpacingToken.spacing2,\n'
      '                justify: justify,\n'
      '                mainAxisSize: MainAxisSize.max,\n'
      '                children: const <Widget>[\n'
      '                  _Box(\'one\'),\n'
      '                  _Box(\'two\'),\n'
      '                  _Box(\'three\'),\n'
      '                ],\n'
      '              ),\n'
      '            ],\n'
      '          ),\n'
      '      ],\n'
      '    );\n'
      '  }\n'
      '}\n',
