      '        gap: AstryxSpacingToken.spacing4,\n'
      '        justify: AstryxStackJustify.between,\n'
      '        mainAxisSize: MainAxisSize.max,\n'
      '        children: <Widget>[\n'
      '          // `Flexible`, because a spreading row hands its children their\n'
      '          // natural width — and two lines of copy will happily exceed a card.\n'
      '          const Flexible(\n'
