  // examples/status_dot_examples.dart
  'status_dot_demo':
      'class StatusDotDemoExample extends StatelessWidget {\n'
      '  const StatusDotDemoExample({super.key});\n'
      '\n'
      '  @override\n'
      '  Widget build(BuildContext context) {\n'
      '    // The dot is never the whole message: the words beside it are what a\n'
      '    // reader who cannot tell green from amber relies on.\n'
      '    return AstryxVStack(\n'
      '      gap: AstryxSpacingToken.spacing3,\n'
      '      children: <Widget>[\n'
      '        for (final (variant, label) in const <(AstryxStatusDotVariant, String)>[\n'
      '          (AstryxStatusDotVariant.success, \'Healthy\'),\n'
      '          (AstryxStatusDotVariant.warning, \'Degraded\'),\n'
      '          (AstryxStatusDotVariant.error, \'Unreachable\'),\n'
      '          (AstryxStatusDotVariant.accent, \'Deploying\'),\n'
      '          (AstryxStatusDotVariant.neutral, \'Not configured\'),\n'
      '        ])\n'
      '          AstryxHStack(\n'
      '            gap: AstryxSpacingToken.spacing2,\n'
      '            children: <Widget>[\n'
      '              AstryxStatusDot(variant, label: label),\n'
      '              AstryxText(label),\n'
      '            ],\n'
      '          ),\n'
      '      ],\n'
      '    );\n'
      '  }\n'
      '}\n',
  // examples/status_dot_examples.dart
  'status_dot_in_place':
      'class StatusDotInPlaceExample extends StatelessWidget {\n'
      '  const StatusDotInPlaceExample({super.key});\n'
      '\n'
      '  @override\n'
      '  Widget build(BuildContext context) {\n'
      '    // Where a dot earns its keep: a list of rows whose text already says what\n'
      '    // the state is, so the dot only has to make it scannable.\n'
      '    return AstryxVStack(\n'
      '      gap: AstryxSpacingToken.spacing2,\n'
      '      align: AstryxStackAlign.stretch,\n'
      '      children: <Widget>[\n'
      '        for (final (variant, service, state, pulsing)\n'
      '            in const <(AstryxStatusDotVariant, String, String, bool)>[\n'
      '          (AstryxStatusDotVariant.success, \'api-gateway\', \'Healthy\', false),\n'
      '          (AstryxStatusDotVariant.accent, \'billing\', \'Deploying\', true),\n'
      '          (AstryxStatusDotVariant.warning, \'search\', \'Degraded\', false),\n'
      '          (AstryxStatusDotVariant.error, \'mailer\', \'Unreachable\', false),\n'
      '        ])\n'
      '          AstryxCard(\n'
      '            padding: AstryxSpacingToken.spacing3,\n'
      '            child: AstryxHStack(\n'
      '              gap: AstryxSpacingToken.spacing3,\n'
      '              children: <Widget>[\n'
      '                AstryxStatusDot(\n'
      '                  variant,\n'
      '                  label: state,\n'
      '                  pulsing: pulsing,\n'
      '                  tooltip: \'\$service is \$state\'.toLowerCase(),\n'
      '                ),\n'
      '                Expanded(child: AstryxText(service)),\n'
      '                AstryxText(\n'
      '                  state,\n'
      '                  type: AstryxTextType.supporting,\n'
      '                  color: AstryxTextColor.secondary,\n'
      '                ),\n'
      '              ],\n'
      '            ),\n'
      '          ),\n'
      '      ],\n'
      '    );\n'
      '  }\n'
      '}\n',
  // examples/styling_examples.dart
  'styling_scopes':
      'class StylingScopesExample extends StatelessWidget {\n'
      '  const StylingScopesExample({super.key});\n'
      '\n'
      '  /// Square corners and a heavier label, as a component theme.\n'
      '  ///\n'
      '  /// Every field is nullable, and null means "fall through to the token\n'
      '  /// default" — so this changes two things and inherits the rest.\n'
      '  static const AstryxButtonTheme _squared = AstryxButtonTheme(\n'
      '    borderRadius: BorderRadius.zero,\n'
      '  );\n'
      '\n'
      '  @override\n'
      '  Widget build(BuildContext context) {\n'
      '    return AstryxGrid(\n'
      '      minWidth: 210,\n'
      '      gap: AstryxSpacingToken.spacing3,\n'
      '      children: <Widget>[\n'
      '        _Scope(\n'
      '          title: \'the theme\',\n'
      '          note: \'Nothing overridden.\',\n'
      '          child: AstryxButton(\n'
      '            label: \'Save\',\n'
      '            variant: AstryxButtonVariant.primary,\n'
      '            onPressed: () {},\n'
      '          ),\n'
      '        ),\n'
      '        _Scope(\n'
      '          title: \'one button\',\n'
      '          note: \'`theme:` on the widget.\',\n'
      '          child: AstryxButton(\n'
      '            label: \'Save\',\n'
      '            variant: AstryxButtonVariant.primary,\n'
      '            theme: _squared,\n'
      '            onPressed: () {},\n'
      '          ),\n'
      '        ),\n'
      '        // Everything below inherits it — including a button three widgets deep\n'
      '        // that knows nothing about this.\n'
      '        AstryxTheme(\n'
      '          data: AstryxTheme.of(context).copyWith(button: _squared),\n'
      '          density: AstryxTheme.densityOf(context),\n'
      '          icons: AstryxTheme.iconsOf(context),\n'
      '          child: _Scope(\n'
      '            title: \'a subtree\',\n'
      '            note: \'`AstryxTheme` with `copyWith`.\',\n'
      '            child: AstryxHStack(\n'
      '              gap: AstryxSpacingToken.spacing2,\n'
      '              children: <Widget>[\n'
      '                AstryxButton(\n'
      '                  label: \'Save\',\n'
      '                  variant: AstryxButtonVariant.primary,\n'
      '                  onPressed: () {},\n'
      '                ),\n'
      '                AstryxButton(label: \'Cancel\', onPressed: () {}),\n'
      '              ],\n'
      '            ),\n'
      '          ),\n'
      '        ),\n'
      '      ],\n'
      '    );\n'
      '  }\n'
      '}\n'
      '\n'
      'class _Scope extends StatelessWidget {\n'
      '  const _Scope({required this.title, required this.note, required this.child});\n'
      '\n'
      '  final String title;\n'
      '  final String note;\n'
      '  final Widget child;\n'
      '\n'
      '  @override\n'
      '  Widget build(BuildContext context) {\n'
      '    return AstryxCard(\n'
      '      padding: AstryxSpacingToken.spacing3,\n'
      '      child: AstryxVStack(\n'
      '        gap: AstryxSpacingToken.spacing2,\n'
      '        align: AstryxStackAlign.stretch,\n'
      '        children: <Widget>[\n'
      '          AstryxText(title, type: AstryxTextType.label),\n'
      '          child,\n'
      '          AstryxText(\n'
      '            note,\n'
      '            type: AstryxTextType.supporting,\n'
      '            color: AstryxTextColor.secondary,\n'
      '          ),\n'
      '        ],\n'
      '      ),\n'
      '    );\n'
      '  }\n'
      '}\n',
