  // examples/switch_examples.dart
  'switch_settings_list':
      'class SwitchSettingsListExample extends StatefulWidget {\n'
      '  const SwitchSettingsListExample({super.key});\n'
      '\n'
      '  @override\n'
      '  State<SwitchSettingsListExample> createState() =>\n'
      '      _SwitchSettingsListExampleState();\n'
      '}\n'
      '\n'
      'class _SwitchSettingsListExampleState extends State<SwitchSettingsListExample> {\n'
      '  final Set<String> _on = <String>{\'digest\'};\n'
      '\n'
      '  @override\n'
      '  Widget build(BuildContext context) {\n'
      '    // The settings-list shape: label at the reading edge, switch at the\n'
      '    // trailing one, the row spread between them.\n'
      '    return AstryxCard(\n'
      '      maxWidth: 380,\n'
      '      child: AstryxVStack(\n'
      '        gap: AstryxSpacingToken.spacing3,\n'
      '        align: AstryxStackAlign.stretch,\n'
      '        children: <Widget>[\n'
      '          for (final setting in const <List<String>>[\n'
      '            <String>[\'digest\', \'Weekly digest\', \'Every Monday, 9am\'],\n'
      '            <String>[\'mentions\', \'Mentions\', \'When someone @s you\'],\n'
      '            <String>[\'deploys\', \'Deploy failures\', \'Errors only\'],\n'
      '          ])\n'
      '            AstryxSwitch(\n'
      '              label: setting[1],\n'
      '              description: setting[2],\n'
      '              value: _on.contains(setting[0]),\n'
      '              labelPosition: AstryxToggleLabelPosition.start,\n'
      '              labelSpacing: AstryxToggleLabelSpacing.spread,\n'
      '              onChanged: (value) => setState(() {\n'
      '                if (value) {\n'
      '                  _on.add(setting[0]);\n'
      '                } else {\n'
      '                  _on.remove(setting[0]);\n'
      '                }\n'
      '              }),\n'
      '            ),\n'
      '        ],\n'
      '      ),\n'
      '    );\n'
      '  }\n'
      '}\n',
  // examples/switch_examples.dart
