  // examples/tab_list_examples.dart
  'tab_list_fill':
      'class TabListFillExample extends StatefulWidget {\n'
      '  const TabListFillExample({super.key});\n'
      '\n'
      '  @override\n'
      '  State<TabListFillExample> createState() => _TabListFillExampleState();\n'
      '}\n'
      '\n'
      'class _TabListFillExampleState extends State<TabListFillExample> {\n'
      '  String _tab = \'a\';\n'
      '\n'
      '  @override\n'
      '  Widget build(BuildContext context) {\n'
      '    // `fill` splits the width equally — for two or three tabs in a narrow\n'
      '    // panel, where a left-packed strip looks unfinished.\n'
      '    return AstryxVStack(\n'
      '      gap: AstryxSpacingToken.spacing4,\n'
      '      align: AstryxStackAlign.stretch,\n'
      '      children: <Widget>[\n'
      '        AstryxTabList<String>(\n'
      '          fill: true,\n'
      '          value: _tab,\n'
      '          onChanged: (value) => setState(() => _tab = value),\n'
      '          tabs: const <AstryxTab<String>>[\n'
      '            AstryxTab(value: \'a\', label: \'Monthly\'),\n'
      '            AstryxTab(value: \'b\', label: \'Yearly\'),\n'
      '          ],\n'
      '        ),\n'
      '        AstryxTabList<String>(\n'
      '          showDivider: false,\n'
      '          value: _tab,\n'
      '          onChanged: (value) => setState(() => _tab = value),\n'
      '          tabs: const <AstryxTab<String>>[\n'
      '            AstryxTab(value: \'a\', label: \'No divider\'),\n'
      '            AstryxTab(value: \'b\', label: \'Under the strip\'),\n'
      '          ],\n'
      '        ),\n'
      '      ],\n'
      '    );\n'
      '  }\n'
      '}\n',
  // examples/tab_list_examples.dart
  'tab_list_overflow':
      'class TabListOverflowExample extends StatefulWidget {\n'
      '  const TabListOverflowExample({super.key});\n'
      '\n'
      '  @override\n'
      '  State<TabListOverflowExample> createState() =>\n'
      '      _TabListOverflowExampleState();\n'
      '}\n'
      '\n'
      'class _TabListOverflowExampleState extends State<TabListOverflowExample> {\n'
      '  int _tab = 0;\n'
      '\n'
      '  @override\n'
      '  Widget build(BuildContext context) {\n'
      '    // Too many tabs scroll rather than shrink, with a fade at whichever edge\n'
      '    // has more. Arrowing to an off-screen tab scrolls it into view — a\n'
      '    // selection you cannot see is worse than none.\n'
      '    return SizedBox(\n'
      '      width: 360,\n'
      '      child: AstryxTabList<int>(\n'
      '        value: _tab,\n'
      '        onChanged: (value) => setState(() => _tab = value),\n'
      '        tabs: <AstryxTab<int>>[\n'
      '          for (var i = 0; i < 16; i++)\n'
      '            AstryxTab<int>(value: i, label: \'Section \$i\'),\n'
      '        ],\n'
      '      ),\n'
      '    );\n'
      '  }\n'
      '}\n',
