      '      rows: const <Project>[],\n'
      '      keyOf: (row) => row.id,\n'
      '      emptyState: AstryxVStack(\n'
      '        gap: AstryxSpacingToken.spacing2,\n'
      '        align: AstryxStackAlign.center,\n'
      '        children: <Widget>[\n'
      '          const AstryxText(\'No projects match this filter.\'),\n'
      '          AstryxButton(\n'
      '            label: \'Clear filters\',\n'
      '            size: AstryxButtonSize.sm,\n'
      '            onPressed: () {},\n'
      '          ),\n'
      '        ],\n'
      '      ),\n'
      '      columns: <AstryxTableColumn<Project>>[\n'
      '        AstryxTableColumn<Project>(\n'
      '          id: \'name\',\n'
      '          header: \'Project\',\n'
      '          cellBuilder: (context, row) => AstryxText(row.name),\n'
      '        ),\n'
      '        AstryxTableColumn<Project>(\n'
      '          id: \'owner\',\n'
      '          header: \'Owner\',\n'
      '          cellBuilder: (context, row) => AstryxText(row.owner),\n'
      '        ),\n'
      '      ],\n'
      '    );\n'
      '  }\n'
      '}\n',
  // examples/template_board_examples.dart
  'template_kanban_board':
      '/// One card on the board.\n'
      'typedef Ticket = ({\n'
      '  String id,\n'
      '  String title,\n'
      '  String assignee,\n'
      '  String tag,\n'
      '  int points,\n'
      '  bool blocked,\n'
      '});\n'
      '\n'
      '/// One column, and the work-in-progress limit it is judged against.\n'
      'typedef Lane = ({String id, String title, int? limit});\n'
      '\n'
      'class KanbanBoardTemplate extends StatefulWidget {\n'
      '  const KanbanBoardTemplate({super.key});\n'
      '\n'
      '  @override\n'
      '  State<KanbanBoardTemplate> createState() => _KanbanBoardTemplateState();\n'
      '}\n'
      '\n'
      'class _KanbanBoardTemplateState extends State<KanbanBoardTemplate> {\n'
      '  static const List<Lane> _lanes = <Lane>[\n'
      '    (id: \'triage\', title: \'Triage\', limit: null),\n'
      '    (id: \'doing\', title: \'In progress\', limit: 3),\n'
      '    (id: \'review\', title: \'In review\', limit: 2),\n'
      '    (id: \'done\', title: \'Done\', limit: null),\n'
      '  ];\n'
      '\n'
      '  static const List<Ticket> _tickets = <Ticket>[\n'
      '    (\n'
      '      id: \'ATL-412\',\n'
      '      title: \'Health check gives up before the port binds\',\n'
      '      assignee: \'Ada Lovelace\',\n'
      '      tag: \'scheduler\',\n'
      '      points: 5,\n'
      '      blocked: false,\n'
      '    ),\n'
      '    (\n'
      '      id: \'ATL-408\',\n'
      '      title: \'Artifact upload retries without backing off\',\n'
      '      assignee: \'Grace Hopper\',\n'
      '      tag: \'artifacts\',\n'
      '      points: 3,\n'
      '      blocked: true,\n'
      '    ),\n'
      '    (\n'
      '      id: \'ATL-401\',\n'
      '      title: \'Rollback leaves the old revision in the routing table\',\n'
      '      assignee: \'Alan Turing\',\n'
      '      tag: \'edge\',\n'
      '      points: 8,\n'
      '      blocked: false,\n'
      '    ),\n'
      '    (\n'
      '      id: \'ATL-397\',\n'
      '      title: \'Deploy log truncates at 400 lines\',\n'
      '      assignee: \'Ada Lovelace\',\n'
      '      tag: \'logs\',\n'
      '      points: 2,\n'
      '      blocked: false,\n'
      '    ),\n'
      '    (\n'
      '      id: \'ATL-392\',\n'
      '      title: \'Metrics shard 4 lags behind by ninety seconds\',\n'
      '      assignee: \'Katherine Johnson\',\n'
      '      tag: \'metrics\',\n'
      '      points: 5,\n'
      '      blocked: false,\n'
      '    ),\n'
      '    (\n'
      '      id: \'ATL-388\',\n'
      '      title: \'On-call rota export drops the last row\',\n'
      '      assignee: \'Grace Hopper\',\n'
      '      tag: \'oncall\',\n'
      '      points: 1,\n'
      '      blocked: false,\n'
      '    ),\n'
      '    (\n'
      '      id: \'ATL-380\',\n'
      '      title: \'Pipeline variables are not masked in the log\',\n'
      '      assignee: \'Alan Turing\',\n'
      '      tag: \'security\',\n'
      '      points: 3,\n'
      '      blocked: false,\n'
      '    ),\n'
      '  ];\n'
      '\n'
      '  /// Where each ticket is. The board is this map, and everything on screen is\n'
      '  /// derived from it — which is what makes a drag and a menu the same edit.\n'
      '  final Map<String, String> _lane = <String, String>{\n'
      '    \'ATL-412\': \'doing\',\n'
      '    \'ATL-408\': \'doing\',\n'
      '    \'ATL-401\': \'review\',\n'
      '    \'ATL-397\': \'triage\',\n'
      '    \'ATL-392\': \'triage\',\n'
      '    \'ATL-388\': \'done\',\n'
      '    \'ATL-380\': \'triage\',\n'
      '  };\n'
      '\n'
      '  /// The card a pointer is currently carrying, so its origin can dim.\n'
      '  String? _dragging;\n'
      '\n'
      '  List<Ticket> _inLane(String lane) =>\n'
      '      _tickets.where((ticket) => _lane[ticket.id] == lane).toList();\n'
      '\n'
      '  /// The one edit this screen makes. A drag calls it; so does a menu row.\n'
      '  void _move(String ticket, String lane) {\n'
      '    if (_lane[ticket] == lane) return;\n'
      '    final title = _lanes.firstWhere((entry) => entry.id == lane).title;\n'
      '    setState(() => _lane[ticket] = lane);\n'
      '    AstryxToastScope.of(context).show(\n'
      '      AstryxToast(message: \'\$ticket moved to \$title\'),\n'
      '    );\n'
      '  }\n'
      '\n'
      '  @override\n'
      '  Widget build(BuildContext context) {\n'
      '    return SizedBox(\n'
      '      height: 620,\n'
      '      child: AstryxLayout(\n'
      '        scrollable: false,\n'
      '        header: AstryxHStack(\n'
      '          gap: AstryxSpacingToken.spacing3,\n'
      '          justify: AstryxStackJustify.between,\n'
      '          mainAxisSize: MainAxisSize.max,\n'
      '          wrap: true,\n'
      '          runGap: AstryxSpacingToken.spacing2,\n'
      '          children: <Widget>[\n'
      '            AstryxVStack(\n'
      '              gap: AstryxSpacingToken.spacing1,\n'
      '              children: <Widget>[\n'
      '                const AstryxHeading(\'Sprint 42\', level: 1),\n'
      '                AstryxText(\n'
      '                  \'\${_tickets.length} tickets · \'\n'
      '                  \'\${_tickets.fold<int>(0, (sum, t) => sum + t.points)} points\',\n'
      '                  type: AstryxTextType.supporting,\n'
      '                  color: AstryxTextColor.secondary,\n'
      '                ),\n'
      '              ],\n'
      '            ),\n'
      '            AstryxButton(\n'
      '              label: \'New ticket\',\n'
      '              variant: AstryxButtonVariant.primary,\n'
      '              size: AstryxButtonSize.sm,\n'
      '              onPressed: () {},\n'
      '            ),\n'
      '          ],\n'
      '        ),\n'
      '        child: SingleChildScrollView(\n'
      '          scrollDirection: Axis.horizontal,\n'
      '          child: AstryxHStack(\n'
      '            gap: AstryxSpacingToken.spacing3,\n'
      '            align: AstryxStackAlign.stretch,\n'
      '            children: <Widget>[\n'
      '              for (final lane in _lanes)\n'
      '                SizedBox(\n'
      '                  width: 268,\n'
      '                  child: _Lane(\n'
      '                    lane: lane,\n'
      '                    tickets: _inLane(lane.id),\n'
      '                    lanes: _lanes,\n'
      '                    dragging: _dragging,\n'
      '                    onMove: _move,\n'
      '                    onDragStart: (id) => setState(() => _dragging = id),\n'
      '                    onDragEnd: () => setState(() => _dragging = null),\n'
      '                  ),\n'
      '                ),\n'
      '            ],\n'
      '          ),\n'
      '        ),\n'
      '      ),\n'
      '    );\n'
      '  }\n'
      '}\n'
      '\n'
      '/// One column: a header, a drop target, and the cards in it.\n'
      'class _Lane extends StatelessWidget {\n'
      '  const _Lane({\n'
      '    required this.lane,\n'
      '    required this.tickets,\n'
      '    required this.lanes,\n'
      '    required this.dragging,\n'
      '    required this.onMove,\n'
      '    required this.onDragStart,\n'
      '    required this.onDragEnd,\n'
      '  });\n'
      '\n'
      '  final Lane lane;\n'
      '  final List<Ticket> tickets;\n'
      '  final List<Lane> lanes;\n'
      '  final String? dragging;\n'
      '  final void Function(String ticket, String lane) onMove;\n'
      '  final ValueChanged<String> onDragStart;\n'
      '  final VoidCallback onDragEnd;\n'
      '\n'
      '  bool get _overLimit => lane.limit != null && tickets.length > lane.limit!;\n'
      '\n'
      '  @override\n'
      '  Widget build(BuildContext context) {\n'
      '    // `DragTarget` is the framework\'s, not the package\'s. What `astryx_ui`\n'
      '    // contributes is everything the column *looks* like — and the card\n'
      '    // variant is what says "let go here", because a border that only appears\n'
      '    // under a pointer is the one signal a drag is allowed to use.\n'
      '    return DragTarget<String>(\n'
      '      onWillAcceptWithDetails: (details) => true,\n'
      '      onAcceptWithDetails: (details) => onMove(details.data, lane.id),\n'
      '      builder: (context, candidate, rejected) {\n'
      '        final active = candidate.isNotEmpty;\n'
      '\n'
      '        return AstryxCard(\n'
      '          variant: active\n'
      '              ? AstryxCardVariant.standard\n'
      '              : AstryxCardVariant.muted,\n'
      '          elevation: active ? AstryxElevation.low : AstryxElevation.none,\n'
      '          padding: AstryxSpacingToken.spacing3,\n'
      '          // The lane is stretched to the height of the board, and a busy\n'
      '          // column holds more cards than that. `scrollable` is what keeps the\n'
      '          // header pinned while the cards under it move.\n'
      '          scrollable: true,\n'
      '          header: AstryxHStack(\n'
      '            gap: AstryxSpacingToken.spacing2,\n'
      '            justify: AstryxStackJustify.between,\n'
      '            mainAxisSize: MainAxisSize.max,\n'
      '            children: <Widget>[\n'
      '              Flexible(\n'
      '                child: AstryxText(\n'
      '                  lane.title,\n'
      '                  type: AstryxTextType.label,\n'
      '                  maxLines: 1,\n'
      '                ),\n'
      '              ),\n'
      '              // The limit is a number *and* a word when it is breached. A\n'
      '              // column that turned red and said nothing is a rule nobody can\n'
      '              // look up.\n'
      '              if (lane.limit == null)\n'
      '                AstryxBadge(\'\${tickets.length}\')\n'
      '              else\n'
      '                AstryxBadge(\n'
      '                  \'\${tickets.length}/\${lane.limit}\',\n'
      '                  variant: _overLimit\n'
      '                      ? AstryxBadgeVariant.warning\n'
      '                      : AstryxBadgeVariant.neutral,\n'
      '                  icon: _overLimit\n'
      '                      ? const AstryxIcon(AstryxIconName.warning)\n'
      '                      : null,\n'
      '                  semanticsLabel: _overLimit\n'
      '                      ? \'\${tickets.length} of \${lane.limit}, over the limit\'\n'
      '                      : \'\${tickets.length} of \${lane.limit}\',\n'
      '                ),\n'
      '            ],\n'
      '          ),\n'
      '          child: AstryxVStack(\n'
      '            gap: AstryxSpacingToken.spacing2,\n'
      '            align: AstryxStackAlign.stretch,\n'
      '            children: <Widget>[\n'
      '              if (tickets.isEmpty)\n'
      '                AstryxEmptyState(\n'
      '                  title: active ? \'Drop it here\' : \'Nothing here\',\n'
      '                  size: AstryxEmptyStateSize.compact,\n'
      '                  minHeight: 120,\n'
      '                )\n'
      '              else\n'
      '                for (final ticket in tickets)\n'
      '                  _TicketCard(\n'
      '                    ticket: ticket,\n'
      '                    lanes: lanes,\n'
      '                    lane: lane,\n'
      '                    dimmed: dragging == ticket.id,\n'
      '                    onMove: onMove,\n'
      '                    onDragStart: onDragStart,\n'
      '                    onDragEnd: onDragEnd,\n'
      '                  ),\n'
      '            ],\n'
      '          ),\n'
      '        );\n'
      '      },\n'
      '    );\n'
      '  }\n'
      '}\n'
      '\n'
      '/// One ticket: draggable for a pointer, and movable by menu for everyone else.\n'
      'class _TicketCard extends StatelessWidget {\n'
      '  const _TicketCard({\n'
      '    required this.ticket,\n'
      '    required this.lanes,\n'
      '    required this.lane,\n'
      '    required this.dimmed,\n'
      '    required this.onMove,\n'
      '    required this.onDragStart,\n'
      '    required this.onDragEnd,\n'
      '  });\n'
      '\n'
      '  final Ticket ticket;\n'
      '  final List<Lane> lanes;\n'
      '  final Lane lane;\n'
      '  final bool dimmed;\n'
      '  final void Function(String ticket, String lane) onMove;\n'
      '  final ValueChanged<String> onDragStart;\n'
      '  final VoidCallback onDragEnd;\n'
      '\n'
      '  @override\n'
      '  Widget build(BuildContext context) {\n'
      '    final card = _body(context);\n'
      '\n'
      '    // `Draggable` for a mouse, `LongPressDraggable` for a thumb. Neither is\n'
      '    // reachable from a keyboard, which is exactly why the menu inside `card`\n'
      '    // is not an extra: it is the path that always works.\n'
      '    return Draggable<String>(\n'
      '      data: ticket.id,\n'
      '      onDragStarted: () => onDragStart(ticket.id),\n'
      '      onDragEnd: (_) => onDragEnd(),\n'
      '      onDraggableCanceled: (_, _) => onDragEnd(),\n'
      '      feedback: SizedBox(width: 244, child: _body(context, lifted: true)),\n'
      '      childWhenDragging: Opacity(opacity: 0.4, child: card),\n'
      '      child: card,\n'
      '    );\n'
      '  }\n'
      '\n'
      '  Widget _body(BuildContext context, {bool lifted = false}) {\n'
      '    return AstryxCard(\n'
      '      padding: AstryxSpacingToken.spacing3,\n'
      '      elevation: lifted ? AstryxElevation.high : AstryxElevation.none,\n'
      '      header: AstryxHStack(\n'
      '        gap: AstryxSpacingToken.spacing2,\n'
      '        justify: AstryxStackJustify.between,\n'
      '        mainAxisSize: MainAxisSize.max,\n'
      '        children: <Widget>[\n'
      '          AstryxText(ticket.id, type: AstryxTextType.code),\n'
      '          // The move menu. Named for the ticket, not "More" — a board of seven\n'
      '          // identical "More" buttons is seven identical announcements.\n'
      '          if (!lifted)\n'
      '            AstryxMoreMenu(\n'
      '              label: \'Move \${ticket.id}\',\n'
      '              entries: <AstryxMenuEntry>[\n'
      '                const AstryxMenuSection(\'Move to\'),\n'
      '                for (final target in lanes)\n'
      '                  AstryxMenuItem(\n'
      '                    label: target.title,\n'
      '                    enabled: target.id != lane.id,\n'
      '                    onSelected: () => onMove(ticket.id, target.id),\n'
      '                  ),\n'
      '              ],\n'
      '            ),\n'
      '        ],\n'
      '      ),\n'
      '      footer: AstryxHStack(\n'
      '        gap: AstryxSpacingToken.spacing2,\n'
      '        justify: AstryxStackJustify.between,\n'
      '        mainAxisSize: MainAxisSize.max,\n'
      '        children: <Widget>[\n'
      '          AstryxAvatar(name: ticket.assignee, size: AstryxAvatarSize.xs),\n'
      '          AstryxHStack(\n'
      '            gap: AstryxSpacingToken.spacing1,\n'
      '            children: <Widget>[\n'
      '              AstryxBadge(ticket.tag),\n'
      '              AstryxBadge(\n'
      '                \'\${ticket.points}\',\n'
      '                semanticsLabel: \'\${ticket.points} points\',\n'
      '              ),\n'
      '            ],\n'
      '          ),\n'
      '        ],\n'
      '      ),\n'
      '      child: AstryxVStack(\n'
      '        gap: AstryxSpacingToken.spacing2,\n'
      '        align: AstryxStackAlign.stretch,\n'
      '        children: <Widget>[\n'
      '          AstryxText(ticket.title, maxLines: 3),\n'
      '          if (ticket.blocked)\n'
      '            const AstryxBadge(\n'
      '              \'Blocked\',\n'
      '              variant: AstryxBadgeVariant.error,\n'
      '              icon: AstryxIcon(AstryxIconName.error),\n'
      '            ),\n'
      '        ],\n'
      '      ),\n'
      '    );\n'
      '  }\n'
      '}\n',
  // examples/template_chart_examples.dart
  'template_dashboard_portfolio':
      '/// One holding in the portfolio.\n'
      'typedef Holding = ({\n'
      '  String ticker,\n'
      '  String name,\n'
      '  String sector,\n'
      '  int price,\n'
      '  int value,\n'
      '  double change,\n'
      '});\n'
      '\n'
      'class PortfolioDashboardTemplate extends StatefulWidget {\n'
      '  const PortfolioDashboardTemplate({super.key});\n'
      '\n'
      '  @override\n'
      '  State<PortfolioDashboardTemplate> createState() =>\n'
      '      _PortfolioDashboardTemplateState();\n'
      '}\n'
      '\n'
      'class _PortfolioDashboardTemplateState\n'
      '    extends State<PortfolioDashboardTemplate> {\n'
      '  static const List<Holding> _holdings = <Holding>[\n'
      '    (\n'
      '      ticker: \'ACME\',\n'
      '      name: \'Acme Corporation\',\n'
      '      sector: \'Industrials\',\n'
      '      price: 42150,\n'
      '      value: 1264500,\n'
      '      change: 2.41,\n'
      '    ),\n'
      '    (\n'
      '      ticker: \'GLBX\',\n'
      '      name: \'Globex\',\n'
      '      sector: \'Technology\',\n'
      '      price: 18820,\n'
      '      value: 941000,\n'
      '      change: -1.08,\n'
      '    ),\n'
      '    (\n'
      '      ticker: \'INIT\',\n'
      '      name: \'Initech\',\n'
      '      sector: \'Technology\',\n'
      '      price: 9640,\n'
      '      value: 578400,\n'
      '      change: 5.62,\n'
      '    ),\n'
      '    (\n'
      '      ticker: \'UMBR\',\n'
      '      name: \'Umbrella Health\',\n'
      '      sector: \'Healthcare\',\n'
      '      price: 27310,\n'
      '      value: 546200,\n'
      '      change: 0.34,\n'
      '    ),\n'
      '    (\n'
      '      ticker: \'NRTH\',\n'
      '      name: \'Northwind Energy\',\n'
      '      sector: \'Energy\',\n'
      '      price: 6125,\n'
      '      value: 306250,\n'
      '      change: -3.87,\n'
      '    ),\n'
      '    (\n'
      '      ticker: \'CONT\',\n'
      '      name: \'Contoso Retail\',\n'
      '      sector: \'Consumer\',\n'
      '      price: 3480,\n'
      '      value: 174000,\n'
      '      change: 1.19,\n'
      '    ),\n'
      '  ];\n'
      '\n'
      '  /// The series behind each range. Real data arrives from somewhere; the\n'
      '  /// screen\'s job is the same either way.\n'
      '  static const Map<String, List<double>> _series = <String, List<double>>{\n'
      '    \'1m\': <double>[\n'
      '      37.4, 37.9, 37.1, 38.2, 38.05, 38.6, 39.1, 38.8, 39.4, 39.2, 39.9, 40.1,\n'
      '    ],\n'
      '    \'6m\': <double>[\n'
      '      31.2, 32.8, 32.1, 34.6, 33.9, 35.8, 36.4, 35.1, 37.2, 38.4, 39.05, 40.1,\n'
      '    ],\n'
      '    \'1y\': <double>[\n'
      '      28.4, 27.1, 29.6, 31.2, 30.4, 33.1, 32.2, 34.9, 36.1, 35.4, 38.2, 40.1,\n'
      '    ],\n'
      '  };\n'
      '\n'
      '  static const Map<String, String> _rangeLabels = <String, String>{\n'
      '    \'1m\': \'the last month\',\n'
      '    \'6m\': \'the last six months\',\n'
      '    \'1y\': \'the last year\',\n'
      '  };\n'
      '\n'
      '  String _range = \'6m\';\n'
      '  AstryxTableSort? _sort = const AstryxTableSort(\n'
      '    \'value\',\n'
      '    AstryxSortDirection.descending,\n'
      '  );\n'
      '\n'
      '  int get _total =>\n'
      '      _holdings.fold<int>(0, (sum, holding) => sum + holding.value);\n'
      '\n'
      '  List<double> get _values => _series[_range]!;\n'
      '\n'
      '  double get _rangeChange {\n'
      '    final series = _values;\n'
      '    return (series.last - series.first) / series.first * 100;\n'
      '  }\n'
      '\n'
      '  /// Sorted in the caller. `AstryxTable.rows` is documented as already sorted\n'
      '  /// and already paginated, and a table that sorted itself could not be handed\n'
      '  /// a page.\n'
      '  List<Holding> get _rows {\n'
      '    final rows = List<Holding>.of(_holdings);\n'
      '    final sort = _sort;\n'
      '    if (sort == null) return rows;\n'
      '\n'
      '    int by(Holding a, Holding b) => switch (sort.columnId) {\n'
      '      \'name\' => a.name.compareTo(b.name),\n'
      '      \'price\' => a.price.compareTo(b.price),\n'
      '      \'change\' => a.change.compareTo(b.change),\n'
      '      _ => a.value.compareTo(b.value),\n'
      '    };\n'
      '    rows.sort(\n'
      '      (a, b) =>\n'
      '          sort.direction == AstryxSortDirection.ascending ? by(a, b) : by(b, a),\n'
      '    );\n'
      '    return rows;\n'
      '  }\n'
      '\n'
      '  /// What each sector is worth, largest first.\n'
      '  List<({String sector, int value})> get _allocation {\n'
      '    final totals = <String, int>{};\n'
      '    for (final holding in _holdings) {\n'
      '      totals[holding.sector] = (totals[holding.sector] ?? 0) + holding.value;\n'
      '    }\n'
      '    final rows = <({String sector, int value})>[\n'
      '      for (final entry in totals.entries)\n'
      '        (sector: entry.key, value: entry.value),\n'
      '    ];\n'
      '    return rows..sort((a, b) => b.value.compareTo(a.value));\n'
      '  }\n'
      '\n'
      '  @override\n'
      '  Widget build(BuildContext context) {\n'
      '    final change = _rangeChange;\n'
      '    final up = change >= 0;\n'
      '\n'
      '    return AstryxVStack(\n'
      '      gap: AstryxSpacingToken.spacing6,\n'
      '      align: AstryxStackAlign.stretch,\n'
      '      children: <Widget>[\n'
      '        AstryxHStack(\n'
      '          gap: AstryxSpacingToken.spacing3,\n'
      '          justify: AstryxStackJustify.between,\n'
      '          mainAxisSize: MainAxisSize.max,\n'
      '          wrap: true,\n'
      '          runGap: AstryxSpacingToken.spacing2,\n'
      '          children: <Widget>[\n'
      '            AstryxVStack(\n'
      '              gap: AstryxSpacingToken.spacing1,\n'
      '              children: <Widget>[\n'
      '                const AstryxHeading(\'Portfolio\', level: 1),\n'
      '                // The figure is text, at display size, and the chart is\n'
      '                // underneath it. A dashboard whose headline number can only be\n'
      '                // read off a curve is a dashboard nobody can quote.\n'
      '                AstryxText(\n'
      '                  pence(_total),\n'
      '                  type: AstryxTextType.display3,\n'
      '                  tabularNumbers: true,\n'
      '                ),\n'
      '                AstryxHStack(\n'
      '                  gap: AstryxSpacingToken.spacing2,\n'
      '                  // The badge carries the number and the words carry the\n'
      '                  // window it is over. Neither can be cut off, so on a narrow\n'
      '                  // column they take a line each.\n'
      '                  wrap: true,\n'
      '                  runGap: AstryxSpacingToken.spacing1,\n'
      '                  children: <Widget>[\n'
      '                    AstryxBadge(\n'
      '                      signed(change),\n'
      '                      variant: up\n'
      '                          ? AstryxBadgeVariant.success\n'
      '                          : AstryxBadgeVariant.error,\n'
      '                      icon: AstryxIcon(\n'
      '                        up ? AstryxIconName.arrowUp : AstryxIconName.arrowDown,\n'
      '                      ),\n'
      '                    ),\n'
      '                    AstryxText(\n'
      '                      \'over \${_rangeLabels[_range]}\',\n'
      '                      type: AstryxTextType.supporting,\n'
      '                      color: AstryxTextColor.secondary,\n'
      '                    ),\n'
      '                  ],\n'
      '                ),\n'
      '              ],\n'
      '            ),\n'
      '            AstryxSegmentedControl<String>(\n'
      '              label: \'Range\',\n'
      '              value: _range,\n'
      '              size: AstryxButtonSize.sm,\n'
      '              onChanged: (value) => setState(() => _range = value),\n'
      '              segments: const <AstryxSegment<String>>[\n'
      '                AstryxSegment(value: \'1m\', label: \'1M\'),\n'
      '                AstryxSegment(value: \'6m\', label: \'6M\'),\n'
      '                AstryxSegment(value: \'1y\', label: \'1Y\'),\n'
      '              ],\n'
      '            ),\n'
      '          ],\n'
      '        ),\n'
      '        AstryxCard(\n'
      '          footer: AstryxHStack(\n'
      '            gap: AstryxSpacingToken.spacing3,\n'
      '            justify: AstryxStackJustify.between,\n'
      '            mainAxisSize: MainAxisSize.max,\n'
      '            children: <Widget>[\n'
      '              AstryxText(\n'
      '                \'£\${_values.first.toStringAsFixed(1)}k\',\n'
      '                type: AstryxTextType.supporting,\n'
      '                color: AstryxTextColor.secondary,\n'
      '                tabularNumbers: true,\n'
      '              ),\n'
      '              AstryxText(\n'
      '                \'£\${_values.last.toStringAsFixed(1)}k\',\n'
      '                type: AstryxTextType.supporting,\n'
      '                color: AstryxTextColor.secondary,\n'
      '                tabularNumbers: true,\n'
      '              ),\n'
      '            ],\n'
      '          ),\n'
      '          child: TrendChart(\n'
      '            values: _values,\n'
      '            height: 180,\n'
      '            color: up ? AstryxColorToken.success : AstryxColorToken.error,\n'
      '            label: \'Portfolio value over \${_rangeLabels[_range]}\',\n'
      '            // The chart\'s whole content, in a sentence. Everything a sighted\n'
      '            // reader takes from the shape is stated here instead.\n'
      '            semanticsValue:\n'
      '                \'From £\${_values.first.toStringAsFixed(1)}k to \'\n'
      '                \'£\${_values.last.toStringAsFixed(1)}k, \'\n'
      '                \'\${signed(change)}\',\n'
      '          ),\n'
      '        ),\n'
      '        AstryxSection(\n'
      '          title: \'Allocation\',\n'
      '          description: \'What each sector is worth, as a share of the whole.\',\n'
      '          child: AstryxVStack(\n'
      '            gap: AstryxSpacingToken.spacing3,\n'
      '            align: AstryxStackAlign.stretch,\n'
      '            children: <Widget>[\n'
      '              // Bars, not a pie. A proportion each reader can compare against\n'
      '              // its neighbour beats a wedge nobody can measure — and\n'
      '              // `AstryxProgressBar` is already a proportion with an announced\n'
      '              // label, so there is nothing to draw.\n'
      '              for (final row in _allocation)\n'
      '                AstryxProgressBar(\n'
      '                  label: row.sector,\n'
      '                  value: row.value / _total,\n'
      '                  showValueLabel: true,\n'
      '                  formatValue: (value) =>\n'
      '                      \'\${(value * 100).round()}% · \${pence(row.value)}\',\n'
      '                ),\n'
      '            ],\n'
      '          ),\n'
      '        ),\n'
      '        AstryxSection(\n'
      '          title: \'Holdings\',\n'
      '          description: \'Six positions. Press a column header to sort.\',\n'
      '          child: AstryxTable<Holding>(\n'
      '            label: \'Holdings\',\n'
      '            keyOf: (row) => row.ticker,\n'
      '            rowLabelOf: (row) => row.name,\n'
      '            sort: _sort,\n'
      '            onSortChanged: (sort) => setState(() => _sort = sort),\n'
      '            minWidth: 640,\n'
      '            columns: <AstryxTableColumn<Holding>>[\n'
      '              AstryxTableColumn<Holding>(\n'
      '                id: \'name\',\n'
      '                header: \'Holding\',\n'
      '                compare: (a, b) => a.name.compareTo(b.name),\n'
      '                cellBuilder: (context, row) => AstryxVStack(\n'
      '                  gap: AstryxSpacingToken.spacing0_5,\n'
      '                  children: <Widget>[\n'
      '                    AstryxText(row.ticker, type: AstryxTextType.code),\n'
      '                    AstryxText(\n'
      '                      row.name,\n'
      '                      type: AstryxTextType.supporting,\n'
      '                      color: AstryxTextColor.secondary,\n'
      '                      maxLines: 1,\n'
      '                    ),\n'
      '                  ],\n'
      '                ),\n'
      '              ),\n'
      '              AstryxTableColumn<Holding>(\n'
      '                id: \'sector\',\n'
      '                header: \'Sector\',\n'
      '                width: const AstryxTableColumnWidth.fixed(130),\n'
      '                cellBuilder: (context, row) => AstryxBadge(row.sector),\n'
      '              ),\n'
      '              AstryxTableColumn<Holding>(\n'
      '                id: \'price\',\n'
      '                header: \'Price\',\n'
      '                width: const AstryxTableColumnWidth.fixed(120),\n'
      '                alignment: AstryxTableAlignment.end,\n'
      '                compare: (a, b) => a.price.compareTo(b.price),\n'
      '                cellBuilder: (context, row) =>\n'
      '                    AstryxText(pence(row.price), tabularNumbers: true),\n'
      '              ),\n'
      '              AstryxTableColumn<Holding>(\n'
      '                id: \'change\',\n'
      '                header: \'Change\',\n'
      '                width: const AstryxTableColumnWidth.fixed(136),\n'
      '                alignment: AstryxTableAlignment.end,\n'
      '                compare: (a, b) => a.change.compareTo(b.change),\n'
      '                // A sign and a glyph, not only a colour. Red and green are the\n'
      '                // two hues most readers cannot tell apart, and this is the\n'
      '                // column where that matters most.\n'
      '                cellBuilder: (context, row) => AstryxHStack(\n'
      '                  gap: AstryxSpacingToken.spacing1,\n'
      '                  justify: AstryxStackJustify.end,\n'
      '                  mainAxisSize: MainAxisSize.max,\n'
      '                  children: <Widget>[\n'
      '                    AstryxIcon(\n'
      '                      row.change >= 0\n'
      '                          ? AstryxIconName.arrowUp\n'
      '                          : AstryxIconName.arrowDown,\n'
      '                      size: AstryxIconSize.sm,\n'
      '                      color: row.change >= 0\n'
      '                          ? AstryxIconColor.success\n'
      '                          : AstryxIconColor.error,\n'
      '                    ),\n'
      '                    AstryxText(signed(row.change), tabularNumbers: true),\n'
      '                  ],\n'
      '                ),\n'
      '              ),\n'
      '              AstryxTableColumn<Holding>(\n'
      '                id: \'value\',\n'
      '                header: \'Value\',\n'
      '                width: const AstryxTableColumnWidth.fixed(140),\n'
      '                alignment: AstryxTableAlignment.end,\n'
      '                compare: (a, b) => a.value.compareTo(b.value),\n'
      '                cellBuilder: (context, row) =>\n'
      '                    AstryxText(pence(row.value), tabularNumbers: true),\n'
      '              ),\n'
      '            ],\n'
      '            rows: _rows,\n'
      '          ),\n'
      '        ),\n'
      '      ],\n'
      '    );\n'
      '  }\n'
      '}\n',
  // examples/template_chart_examples.dart
  'template_table_page_chart':
      '/// One day of trading for the whole book.\n'
      'typedef Session = ({\n'
      '  String date,\n'
      '  String desk,\n'
      '  int volume,\n'
      '  int pnl,\n'
      '  bool breached,\n'
      '});\n'
      '\n'
      'class TablePageChartTemplate extends StatefulWidget {\n'
      '  const TablePageChartTemplate({super.key});\n'
      '\n'
      '  @override\n'
      '  State<TablePageChartTemplate> createState() => _TablePageChartTemplateState();\n'
      '}\n'
      '\n'
      'class _TablePageChartTemplateState extends State<TablePageChartTemplate> {\n'
      '  static const List<Session> _all = <Session>[\n'
      '    (date: \'12 Aug\', desk: \'Rates\', volume: 4120, pnl: 184200, breached: false),\n'
      '    (date: \'12 Aug\', desk: \'Credit\', volume: 2980, pnl: -41100, breached: true),\n'
      '    (date: \'11 Aug\', desk: \'Rates\', volume: 3860, pnl: 96400, breached: false),\n'
      '    (\n'
      '      date: \'11 Aug\',\n'
      '      desk: \'Equity\',\n'
      '      volume: 5210,\n'
      '      pnl: 210500,\n'
      '      breached: false,\n'
      '    ),\n'
      '    (date: \'11 Aug\', desk: \'Credit\', volume: 3140, pnl: 28800, breached: false),\n'
      '    (date: \'10 Aug\', desk: \'Rates\', volume: 2740, pnl: -18600, breached: false),\n'
      '    (\n'
      '      date: \'10 Aug\',\n'
      '      desk: \'Equity\',\n'
      '      volume: 4890,\n'
      '      pnl: 152300,\n'
      '      breached: false,\n'
      '    ),\n'
      '    (date: \'9 Aug\', desk: \'Credit\', volume: 2210, pnl: -92400, breached: true),\n'
      '    (date: \'9 Aug\', desk: \'Rates\', volume: 3320, pnl: 64100, breached: false),\n'
      '    (date: \'8 Aug\', desk: \'Equity\', volume: 4460, pnl: 118900, breached: false),\n'
      '    (date: \'8 Aug\', desk: \'Credit\', volume: 2650, pnl: 36200, breached: false),\n'
      '    (date: \'7 Aug\', desk: \'Rates\', volume: 3980, pnl: 142700, breached: false),\n'
      '  ];\n'
      '\n'
      '  /// The series the chart draws, in the same order as the rows below it.\n'
      '  static const List<double> _cumulative = <double>[\n'
      '    0.14, 0.28, 0.19, 0.34, 0.41, 0.36, 0.52, 0.44, 0.58, 0.71, 0.66, 0.82,\n'
      '  ];\n'
      '\n'
      '  String _desk = \'All\';\n'
      '  int _page = 1;\n'
      '  static const int _pageSize = 5;\n'
      '\n'
      '  List<Session> get _matches =>\n'
      '      _desk == \'All\' ? _all : _all.where((row) => row.desk == _desk).toList();\n'
      '\n'
      '  List<Session> get _rows {\n'
      '    final matches = _matches;\n'
      '    final start = (_page - 1) * _pageSize;\n'
      '    if (start >= matches.length) return const <Session>[];\n'
      '    final end = start + _pageSize;\n'
      '    return matches.sublist(start, end > matches.length ? matches.length : end);\n'
      '  }\n'
      '\n'
      '  /// Every filter goes through here, because narrowing the set while on page\n'
      '  /// three shows an empty table — which reads as "no data" rather than "you\n'
      '  /// are past the end".\n'
      '  void _refilter(VoidCallback change) => setState(() {\n'
      '    change();\n'
      '    _page = 1;\n'
      '  });\n'
      '\n'
      '  @override\n'
      '  Widget build(BuildContext context) {\n'
      '    final matches = _matches;\n'
      '    final rows = _rows;\n'
      '    final pages = (matches.length / _pageSize).ceil().clamp(1, 999);\n'
      '    final start = matches.isEmpty ? 0 : (_page - 1) * _pageSize + 1;\n'
      '    final end = start + rows.length - 1;\n'
      '\n'
      '    return SizedBox(\n'
      '      height: 620,\n'
      '      child: AstryxLayout(\n'
      '        // The table scrolls its own body under its own header row. Leaving the\n'
      '        // layout scrollable puts one scroll view inside another.\n'
      '        scrollable: false,\n'
      '        header: AstryxVStack(\n'
      '          gap: AstryxSpacingToken.spacing4,\n'
      '          align: AstryxStackAlign.stretch,\n'
      '          children: <Widget>[\n'
      '            AstryxHStack(\n'
      '              gap: AstryxSpacingToken.spacing3,\n'
      '              justify: AstryxStackJustify.between,\n'
      '              mainAxisSize: MainAxisSize.max,\n'
      '              wrap: true,\n'
      '              runGap: AstryxSpacingToken.spacing2,\n'
      '              children: <Widget>[\n'
      '                AstryxVStack(\n'
      '                  gap: AstryxSpacingToken.spacing1,\n'
      '                  children: <Widget>[\n'
      '                    const AstryxHeading(\'Trading sessions\', level: 1),\n'
      '                    AstryxText(\n'
      '                      \'\${matches.length} of \${_all.length} sessions\',\n'
      '                      type: AstryxTextType.supporting,\n'
      '                      color: AstryxTextColor.secondary,\n'
      '                    ),\n'
      '                  ],\n'
      '                ),\n'
      '                AstryxSegmentedControl<String>(\n'
      '                  label: \'Desk\',\n'
      '                  value: _desk,\n'
      '                  size: AstryxButtonSize.sm,\n'
      '                  onChanged: (value) => _refilter(() => _desk = value),\n'
      '                  segments: const <AstryxSegment<String>>[\n'
      '                    AstryxSegment(value: \'All\', label: \'All\'),\n'
      '                    AstryxSegment(value: \'Rates\', label: \'Rates\'),\n'
      '                    AstryxSegment(value: \'Credit\', label: \'Credit\'),\n'
      '                    AstryxSegment(value: \'Equity\', label: \'Equity\'),\n'
      '                  ],\n'
      '                ),\n'
      '              ],\n'
      '            ),\n'
      '            // The chart summarises the *whole* set, not the page. A summary\n'
      '            // that moved every time the reader turned a page would be a\n'
      '            // summary of the page, which the page already is.\n'
      '            const AstryxCard(\n'
      '              variant: AstryxCardVariant.muted,\n'
      '              padding: AstryxSpacingToken.spacing3,\n'
      '              header: AstryxText(\n'
      '                \'Cumulative P&L, all desks\',\n'
      '                type: AstryxTextType.label,\n'
      '              ),\n'
      '              child: TrendChart(\n'
      '                values: _cumulative,\n'
      '                height: 88,\n'
      '                showBaseline: false,\n'
      '                label: \'Cumulative profit and loss over twelve sessions\',\n'
      '                semanticsValue:\n'
      '                    \'Rising from 0.14 to 0.82 million, with drawdowns on the \'\n'
      '                    \'9th and the 11th\',\n'
      '              ),\n'
      '            ),\n'
      '          ],\n'
      '        ),\n'
      '        footer: AstryxHStack(\n'
      '          gap: AstryxSpacingToken.spacing3,\n'
      '          justify: AstryxStackJustify.between,\n'
      '          mainAxisSize: MainAxisSize.max,\n'
      '          wrap: true,\n'
      '          runGap: AstryxSpacingToken.spacing2,\n'
      '          children: <Widget>[\n'
      '            AstryxText(\n'
      '              matches.isEmpty ? \'Nothing to show\' : \'\$start–\$end of \'\n'
      '                  \'\${matches.length}\',\n'
      '              type: AstryxTextType.supporting,\n'
      '              color: AstryxTextColor.secondary,\n'
      '              tabularNumbers: true,\n'
      '            ),\n'
      '            AstryxPagination(\n'
      '              page: _page,\n'
      '              pageCount: pages,\n'
      '              onPageChanged: (page) => setState(() => _page = page),\n'
      '            ),\n'
      '          ],\n'
      '        ),\n'
      '        child: AstryxTable<Session>(\n'
      '          label: \'Trading sessions\',\n'
      '          keyOf: (row) => \'\${row.date}/\${row.desk}\',\n'
      '          rowLabelOf: (row) => \'\${row.desk} on \${row.date}\',\n'
      '          density: AstryxTableDensity.compact,\n'
      '          minWidth: 560,\n'
      '          emptyState: AstryxEmptyState(\n'
      '            title: \'No sessions for that desk\',\n'
      '            size: AstryxEmptyStateSize.compact,\n'
      '            actions: <Widget>[\n'
      '              AstryxButton(\n'
      '                label: \'Show all desks\',\n'
      '                onPressed: () => _refilter(() => _desk = \'All\'),\n'
      '              ),\n'
      '            ],\n'
      '          ),\n'
      '          columns: <AstryxTableColumn<Session>>[\n'
      '            AstryxTableColumn<Session>(\n'
      '              id: \'date\',\n'
      '              header: \'Date\',\n'
      '              width: const AstryxTableColumnWidth.fixed(90),\n'
      '              cellBuilder: (context, row) => AstryxText(row.date, maxLines: 1),\n'
      '            ),\n'
      '            AstryxTableColumn<Session>(\n'
      '              id: \'desk\',\n'
      '              header: \'Desk\',\n'
      '              cellBuilder: (context, row) => AstryxBadge(row.desk),\n'
      '            ),\n'
      '            AstryxTableColumn<Session>(\n'
      '              id: \'volume\',\n'
      '              header: \'Volume\',\n'
      '              width: const AstryxTableColumnWidth.fixed(100),\n'
      '              alignment: AstryxTableAlignment.end,\n'
      '              cellBuilder: (context, row) =>\n'
      '                  AstryxText(\'\${row.volume}\', tabularNumbers: true),\n'
      '            ),\n'
      '            AstryxTableColumn<Session>(\n'
      '              id: \'pnl\',\n'
      '              header: \'P&L\',\n'
      '              width: const AstryxTableColumnWidth.fixed(120),\n'
      '              alignment: AstryxTableAlignment.end,\n'
      '              cellBuilder: (context, row) => AstryxText(\n'
      '                \'\${row.pnl < 0 ? \'−\' : \'\'}\${pence(row.pnl.abs())}\',\n'
      '                tabularNumbers: true,\n'
      '              ),\n'
      '            ),\n'
      '            AstryxTableColumn<Session>(\n'
      '              id: \'limit\',\n'
      '              header: \'Limit\',\n'
      '              width: const AstryxTableColumnWidth.fixed(120),\n'
      '              cellBuilder: (context, row) => row.breached\n'
      '                  ? const AstryxBadge(\n'
      '                      \'Breached\',\n'
      '                      variant: AstryxBadgeVariant.error,\n'
      '                      icon: AstryxIcon(AstryxIconName.error),\n'
      '                    )\n'
      '                  : const AstryxBadge(\n'
      '                      \'Within\',\n'
      '                      variant: AstryxBadgeVariant.success,\n'
      '                      icon: AstryxIcon(AstryxIconName.success),\n'
      '                    ),\n'
      '            ),\n'
      '          ],\n'
      '          rows: rows,\n'
      '        ),\n'
      '      ),\n'
      '    );\n'
      '  }\n'
      '}\n',
  // examples/template_chat_examples.dart
  'template_ai_chat':
      '/// One turn of the conversation this template pretends to have had.\n'
      '///\n'
      '/// A record rather than a widget list: the transcript is data, and the widgets\n'
      '/// are how it is drawn. Swapping the drawing is then a local change.\n'
      'typedef _Turn = ({\n'
      '  AstryxChatRole role,\n'
      '  String text,\n'
      '  List<AstryxToolCall> calls,\n'
      '  bool cited,\n'
      '});\n'
      '\n'
      'class AiChatTemplate extends StatefulWidget {\n'
      '  const AiChatTemplate({super.key});\n'
      '\n'
      '  @override\n'
      '  State<AiChatTemplate> createState() => _AiChatTemplateState();\n'
      '}\n'
      '\n'
      'class _AiChatTemplateState extends State<AiChatTemplate> {\n'
      '  static const List<_Turn> _conversation = <_Turn>[\n'
      '    (\n'
      '      role: AstryxChatRole.user,\n'
      '      text: \'Why did the 14:02 deploy fail?\',\n'
      '      calls: <AstryxToolCall>[],\n'
      '      cited: false,\n'
      '    ),\n'
      '    (\n'
      '      role: AstryxChatRole.assistant,\n'
      '      text: \'\'\'\n'
      'The health check **timed out**. The scheduler took 41 seconds to bind its port\n'
      'and the check gives up at `30`.\n'
      '\n'
      '- Three services restarted before the rollback\n'
      '- The bind is the *real* problem — it used to take four seconds\n'
      '\n'
      '1. Raise the timeout to 60 seconds to stop the bleeding\n'
      '2. Look at the migration that ships with this release\n'
      '\'\'\',\n'
      '      calls: <AstryxToolCall>[\n'
      '        AstryxToolCall(\n'
      '          name: \'search_logs\',\n'
      '          summary: \'Searched 412 lines in deploy-log.txt\',\n'
      '          arguments: \'{"query": "bind", "limit": 500}\',\n'
      '          result: \'{"matches": 3, "first": "14:02:41"}\',\n'
      '        ),\n'
      '        AstryxToolCall(\n'
      '          name: \'read_file\',\n'
      '          summary: \'scheduler/health.md\',\n'
      '          result: \'timeout: 30s\',\n'
      '          language: \'yaml\',\n'
      '        ),\n'
      '      ],\n'
      '      cited: true,\n'
      '    ),\n'
      '  ];\n'
      '\n'
      '  final TextEditingController _draft = TextEditingController();\n'
      '  final List<_Turn> _turns = List<_Turn>.of(_conversation);\n'
      '\n'
      '  bool _generating = false;\n'
      '  bool _listening = false;\n'
      '  String _model = \'long\';\n'
      '\n'
      '  /// The prompts the empty state offers, and what a fresh screen starts from.\n'
      '  static const List<String> _suggestions = <String>[\n'
      '    \'Why did the 14:02 deploy fail?\',\n'
      '    \'Which service restarted most this week?\',\n'
      '    \'Summarise last night’s on-call\',\n'
      '  ];\n'
      '\n'
      '  @override\n'
      '  void dispose() {\n'
      '    _draft.dispose();\n'
      '    super.dispose();\n'
      '  }\n'
      '\n'
      '  void _send(String text) {\n'
      '    if (text.trim().isEmpty) return;\n'
      '    setState(() {\n'
      '      _turns.add((\n'
      '        role: AstryxChatRole.user,\n'
      '        text: text.trim(),\n'
      '        calls: <AstryxToolCall>[],\n'
      '        cited: false,\n'
      '      ));\n'
      '      _draft.clear();\n'
      '      _generating = true;\n'
      '    });\n'
      '  }\n'
      '\n'
      '  /// Stands in for the answer arriving. A real screen appends tokens here.\n'
      '  void _finish() {\n'
      '    setState(() {\n'
      '      _generating = false;\n'
      '      _turns.add((\n'
      '        role: AstryxChatRole.assistant,\n'
      '        text:\n'
      '            \'This example does not actually answer — but this is where the \'\n'
      '            \'streamed reply lands.\',\n'
      '        calls: <AstryxToolCall>[],\n'
      '        cited: false,\n'
      '      ));\n'
      '    });\n'
      '  }\n'
      '\n'
      '  @override\n'
      '  Widget build(BuildContext context) {\n'
      '    // Bounded height: the chat layout divides what it is given between the\n'
      '    // transcript and the composer, and a column hands its child an unbounded\n'
      '    // height it cannot divide.\n'
      '    return SizedBox(\n'
      '      height: 560,\n'
      '      child: AstryxLayout(\n'
      '        padding: AstryxSpacingToken.spacing0,\n'
      '        // The transcript owns its own scrolling — it opens at the newest turn\n'
      '        // and stays there as turns arrive. Two scroll views is one too many.\n'
      '        scrollable: false,\n'
      '        header: _ChatHeader(\n'
      '          turns: _turns.length,\n'
      '          model: _model,\n'
      '          onModelChanged: (value) => setState(() => _model = value ?? _model),\n'
      '          onNew: () => setState(() {\n'
      '            _turns.clear();\n'
      '            _generating = false;\n'
      '          }),\n'
      '        ),\n'
      '        child: AstryxChatLayout(\n'
      '          messages: <Widget>[\n'
      '            for (final turn in _turns) _turnMessage(turn),\n'
      '            if (_generating)\n'
      '              AstryxChatMessage(\n'
      '                author: \'Assistant\',\n'
      '                child: AstryxHStack(\n'
      '                  gap: AstryxSpacingToken.spacing2,\n'
      '                  children: <Widget>[\n'
      '                    const AstryxSpinner(\n'
      '                      size: AstryxSpinnerSize.sm,\n'
      '                      label: \'Thinking\',\n'
      '                    ),\n'
      '                    AstryxButton(\n'
      '                      label: \'Skip the wait\',\n'
      '                      variant: AstryxButtonVariant.ghost,\n'
      '                      size: AstryxButtonSize.sm,\n'
      '                      onPressed: _finish,\n'
      '                    ),\n'
      '                  ],\n'
      '                ),\n'
      '              ),\n'
      '          ],\n'
      '          empty: AstryxCenter(\n'
      '            maxWidth: 460,\n'
      '            child: AstryxVStack(\n'
      '              gap: AstryxSpacingToken.spacing4,\n'
      '              align: AstryxStackAlign.center,\n'
      '              children: <Widget>[\n'
      '                const AstryxHeading(\n'
      '                  \'Ask about a deploy\',\n'
      '                  justify: AstryxTextJustify.center,\n'
      '                ),\n'
      '                const AstryxText(\n'
      '                  \'Logs, timings and health checks for the last 30 days.\',\n'
      '                  color: AstryxTextColor.secondary,\n'
      '                  justify: AstryxTextJustify.center,\n'
      '                ),\n'
      '                // Suggestions are buttons, not placeholder text: a prompt you\n'
      '                // have to retype is a prompt nobody uses.\n'
      '                AstryxHStack(\n'
      '                  gap: AstryxSpacingToken.spacing2,\n'
      '                  wrap: true,\n'
      '                  runGap: AstryxSpacingToken.spacing2,\n'
      '                  justify: AstryxStackJustify.center,\n'
      '                  children: <Widget>[\n'
      '                    for (final prompt in _suggestions)\n'
      '                      AstryxButton(\n'
      '                        label: prompt,\n'
      '                        size: AstryxButtonSize.sm,\n'
      '                        onPressed: () => _send(prompt),\n'
      '                      ),\n'
      '                  ],\n'
      '                ),\n'
      '              ],\n'
      '            ),\n'
      '          ),\n'
      '          composer: AstryxChatComposer(\n'
      '            controller: _draft,\n'
      '            generating: _generating,\n'
      '            placeholder: \'Ask about a deploy, a service or an incident\',\n'
      '            onSubmit: _send,\n'
      '            onStop: () => setState(() => _generating = false),\n'
      '            leading: <Widget>[\n'
      '              AstryxIconButton(\n'
      '                icon: AstryxIconName.copy,\n'
      '                label: \'Attach a file\',\n'
      '                variant: AstryxButtonVariant.ghost,\n'
      '                onPressed: () {},\n'
      '              ),\n'
      '            ],\n'
      '            trailing: <Widget>[\n'
      '              AstryxChatDictationButton(\n'
      '                listening: _listening,\n'
      '                onStart: () => setState(() => _listening = true),\n'
      '                onStop: () => setState(() => _listening = false),\n'
      '              ),\n'
      '            ],\n'
      '            footer: const AstryxText(\n'
      '              \'Answers cite the logs they came from. Check anything you are \'\n'
      '              \'about to act on.\',\n'
      '              type: AstryxTextType.supporting,\n'
      '              color: AstryxTextColor.secondary,\n'
      '            ),\n'
      '          ),\n'
      '        ),\n'
      '      ),\n'
      '    );\n'
      '  }\n'
      '\n'
      '  /// One turn, drawn according to who said it.\n'
      '  ///\n'
      '  /// The user\'s words are their own — plain text, never markdown, because\n'
      '  /// rendering what somebody typed changes what they said. The assistant\'s\n'
      '  /// answer is markdown, which is the format it arrives in.\n'
      '  Widget _turnMessage(_Turn turn) {\n'
      '    if (turn.role == AstryxChatRole.user) {\n'
      '      return AstryxChatMessage(\n'
      '        role: AstryxChatRole.user,\n'
      '        author: \'You\',\n'
      '        child: AstryxText(turn.text),\n'
      '      );\n'
      '    }\n'
      '\n'
      '    return AstryxChatMessage(\n'
      '      author: \'Assistant\',\n'
      '      timestamp: AstryxTimestamp(\n'
      '        DateTime.utc(2026, 8, 12, 14, 4),\n'
      '        format: AstryxTimestampFormat.time,\n'
      '        type: AstryxTextType.supporting,\n'
      '        color: AstryxTextColor.secondary,\n'
      '      ),\n'
      '      actions: <Widget>[\n'
      '        AstryxIconButton(\n'
      '          icon: AstryxIconName.copy,\n'
      '          label: \'Copy this answer\',\n'
      '          variant: AstryxButtonVariant.ghost,\n'
      '          size: AstryxButtonSize.sm,\n'
      '          onPressed: () {},\n'
      '        ),\n'
      '        AstryxIconButton(\n'
      '          icon: AstryxIconName.arrowUp,\n'
      '          label: \'Good answer\',\n'
      '          variant: AstryxButtonVariant.ghost,\n'
      '          size: AstryxButtonSize.sm,\n'
      '          onPressed: () {},\n'
      '        ),\n'
      '        AstryxIconButton(\n'
      '          icon: AstryxIconName.arrowDown,\n'
      '          label: \'Bad answer\',\n'
      '          variant: AstryxButtonVariant.ghost,\n'
      '          size: AstryxButtonSize.sm,\n'
      '          onPressed: () {},\n'
      '        ),\n'
      '      ],\n'
      '      footer: turn.calls.isEmpty\n'
      '          ? null\n'
      '          : AstryxChatToolCalls(calls: turn.calls),\n'
      '      child: AstryxVStack(\n'
      '        gap: AstryxSpacingToken.spacing3,\n'
      '        align: AstryxStackAlign.stretch,\n'
      '        children: <Widget>[\n'
      '          AstryxMarkdown(turn.text, onLinkPressed: (_) {}),\n'
      '          if (turn.cited)\n'
      '            Text.rich(\n'
      '              TextSpan(\n'
      '                children: <InlineSpan>[\n'
      '                  const TextSpan(text: \'From \'),\n'
      '                  AstryxCitation.span(\n'
      '                    1,\n'
      '                    source: \'scheduler/health.md\',\n'
      '                    onPressed: () {},\n'
      '                  ),\n'
      '                  const TextSpan(text: \' and \'),\n'
      '                  AstryxCitation.span(\n'
      '                    2,\n'
      '                    source: \'deploy-log.txt#L412\',\n'
      '                    onPressed: () {},\n'
      '                  ),\n'
      '                  const TextSpan(text: \'.\'),\n'
      '                ],\n'
      '              ),\n'
      '            ),\n'
      '        ],\n'
      '      ),\n'
      '    );\n'
      '  }\n'
      '}\n'
      '\n'
      '/// The band above the transcript: which model, and a way out of this thread.\n'
      'class _ChatHeader extends StatelessWidget {\n'
      '  const _ChatHeader({\n'
      '    required this.turns,\n'
      '    required this.model,\n'
      '    required this.onModelChanged,\n'
      '    required this.onNew,\n'
      '  });\n'
      '\n'
      '  final int turns;\n'
      '  final String model;\n'
      '  final ValueChanged<String?> onModelChanged;\n'
      '  final VoidCallback onNew;\n'
      '\n'
      '  @override\n'
      '  Widget build(BuildContext context) {\n'
      '    // Wrapping, so the title and the controls take a line each rather than\n'
      '    // fighting over one. `Flexible` alone cannot save this row: the model\n'
      '    // selector and the New chat button have a width they cannot go under, and\n'
      '    // below about 500 logical pixels there is no share of the line that leaves\n'
      '    // the heading anything to say.\n'
      '    return AstryxHStack(\n'
      '      gap: AstryxSpacingToken.spacing3,\n'
      '      justify: AstryxStackJustify.between,\n'
      '      mainAxisSize: MainAxisSize.max,\n'
      '      wrap: true,\n'
      '      runGap: AstryxSpacingToken.spacing2,\n'
      '      children: <Widget>[\n'
      '        AstryxHStack(\n'
      '          gap: AstryxSpacingToken.spacing2,\n'
      '          children: <Widget>[\n'
      '            const Flexible(\n'
      '              child: AstryxHeading(\'Why did 14:02 fail?\', level: 1),\n'
      '            ),\n'
      '            AstryxBadge(\'\$turns turns\'),\n'
      '          ],\n'
      '        ),\n'
      '        AstryxHStack(\n'
      '          gap: AstryxSpacingToken.spacing2,\n'
      '          children: <Widget>[\n'
      '            AstryxSelector<String>(\n'
      '              label: \'Model\',\n'
      '              labelHidden: true,\n'
      '              value: model,\n'
      '              // A field stretches to whatever it is given, and a hugging row\n'
      '              // gives it nothing to stretch to — so the width is stated here.\n'
      '              width: 168,\n'
      '              size: AstryxInputSize.sm,\n'
      '              onChanged: onModelChanged,\n'
      '              options: const <AstryxSelectorOption<String>>[\n'
      '                AstryxSelectorOption(value: \'fast\', label: \'Fast\'),\n'
      '                AstryxSelectorOption(value: \'long\', label: \'Long context\'),\n'
      '              ],\n'
      '            ),\n'
      '            AstryxButton(\n'
      '              label: \'New chat\',\n'
      '              size: AstryxButtonSize.sm,\n'
      '              onPressed: onNew,\n'
      '            ),\n'
      '          ],\n'
      '        ),\n'
      '      ],\n'
      '    );\n'
      '  }\n'
      '}\n',
  // examples/template_chat_examples.dart
  'template_ai_chat_landing':
      '/// One offered prompt, and what it is for.\n'
      'typedef Prompt = ({String group, String label, String text});\n'
      '\n'
      'class AiChatLandingTemplate extends StatefulWidget {\n'
      '  const AiChatLandingTemplate({super.key});\n'
      '\n'
      '  @override\n'
      '  State<AiChatLandingTemplate> createState() => _AiChatLandingTemplateState();\n'
      '}\n'
      '\n'
      'class _AiChatLandingTemplateState extends State<AiChatLandingTemplate> {\n'
      '  static const List<Prompt> _prompts = <Prompt>[\n'
      '    (\n'
      '      group: \'Diagnose\',\n'
      '      label: \'Why did the last deploy fail?\',\n'
      '      text: \'Why did the 14:02 deploy fail?\',\n'
      '    ),\n'
      '    (\n'
      '      group: \'Diagnose\',\n'
      '      label: \'What changed before the latency spike?\',\n'
      '      text: \'What changed in the hour before the 13:40 latency spike?\',\n'
      '    ),\n'
      '    (\n'
      '      group: \'Summarise\',\n'
      '      label: \'Last night’s on-call\',\n'
      '      text: \'Summarise last night’s on-call in five bullets.\',\n'
      '    ),\n'
      '    (\n'
      '      group: \'Summarise\',\n'
      '      label: \'This week’s incidents\',\n'
      '      text: \'Summarise every incident opened this week, worst first.\',\n'
      '    ),\n'
      '    (\n'
      '      group: \'Write\',\n'
      '      label: \'Draft a post-mortem\',\n'
      '      text: \'Draft a post-mortem for INC-4102 from the timeline.\',\n'
      '    ),\n'
      '  ];\n'
      '\n'
      '  static const List<String> _recent = <String>[\n'
      '    \'Why did 14:02 fail?\',\n'
      '    \'Scheduler bind times, last 30 days\',\n'
      '    \'Who owns the artifacts service?\',\n'
      '  ];\n'
      '\n'
      '  final TextEditingController _draft = TextEditingController();\n'
      '\n'
      '  /// The one turn the conversation has, once it has one.\n'
      '  String? _asked;\n'
      '\n'
      '  @override\n'
      '  void dispose() {\n'
      '    _draft.dispose();\n'
      '    super.dispose();\n'
      '  }\n'
      '\n'
      '  void _send(String text) {\n'
      '    if (text.trim().isEmpty) return;\n'
      '    setState(() {\n'
      '      _asked = text.trim();\n'
      '      _draft.clear();\n'
      '    });\n'
      '  }\n'
      '\n'
      '  @override\n'
      '  Widget build(BuildContext context) {\n'
      '    return SizedBox(\n'
      '      height: 560,\n'
      '      child: _asked == null ? _landing(context) : _conversation(context),\n'
      '    );\n'
      '  }\n'
      '\n'
      '  /// Before the first turn: the composer is the middle of the page.\n'
      '  ///\n'
      '  /// That is the whole difference between this and the `empty:` slot of\n'
      '  /// [AiChatTemplate]. A slot sits above a composer pinned to the bottom; a\n'
      '  /// landing puts the composer where the reader is already looking, because\n'
      '  /// there is no transcript for it to be beneath.\n'
      '  Widget _landing(BuildContext context) {\n'
      '    final groups = <String>{for (final prompt in _prompts) prompt.group};\n'
      '\n'
      '    return SingleChildScrollView(\n'
      '      child: AstryxCenter(\n'
      '        maxWidth: 680,\n'
      '        child: AstryxVStack(\n'
      '          gap: AstryxSpacingToken.spacing6,\n'
      '          align: AstryxStackAlign.stretch,\n'
      '          children: <Widget>[\n'
      '            const AstryxVStack(\n'
      '              gap: AstryxSpacingToken.spacing2,\n'
      '              align: AstryxStackAlign.center,\n'
      '              children: <Widget>[\n'
      '                AstryxHeading(\n'
      '                  \'What do you want to know?\',\n'
      '                  level: 1,\n'
      '                  type: AstryxHeadingType.display3,\n'
      '                  justify: AstryxTextJustify.center,\n'
      '                ),\n'
      '                AstryxText(\n'
      '                  \'Logs, timings and health checks for the last 30 days.\',\n'
      '                  type: AstryxTextType.large,\n'
      '                  color: AstryxTextColor.secondary,\n'
      '                  justify: AstryxTextJustify.center,\n'
      '                ),\n'
      '              ],\n'
      '            ),\n'
      '            // The same widget the conversation ends up using. A landing that\n'
      '            // drew its own input would be a second field with its own\n'
      '            // shortcuts, its own send button and its own bugs.\n'
      '            AstryxChatComposer(\n'
      '              controller: _draft,\n'
      '              placeholder: \'Ask about a deploy, a service or an incident\',\n'
      '              label: \'Ask a question\',\n'
      '              onSubmit: _send,\n'
      '              leading: <Widget>[\n'
      '                AstryxIconButton(\n'
      '                  icon: AstryxIconName.copy,\n'
      '                  label: \'Attach a file\',\n'
      '                  variant: AstryxButtonVariant.ghost,\n'
      '                  onPressed: () {},\n'
      '                ),\n'
      '              ],\n'
      '              footer: const AstryxText(\n'
      '                \'Answers cite the logs they came from. Check anything you are \'\n'
      '                \'about to act on.\',\n'
      '                type: AstryxTextType.supporting,\n'
      '                color: AstryxTextColor.secondary,\n'
      '              ),\n'
      '            ),\n'
      '            // Suggestions are grouped, and every one of them is a button that\n'
      '            // sends itself. A prompt the reader has to retype is a prompt\n'
      '            // nobody uses; a wall of twelve ungrouped ones is a menu nobody\n'
      '            // reads.\n'
      '            for (final group in groups)\n'
      '              AstryxSection(\n'
      '                title: group,\n'
      '                level: 2,\n'
      '                gap: AstryxSpacingToken.spacing2,\n'
      '                child: AstryxHStack(\n'
      '                  gap: AstryxSpacingToken.spacing2,\n'
      '                  wrap: true,\n'
      '                  runGap: AstryxSpacingToken.spacing2,\n'
      '                  children: <Widget>[\n'
      '                    for (final prompt in _prompts.where(\n'
      '                      (prompt) => prompt.group == group,\n'
      '                    ))\n'
      '                      AstryxButton(\n'
      '                        label: prompt.label,\n'
      '                        size: AstryxButtonSize.sm,\n'
      '                        onPressed: () => _send(prompt.text),\n'
      '                      ),\n'
      '                  ],\n'
      '                ),\n'
      '              ),\n'
      '            const AstryxDivider(),\n'
      '            AstryxSection(\n'
      '              title: \'Recent\',\n'
      '              level: 2,\n'
      '              gap: AstryxSpacingToken.spacing2,\n'
      '              child: AstryxList(\n'
      '                label: \'Recent conversations\',\n'
      '                density: AstryxItemDensity.compact,\n'
      '                showDividers: true,\n'
      '                children: <Widget>[\n'
      '                  for (final thread in _recent)\n'
      '                    AstryxItem(\n'
      '                      label: thread,\n'
      '                      leading: const AstryxIcon(AstryxIconName.clock),\n'
      '                      trailing: const AstryxIcon(AstryxIconName.chevronRight),\n'
      '                      onPressed: () => _send(thread),\n'
      '                    ),\n'
      '                ],\n'
      '              ),\n'
      '            ),\n'
      '          ],\n'
      '        ),\n'
      '      ),\n'
      '    );\n'
      '  }\n'
      '\n'
      '  /// After the first turn: the same composer, now pinned under a transcript.\n'
      '  Widget _conversation(BuildContext context) {\n'
      '    return AstryxLayout(\n'
      '      padding: AstryxSpacingToken.spacing0,\n'
      '      scrollable: false,\n'
      '      header: AstryxHStack(\n'
      '        gap: AstryxSpacingToken.spacing3,\n'
      '        justify: AstryxStackJustify.between,\n'
      '        mainAxisSize: MainAxisSize.max,\n'
      '        children: <Widget>[\n'
      '          const Flexible(child: AstryxHeading(\'Atlas assistant\', level: 1)),\n'
      '          AstryxButton(\n'
      '            label: \'New chat\',\n'
      '            size: AstryxButtonSize.sm,\n'
      '            onPressed: () => setState(() => _asked = null),\n'
      '          ),\n'
      '        ],\n'
      '      ),\n'
      '      child: AstryxChatLayout(\n'
      '        messages: <Widget>[\n'
      '          AstryxChatMessage(\n'
      '            role: AstryxChatRole.user,\n'
      '            author: \'You\',\n'
      '            child: AstryxText(_asked!),\n'
      '          ),\n'
      '          const AstryxChatMessage(\n'
      '            author: \'Assistant\',\n'
      '            child: AstryxText(\n'
      '              \'The landing has handed over. From here the screen is the \'\n'
      '              \'ai_chat template — same composer, now at the bottom of a \'\n'
      '              \'transcript that owns its own scrolling.\',\n'
      '            ),\n'
      '          ),\n'
      '        ],\n'
      '        composer: AstryxChatComposer(\n'
      '          controller: _draft,\n'
      '          placeholder: \'Ask a follow-up\',\n'
      '          onSubmit: _send,\n'
      '        ),\n'
      '      ),\n'
      '    );\n'
      '  }\n'
      '}\n',
  // examples/template_commerce_examples.dart
  'template_product_detail':
      'class ProductDetailTemplate extends StatefulWidget {\n'
      '  const ProductDetailTemplate({super.key});\n'
      '\n'
      '  @override\n'
      '  State<ProductDetailTemplate> createState() => _ProductDetailTemplateState();\n'
      '}\n'
      '\n'
      'class _ProductDetailTemplateState extends State<ProductDetailTemplate> {\n'
      '  static const List<String> _shots = <String>[\n'
      '    \'Three-quarter view\',\n'
      '    \'Sole detail\',\n'
      '    \'Heel counter\',\n'
      '    \'In the box\',\n'
      '  ];\n'
      '\n'
      '  /// Sizes, and the ones nobody can buy today.\n'
      '  ///\n'
      '  /// Out of stock is `enabled: false` on the option rather than a missing\n'
      '  /// option: a size that vanishes leaves the reader wondering whether it ever\n'
      '  /// existed, and it is the answer to "do you make my size at all".\n'
      '  static const List<AstryxRadioOption<String>> _sizes =\n'
      '      <AstryxRadioOption<String>>[\n'
      '        AstryxRadioOption(value: \'8\', label: \'UK 8\'),\n'
      '        AstryxRadioOption(value: \'9\', label: \'UK 9\'),\n'
      '        AstryxRadioOption(\n'
      '          value: \'10\',\n'
      '          label: \'UK 10\',\n'
      '          description: \'Back in stock on 3 September\',\n'
      '          enabled: false,\n'
      '        ),\n'
      '        AstryxRadioOption(value: \'11\', label: \'UK 11\'),\n'
      '      ];\n'
      '\n'
      '  static const int _price = 12500;\n'
      '\n'
      '  int _shot = 0;\n'
      '  String? _size;\n'
      '  num? _quantity = 1;\n'
      '  bool _submitted = false;\n'
      '\n'
      '  final AstryxOverlayController _viewer = AstryxOverlayController();\n'
      '\n'
      '  @override\n'
      '  void dispose() {\n'
      '    _viewer.dispose();\n'
      '    super.dispose();\n'
      '  }\n'
      '\n'
      '  /// Nothing is red until the reader has tried to add to the basket.\n'
      '  AstryxFieldStatus? get _sizeStatus {\n'
      '    if (!_submitted || _size != null) return null;\n'
      '    return const AstryxFieldStatus.error(\'Choose a size\');\n'
      '  }\n'
      '\n'
      '  void _add(BuildContext context) {\n'
      '    setState(() => _submitted = true);\n'
      '    if (_size == null) return;\n'
      '\n'
      '    AstryxToastScope.of(context).show(\n'
      '      AstryxToast(\n'
      '        message: \'Added \$_quantity × Trail Runner GTX, UK \$_size to the basket\',\n'
      '      ),\n'
      '    );\n'
      '  }\n'
      '\n'
      '  @override\n'
      '  Widget build(BuildContext context) {\n'
      '    return AstryxVStack(\n'
      '      gap: AstryxSpacingToken.spacing5,\n'
      '      align: AstryxStackAlign.stretch,\n'
      '      children: <Widget>[\n'
      '        AstryxBreadcrumbs(\n'
      '          label: \'You are here\',\n'
      '          items: <AstryxBreadcrumb>[\n'
      '            AstryxBreadcrumb(label: \'Shop\', onPressed: () {}),\n'
      '            AstryxBreadcrumb(label: \'Footwear\', onPressed: () {}),\n'
      '            AstryxBreadcrumb(label: \'Trail\', onPressed: () {}),\n'
      '            const AstryxBreadcrumb(label: \'Trail Runner GTX\'),\n'
      '          ],\n'
      '        ),\n'
      '        LayoutBuilder(\n'
      '          builder: (context, constraints) {\n'
      '            final wide = constraints.maxWidth >= 720;\n'
      '            final media = _Media(\n'
      '              shots: _shots,\n'
      '              index: _shot,\n'
      '              onSelected: (index) => setState(() => _shot = index),\n'
      '              viewer: _viewer,\n'
      '            );\n'
      '            final details = _details(context);\n'
      '\n'
      '            // One column below 720, because a picture and a form side by side\n'
      '            // at 300 apiece is two things neither of which can be used.\n'
      '            if (!wide) {\n'
      '              return AstryxVStack(\n'
      '                gap: AstryxSpacingToken.spacing5,\n'
      '                align: AstryxStackAlign.stretch,\n'
      '                children: <Widget>[media, details],\n'
      '              );\n'
      '            }\n'
      '\n'
      '            return AstryxHStack(\n'
      '              gap: AstryxSpacingToken.spacing6,\n'
      '              align: AstryxStackAlign.start,\n'
      '              mainAxisSize: MainAxisSize.max,\n'
      '              children: <Widget>[\n'
      '                Expanded(child: media),\n'
      '                SizedBox(width: 340, child: details),\n'
      '              ],\n'
      '            );\n'
      '          },\n'
      '        ),\n'
      '      ],\n'
      '    );\n'
      '  }\n'
      '\n'
      '  /// The half of the screen that is words: what it costs, what to choose, and\n'
      '  /// the one button that spends money.\n'
      '  Widget _details(BuildContext context) {\n'
      '    return AstryxVStack(\n'
      '      gap: AstryxSpacingToken.spacing4,\n'
      '      align: AstryxStackAlign.stretch,\n'
      '      children: <Widget>[\n'
      '        AstryxVStack(\n'
      '          gap: AstryxSpacingToken.spacing2,\n'
      '          align: AstryxStackAlign.stretch,\n'
      '          children: <Widget>[\n'
      '            const AstryxHeading(\'Trail Runner GTX\', level: 1),\n'
      '            // Both rows wrap. A details column is narrow by design, and a\n'
      '            // price beside a was-price is exactly the pair that stops fitting\n'
      '            // first — a spreading row here would overflow rather than reflow.\n'
      '            AstryxHStack(\n'
      '              gap: AstryxSpacingToken.spacing2,\n'
      '              wrap: true,\n'
      '              runGap: AstryxSpacingToken.spacing1,\n'
      '              children: <Widget>[\n'
      '                // Figures are `tabularNumbers`, and the was-price is a\n'
      '                // separate node rather than a strikethrough on the same one:\n'
      '                // a screen reader reading "£125.00 £150.00" with no\n'
      '                // explanation has said the wrong thing twice.\n'
      '                AstryxText(\n'
      '                  money(_price),\n'
      '                  type: AstryxTextType.large,\n'
      '                  weight: AstryxTextWeight.semibold,\n'
      '                  tabularNumbers: true,\n'
      '                ),\n'
      '                AstryxText(\n'
      '                  \'\${money(15000)} before the discount\',\n'
      '                  type: AstryxTextType.supporting,\n'
      '                  color: AstryxTextColor.secondary,\n'
      '                  tabularNumbers: true,\n'
      '                ),\n'
      '              ],\n'
      '            ),\n'
      '            const AstryxHStack(\n'
      '              gap: AstryxSpacingToken.spacing2,\n'
      '              wrap: true,\n'
      '              runGap: AstryxSpacingToken.spacing1,\n'
      '              children: <Widget>[\n'
      '                AstryxBadge(\n'
      '                  \'In stock\',\n'
      '                  variant: AstryxBadgeVariant.success,\n'
      '                  icon: AstryxIcon(AstryxIconName.success),\n'
      '                ),\n'
      '                AstryxText(\n'
      '                  \'Free delivery over £50\',\n'
      '                  type: AstryxTextType.supporting,\n'
      '                  color: AstryxTextColor.secondary,\n'
      '                ),\n'
      '              ],\n'
      '            ),\n'
      '          ],\n'
      '        ),\n'
      '        const AstryxDivider(),\n'
      '        // Seven options or fewer, and all of them worth seeing at once, so a\n'
      '        // radio list rather than a selector. A size hidden behind a dropdown\n'
      '        // is a size the reader has to go looking for.\n'
      '        AstryxRadioList<String>(\n'
      '          label: \'Size\',\n'
      '          value: _size,\n'
      '          status: _sizeStatus,\n'
      '          required: true,\n'
      '          orientation: AstryxRadioListOrientation.horizontal,\n'
      '          onChanged: (value) => setState(() => _size = value),\n'
      '          options: _sizes,\n'
      '        ),\n'
      '        AstryxNumberInput(\n'
      '          label: \'Quantity\',\n'
      '          value: _quantity,\n'
      '          min: 1,\n'
      '          max: 6,\n'
      '          integerOnly: true,\n'
      '          width: 140,\n'
      '          onChanged: (value) => setState(() => _quantity = value),\n'
      '        ),\n'
      '        AstryxButton(\n'
      '          label: \'Add to basket · \${money(_price * (_quantity ?? 1).toInt())}\',\n'
      '          variant: AstryxButtonVariant.primary,\n'
      '          size: AstryxButtonSize.lg,\n'
      '          onPressed: () => _add(context),\n'
      '        ),\n'
      '        // Everything a reader might want and most will not: collapsed, in one\n'
      '        // group, so the page below the button stays short enough to end.\n'
      '        const AstryxCollapsibleGroup(\n'
      '          children: <AstryxCollapsible>[\n'
      '            AstryxCollapsible(\n'
      '              title: \'Details\',\n'
      '              initiallyExpanded: true,\n'
      '              child: AstryxText(\n'
      '                \'A waterproof trail shoe with a 6 mm drop and a rock plate. \'\n'
      '                \'Weighs 284 g in a UK 9.\',\n'
      '              ),\n'
      '            ),\n'
      '            AstryxCollapsible(\n'
      '              title: \'Delivery\',\n'
      '              child: AstryxText(\n'
      '                \'Next working day to the UK if ordered before 3pm. Two to \'\n'
      '                \'four days to the EU.\',\n'
      '              ),\n'
      '            ),\n'
      '            AstryxCollapsible(\n'
      '              title: \'Returns\',\n'
      '              child: AstryxText(\n'
      '                \'Sixty days, worn outdoors or not. Return postage is on us.\',\n'
      '              ),\n'
      '            ),\n'
      '          ],\n'
      '        ),\n'
      '      ],\n'
      '    );\n'
      '  }\n'
      '}\n'
      '\n'
      '/// The half of the screen that is pictures: one large, the rest as a strip.\n'
      'class _Media extends StatelessWidget {\n'
      '  const _Media({\n'
      '    required this.shots,\n'
      '    required this.index,\n'
      '    required this.onSelected,\n'
      '    required this.viewer,\n'
      '  });\n'
      '\n'
      '  final List<String> shots;\n'
      '  final int index;\n'
      '  final ValueChanged<int> onSelected;\n'
      '  final AstryxOverlayController viewer;\n'
      '\n'
      '  @override\n'
      '  Widget build(BuildContext context) {\n'
      '    return AstryxVStack(\n'
      '      gap: AstryxSpacingToken.spacing3,\n'
      '      align: AstryxStackAlign.stretch,\n'
      '      children: <Widget>[\n'
      '        AstryxCard(\n'
      '          padding: AstryxSpacingToken.spacing0,\n'
      '          semanticsLabel: \'\${shots[index]} — open the full-size viewer\',\n'
      '          onPressed: viewer.show,\n'
      '          child: AstryxAspectRatio(\n'
      '            ratio: 4 / 3,\n'
      '            semanticsLabel: shots[index],\n'
      '            child: Center(\n'
      '              child: AstryxText(\n'
      '                shots[index],\n'
      '                color: AstryxTextColor.secondary,\n'
      '              ),\n'
      '            ),\n'
      '          ),\n'
      '        ),\n'
      '        AstryxHStack(\n'
      '          gap: AstryxSpacingToken.spacing2,\n'
      '          wrap: true,\n'
      '          runGap: AstryxSpacingToken.spacing2,\n'
      '          children: <Widget>[\n'
      '            for (var i = 0; i < shots.length; i++)\n'
      '              AstryxThumbnail(\n'
      '                label: shots[i],\n'
      '                icon: AstryxIconName.viewColumns,\n'
      '                width: 76,\n'
      '                selected: i == index,\n'
      '                onPressed: () => onSelected(i),\n'
      '              ),\n'
      '          ],\n'
      '        ),\n'
      '        AstryxLightbox(\n'
      '          controller: viewer,\n'
      '          initialIndex: index,\n'
      '          label: \'Trail Runner GTX\',\n'
      '          items: <AstryxLightboxItem>[\n'
      '            for (final shot in shots)\n'
      '              AstryxLightboxItem(\n'
      '                label: shot,\n'
      '                caption: \'Trail Runner GTX · \$shot\',\n'
      '                child: SizedBox(\n'
      '                  width: 620,\n'
      '                  child: AstryxAspectRatio(\n'
      '                    ratio: 4 / 3,\n'
      '                    background: AstryxColorToken.backgroundCard,\n'
      '                    child: Center(\n'
      '                      child: AstryxText(\n'
      '                        shot,\n'
      '                        color: AstryxTextColor.secondary,\n'
      '                      ),\n'
      '                    ),\n'
      '                  ),\n'
      '                ),\n'
      '              ),\n'
      '          ],\n'
      '        ),\n'
      '      ],\n'
      '    );\n'
      '  }\n'
      '}\n',
  // examples/template_commerce_examples.dart
  'template_product_gallery':
      '/// One product on the wall.\n'
      'typedef Product = ({\n'
      '  String name,\n'
      '  String category,\n'
      '  int price,\n'
      '  double rating,\n'
      '  bool inStock,\n'
      '});\n'
      '\n'
      'class ProductGalleryTemplate extends StatefulWidget {\n'
      '  const ProductGalleryTemplate({super.key});\n'
      '\n'
      '  @override\n'
      '  State<ProductGalleryTemplate> createState() => _ProductGalleryTemplateState();\n'
      '}\n'
      '\n'
      'class _ProductGalleryTemplateState extends State<ProductGalleryTemplate> {\n'
      '  static const List<Product> _catalogue = <Product>[\n'
      '    (\n'
      '      name: \'Trail Runner GTX\',\n'
      '      category: \'Footwear\',\n'
      '      price: 12500,\n'
      '      rating: 4.6,\n'
      '      inStock: true,\n'
      '    ),\n'
      '    (\n'
      '      name: \'Fell Shoe 3\',\n'
      '      category: \'Footwear\',\n'
      '      price: 9800,\n'
      '      rating: 4.2,\n'
      '      inStock: true,\n'
      '    ),\n'
      '    (\n'
      '      name: \'Approach Mid\',\n'
      '      category: \'Footwear\',\n'
      '      price: 15900,\n'
      '      rating: 4.8,\n'
      '      inStock: false,\n'
      '    ),\n'
      '    (\n'
      '      name: \'Windshell 40\',\n'
      '      category: \'Outerwear\',\n'
      '      price: 8400,\n'
      '      rating: 4.1,\n'
      '      inStock: true,\n'
      '    ),\n'
      '    (\n'
      '      name: \'Hardshell Pro\',\n'
      '      category: \'Outerwear\',\n'
      '      price: 24000,\n'
      '      rating: 4.9,\n'
      '      inStock: true,\n'
      '    ),\n'
      '    (\n'
      '      name: \'Merino Base\',\n'
      '      category: \'Layers\',\n'
      '      price: 5200,\n'
      '      rating: 4.4,\n'
      '      inStock: true,\n'
      '    ),\n'
      '    (\n'
      '      name: \'Grid Fleece\',\n'
      '      category: \'Layers\',\n'
      '      price: 6900,\n'
      '      rating: 4.0,\n'
      '      inStock: false,\n'
      '    ),\n'
      '    (\n'
      '      name: \'Summit Pack 32\',\n'
      '      category: \'Packs\',\n'
      '      price: 11000,\n'
      '      rating: 4.5,\n'
      '      inStock: true,\n'
      '    ),\n'
      '  ];\n'
      '\n'
      '  final TextEditingController _query = TextEditingController();\n'
      '\n'
      '  Set<String> _categories = <String>{};\n'
      '  bool _inStockOnly = false;\n'
      '  (num, num) _priceRange = (0, 250);\n'
      '  String _sort = \'popular\';\n'
      '\n'
      '  @override\n'
      '  void initState() {\n'
      '    super.initState();\n'
      '    _query.addListener(() => setState(() {}));\n'
      '  }\n'
      '\n'
      '  @override\n'
      '  void dispose() {\n'
      '    _query.dispose();\n'
      '    super.dispose();\n'
      '  }\n'
      '\n'
      '  /// The wall does not filter itself.\n'
      '  ///\n'
      '  /// Filtering here, in the caller, is what lets the empty state tell "nothing\n'
      '  /// matched" from "nothing to sell" — and those two need different words and\n'
      '  /// a different way out.\n'
      '  List<Product> get _results {\n'
      '    final text = _query.text.trim().toLowerCase();\n'
      '    final matches = _catalogue.where((product) {\n'
      '      final inCategory =\n'
      '          _categories.isEmpty || _categories.contains(product.category);\n'
      '      final inPrice =\n'
      '          product.price >= _priceRange.\$1 * 100 &&\n'
      '          product.price <= _priceRange.\$2 * 100;\n'
      '      final matchesText =\n'
      '          text.isEmpty || product.name.toLowerCase().contains(text);\n'
      '      return inCategory &&\n'
      '          inPrice &&\n'
      '          matchesText &&\n'
      '          (!_inStockOnly || product.inStock);\n'
      '    }).toList();\n'
      '\n'
      '    return matches..sort(switch (_sort) {\n'
      '      \'price_low\' => (a, b) => a.price.compareTo(b.price),\n'
      '      \'price_high\' => (a, b) => b.price.compareTo(a.price),\n'
      '      _ => (a, b) => b.rating.compareTo(a.rating),\n'
      '    });\n'
      '  }\n'
      '\n'
      '  void _clear() => setState(() {\n'
      '    _categories = <String>{};\n'
      '    _inStockOnly = false;\n'
      '    _priceRange = (0, 250);\n'
      '    _query.clear();\n'
      '  });\n'
      '\n'
      '  @override\n'
      '  Widget build(BuildContext context) {\n'
      '    final results = _results;\n'
      '\n'
      '    return SizedBox(\n'
      '      height: 620,\n'
      '      child: AstryxLayout(\n'
      '        panelSide: AstryxLayoutPanelSide.start,\n'
      '        panelWidth: 230,\n'
      '        header: AstryxHStack(\n'
      '          gap: AstryxSpacingToken.spacing3,\n'
      '          justify: AstryxStackJustify.between,\n'
      '          mainAxisSize: MainAxisSize.max,\n'
      '          wrap: true,\n'
      '          runGap: AstryxSpacingToken.spacing2,\n'
      '          children: <Widget>[\n'
      '            AstryxVStack(\n'
      '              gap: AstryxSpacingToken.spacing1,\n'
      '              children: <Widget>[\n'
      '                const AstryxHeading(\'Shop\', level: 1),\n'
      '                AstryxText(\n'
      '                  \'\${results.length} of \${_catalogue.length} products\',\n'
      '                  type: AstryxTextType.supporting,\n'
      '                  color: AstryxTextColor.secondary,\n'
      '                ),\n'
      '              ],\n'
      '            ),\n'
      '            AstryxHStack(\n'
      '              gap: AstryxSpacingToken.spacing2,\n'
      '              // Search and sort are 400 logical pixels of field between them,\n'
      '              // which is wider than a phone. They take a line each rather than\n'
      '              // one of them being pushed off the end.\n'
      '              wrap: true,\n'
      '              runGap: AstryxSpacingToken.spacing2,\n'
      '              children: <Widget>[\n'
      '                SizedBox(\n'
      '                  width: 220,\n'
      '                  child: AstryxTextInput(\n'
      '                    controller: _query,\n'
      '                    label: \'Search products\',\n'
      '                    labelHidden: true,\n'
      '                    placeholder: \'Search products\',\n'
      '                    showClear: true,\n'
      '                    size: AstryxInputSize.sm,\n'
      '                    leading: const AstryxIcon(\n'
      '                      AstryxIconName.search,\n'
      '                      size: AstryxIconSize.sm,\n'
      '                    ),\n'
      '                  ),\n'
      '                ),\n'
      '                // A selector, because it picks a value and shows the current\n'
      '                // one. A menu would perform an action and report nothing.\n'
      '                SizedBox(\n'
      '                  width: 180,\n'
      '                  child: AstryxSelector<String>(\n'
      '                    label: \'Sort by\',\n'
      '                    labelHidden: true,\n'
      '                    value: _sort,\n'
      '                    size: AstryxInputSize.sm,\n'
      '                    onChanged: (value) =>\n'
      '                        setState(() => _sort = value ?? _sort),\n'
      '                    options: const <AstryxSelectorOption<String>>[\n'
      '                      AstryxSelectorOption(\n'
      '                        value: \'popular\',\n'
      '                        label: \'Best rated\',\n'
      '                      ),\n'
      '                      AstryxSelectorOption(\n'
      '                        value: \'price_low\',\n'
      '                        label: \'Price: low to high\',\n'
      '                      ),\n'
      '                      AstryxSelectorOption(\n'
      '                        value: \'price_high\',\n'
      '                        label: \'Price: high to low\',\n'
      '                      ),\n'
      '                    ],\n'
      '                  ),\n'
      '                ),\n'
      '              ],\n'
      '            ),\n'
      '          ],\n'
      '        ),\n'
      '        panel: AstryxVStack(\n'
      '          gap: AstryxSpacingToken.spacing5,\n'
      '          align: AstryxStackAlign.stretch,\n'
      '          children: <Widget>[\n'
      '            AstryxHStack(\n'
      '              gap: AstryxSpacingToken.spacing2,\n'
      '              justify: AstryxStackJustify.between,\n'
      '              mainAxisSize: MainAxisSize.max,\n'
      '              children: <Widget>[\n'
      '                const Flexible(child: AstryxHeading(\'Filters\')),\n'
      '                AstryxButton(\n'
      '                  label: \'Clear\',\n'
      '                  variant: AstryxButtonVariant.ghost,\n'
      '                  size: AstryxButtonSize.sm,\n'
      '                  onPressed: _clear,\n'
      '                ),\n'
      '              ],\n'
      '            ),\n'
      '            AstryxCheckboxList<String>(\n'
      '              label: \'Category\',\n'
      '              values: _categories,\n'
      '              onChanged: (values) => setState(() => _categories = values),\n'
      '              options: const <AstryxCheckboxOption<String>>[\n'
      '                AstryxCheckboxOption(value: \'Footwear\', label: \'Footwear\'),\n'
      '                AstryxCheckboxOption(value: \'Outerwear\', label: \'Outerwear\'),\n'
      '                AstryxCheckboxOption(value: \'Layers\', label: \'Layers\'),\n'
      '                AstryxCheckboxOption(value: \'Packs\', label: \'Packs\'),\n'
      '              ],\n'
      '            ),\n'
      '            AstryxSlider.range(\n'
      '              label: \'Price\',\n'
      '              values: _priceRange,\n'
      '              max: 250,\n'
      '              step: 10,\n'
      '              formatValue: (value) => \'£\${value.round()}\',\n'
      '              onChanged: (values) => setState(() => _priceRange = values),\n'
      '            ),\n'
      '            // A checkbox, not a switch — but there is no Save button here, so\n'
      '            // the rule needs saying out loud: this filter *is* applied\n'
      '            // immediately, and it is a checkbox because it is one of a set of\n'
      '            // filters rather than a setting of its own.\n'
      '            AstryxCheckbox(\n'
      '              label: \'In stock only\',\n'
      '              value: _inStockOnly,\n'
      '              onChanged: (value) => setState(() => _inStockOnly = value),\n'
      '            ),\n'
      '          ],\n'
      '        ),\n'
      '        child: results.isEmpty\n'
      '            ? AstryxEmptyState(\n'
      '                title: \'Nothing matches those filters\',\n'
      '                description:\n'
      '                    \'Every product is still here — the filters are what is \'\n'
      '                    \'hiding them.\',\n'
      '                icon: const AstryxIcon(\n'
      '                  AstryxIconName.funnel,\n'
      '                  size: AstryxIconSize.lg,\n'
      '                ),\n'
      '                actions: <Widget>[\n'
      '                  AstryxButton(\n'
      '                    label: \'Clear filters\',\n'
      '                    variant: AstryxButtonVariant.primary,\n'
      '                    onPressed: _clear,\n'
      '                  ),\n'
      '                ],\n'
      '              )\n'
      '            : AstryxHStack(\n'
      '                gap: AstryxSpacingToken.spacing3,\n'
      '                wrap: true,\n'
      '                runGap: AstryxSpacingToken.spacing3,\n'
      '                align: AstryxStackAlign.start,\n'
      '                children: <Widget>[\n'
      '                  for (final product in results) _ProductTile(product: product),\n'
      '                ],\n'
      '              ),\n'
      '      ),\n'
      '    );\n'
      '  }\n'
      '}\n'
      '\n'
      '/// One product: a picture, a name, a price, and whether it can be bought.\n'
      'class _ProductTile extends StatelessWidget {\n'
      '  const _ProductTile({required this.product});\n'
      '\n'
      '  final Product product;\n'
      '\n'
      '  @override\n'
      '  Widget build(BuildContext context) {\n'
      '    return SizedBox(\n'
      '      width: 190,\n'
      '      child: AstryxCard(\n'
      '        padding: AstryxSpacingToken.spacing3,\n'
      '        // One sentence, once. The three lines below are what a sighted reader\n'
      '        // assembles for themselves; a screen reader is handed the assembled\n'
      '        // version instead of hearing four separate nodes.\n'
      '        semanticsLabel:\n'
      '            \'\${product.name}, \${money(product.price)}, rated \'\n'
      '            \'\${product.rating} out of 5\'\n'
      '            \'\${product.inStock ? \'\' : \', out of stock\'}\',\n'
      '        onPressed: () {},\n'
      '        footer: AstryxVStack(\n'
      '          gap: AstryxSpacingToken.spacing1,\n'
      '          align: AstryxStackAlign.stretch,\n'
      '          children: <Widget>[\n'
      '            AstryxText(product.name, type: AstryxTextType.label, maxLines: 1),\n'
      '            AstryxHStack(\n'
      '              gap: AstryxSpacingToken.spacing2,\n'
      '              justify: AstryxStackJustify.between,\n'
      '              mainAxisSize: MainAxisSize.max,\n'
      '              children: <Widget>[\n'
      '                Flexible(\n'
      '                  child: AstryxText(\n'
      '                    money(product.price),\n'
      '                    tabularNumbers: true,\n'
      '                    maxLines: 1,\n'
      '                  ),\n'
      '                ),\n'
      '                AstryxText(\n'
      '                  \'★ \${product.rating}\',\n'
      '                  type: AstryxTextType.supporting,\n'
      '                  color: AstryxTextColor.secondary,\n'
      '                  tabularNumbers: true,\n'
      '                ),\n'
      '              ],\n'
      '            ),\n'
      '            if (!product.inStock)\n'
      '              const AstryxBadge(\n'
      '                \'Out of stock\',\n'
      '                variant: AstryxBadgeVariant.warning,\n'
      '                icon: AstryxIcon(AstryxIconName.warning),\n'
      '              ),\n'
      '          ],\n'
      '        ),\n'
      '        child: AstryxAspectRatio(\n'
      '          ratio: 1,\n'
      '          semanticsLabel: product.name,\n'
      '          child: const Center(\n'
      '            child: AstryxIcon(AstryxIconName.viewColumns),\n'
      '          ),\n'
      '        ),\n'
      '      ),\n'
      '    );\n'
      '  }\n'
      '}\n',
  // examples/template_console_examples.dart
  'template_incident_console':
      '/// One live incident.\n'
      'typedef Incident = ({\n'
      '  String id,\n'
      '  int severity,\n'
      '  String title,\n'
      '  String service,\n'
      '  String owner,\n'
      '  bool acknowledged,\n'
      '  Duration age,\n'
      '});\n'
      '\n'
      '/// One entry in an incident\'s timeline.\n'
      'typedef Event = ({String who, String what, Duration ago});\n'
      '\n'
      'class IncidentConsoleTemplate extends StatefulWidget {\n'
      '  const IncidentConsoleTemplate({super.key});\n'
      '\n'
      '  @override\n'
      '  State<IncidentConsoleTemplate> createState() =>\n'
      '      _IncidentConsoleTemplateState();\n'
      '}\n'
      '\n'
      'class _IncidentConsoleTemplateState extends State<IncidentConsoleTemplate> {\n'
      '  static const List<Incident> _all = <Incident>[\n'
      '    (\n'
      '      id: \'INC-4102\',\n'
      '      severity: 1,\n'
      '      title: \'Scheduler health check timing out\',\n'
      '      service: \'scheduler\',\n'
      '      owner: \'Ada Lovelace\',\n'
      '      acknowledged: true,\n'
      '      age: Duration(minutes: 41),\n'
      '    ),\n'
      '    (\n'
      '      id: \'INC-4101\',\n'
      '      severity: 2,\n'
      '      title: \'Elevated 5xx from the edge in eu-west\',\n'
      '      service: \'edge\',\n'
      '      owner: \'Grace Hopper\',\n'
      '      acknowledged: true,\n'
      '      age: Duration(hours: 2, minutes: 12),\n'
      '    ),\n'
      '    (\n'
      '      id: \'INC-4100\',\n'
      '      severity: 3,\n'
      '      title: \'Artifact upload retries above baseline\',\n'
      '      service: \'artifacts\',\n'
      '      owner: \'Unassigned\',\n'
      '      acknowledged: false,\n'
      '      age: Duration(minutes: 6),\n'
      '    ),\n'
      '    (\n'
      '      id: \'INC-4098\',\n'
      '      severity: 3,\n'
      '      title: \'Metrics ingestion lag on shard 4\',\n'
      '      service: \'metrics\',\n'
      '      owner: \'Alan Turing\',\n'
      '      acknowledged: true,\n'
      '      age: Duration(hours: 5, minutes: 3),\n'
      '    ),\n'
      '  ];\n'
      '\n'
      '  static const Map<String, List<Event>> _timeline = <String, List<Event>>{\n'
      '    \'INC-4102\': <Event>[\n'
      '      (\n'
      '        who: \'Ada Lovelace\',\n'
      '        what: \'Raised the health-check timeout to 60 seconds\',\n'
      '        ago: Duration(minutes: 4),\n'
      '      ),\n'
      '      (\n'
      '        who: \'Ada Lovelace\',\n'
      '        what: \'Acknowledged and took ownership\',\n'
      '        ago: Duration(minutes: 33),\n'
      '      ),\n'
      '      (\n'
      '        who: \'Atlas\',\n'
      '        what: \'Paged the Europe rotation\',\n'
      '        ago: Duration(minutes: 40),\n'
      '      ),\n'
      '      (\n'
      '        who: \'Atlas\',\n'
      '        what: \'Opened after three failed deploys in a row\',\n'
      '        ago: Duration(minutes: 41),\n'
      '      ),\n'
      '    ],\n'
      '  };\n'
      '\n'
      '  /// A single instant that every relative stamp on this screen is measured\n'
      '  /// from, so two rows the same age never disagree by a second.\n'
      '  late final DateTime _opened = DateTime.now();\n'
      '\n'
      '  int? _severity;\n'
      '  String _selected = \'INC-4102\';\n'
      '\n'
      '  List<Incident> get _shown => _severity == null\n'
      '      ? _all\n'
      '      : _all.where((incident) => incident.severity == _severity).toList();\n'
      '\n'
      '  Incident get _open => _all.firstWhere((incident) => incident.id == _selected);\n'
      '\n'
      '  @override\n'
      '  Widget build(BuildContext context) {\n'
      '    final shown = _shown;\n'
      '\n'
      '    return SizedBox(\n'
      '      height: 620,\n'
      '      child: AstryxLayout(\n'
      '        panelWidth: 280,\n'
      '        header: AstryxHStack(\n'
      '          gap: AstryxSpacingToken.spacing3,\n'
      '          justify: AstryxStackJustify.between,\n'
      '          mainAxisSize: MainAxisSize.max,\n'
      '          wrap: true,\n'
      '          runGap: AstryxSpacingToken.spacing2,\n'
      '          children: <Widget>[\n'
      '            AstryxVStack(\n'
      '              gap: AstryxSpacingToken.spacing1,\n'
      '              children: <Widget>[\n'
      '                const AstryxHStack(\n'
      '                  gap: AstryxSpacingToken.spacing2,\n'
      '                  children: <Widget>[\n'
      '                    AstryxHeading(\'Incidents\', level: 1),\n'
      '                    // Pulsing says *live*, and the label says what live\n'
      '                    // means. The pulse honours reduced motion; the words do\n'
      '                    // not need to.\n'
      '                    AstryxStatusDot(\n'
      '                      AstryxStatusDotVariant.error,\n'
      '                      label: \'Live — updating as events arrive\',\n'
      '                      pulsing: true,\n'
      '                    ),\n'
      '                  ],\n'
      '                ),\n'
      '                AstryxText(\n'
      '                  \'\${shown.length} open · \'\n'
      '                  \'\${_all.where((i) => !i.acknowledged).length} \'\n'
      '                  \'unacknowledged\',\n'
      '                  type: AstryxTextType.supporting,\n'
      '                  color: AstryxTextColor.secondary,\n'
      '                ),\n'
      '              ],\n'
      '            ),\n'
      '            AstryxHStack(\n'
      '              gap: AstryxSpacingToken.spacing2,\n'
      '              wrap: true,\n'
      '              runGap: AstryxSpacingToken.spacing2,\n'
      '              children: <Widget>[\n'
      '                AstryxSegmentedControl<int?>(\n'
      '                  label: \'Severity\',\n'
      '                  value: _severity,\n'
      '                  size: AstryxButtonSize.sm,\n'
      '                  onChanged: (value) => setState(() => _severity = value),\n'
      '                  segments: const <AstryxSegment<int?>>[\n'
      '                    AstryxSegment<int?>(value: null, label: \'All\'),\n'
      '                    AstryxSegment<int?>(value: 1, label: \'Sev-1\'),\n'
      '                    AstryxSegment<int?>(value: 2, label: \'Sev-2\'),\n'
      '                    AstryxSegment<int?>(value: 3, label: \'Sev-3\'),\n'
      '                  ],\n'
      '                ),\n'
      '                AstryxButton(\n'
      '                  label: \'Declare an incident\',\n'
      '                  variant: AstryxButtonVariant.primary,\n'
      '                  size: AstryxButtonSize.sm,\n'
      '                  onPressed: () {},\n'
      '                ),\n'
      '              ],\n'
      '            ),\n'
      '          ],\n'
      '        ),\n'
      '        panel: _OnCallPanel(incident: _open, opened: _opened),\n'
      '        child: shown.isEmpty\n'
      '            ? const AstryxEmptyState(\n'
      '                title: \'Nothing at that severity\',\n'
      '                description: \'Four incidents are open at other severities.\',\n'
      '                icon: AstryxIcon(\n'
      '                  AstryxIconName.success,\n'
      '                  size: AstryxIconSize.lg,\n'
      '                ),\n'
      '              )\n'
      '            : AstryxVStack(\n'
      '                gap: AstryxSpacingToken.spacing3,\n'
      '                align: AstryxStackAlign.stretch,\n'
      '                children: <Widget>[\n'
      '                  for (final incident in shown)\n'
      '                    _IncidentCard(\n'
      '                      incident: incident,\n'
      '                      opened: _opened,\n'
      '                      selected: incident.id == _selected,\n'
      '                      onPressed: () => setState(() => _selected = incident.id),\n'
      '                    ),\n'
      '                  AstryxSection(\n'
      '                    title: \'Timeline · \$_selected\',\n'
      '                    description:\n'
      '                        \'Newest first. Every entry names who did it, because \'\n'
      '                        \'"acknowledged" with no name is the thing nobody can \'\n'
      '                        \'follow up.\',\n'
      '                    child: AstryxList(\n'
      '                      label: \'Timeline for \$_selected\',\n'
      '                      showDividers: true,\n'
      '                      children: <Widget>[\n'
      '                        for (final event\n'
      '                            in _timeline[_selected] ?? const <Event>[])\n'
      '                          AstryxItem(\n'
      '                            label: event.what,\n'
      '                            description: event.who,\n'
      '                            maxLines: 2,\n'
      '                            trailing: AstryxTimestamp(\n'
      '                              _opened.subtract(event.ago),\n'
      '                              type: AstryxTextType.supporting,\n'
      '                            ),\n'
      '                          ),\n'
      '                        if ((_timeline[_selected] ?? const <Event>[]).isEmpty)\n'
      '                          const AstryxItem(\n'
      '                            label: \'Nothing has happened yet\',\n'
      '                            description:\n'
      '                                \'This incident was opened automatically and \'\n'
      '                                \'has not been touched.\',\n'
      '                          ),\n'
      '                      ],\n'
      '                    ),\n'
      '                  ),\n'
      '                ],\n'
      '              ),\n'
      '      ),\n'
      '    );\n'
      '  }\n'
      '}\n'
      '\n'
      '/// One incident, as a card that is also the way into it.\n'
      'class _IncidentCard extends StatelessWidget {\n'
      '  const _IncidentCard({\n'
      '    required this.incident,\n'
      '    required this.opened,\n'
      '    required this.selected,\n'
      '    required this.onPressed,\n'
      '  });\n'
      '\n'
      '  final Incident incident;\n'
      '  final DateTime opened;\n'
      '  final bool selected;\n'
      '  final VoidCallback onPressed;\n'
      '\n'
      '  /// The badge for a severity.\n'
      '  ///\n'
      '  /// The number is in the text, not only in the colour — the palettes are\n'
      '  /// *categorical*, and a reader who cannot tell red from orange still has to\n'
      '  /// know which of these to look at first.\n'
      '  AstryxBadgeVariant get _severityVariant => switch (incident.severity) {\n'
      '    1 => AstryxBadgeVariant.error,\n'
      '    2 => AstryxBadgeVariant.warning,\n'
      '    _ => AstryxBadgeVariant.neutral,\n'
      '  };\n'
      '\n'
      '  @override\n'
      '  Widget build(BuildContext context) {\n'
      '    return AstryxCard(\n'
      '      padding: AstryxSpacingToken.spacing3,\n'
      '      variant: selected\n'
      '          ? AstryxCardVariant.standard\n'
      '          : AstryxCardVariant.transparent,\n'
      '      elevation: selected ? AstryxElevation.low : AstryxElevation.none,\n'
      '      semanticsLabel:\n'
      '          \'\${incident.id}, severity \${incident.severity}, \'\n'
      '          \'\${incident.title}, owned by \${incident.owner}\',\n'
      '      onPressed: onPressed,\n'
      '      child: AstryxHStack(\n'
      '        gap: AstryxSpacingToken.spacing3,\n'
      '        justify: AstryxStackJustify.between,\n'
      '        mainAxisSize: MainAxisSize.max,\n'
      '        children: <Widget>[\n'
      '          Flexible(\n'
      '            child: AstryxVStack(\n'
      '              gap: AstryxSpacingToken.spacing1,\n'
      '              children: <Widget>[\n'
      '                // Wrapping, not truncating. Every badge in this row is a\n'
      '                // fact about how urgent the card is; a phone that clips\n'
      '                // "Unacknowledged" off the end has hidden the one word that\n'
      '                // decides whether anybody picks the incident up.\n'
      '                AstryxHStack(\n'
      '                  gap: AstryxSpacingToken.spacing2,\n'
      '                  wrap: true,\n'
      '                  runGap: AstryxSpacingToken.spacing1,\n'
      '                  children: <Widget>[\n'
      '                    AstryxBadge(\n'
      '                      \'Sev-\${incident.severity}\',\n'
      '                      variant: _severityVariant,\n'
      '                      icon: AstryxIcon(\n'
      '                        incident.severity == 1\n'
      '                            ? AstryxIconName.error\n'
      '                            : AstryxIconName.warning,\n'
      '                      ),\n'
      '                    ),\n'
      '                    AstryxText(incident.id, type: AstryxTextType.code),\n'
      '                    if (!incident.acknowledged)\n'
      '                      const AstryxBadge(\n'
      '                        \'Unacknowledged\',\n'
      '                        variant: AstryxBadgeVariant.warning,\n'
      '                        icon: AstryxIcon(AstryxIconName.clock),\n'
      '                      ),\n'
      '                  ],\n'
      '                ),\n'
      '                AstryxText(\n'
      '                  incident.title,\n'
      '                  type: AstryxTextType.label,\n'
      '                  maxLines: 1,\n'
      '                ),\n'
      '                AstryxText(\n'
      '                  \'\${incident.service} · \${incident.owner}\',\n'
      '                  type: AstryxTextType.supporting,\n'
      '                  color: AstryxTextColor.secondary,\n'
      '                  maxLines: 1,\n'
      '                ),\n'
      '              ],\n'
      '            ),\n'
      '          ),\n'
      '          // A relative stamp that keeps ticking. On a wall display, "41\n'
      '          // minutes" that froze at load is worse than no clock at all.\n'
      '          AstryxTimestamp(\n'
      '            opened.subtract(incident.age),\n'
      '            type: AstryxTextType.supporting,\n'
      '          ),\n'
      '        ],\n'
      '      ),\n'
      '    );\n'
      '  }\n'
      '}\n'
      '\n'
      '/// Who has the incident, and who to reach if they do not answer.\n'
      'class _OnCallPanel extends StatelessWidget {\n'
      '  const _OnCallPanel({required this.incident, required this.opened});\n'
      '\n'
      '  final Incident incident;\n'
      '  final DateTime opened;\n'
      '\n'
      '  @override\n'
      '  Widget build(BuildContext context) {\n'
      '    return AstryxVStack(\n'
      '      gap: AstryxSpacingToken.spacing5,\n'
      '      align: AstryxStackAlign.stretch,\n'
      '      children: <Widget>[\n'
      '        AstryxSection(\n'
      '          title: \'On call\',\n'
      '          level: 2,\n'
      '          child: AstryxVStack(\n'
      '            gap: AstryxSpacingToken.spacing3,\n'
      '            align: AstryxStackAlign.stretch,\n'
      '            children: <Widget>[\n'
      '              AstryxItem(\n'
      '                label: incident.owner,\n'
      '                description: \'Europe, until 18:00\',\n'
      '                leading: AstryxAvatar(\n'
      '                  name: incident.owner,\n'
      '                  status: AstryxStatusDotVariant.success,\n'
      '                  statusLabel: \'Available\',\n'
      '                ),\n'
      '              ),\n'
      '              const AstryxAvatarGroup(\n'
      '                label: \'Also on this incident\',\n'
      '                size: AstryxAvatarSize.sm,\n'
      '                avatars: <AstryxAvatar>[\n'
      '                  AstryxAvatar(name: \'Grace Hopper\'),\n'
      '                  AstryxAvatar(name: \'Alan Turing\'),\n'
      '                  AstryxAvatar(name: \'Katherine Johnson\'),\n'
      '                  AstryxAvatar(name: \'Edsger Dijkstra\'),\n'
      '                ],\n'
      '              ),\n'
      '              AstryxButton(\n'
      '                label: \'Page the escalation\',\n'
      '                variant: AstryxButtonVariant.destructive,\n'
      '                size: AstryxButtonSize.sm,\n'
      '                onPressed: () {},\n'
      '              ),\n'
      '            ],\n'
      '          ),\n'
      '        ),\n'
      '        const AstryxDivider(),\n'
      '        AstryxSection(\n'
      '          title: \'This incident\',\n'
      '          level: 2,\n'
      '          child: AstryxMetadataList(\n'
      '            items: <AstryxMetadataItem>[\n'
      '              AstryxMetadataItem.text(label: \'Id\', value: incident.id),\n'
      '              AstryxMetadataItem.text(\n'
      '                label: \'Service\',\n'
      '                value: incident.service,\n'
      '              ),\n'
      '              AstryxMetadataItem(\n'
      '                label: \'Opened\',\n'
      '                semanticsValue: \'\${incident.age.inMinutes} minutes ago\',\n'
      '                value: AstryxTimestamp(opened.subtract(incident.age)),\n'
      '              ),\n'
      '              AstryxMetadataItem.text(\n'
      '                label: \'Severity\',\n'
      '                value: \'Sev-\${incident.severity}\',\n'
      '              ),\n'
      '            ],\n'
      '          ),\n'
      '        ),\n'
      '        const AstryxDivider(),\n'
      '        const AstryxSection(\n'
      '          title: \'Error budget\',\n'
      '          level: 2,\n'
      '          child: AstryxProgressBar(\n'
      '            label: \'Error budget consumed this window\',\n'
      '            value: 0.68,\n'
      '            variant: AstryxProgressVariant.warning,\n'
      '            showValueLabel: true,\n'
      '          ),\n'
      '        ),\n'
      '      ],\n'
      '    );\n'
      '  }\n'
      '}\n',
  // examples/template_docs_examples.dart
  'template_documentation_design':
      '/// One row of the specimen wall: a token, and what it is for.\n'
      'typedef Swatch = ({String name, AstryxColorToken token, String use});\n'
      '\n'
      'class DocumentationDesignTemplate extends StatefulWidget {\n'
      '  const DocumentationDesignTemplate({super.key});\n'
      '\n'
      '  @override\n'
      '  State<DocumentationDesignTemplate> createState() =>\n'
      '      _DocumentationDesignTemplateState();\n'
      '}\n'
      '\n'
      'class _DocumentationDesignTemplateState\n'
      '    extends State<DocumentationDesignTemplate> {\n'
      '  static const List<({String id, String title})> _sections =\n'
      '      <({String id, String title})>[\n'
      '        (id: \'roles\', title: \'Semantic roles\'),\n'
      '        (id: \'families\', title: \'Categorical families\'),\n'
      '        (id: \'pairs\', title: \'Text on ground\'),\n'
      '        (id: \'wrong\', title: \'What goes wrong\'),\n'
      '      ];\n'
      '\n'
      '  static const List<Swatch> _roles = <Swatch>[\n'
      '    (\n'
      '      name: \'accent\',\n'
      '      token: AstryxColorToken.accent,\n'
      '      use: \'The one action in a view.\',\n'
      '    ),\n'
      '    (\n'
      '      name: \'success\',\n'
      '      token: AstryxColorToken.success,\n'
      '      use: \'A thing that finished, and finished well.\',\n'
      '    ),\n'
      '    (\n'
      '      name: \'warning\',\n'
      '      token: AstryxColorToken.warning,\n'
      '      use: \'Something the reader should look at before it is a problem.\',\n'
      '    ),\n'
      '    (\n'
      '      name: \'error\',\n'
      '      token: AstryxColorToken.error,\n'
      '      use: \'Something that failed, or will.\',\n'
      '    ),\n'
      '  ];\n'
      '\n'
      '  static const List<({String name, AstryxPalette palette})> _families =\n'
      '      <({String name, AstryxPalette palette})>[\n'
      '        (name: \'blue\', palette: AstryxPalette.blue),\n'
      '        (name: \'green\', palette: AstryxPalette.green),\n'
      '        (name: \'orange\', palette: AstryxPalette.orange),\n'
      '        (name: \'purple\', palette: AstryxPalette.purple),\n'
      '        (name: \'teal\', palette: AstryxPalette.teal),\n'
      '        (name: \'pink\', palette: AstryxPalette.pink),\n'
      '      ];\n'
      '\n'
      '  final ScrollController _scroll = ScrollController();\n'
      '\n'
      '  final Map<String, GlobalKey> _anchors = <String, GlobalKey>{\n'
      '    for (final section in _sections) section.id: GlobalKey(),\n'
      '  };\n'
      '\n'
      '  @override\n'
      '  void dispose() {\n'
      '    _scroll.dispose();\n'
      '    super.dispose();\n'
      '  }\n'
      '\n'
      '  @override\n'
      '  Widget build(BuildContext context) {\n'
      '    // A design page is read by looking, so the specimens are the content and\n'
      '    // the prose is the caption. The measure still applies to the prose — but\n'
      '    // the specimen wall is allowed to be wider than it, which is why\n'
      '    // `maxContentWidth` is generous rather than 720.\n'
      '    return SizedBox(\n'
      '      height: 560,\n'
      '      child: AstryxLayout(\n'
      '        scrollController: _scroll,\n'
      '        maxContentWidth: 840,\n'
      '        panelWidth: 190,\n'
      '        header: AstryxBreadcrumbs(\n'
      '          label: \'You are here\',\n'
      '          items: <AstryxBreadcrumb>[\n'
      '            AstryxBreadcrumb(label: \'Design\', onPressed: () {}),\n'
      '            AstryxBreadcrumb(label: \'Foundations\', onPressed: () {}),\n'
      '            const AstryxBreadcrumb(label: \'Colour\'),\n'
      '          ],\n'
      '        ),\n'
      '        panel: AstryxOutline(\n'
      '          label: \'On this page\',\n'
      '          controller: _scroll,\n'
      '          entries: <AstryxOutlineEntry>[\n'
      '            for (final section in _sections)\n'
      '              AstryxOutlineEntry(\n'
      '                id: section.id,\n'
      '                label: section.title,\n'
      '                anchor: _anchors[section.id],\n'
      '              ),\n'
      '          ],\n'
      '        ),\n'
      '        child: AstryxVStack(\n'
      '          gap: AstryxSpacingToken.spacing6,\n'
      '          align: AstryxStackAlign.stretch,\n'
      '          children: <Widget>[\n'
      '            const AstryxVStack(\n'
      '              gap: AstryxSpacingToken.spacing3,\n'
      '              align: AstryxStackAlign.stretch,\n'
      '              children: <Widget>[\n'
      '                AstryxHeading(\'Colour\', level: 1),\n'
      '                AstryxText(\n'
      '                  \'Two systems that look like one: four semantic roles that \'\n'
      '                  \'mean something, and ten families that mean nothing at all.\',\n'
      '                  type: AstryxTextType.large,\n'
      '                  color: AstryxTextColor.secondary,\n'
      '                ),\n'
      '              ],\n'
      '            ),\n'
      '            AstryxSection(\n'
      '              title: \'Semantic roles\',\n'
      '              description: \'These carry meaning, and there are only four.\',\n'
      '              headerKey: _anchors[\'roles\'],\n'
      '              child: AstryxVStack(\n'
      '                gap: AstryxSpacingToken.spacing3,\n'
      '                align: AstryxStackAlign.stretch,\n'
      '                children: <Widget>[\n'
      '                  for (final swatch in _roles) _SwatchRow(swatch: swatch),\n'
      '                ],\n'
      '              ),\n'
      '            ),\n'
      '            AstryxSection(\n'
      '              title: \'Categorical families\',\n'
      '              description:\n'
      '                  \'These carry no severity whatever. "The Red team" is a \'\n'
      '                  \'name, not a warning.\',\n'
      '              headerKey: _anchors[\'families\'],\n'
      '              child: AstryxGrid(\n'
      '                minWidth: 150,\n'
      '                gap: AstryxSpacingToken.spacing3,\n'
      '                children: <Widget>[\n'
      '                  for (final family in _families)\n'
      '                    AstryxCard(\n'
      '                      variant: AstryxCardVariant.palette(family.palette),\n'
      '                      padding: AstryxSpacingToken.spacing3,\n'
      '                      child: AstryxVStack(\n'
      '                        gap: AstryxSpacingToken.spacing2,\n'
      '                        children: <Widget>[\n'
      '                          AstryxText(\n'
      '                            family.name,\n'
      '                            type: AstryxTextType.label,\n'
      '                          ),\n'
      '                          AstryxBadge(\n'
      '                            \'Badge\',\n'
      '                            variant: AstryxBadgeVariant.palette(family.palette),\n'
      '                          ),\n'
      '                        ],\n'
      '                      ),\n'
      '                    ),\n'
      '                ],\n'
      '              ),\n'
      '            ),\n'
      '            AstryxSection(\n'
      '              title: \'Text on ground\',\n'
      '              description:\n'
      '                  \'Every filled surface has a paired foreground. Reaching for \'\n'
      '                  \'one without the other is where contrast is lost.\',\n'
      '              headerKey: _anchors[\'pairs\'],\n'
      '              child: const AstryxCodeBlock(\'\'\'\n'
      'final theme = AstryxTheme.of(context);\n'
      '\n'
      '// Right: the pair.\n'
      'theme.color(AstryxColorToken.accent);      // ground\n'
      'theme.color(AstryxColorToken.onAccent);    // text on it\n'
      '\n'
      '// Wrong: a ground with the page\'s own text colour on top.\n'
      'theme.color(AstryxColorToken.accent);\n'
      'theme.color(AstryxColorToken.textPrimary);\'\'\', language: \'dart\'),\n'
      '            ),\n'
      '            AstryxSection(\n'
      '              title: \'What goes wrong\',\n'
      '              headerKey: _anchors[\'wrong\'],\n'
      '              child: const AstryxVStack(\n'
      '                gap: AstryxSpacingToken.spacing3,\n'
      '                align: AstryxStackAlign.stretch,\n'
      '                children: <Widget>[\n'
      '                  AstryxBanner(\n'
      '                    status: AstryxBannerStatus.warning,\n'
      '                    title: \'Colour is never the only signal\',\n'
      '                    description:\n'
      '                        \'Every status here is a colour and a glyph and a \'\n'
      '                        \'word. In greyscale, or to a colour-blind reader, the \'\n'
      '                        \'colour is the part that is gone.\',\n'
      '                    announce: false,\n'
      '                  ),\n'
      '                  // A do-and-don\'t pair, side by side rather than one above the\n'
      '                  // other: the comparison is the point, and a reader who has to\n'
      '                  // scroll between the two is not comparing anything.\n'
      '                  AstryxGrid(\n'
      '                    minWidth: 240,\n'
      '                    gap: AstryxSpacingToken.spacing3,\n'
      '                    children: <Widget>[\n'
      '                      _SpecimenCard(\n'
      '                        verdict: \'Do\',\n'
      '                        good: true,\n'
      '                        caption: \'A glyph, a word, and a colour.\',\n'
      '                        child: AstryxBadge(\n'
      '                          \'Failed\',\n'
      '                          variant: AstryxBadgeVariant.error,\n'
      '                          icon: AstryxIcon(AstryxIconName.error),\n'
      '                        ),\n'
      '                      ),\n'
      '                      // The dot never paints its label — the string is its\n'
      '                      // accessible name. Which is the whole demonstration: a\n'
      '                      // sighted reader gets a red circle and nothing else.\n'
      '                      _SpecimenCard(\n'
      '                        verdict: "Don\'t",\n'
      '                        good: false,\n'
      '                        caption: \'A dot, and a reader guessing what red means.\',\n'
      '                        child: AstryxStatusDot(\n'
      '                          AstryxStatusDotVariant.error,\n'
      '                          label: \'Failed\',\n'
      '                        ),\n'
      '                      ),\n'
      '                    ],\n'
      '                  ),\n'
      '                ],\n'
      '              ),\n'
      '            ),\n'
      '          ],\n'
      '        ),\n'
      '      ),\n'
      '    );\n'
      '  }\n'
      '}\n'
      '\n'
      '/// A swatch, its token name, and the sentence saying when to use it.\n'
      'class _SwatchRow extends StatelessWidget {\n'
      '  const _SwatchRow({required this.swatch});\n'
      '\n'
      '  final Swatch swatch;\n'
      '\n'
      '  @override\n'
      '  Widget build(BuildContext context) {\n'
      '    final theme = AstryxTheme.of(context);\n'
      '\n'
      '    return AstryxHStack(\n'
      '      gap: AstryxSpacingToken.spacing3,\n'
      '      mainAxisSize: MainAxisSize.max,\n'
      '      children: <Widget>[\n'
      '        // The one place a raw `Container` is right: this *is* the colour, so\n'
      '        // there is no widget between the token and the reader\'s eye. It still\n'
      '        // comes from `theme.color`, which is why the page is correct in all\n'
      '        // eight themes and both brightnesses.\n'
      '        Container(\n'
      '          width: 56,\n'
      '          height: 40,\n'
      '          decoration: BoxDecoration(\n'
      '            color: theme.color(swatch.token),\n'
      '            borderRadius: theme.borderRadius(AstryxRadiusToken.inner),\n'
      '            border: Border.all(color: theme.color(AstryxColorToken.border)),\n'
      '          ),\n'
      '        ),\n'
      '        Flexible(\n'
      '          child: AstryxVStack(\n'
      '            gap: AstryxSpacingToken.spacing0_5,\n'
      '            children: <Widget>[\n'
      '              AstryxText(swatch.name, type: AstryxTextType.code),\n'
      '              AstryxText(\n'
      '                swatch.use,\n'
      '                type: AstryxTextType.supporting,\n'
      '                color: AstryxTextColor.secondary,\n'
      '              ),\n'
      '            ],\n'
      '          ),\n'
      '        ),\n'
      '      ],\n'
      '    );\n'
      '  }\n'
      '}\n'
      '\n'
      '/// One half of a do-and-don\'t pair.\n'
      'class _SpecimenCard extends StatelessWidget {\n'
      '  const _SpecimenCard({\n'
      '    required this.verdict,\n'
      '    required this.good,\n'
      '    required this.caption,\n'
      '    required this.child,\n'
      '  });\n'
      '\n'
      '  final String verdict;\n'
      '  final bool good;\n'
      '  final String caption;\n'
      '  final Widget child;\n'
      '\n'
      '  @override\n'
      '  Widget build(BuildContext context) {\n'
      '    return AstryxCard(\n'
      '      padding: AstryxSpacingToken.spacing3,\n'
      '      header: AstryxBadge(\n'
      '        verdict,\n'
      '        variant: good ? AstryxBadgeVariant.success : AstryxBadgeVariant.error,\n'
      '        icon: AstryxIcon(\n'
      '          good ? AstryxIconName.success : AstryxIconName.error,\n'
      '        ),\n'
      '      ),\n'
      '      footer: AstryxText(\n'
      '        caption,\n'
      '        type: AstryxTextType.supporting,\n'
      '        color: AstryxTextColor.secondary,\n'
      '      ),\n'
      '      child: Align(alignment: AlignmentDirectional.centerStart, child: child),\n'
      '    );\n'
      '  }\n'
      '}\n',
  // examples/template_docs_examples.dart
  'template_documentation_technical':
      '/// One row of the property table.\n'
      'typedef ApiProperty = ({\n'
      '  String name,\n'
      '  String type,\n'
      '  String fallback,\n'
      '  String notes,\n'
      '  bool required,\n'
      '});\n'
      '\n'
      'class DocumentationTechnicalTemplate extends StatefulWidget {\n'
      '  const DocumentationTechnicalTemplate({super.key});\n'
      '\n'
      '  @override\n'
      '  State<DocumentationTechnicalTemplate> createState() =>\n'
      '      _DocumentationTechnicalTemplateState();\n'
      '}\n'
      '\n'
      'class _DocumentationTechnicalTemplateState\n'
      '    extends State<DocumentationTechnicalTemplate> {\n'
      '  static const List<({String id, String title})> _sections =\n'
      '      <({String id, String title})>[\n'
      '        (id: \'usage\', title: \'Usage\'),\n'
      '        (id: \'auth\', title: \'Authentication\'),\n'
      '        (id: \'properties\', title: \'Properties\'),\n'
      '        (id: \'errors\', title: \'Errors\'),\n'
      '      ];\n'
      '\n'
      '  static const List<ApiProperty> _properties = <ApiProperty>[\n'
      '    (\n'
      '      name: \'project\',\n'
      '      type: \'String\',\n'
      '      fallback: \'—\',\n'
      '      notes: \'The project the run belongs to. Slug, not id.\',\n'
      '      required: true,\n'
      '    ),\n'
      '    (\n'
      '      name: \'ref\',\n'
      '      type: \'String\',\n'
      '      fallback: \'HEAD\',\n'
      '      notes: \'A branch, a tag or a commit.\',\n'
      '      required: false,\n'
      '    ),\n'
      '    (\n'
      '      name: \'variables\',\n'
      '      type: \'Map<String, String>\',\n'
      '      fallback: \'{}\',\n'
      '      notes: \'Overrides for the pipeline’s own variables.\',\n'
      '      required: false,\n'
      '    ),\n'
      '    (\n'
      '      name: \'dryRun\',\n'
      '      type: \'bool\',\n'
      '      fallback: \'false\',\n'
      '      notes: \'Validates the request and reports what would run.\',\n'
      '      required: false,\n'
      '    ),\n'
      '  ];\n'
      '\n'
      '  final ScrollController _scroll = ScrollController();\n'
      '\n'
      '  final Map<String, GlobalKey> _anchors = <String, GlobalKey>{\n'
      '    for (final section in _sections) section.id: GlobalKey(),\n'
      '  };\n'
      '\n'
      '  /// Which language the usage sample is shown in.\n'
      '  String _language = \'dart\';\n'
      '\n'
      '  @override\n'
      '  void dispose() {\n'
      '    _scroll.dispose();\n'
      '    super.dispose();\n'
      '  }\n'
      '\n'
      '  static const Map<String, String> _samples = <String, String>{\n'
      '    \'dart\': \'\'\'\n'
      'final run = await foundry.runs.create(\n'
      '  project: \'acme/platform\',\n'
      '  ref: \'main\',\n'
      '  variables: <String, String>{\'TARGET\': \'production\'},\n'
      ');\n'
      '\n'
      'print(run.id);   // run_8f21c4\'\'\',\n'
      '    \'curl\': r\'\'\'\n'
      'curl https://api.foundry.example/v1/runs \\\n'
      '  -H "Authorization: Bearer \$FOUNDRY_TOKEN" \\\n'
      '  -d project=acme/platform \\\n'
      '  -d ref=main\'\'\',\n'
      '  };\n'
      '\n'
      '  @override\n'
      '  Widget build(BuildContext context) {\n'
      '    // Prose is not the content here — code and a property table are, and both\n'
      '    // want width. `maxContentWidth` is still set, because the *sentences*\n'
      '    // between them are what a reader loses first when a line runs too long.\n'
      '    return SizedBox(\n'
      '      height: 560,\n'
      '      child: AstryxLayout(\n'
      '        scrollController: _scroll,\n'
      '        maxContentWidth: 780,\n'
      '        panelWidth: 190,\n'
      '        header: AstryxHStack(\n'
      '          gap: AstryxSpacingToken.spacing3,\n'
      '          justify: AstryxStackJustify.between,\n'
      '          mainAxisSize: MainAxisSize.max,\n'
      '          children: <Widget>[\n'
      '            Flexible(\n'
      '              child: AstryxBreadcrumbs(\n'
      '                label: \'You are here\',\n'
      '                items: <AstryxBreadcrumb>[\n'
      '                  AstryxBreadcrumb(label: \'API\', onPressed: () {}),\n'
      '                  AstryxBreadcrumb(label: \'Runs\', onPressed: () {}),\n'
      '                  const AstryxBreadcrumb(label: \'Create a run\'),\n'
      '                ],\n'
      '              ),\n'
      '            ),\n'
      '            const AstryxBadge(\'v1\', variant: AstryxBadgeVariant.info),\n'
      '          ],\n'
      '        ),\n'
      '        panel: AstryxOutline(\n'
      '          label: \'On this page\',\n'
      '          controller: _scroll,\n'
      '          entries: <AstryxOutlineEntry>[\n'
      '            for (final section in _sections)\n'
      '              AstryxOutlineEntry(\n'
      '                id: section.id,\n'
      '                label: section.title,\n'
      '                anchor: _anchors[section.id],\n'
      '              ),\n'
      '          ],\n'
      '        ),\n'
      '        child: AstryxVStack(\n'
      '          gap: AstryxSpacingToken.spacing6,\n'
      '          align: AstryxStackAlign.stretch,\n'
      '          children: <Widget>[\n'
      '            const AstryxVStack(\n'
      '              gap: AstryxSpacingToken.spacing3,\n'
      '              align: AstryxStackAlign.stretch,\n'
      '              children: <Widget>[\n'
      '                AstryxHeading(\'Create a run\', level: 1),\n'
      '                // The method and path are the first thing anybody looks for on\n'
      '                // a reference page, so they are on the page rather than in a\n'
      '                // code block that has to be read for them.\n'
      '                AstryxHStack(\n'
      '                  gap: AstryxSpacingToken.spacing2,\n'
      '                  // The method, the path and the guarantee are three separate\n'
      '                  // facts, so a narrow page takes them on separate lines\n'
      '                  // rather than choosing which one to cut off.\n'
      '                  wrap: true,\n'
      '                  runGap: AstryxSpacingToken.spacing2,\n'
      '                  children: <Widget>[\n'
      '                    AstryxBadge(\'POST\', variant: AstryxBadgeVariant.success),\n'
      '                    AstryxCode(\'/v1/runs\'),\n'
      '                    AstryxBadge(\n'
      '                      \'Idempotent\',\n'
      '                      icon: AstryxIcon(AstryxIconName.check),\n'
      '                      semanticsLabel:\n'
      '                          \'Idempotent — repeating this request is safe\',\n'
      '                    ),\n'
      '                  ],\n'
      '                ),\n'
      '              ],\n'
      '            ),\n'
      '            AstryxSection(\n'
      '              title: \'Usage\',\n'
      '              headerKey: _anchors[\'usage\'],\n'
      '              child: AstryxVStack(\n'
      '                gap: AstryxSpacingToken.spacing3,\n'
      '                align: AstryxStackAlign.stretch,\n'
      '                children: <Widget>[\n'
      '                  // The strip reports a value and owns no panel, so which\n'
      '                  // sample is showing is one field and a lookup. That is what\n'
      '                  // makes the choice linkable from a route.\n'
      '                  AstryxTabList<String>(\n'
      '                    label: \'Language\',\n'
      '                    value: _language,\n'
      '                    size: AstryxTabSize.sm,\n'
      '                    onChanged: (value) => setState(() => _language = value),\n'
      '                    tabs: const <AstryxTab<String>>[\n'
      '                      AstryxTab(value: \'dart\', label: \'Dart\'),\n'
      '                      AstryxTab(value: \'curl\', label: \'curl\'),\n'
      '                    ],\n'
      '                  ),\n'
      '                  AstryxCodeBlock(\n'
      '                    _samples[_language]!,\n'
      '                    language: _language,\n'
      '                    showLineNumbers: true,\n'
      '                  ),\n'
      '                ],\n'
      '              ),\n'
      '            ),\n'
      '            AstryxSection(\n'
      '              title: \'Authentication\',\n'
      '              headerKey: _anchors[\'auth\'],\n'
      '              child: Text.rich(\n'
      '                TextSpan(\n'
      '                  style: AstryxTheme.of(\n'
      '                    context,\n'
      '                  ).textStyle(AstryxTypeRole.body),\n'
      '                  children: <InlineSpan>[\n'
      '                    const TextSpan(text: \'Send a project token in \'),\n'
      '                    AstryxCode.span(\'Authorization\'),\n'
      '                    const TextSpan(text: \'. Tokens are issued from \'),\n'
      '                    AstryxLink.span(\'Settings › Secrets\', onPressed: () {}),\n'
      '                    const TextSpan(\n'
      '                      text:\n'
      '                          \' and are scoped to one project — a token for \'\n'
      '                          \'another project fails closed rather than falling \'\n'
      '                          \'back to read-only.\',\n'
      '                    ),\n'
      '                  ],\n'
      '                ),\n'
      '              ),\n'
      '            ),\n'
      '            AstryxSection(\n'
      '              title: \'Properties\',\n'
      '              headerKey: _anchors[\'properties\'],\n'
      '              child: AstryxTable<ApiProperty>(\n'
      '                label: \'Request properties\',\n'
      '                keyOf: (row) => row.name,\n'
      '                rowLabelOf: (row) => row.name,\n'
      '                columns: <AstryxTableColumn<ApiProperty>>[\n'
      '                  AstryxTableColumn<ApiProperty>(\n'
      '                    id: \'name\',\n'
      '                    header: \'Property\',\n'
      '                    width: const AstryxTableColumnWidth.fixed(150),\n'
      '                    cellBuilder: (context, row) => AstryxHStack(\n'
      '                      gap: AstryxSpacingToken.spacing1,\n'
      '                      children: <Widget>[\n'
      '                        Flexible(child: AstryxCode(row.name)),\n'
      '                        if (row.required)\n'
      '                          const AstryxBadge(\n'
      '                            \'req\',\n'
      '                            variant: AstryxBadgeVariant.warning,\n'
      '                            semanticsLabel: \'Required\',\n'
      '                          ),\n'
      '                      ],\n'
      '                    ),\n'
      '                  ),\n'
      '                  AstryxTableColumn<ApiProperty>(\n'
      '                    id: \'type\',\n'
      '                    header: \'Type\',\n'
      '                    width: const AstryxTableColumnWidth.fixed(160),\n'
      '                    cellBuilder: (context, row) => AstryxText(\n'
      '                      row.type,\n'
      '                      type: AstryxTextType.code,\n'
      '                      maxLines: 1,\n'
      '                    ),\n'
      '                  ),\n'
      '                  AstryxTableColumn<ApiProperty>(\n'
      '                    id: \'default\',\n'
      '                    header: \'Default\',\n'
      '                    width: const AstryxTableColumnWidth.fixed(90),\n'
      '                    cellBuilder: (context, row) => AstryxText(\n'
      '                      row.fallback,\n'
      '                      type: AstryxTextType.code,\n'
      '                      maxLines: 1,\n'
      '                    ),\n'
      '                  ),\n'
      '                  AstryxTableColumn<ApiProperty>(\n'
      '                    id: \'notes\',\n'
      '                    header: \'Notes\',\n'
      '                    cellBuilder: (context, row) =>\n'
      '                        AstryxText(row.notes, maxLines: 2),\n'
      '                  ),\n'
      '                ],\n'
      '                rows: _properties,\n'
      '              ),\n'
      '            ),\n'
      '            AstryxSection(\n'
      '              title: \'Errors\',\n'
      '              headerKey: _anchors[\'errors\'],\n'
      '              child: AstryxVStack(\n'
      '                gap: AstryxSpacingToken.spacing2,\n'
      '                align: AstryxStackAlign.stretch,\n'
      '                children: <Widget>[\n'
      '                  const AstryxBanner(\n'
      '                    title: \'Every error carries a machine-readable code\',\n'
      '                    description:\n'
      '                        \'Match on the code, never on the message: the message \'\n'
      '                        \'is translated and the code is not.\',\n'
      '                    announce: false,\n'
      '                  ),\n'
      '                  AstryxList(\n'
      '                    label: \'Errors\',\n'
      '                    showDividers: true,\n'
      '                    density: AstryxItemDensity.compact,\n'
      '                    children: <Widget>[\n'
      '                      for (final error in const <List<String>>[\n'
      '                        <String>[\n'
      '                          \'400\',\n'
      '                          \'invalid_ref\',\n'
      '                          \'The ref does not exist on the project.\',\n'
      '                        ],\n'
      '                        <String>[\n'
      '                          \'403\',\n'
      '                          \'token_scope\',\n'
      '                          \'The token belongs to a different project.\',\n'
      '                        ],\n'
      '                        <String>[\n'
      '                          \'409\',\n'
      '                          \'run_in_flight\',\n'
      '                          \'A run for this ref is already queued.\',\n'
      '                        ],\n'
      '                      ])\n'
      '                        AstryxItem(\n'
      '                          label: error[1],\n'
      '                          description: error[2],\n'
      '                          leading: AstryxBadge(error[0]),\n'
      '                        ),\n'
      '                    ],\n'
      '                  ),\n'
      '                ],\n'
      '              ),\n'
      '            ),\n'
      '          ],\n'
      '        ),\n'
      '      ),\n'
      '    );\n'
      '  }\n'
      '}\n',
  // examples/template_form_examples.dart
  'template_contact_form':
      'class ContactFormTemplate extends StatefulWidget {\n'
      '  const ContactFormTemplate({super.key});\n'
      '\n'
      '  @override\n'
      '  State<ContactFormTemplate> createState() => _ContactFormTemplateState();\n'
      '}\n'
      '\n'
      'class _ContactFormTemplateState extends State<ContactFormTemplate> {\n'
      '  final TextEditingController _name = TextEditingController();\n'
      '  final TextEditingController _email = TextEditingController();\n'
      '  final TextEditingController _message = TextEditingController();\n'
      '\n'
      '  String? _topic = \'bug\';\n'
      '  bool _submitted = false;\n'
      '  bool _sending = false;\n'
      '  bool _sent = false;\n'
      '\n'
      '  @override\n'
      '  void dispose() {\n'
      '    _name.dispose();\n'
      '    _email.dispose();\n'
      '    _message.dispose();\n'
      '    super.dispose();\n'
      '  }\n'
      '\n'
      '  AstryxFieldStatus? _requiredStatus(String value, String message) {\n'
      '    if (!_submitted || value.trim().isNotEmpty) return null;\n'
      '    return AstryxFieldStatus.error(message);\n'
      '  }\n'
      '\n'
      '  bool get _valid =>\n'
      '      _name.text.trim().isNotEmpty &&\n'
      '      _email.text.contains(\'@\') &&\n'
      '      _message.text.trim().length >= 10;\n'
      '\n'
      '  Future<void> _send() async {\n'
      '    setState(() => _submitted = true);\n'
      '    if (!_valid) return;\n'
      '\n'
      '    setState(() => _sending = true);\n'
      '    await Future<void>.delayed(const Duration(milliseconds: 900));\n'
      '    if (!mounted) return;\n'
      '    setState(() {\n'
      '      _sending = false;\n'
      '      _sent = true;\n'
      '    });\n'
      '  }\n'
      '\n'
      '  void _reset() {\n'
      '    _name.clear();\n'
      '    _email.clear();\n'
      '    _message.clear();\n'
      '    setState(() {\n'
      '      _submitted = false;\n'
      '      _sent = false;\n'
      '      _topic = \'bug\';\n'
      '    });\n'
      '  }\n'
      '\n'
      '  @override\n'
      '  Widget build(BuildContext context) {\n'
      '    // The success state replaces the form rather than sitting above it. A form\n'
      '    // still on screen after it has been sent invites a second submission.\n'
      '    if (_sent) {\n'
      '      return AstryxCenter(\n'
      '        maxWidth: 460,\n'
      '        minHeight: 280,\n'
      '        child: AstryxVStack(\n'
      '          gap: AstryxSpacingToken.spacing4,\n'
      '          align: AstryxStackAlign.center,\n'
      '          children: <Widget>[\n'
      '            const AstryxIcon(\n'
      '              AstryxIconName.success,\n'
      '              size: AstryxIconSize.lg,\n'
      '              color: AstryxIconColor.success,\n'
      '            ),\n'
      '            const AstryxHeading(\'Thanks — that is with us\'),\n'
      '            const AstryxText(\n'
      '              \'We reply to everything within one working day. \'\n'
      '              \'A copy is on its way to your inbox.\',\n'
      '              color: AstryxTextColor.secondary,\n'
      '              justify: AstryxTextJustify.center,\n'
      '            ),\n'
      '            AstryxButton(label: \'Send another\', onPressed: _reset),\n'
      '          ],\n'
      '        ),\n'
      '      );\n'
      '    }\n'
      '\n'
      '    return AstryxCenter(\n'
      '      maxWidth: 460,\n'
      '      child: AstryxVStack(\n'
      '        gap: AstryxSpacingToken.spacing5,\n'
      '        align: AstryxStackAlign.stretch,\n'
      '        children: <Widget>[\n'
      '          const AstryxVStack(\n'
      '            gap: AstryxSpacingToken.spacing2,\n'
      '            align: AstryxStackAlign.stretch,\n'
      '            children: <Widget>[\n'
      '              AstryxHeading(\'Talk to us\', level: 1),\n'
      '              AstryxText(\n'
      '                \'Bugs, access requests, or anything the docs did not answer.\',\n'
      '                color: AstryxTextColor.secondary,\n'
      '              ),\n'
      '            ],\n'
      '          ),\n'
      '          AstryxTextInput(\n'
      '            label: \'Name\',\n'
      '            controller: _name,\n'
      '            required: true,\n'
      '            enabled: !_sending,\n'
      '            status: _requiredStatus(_name.text, \'Tell us who you are\'),\n'
      '            autofillHints: const <String>[AutofillHints.name],\n'
      '            onChanged: (_) => setState(() {}),\n'
      '          ),\n'
      '          AstryxTextInput(\n'
      '            label: \'Email\',\n'
      '            controller: _email,\n'
      '            required: true,\n'
      '            enabled: !_sending,\n'
      '            status: _submitted && !_email.text.contains(\'@\')\n'
      '                ? const AstryxFieldStatus.error(\n'
      '                    \'We need somewhere to reply to\',\n'
      '                  )\n'
      '                : null,\n'
      '            placeholder: \'you@example.com\',\n'
      '            keyboardType: TextInputType.emailAddress,\n'
      '            autofillHints: const <String>[AutofillHints.email],\n'
      '            onChanged: (_) => setState(() {}),\n'
      '          ),\n'
      '          AstryxSelector<String>(\n'
      '            label: \'Topic\',\n'
      '            value: _topic,\n'
      '            enabled: !_sending,\n'
      '            onChanged: (value) => setState(() => _topic = value),\n'
      '            options: const <AstryxSelectorEntry<String>>[\n'
      '              AstryxSelectorOption(\n'
      '                value: \'bug\',\n'
      '                label: \'Something is broken\',\n'
      '                description: \'A page, an export, an integration\',\n'
      '              ),\n'
      '              AstryxSelectorOption(\n'
      '                value: \'access\',\n'
      '                label: \'Access request\',\n'
      '                description: \'A workspace, a role, a seat\',\n'
      '              ),\n'
      '              AstryxSelectorOption(value: \'billing\', label: \'Billing\'),\n'
      '              AstryxSelectorOption(value: \'other\', label: \'Something else\'),\n'
      '            ],\n'
      '          ),\n'
      '          AstryxTextArea(\n'
      '            label: \'Message\',\n'
      '            controller: _message,\n'
      '            required: true,\n'
      '            enabled: !_sending,\n'
      '            status: _submitted && _message.text.trim().length < 10\n'
      '                ? const AstryxFieldStatus.error(\n'
      '                    \'A sentence or two, so we can route it\',\n'
      '                  )\n'
      '                : null,\n'
      '            placeholder: \'What happened, and what you expected instead.\',\n'
      '            maxLength: 1000,\n'
      '            onChanged: (_) => setState(() {}),\n'
      '          ),\n'
      '          AstryxHStack(\n'
      '            gap: AstryxSpacingToken.spacing2,\n'
      '            justify: AstryxStackJustify.end,\n'
      '            mainAxisSize: MainAxisSize.max,\n'
      '            children: <Widget>[\n'
      '              AstryxButton(\n'
      '                label: \'Clear\',\n'
      '                enabled: !_sending,\n'
      '                onPressed: _reset,\n'
      '              ),\n'
      '              AstryxButton(\n'
      '                label: \'Send message\',\n'
      '                variant: AstryxButtonVariant.primary,\n'
      '                loading: _sending,\n'
      '                onPressed: _send,\n'
      '              ),\n'
      '            ],\n'
      '          ),\n'
      '        ],\n'
      '      ),\n'
      '    );\n'
      '  }\n'
      '}\n',
  // examples/template_form_examples.dart
  'template_form_two_column':
      'class FormTwoColumnTemplate extends StatefulWidget {\n'
      '  const FormTwoColumnTemplate({super.key});\n'
      '\n'
      '  @override\n'
      '  State<FormTwoColumnTemplate> createState() => _FormTwoColumnTemplateState();\n'
      '}\n'
      '\n'
      'class _FormTwoColumnTemplateState extends State<FormTwoColumnTemplate> {\n'
      '  final TextEditingController _name = TextEditingController();\n'
      '  final TextEditingController _domain = TextEditingController(\n'
      '    text: \'atlas.example.com\',\n'
      '  );\n'
      '  final TextEditingController _bio = TextEditingController();\n'
      '\n'
      '  String? _region = \'eu\';\n'
      '  String? _visibility = \'members\';\n'
      '  final Set<String> _digests = <String>{\'weekly\'};\n'
      '  bool _dirty = false;\n'
      '\n'
      '  @override\n'
      '  void dispose() {\n'
      '    _name.dispose();\n'
      '    _domain.dispose();\n'
      '    _bio.dispose();\n'
      '    super.dispose();\n'
      '  }\n'
      '\n'
      '  void _touch() => setState(() => _dirty = true);\n'
      '\n'
      '  @override\n'
      '  Widget build(BuildContext context) {\n'
      '    // Each section is a label column and a field column. Under\n'
      '    // `formTwoColumnMinWidth` the label column moves above its fields instead\n'
      '    // of squeezing, which is the whole responsive story — no breakpoint tokens,\n'
      '    // no second layout to maintain.\n'
      '    return AstryxVStack(\n'
      '      gap: AstryxSpacingToken.spacing6,\n'
      '      align: AstryxStackAlign.stretch,\n'
      '      children: <Widget>[\n'
      '        // The saved-state badge sits beside the title at width and under it\n'
      '        // when there is no room. `Flexible` on the title is what lets the\n'
      '        // supporting line wrap instead of pushing the badge off the edge.\n'
      '        LayoutBuilder(\n'
      '          builder: (context, constraints) {\n'
      '            const title = AstryxVStack(\n'
      '              gap: AstryxSpacingToken.spacing1,\n'
      '              children: <Widget>[\n'
      '                AstryxHeading(\'Workspace settings\', level: 1),\n'
      '                AstryxText(\n'
      '                  \'Applies to everyone in Atlas.\',\n'
      '                  color: AstryxTextColor.secondary,\n'
      '                ),\n'
      '              ],\n'
      '            );\n'
      '            final badge = AstryxBadge(\n'
      '              _dirty ? \'Unsaved changes\' : \'Saved\',\n'
      '              variant: _dirty\n'
      '                  ? AstryxBadgeVariant.warning\n'
      '                  : AstryxBadgeVariant.success,\n'
      '              icon: AstryxIcon(\n'
      '                _dirty ? AstryxIconName.warning : AstryxIconName.success,\n'
      '              ),\n'
      '            );\n'
      '\n'
      '            return constraints.maxWidth < formTwoColumnMinWidth\n'
      '                ? AstryxVStack(\n'
      '                    gap: AstryxSpacingToken.spacing2,\n'
      '                    children: <Widget>[title, badge],\n'
      '                  )\n'
      '                : AstryxHStack(\n'
      '                    gap: AstryxSpacingToken.spacing3,\n'
      '                    justify: AstryxStackJustify.between,\n'
      '                    align: AstryxStackAlign.start,\n'
      '                    mainAxisSize: MainAxisSize.max,\n'
      '                    children: <Widget>[\n'
      '                      const Flexible(child: title),\n'
      '                      badge,\n'
      '                    ],\n'
      '                  );\n'
      '          },\n'
      '        ),\n'
      '        _FormSection(\n'
      '          title: \'Identity\',\n'
      '          description: \'How the workspace is named and reached.\',\n'
      '          children: <Widget>[\n'
      '            AstryxTextInput(\n'
      '              label: \'Workspace name\',\n'
      '              controller: _name,\n'
      '              required: true,\n'
      '              placeholder: \'Atlas\',\n'
      '              onChanged: (_) => _touch(),\n'
      '            ),\n'
      '            AstryxTextInput(\n'
      '              label: \'Primary domain\',\n'
      '              controller: _domain,\n'
      '              description: \'Members with this email domain join automatically.\',\n'
      '              onChanged: (_) => _touch(),\n'
      '            ),\n'
      '            AstryxSelector<String>(\n'
      '              label: \'Data region\',\n'
      '              value: _region,\n'
      '              description: \'Cannot be changed after the first write.\',\n'
      '              onChanged: (value) => setState(() {\n'
      '                _region = value;\n'
      '                _dirty = true;\n'
      '              }),\n'
      '              options: const <AstryxSelectorEntry<String>>[\n'
      '                AstryxSelectorSection(\'Europe\'),\n'
      '                AstryxSelectorOption(value: \'eu\', label: \'Frankfurt (eu-1)\'),\n'
      '                AstryxSelectorOption(value: \'uk\', label: \'London (uk-1)\'),\n'
      '                AstryxSelectorSection(\'North America\'),\n'
      '                AstryxSelectorOption(value: \'us\', label: \'Virginia (us-1)\'),\n'
      '              ],\n'
      '            ),\n'
      '          ],\n'
      '        ),\n'
      '        const AstryxDivider(),\n'
      '        _FormSection(\n'
      '          title: \'Access\',\n'
      '          description:\n'
      '              \'Who can see the workspace, and what they get by \'\n'
      '              \'default.\',\n'
      '          children: <Widget>[\n'
      '            AstryxRadioList<String>(\n'
      '              label: \'Visibility\',\n'
      '              value: _visibility,\n'
      '              onChanged: (value) => setState(() {\n'
      '                _visibility = value;\n'
      '                _dirty = true;\n'
      '              }),\n'
      '              options: const <AstryxRadioOption<String>>[\n'
      '                AstryxRadioOption(\n'
      '                  value: \'members\',\n'
      '                  label: \'Members only\',\n'
      '                  description: \'Anyone signed in to the workspace.\',\n'
      '                ),\n'
      '                AstryxRadioOption(\n'
      '                  value: \'invite\',\n'
      '                  label: \'Invite only\',\n'
      '                  description: \'Named people, one at a time.\',\n'
      '                ),\n'
      '                AstryxRadioOption(\n'
      '                  value: \'public\',\n'
      '                  label: \'Anyone with the link\',\n'
      '                  description: \'Read-only, no sign-in.\',\n'
      '                ),\n'
      '              ],\n'
      '            ),\n'
      '            AstryxTextArea(\n'
      '              label: \'Joining note\',\n'
      '              controller: _bio,\n'
      '              optional: true,\n'
      '              placeholder: \'Shown on the invitation screen.\',\n'
      '              onChanged: (_) => _touch(),\n'
      '            ),\n'
      '          ],\n'
      '        ),\n'
      '        const AstryxDivider(),\n'
      '        _FormSection(\n'
      '          title: \'Digests\',\n'
      '          description:\n'
      '              \'Checkboxes, because none of this applies until you \'\n'
      '              \'save.\',\n'
      '          children: <Widget>[\n'
      '            for (final digest in const <List<String>>[\n'
      '              <String>[\'weekly\', \'Weekly summary\', \'Mondays, 9am local time\'],\n'
      '              <String>[\'incidents\', \'Incident recap\', \'After every incident\'],\n'
      '              <String>[\'billing\', \'Billing statement\', \'On the 1st\'],\n'
      '            ])\n'
      '              AstryxCheckbox(\n'
      '                label: digest[1],\n'
      '                description: digest[2],\n'
      '                value: _digests.contains(digest[0]),\n'
      '                onChanged: (value) => setState(() {\n'
      '                  _dirty = true;\n'
      '                  if (value) {\n'
      '                    _digests.add(digest[0]);\n'
      '                  } else {\n'
      '                    _digests.remove(digest[0]);\n'
      '                  }\n'
      '                }),\n'
      '              ),\n'
      '          ],\n'
      '        ),\n'
      '        const AstryxDivider(),\n'
      '        // `wrap`, so the pair drops onto two lines on a phone rather than\n'
      '        // overflowing. Buttons size to their labels, so nothing is squeezed.\n'
      '        AstryxHStack(\n'
      '          gap: AstryxSpacingToken.spacing2,\n'
      '          runGap: AstryxSpacingToken.spacing2,\n'
      '          wrap: true,\n'
      '          justify: AstryxStackJustify.end,\n'
      '          children: <Widget>[\n'
      '            AstryxButton(\n'
      '              label: \'Discard\',\n'
      '              enabled: _dirty,\n'
      '              onPressed: () => setState(() => _dirty = false),\n'
      '            ),\n'
      '            AstryxButton(\n'
      '              label: \'Save changes\',\n'
      '              variant: AstryxButtonVariant.primary,\n'
      '              enabled: _dirty,\n'
      '              onPressed: () => setState(() => _dirty = false),\n'
      '            ),\n'
      '          ],\n'
      '        ),\n'
      '      ],\n'
      '    );\n'
      '  }\n'
      '}\n',
  // examples/template_form_examples.dart
  'template_payment_form':
      'class PaymentFormTemplate extends StatefulWidget {\n'
      '  const PaymentFormTemplate({super.key});\n'
      '\n'
      '  @override\n'
      '  State<PaymentFormTemplate> createState() => _PaymentFormTemplateState();\n'
      '}\n'
      '\n'
      'class _PaymentFormTemplateState extends State<PaymentFormTemplate> {\n'
      '  final TextEditingController _card = TextEditingController();\n'
      '  final TextEditingController _expiry = TextEditingController();\n'
      '  final TextEditingController _cvc = TextEditingController();\n'
      '  final TextEditingController _postcode = TextEditingController();\n'
      '\n'
      '  String? _country = \'gb\';\n'
      '  bool _sameAddress = true;\n'
      '  bool _paying = false;\n'
      '\n'
      '  @override\n'
      '  void dispose() {\n'
      '    _card.dispose();\n'
      '    _expiry.dispose();\n'
      '    _cvc.dispose();\n'
      '    _postcode.dispose();\n'
      '    super.dispose();\n'
      '  }\n'
      '\n'
      '  Future<void> _pay() async {\n'
      '    setState(() => _paying = true);\n'
      '    await Future<void>.delayed(const Duration(milliseconds: 900));\n'
      '    if (!mounted) return;\n'
      '    setState(() => _paying = false);\n'
      '    // The receipt is the real confirmation; the toast only says the request\n'
      '    // landed. Anything the user must keep belongs in the email, not here.\n'
      '    AstryxToastScope.of(\n'
      '      context,\n'
      '    ).show(const AstryxToast(message: \'Payment taken — receipt emailed\'));\n'
      '  }\n'
      '\n'
      '  @override\n'
      '  Widget build(BuildContext context) {\n'
      '    return AstryxVStack(\n'
      '      gap: AstryxSpacingToken.spacing6,\n'
      '      align: AstryxStackAlign.stretch,\n'
      '      children: <Widget>[\n'
      '        const AstryxVStack(\n'
      '          gap: AstryxSpacingToken.spacing1,\n'
      '          children: <Widget>[\n'
      '            AstryxHeading(\'Checkout\', level: 1),\n'
      '            AstryxText(\n'
      '              \'Annual plan, 24 seats. Cancel any time.\',\n'
      '              color: AstryxTextColor.secondary,\n'
      '            ),\n'
      '          ],\n'
      '        ),\n'
      '        // Card details on the reading side, what is being bought on the other.\n'
      '        // Narrow, the summary goes first: agreeing to a figure you have not\n'
      '        // seen yet is not consent.\n'
      '        LayoutBuilder(\n'
      '          builder: (context, constraints) =>\n'
      '              constraints.maxWidth < formTwoColumnMinWidth\n'
      '              ? AstryxVStack(\n'
      '                  gap: AstryxSpacingToken.spacing6,\n'
      '                  align: AstryxStackAlign.stretch,\n'
      '                  children: <Widget>[_summary(), _fields()],\n'
      '                )\n'
      '              : AstryxHStack(\n'
      '                  gap: AstryxSpacingToken.spacing6,\n'
      '                  align: AstryxStackAlign.start,\n'
      '                  mainAxisSize: MainAxisSize.max,\n'
      '                  children: <Widget>[\n'
      '                    Expanded(child: _fields()),\n'
      '                    SizedBox(width: 260, child: _summary()),\n'
      '                  ],\n'
      '                ),\n'
      '        ),\n'
      '        const AstryxDivider(),\n'
      '        AstryxHStack(\n'
      '          gap: AstryxSpacingToken.spacing3,\n'
      '          justify: AstryxStackJustify.between,\n'
      '          mainAxisSize: MainAxisSize.max,\n'
      '          children: <Widget>[\n'
      '            const Flexible(\n'
      '              child: AstryxText(\n'
      '                \'Charged today, then every 12 months.\',\n'
      '                type: AstryxTextType.supporting,\n'
      '                color: AstryxTextColor.secondary,\n'
      '              ),\n'
      '            ),\n'
      '            AstryxButton(\n'
      '              label: r\'Pay \$4,608.00\',\n'
      '              variant: AstryxButtonVariant.primary,\n'
      '              loading: _paying,\n'
      '              onPressed: _pay,\n'
      '            ),\n'
      '          ],\n'
      '        ),\n'
      '      ],\n'
      '    );\n'
      '  }\n'
      '\n'
      '  /// The card and billing fields.\n'
      '  Widget _fields() {\n'
      '    return AstryxVStack(\n'
      '      gap: AstryxSpacingToken.spacing4,\n'
      '      align: AstryxStackAlign.stretch,\n'
      '      children: <Widget>[\n'
      '        AstryxTextInput(\n'
      '          label: \'Card number\',\n'
      '          controller: _card,\n'
      '          required: true,\n'
      '          enabled: !_paying,\n'
      '          placeholder: \'4242 4242 4242 4242\',\n'
      '          keyboardType: TextInputType.number,\n'
      '          autofillHints: const <String>[AutofillHints.creditCardNumber],\n'
      '          inputFormatters: <TextInputFormatter>[\n'
      '            FilteringTextInputFormatter.digitsOnly,\n'
      '            LengthLimitingTextInputFormatter(16),\n'
      '          ],\n'
      '        ),\n'
      '        AstryxHStack(\n'
      '          gap: AstryxSpacingToken.spacing3,\n'
      '          align: AstryxStackAlign.start,\n'
      '          mainAxisSize: MainAxisSize.max,\n'
      '          children: <Widget>[\n'
      '            Expanded(\n'
      '              child: AstryxTextInput(\n'
      '                label: \'Expiry\',\n'
      '                controller: _expiry,\n'
      '                required: true,\n'
      '                enabled: !_paying,\n'
      '                placeholder: \'MM/YY\',\n'
      '                keyboardType: TextInputType.datetime,\n'
      '                inputFormatters: <TextInputFormatter>[\n'
      '                  LengthLimitingTextInputFormatter(5),\n'
      '                ],\n'
      '              ),\n'
      '            ),\n'
      '            Expanded(\n'
      '              child: AstryxTextInput(\n'
      '                label: \'CVC\',\n'
      '                controller: _cvc,\n'
      '                required: true,\n'
      '                enabled: !_paying,\n'
      '                placeholder: \'123\',\n'
      '                keyboardType: TextInputType.number,\n'
      '                inputFormatters: <TextInputFormatter>[\n'
      '                  FilteringTextInputFormatter.digitsOnly,\n'
      '                  LengthLimitingTextInputFormatter(4),\n'
      '                ],\n'
      '              ),\n'
      '            ),\n'
      '          ],\n'
      '        ),\n'
      '        const AstryxDivider(label: \'Billing address\'),\n'
      '        // A checkbox, not a switch: it changes what gets submitted, not what\n'
      '        // happens now.\n'
      '        AstryxCheckbox(\n'
      '          label: \'Same as the workspace address\',\n'
      '          description: \'Frankfurt, Germany\',\n'
      '          value: _sameAddress,\n'
      '          onChanged: _paying\n'
      '              ? null\n'
      '              : (value) => setState(() => _sameAddress = value),\n'
      '        ),\n'
      '        if (!_sameAddress)\n'
      '          AstryxHStack(\n'
      '            gap: AstryxSpacingToken.spacing3,\n'
      '            align: AstryxStackAlign.start,\n'
      '            mainAxisSize: MainAxisSize.max,\n'
      '            children: <Widget>[\n'
      '              Expanded(\n'
      '                child: AstryxSelector<String>(\n'
      '                  label: \'Country\',\n'
      '                  value: _country,\n'
      '                  enabled: !_paying,\n'
      '                  showSearch: true,\n'
      '                  searchPlaceholder: \'Search countries\',\n'
      '                  onChanged: (value) => setState(() => _country = value),\n'
      '                  options: const <AstryxSelectorEntry<String>>[\n'
      '                    AstryxSelectorOption(value: \'gb\', label: \'United Kingdom\'),\n'
      '                    AstryxSelectorOption(value: \'de\', label: \'Germany\'),\n'
      '                    AstryxSelectorOption(value: \'us\', label: \'United States\'),\n'
      '                    AstryxSelectorOption(value: \'jp\', label: \'Japan\'),\n'
      '                  ],\n'
      '                ),\n'
      '              ),\n'
      '              Expanded(\n'
      '                child: AstryxTextInput(\n'
      '                  label: \'Postcode\',\n'
      '                  controller: _postcode,\n'
      '                  required: true,\n'
      '                  enabled: !_paying,\n'
      '                  autofillHints: const <String>[AutofillHints.postalCode],\n'
      '                ),\n'
      '              ),\n'
      '            ],\n'
      '          ),\n'
      '      ],\n'
      '    );\n'
      '  }\n'
      '\n'
      '  /// What is being bought, beside the fields that pay for it.\n'
      '  Widget _summary() {\n'
      '    return const AstryxCard(\n'
      '      variant: AstryxCardVariant.muted,\n'
      '      header: AstryxHeading(\'Order summary\', level: 3),\n'
      '      footer: _SummaryRow(\n'
      '        label: \'Total due today\',\n'
      '        value: r\'\$4,608.00\',\n'
      '        emphasised: true,\n'
      '      ),\n'
      '      child: AstryxVStack(\n'
      '        gap: AstryxSpacingToken.spacing2,\n'
      '        align: AstryxStackAlign.stretch,\n'
      '        children: <Widget>[\n'
      '          _SummaryRow(label: \'Atlas Pro, annual\', value: r\'\$4,800.00\'),\n'
      '          _SummaryRow(label: \'24 seats\', value: \'included\'),\n'
      '          _SummaryRow(label: \'Volume discount\', value: r\'-\$192.00\'),\n'
      '        ],\n'
      '      ),\n'
      '    );\n'
      '  }\n'
      '}\n',
  // examples/template_gallery_examples.dart
  'template_classic_gallery':
      '/// One item in the gallery.\n'
      '///\n'
      '/// `name` is not decoration. A tile whose picture has not loaded, or whose\n'
      '/// reader cannot see it, has nothing else — which is why every media widget in\n'
      '/// this package makes the name required rather than optional.\n'
      'typedef GalleryItem = ({String name, String meta, String album});\n'
      '\n'
      'class ClassicGalleryTemplate extends StatefulWidget {\n'
      '  const ClassicGalleryTemplate({super.key});\n'
      '\n'
      '  @override\n'
      '  State<ClassicGalleryTemplate> createState() => _ClassicGalleryTemplateState();\n'
      '}\n'
      '\n'
      'class _ClassicGalleryTemplateState extends State<ClassicGalleryTemplate> {\n'
      '  static const List<GalleryItem> _items = <GalleryItem>[\n'
      '    (name: \'Cold aisle, rack 14\', meta: \'4032 × 3024\', album: \'Site visit\'),\n'
      '    (name: \'Patch panel B\', meta: \'4032 × 3024\', album: \'Site visit\'),\n'
      '    (name: \'Generator test\', meta: \'1920 × 1080\', album: \'Site visit\'),\n'
      '    (name: \'Latency dashboard\', meta: \'2560 × 1440\', album: \'Incident 4102\'),\n'
      '    (name: \'Scheduler timeline\', meta: \'2560 × 1440\', album: \'Incident 4102\'),\n'
      '    (name: \'Health check log\', meta: \'1440 × 900\', album: \'Incident 4102\'),\n'
      '    (name: \'Rollback approval\', meta: \'1440 × 900\', album: \'Incident 4102\'),\n'
      '    (name: \'Post-mortem board\', meta: \'3024 × 4032\', album: \'Incident 4102\'),\n'
      '  ];\n'
      '\n'
      '  final AstryxOverlayController _viewer = AstryxOverlayController();\n'
      '\n'
      '  /// Which item the viewer opens on, and which tile reads as selected.\n'
      '  int _index = 0;\n'
      '  String _album = \'All\';\n'
      '\n'
      '  @override\n'
      '  void dispose() {\n'
      '    _viewer.dispose();\n'
      '    super.dispose();\n'
      '  }\n'
      '\n'
      '  List<GalleryItem> get _shown => _album == \'All\'\n'
      '      ? _items\n'
      '      : _items.where((item) => item.album == _album).toList();\n'
      '\n'
      '  void _open(int index) {\n'
      '    setState(() => _index = index);\n'
      '    _viewer.show();\n'
      '  }\n'
      '\n'
      '  @override\n'
      '  Widget build(BuildContext context) {\n'
      '    final shown = _shown;\n'
      '\n'
      '    return SizedBox(\n'
      '      height: 620,\n'
      '      child: AstryxLayout(\n'
      '        header: AstryxHStack(\n'
      '          gap: AstryxSpacingToken.spacing3,\n'
      '          wrap: true,\n'
      '          runGap: AstryxSpacingToken.spacing2,\n'
      '          justify: AstryxStackJustify.between,\n'
      '          mainAxisSize: MainAxisSize.max,\n'
      '          children: <Widget>[\n'
      '            AstryxVStack(\n'
      '              gap: AstryxSpacingToken.spacing0_5,\n'
      '              children: <Widget>[\n'
      '                const AstryxHeading(\'Photos\', level: 1),\n'
      '                AstryxText(\n'
      '                  \'\${shown.length} of \${_items.length} items\',\n'
      '                  type: AstryxTextType.supporting,\n'
      '                  color: AstryxTextColor.secondary,\n'
      '                ),\n'
      '              ],\n'
      '            ),\n'
      '            AstryxSegmentedControl<String>(\n'
      '              label: \'Album\',\n'
      '              value: _album,\n'
      '              size: AstryxButtonSize.sm,\n'
      '              onChanged: (value) => setState(() {\n'
      '                _album = value;\n'
      '                _index = 0;\n'
      '              }),\n'
      '              segments: const <AstryxSegment<String>>[\n'
      '                AstryxSegment(value: \'All\', label: \'All\'),\n'
      '                AstryxSegment(value: \'Site visit\', label: \'Site visit\'),\n'
      '                AstryxSegment(value: \'Incident 4102\', label: \'Incident\'),\n'
      '              ],\n'
      '            ),\n'
      '          ],\n'
      '        ),\n'
      '        child: AstryxVStack(\n'
      '          gap: AstryxSpacingToken.spacing4,\n'
      '          align: AstryxStackAlign.stretch,\n'
      '          children: <Widget>[\n'
      '            // A wrapping row of fixed-width tiles rather than an `AstryxGrid`:\n'
      '            // a grid gives every cell in a row the height of the tallest, which\n'
      '            // means measuring each cell intrinsically — and a pressable tile\n'
      '            // sits inside the touch-target wrapper, which cannot answer that\n'
      '            // measurement in touch density. Uniform tiles get the same wall\n'
      '            // either way.\n'
      '            AstryxHStack(\n'
      '              gap: AstryxSpacingToken.spacing3,\n'
      '              wrap: true,\n'
      '              runGap: AstryxSpacingToken.spacing3,\n'
      '              align: AstryxStackAlign.start,\n'
      '              children: <Widget>[\n'
      '                for (var i = 0; i < shown.length; i++)\n'
      '                  _GalleryTile(item: shown[i], onPressed: () => _open(i)),\n'
      '              ],\n'
      '            ),\n'
      '            // The viewer lives beside the wall, not inside a tile: one overlay\n'
      '            // for the whole gallery, opened on whichever item was pressed.\n'
      '            AstryxLightbox(\n'
      '              controller: _viewer,\n'
      '              initialIndex: _index,\n'
      '              label: \'Photos\',\n'
      '              items: <AstryxLightboxItem>[\n'
      '                for (final item in shown)\n'
      '                  AstryxLightboxItem(\n'
      '                    label: item.name,\n'
      '                    caption: \'\${item.name} · \${item.meta} · \${item.album}\',\n'
      '                    child: SizedBox(\n'
      '                      width: 640,\n'
      '                      child: AstryxAspectRatio(\n'
      '                        ratio: 3 / 2,\n'
      '                        background: AstryxColorToken.backgroundCard,\n'
      '                        child: Center(\n'
      '                          child: AstryxText(\n'
      '                            item.name,\n'
      '                            color: AstryxTextColor.secondary,\n'
      '                          ),\n'
      '                        ),\n'
      '                      ),\n'
      '                    ),\n'
      '                  ),\n'
      '              ],\n'
      '              actions: <Widget>[\n'
      '                AstryxIconButton(\n'
      '                  icon: AstryxIconName.copy,\n'
      '                  label: \'Copy a link to this photo\',\n'
      '                  variant: AstryxButtonVariant.ghost,\n'
      '                  size: AstryxButtonSize.sm,\n'
      '                  onPressed: () {},\n'
      '                ),\n'
      '              ],\n'
      '            ),\n'
      '          ],\n'
      '        ),\n'
      '      ),\n'
      '    );\n'
      '  }\n'
      '}\n'
      '\n'
      '/// One tile: a picture, its name over the picture, and the whole thing\n'
      '/// pressable.\n'
      'class _GalleryTile extends StatelessWidget {\n'
      '  const _GalleryTile({required this.item, required this.onPressed});\n'
      '\n'
      '  final GalleryItem item;\n'
      '  final VoidCallback onPressed;\n'
      '\n'
      '  @override\n'
      '  Widget build(BuildContext context) {\n'
      '    final theme = AstryxTheme.of(context);\n'
      '\n'
      '    return SizedBox(\n'
      '      width: 200,\n'
      '      child: AstryxCard(\n'
      '        padding: AstryxSpacingToken.spacing0,\n'
      '        // The name is announced here, once. The caption over the picture is\n'
      '        // decoration by the time a screen reader gets this far.\n'
      '        semanticsLabel: \'\${item.name}, \${item.album}\',\n'
      '        onPressed: onPressed,\n'
      '        child: ClipRRect(\n'
      '          borderRadius: theme.borderRadius(AstryxRadiusToken.container),\n'
      '          child: Stack(\n'
      '            children: <Widget>[\n'
      '              const AstryxAspectRatio(\n'
      '                ratio: 3 / 2,\n'
      '                background: AstryxColorToken.backgroundInverted,\n'
      '                child: Center(\n'
      '                  // Over a dark ground, `inherit` is the only correct answer —\n'
      '                  // and inside a media scope it is the colour that scope set.\n'
      '                  child: AstryxMediaTheme(\n'
      '                    scrim: AstryxMediaScrim.none,\n'
      '                    padding: AstryxSpacingToken.spacing0,\n'
      '                    child: AstryxIcon(\n'
      '                      AstryxIconName.viewColumns,\n'
      '                      size: AstryxIconSize.lg,\n'
      '                    ),\n'
      '                  ),\n'
      '                ),\n'
      '              ),\n'
      '              // Anything drawn over media goes through `AstryxMediaTheme`: the\n'
      '              // page\'s text colour is a guess about a photograph nobody has\n'
      '              // seen, and the scrim is what makes the guess unnecessary.\n'
      '              Positioned.directional(\n'
      '                textDirection: Directionality.of(context),\n'
      '                start: 0,\n'
      '                end: 0,\n'
      '                bottom: 0,\n'
      '                child: AstryxMediaTheme(\n'
      '                  child: AstryxVStack(\n'
      '                    gap: AstryxSpacingToken.spacing0_5,\n'
      '                    children: <Widget>[\n'
      '                      AstryxText(\n'
      '                        item.name,\n'
      '                        color: AstryxTextColor.inherit,\n'
      '                        maxLines: 1,\n'
      '                      ),\n'
      '                      AstryxText(\n'
      '                        item.meta,\n'
      '                        type: AstryxTextType.supporting,\n'
      '                        color: AstryxTextColor.inherit,\n'
      '                        maxLines: 1,\n'
      '                      ),\n'
      '                    ],\n'
      '                  ),\n'
      '                ),\n'
      '              ),\n'
      '            ],\n'
      '          ),\n'
      '        ),\n'
      '      ),\n'
      '    );\n'
      '  }\n'
      '}\n',
  // examples/template_grouped_table_examples.dart
  'template_table_grouped':
      '/// One line of spend.\n'
      'typedef Expense = ({\n'
      '  String id,\n'
      '  String vendor,\n'
      '  String team,\n'
      '  String status,\n'
      '  int amount,\n'
      '  String submitted,\n'
      '});\n'
      '\n'
      'class GroupedTableTemplate extends StatefulWidget {\n'
      '  const GroupedTableTemplate({super.key});\n'
      '\n'
      '  @override\n'
      '  State<GroupedTableTemplate> createState() => _GroupedTableTemplateState();\n'
      '}\n'
      '\n'
      'class _GroupedTableTemplateState extends State<GroupedTableTemplate> {\n'
      '  static const List<Expense> _all = <Expense>[\n'
      '    (\n'
      '      id: \'EXP-2201\',\n'
      '      vendor: \'Cloud hosting\',\n'
      '      team: \'Platform\',\n'
      '      status: \'Approved\',\n'
      '      amount: 482000,\n'
      '      submitted: \'2 Aug\',\n'
      '    ),\n'
      '    (\n'
      '      id: \'EXP-2198\',\n'
      '      vendor: \'Log storage\',\n'
      '      team: \'Platform\',\n'
      '      status: \'Pending\',\n'
      '      amount: 118400,\n'
      '      submitted: \'3 Aug\',\n'
      '    ),\n'
      '    (\n'
      '      id: \'EXP-2194\',\n'
      '      vendor: \'On-call paging\',\n'
      '      team: \'Platform\',\n'
      '      status: \'Approved\',\n'
      '      amount: 64200,\n'
      '      submitted: \'5 Aug\',\n'
      '    ),\n'
      '    (\n'
      '      id: \'EXP-2190\',\n'
      '      vendor: \'Conference tickets\',\n'
      '      team: \'Design\',\n'
      '      status: \'Rejected\',\n'
      '      amount: 240000,\n'
      '      submitted: \'1 Aug\',\n'
      '    ),\n'
      '    (\n'
      '      id: \'EXP-2187\',\n'
      '      vendor: \'Prototyping tool\',\n'
      '      team: \'Design\',\n'
      '      status: \'Approved\',\n'
      '      amount: 39600,\n'
      '      submitted: \'6 Aug\',\n'
      '    ),\n'
      '    (\n'
      '      id: \'EXP-2183\',\n'
      '      vendor: \'Usability panel\',\n'
      '      team: \'Design\',\n'
      '      status: \'Pending\',\n'
      '      amount: 156000,\n'
      '      submitted: \'7 Aug\',\n'
      '    ),\n'
      '    (\n'
      '      id: \'EXP-2179\',\n'
      '      vendor: \'CRM seats\',\n'
      '      team: \'Sales\',\n'
      '      status: \'Approved\',\n'
      '      amount: 372000,\n'
      '      submitted: \'2 Aug\',\n'
      '    ),\n'
      '    (\n'
      '      id: \'EXP-2176\',\n'
      '      vendor: \'Travel, Berlin\',\n'
      '      team: \'Sales\',\n'
      '      status: \'Pending\',\n'
      '      amount: 87300,\n'
      '      submitted: \'8 Aug\',\n'
      '    ),\n'
      '  ];\n'
      '\n'
      '  /// The sort applies to every group, not to one of them.\n'
      '  AstryxTableSort? _sort = const AstryxTableSort(\n'
      '    \'amount\',\n'
      '    AstryxSortDirection.descending,\n'
      '  );\n'
      '\n'
      '  /// One selection across the whole screen, however many tables draw it.\n'
      '  Set<Object> _selected = <Object>{};\n'
      '\n'
      '  /// Which field the rows are bucketed by. Grouping is a decision the caller\n'
      '  /// makes about the data, not something a table can be asked to work out.\n'
      '  String _groupBy = \'team\';\n'
      '\n'
      '  String _keyOf(Expense row) => _groupBy == \'team\' ? row.team : row.status;\n'
      '\n'
      '  /// The groups, in a stable order, each with its rows already sorted.\n'
      '  List<({String title, List<Expense> rows, int subtotal})> get _groups {\n'
      '    final buckets = <String, List<Expense>>{};\n'
      '    for (final row in _all) {\n'
      '      buckets.putIfAbsent(_keyOf(row), () => <Expense>[]).add(row);\n'
      '    }\n'
      '\n'
      '    final groups = <({String title, List<Expense> rows, int subtotal})>[];\n'
      '    for (final entry in buckets.entries) {\n'
      '      final rows = List<Expense>.of(entry.value);\n'
      '      final sort = _sort;\n'
      '      if (sort != null) {\n'
      '        int by(Expense a, Expense b) => switch (sort.columnId) {\n'
      '          \'vendor\' => a.vendor.compareTo(b.vendor),\n'
      '          \'status\' => a.status.compareTo(b.status),\n'
      '          _ => a.amount.compareTo(b.amount),\n'
      '        };\n'
      '        rows.sort(\n'
      '          (a, b) => sort.direction == AstryxSortDirection.ascending\n'
      '              ? by(a, b)\n'
      '              : by(b, a),\n'
      '        );\n'
      '      }\n'
      '      groups.add((\n'
      '        title: entry.key,\n'
      '        rows: rows,\n'
      '        subtotal: rows.fold<int>(0, (sum, row) => sum + row.amount),\n'
      '      ));\n'
      '    }\n'
      '\n'
      '    return groups..sort((a, b) => b.subtotal.compareTo(a.subtotal));\n'
      '  }\n'
      '\n'
      '  int get _total => _all.fold<int>(0, (sum, row) => sum + row.amount);\n'
      '\n'
      '  /// The columns, declared once and reused by every group.\n'
      '  ///\n'
      '  /// This is what keeps the groups lined up. Each table works out its own\n'
      '  /// widths from its own rows, so a column left to size itself would be one\n'
      '  /// width under Platform and another under Design — and a grouped table whose\n'
      '  /// columns do not line up is a set of unrelated tables in a stack.\n'
      '  List<AstryxTableColumn<Expense>> get _columns => <AstryxTableColumn<Expense>>[\n'
      '    AstryxTableColumn<Expense>(\n'
      '      id: \'vendor\',\n'
      '      header: \'Vendor\',\n'
      '      compare: (a, b) => a.vendor.compareTo(b.vendor),\n'
      '      cellBuilder: (context, row) => AstryxVStack(\n'
      '        gap: AstryxSpacingToken.spacing0_5,\n'
      '        children: <Widget>[\n'
      '          AstryxText(row.vendor, maxLines: 1),\n'
      '          AstryxText(\n'
      '            row.id,\n'
      '            type: AstryxTextType.code,\n'
      '            color: AstryxTextColor.secondary,\n'
      '          ),\n'
      '        ],\n'
      '      ),\n'
      '    ),\n'
      '    AstryxTableColumn<Expense>(\n'
      '      id: \'status\',\n'
      '      header: \'Status\',\n'
      '      width: const AstryxTableColumnWidth.fixed(140),\n'
      '      compare: (a, b) => a.status.compareTo(b.status),\n'
      '      cellBuilder: (context, row) => switch (row.status) {\n'
      '        \'Approved\' => const AstryxBadge(\n'
      '          \'Approved\',\n'
      '          variant: AstryxBadgeVariant.success,\n'
      '          icon: AstryxIcon(AstryxIconName.success),\n'
      '        ),\n'
      '        \'Rejected\' => const AstryxBadge(\n'
      '          \'Rejected\',\n'
      '          variant: AstryxBadgeVariant.error,\n'
      '          icon: AstryxIcon(AstryxIconName.error),\n'
      '        ),\n'
      '        _ => const AstryxBadge(\n'
      '          \'Pending\',\n'
      '          variant: AstryxBadgeVariant.warning,\n'
      '          icon: AstryxIcon(AstryxIconName.clock),\n'
      '        ),\n'
      '      },\n'
      '    ),\n'
      '    AstryxTableColumn<Expense>(\n'
      '      id: \'submitted\',\n'
      '      header: \'Submitted\',\n'
      '      width: const AstryxTableColumnWidth.fixed(110),\n'
      '      cellBuilder: (context, row) => AstryxText(\n'
      '        row.submitted,\n'
      '        type: AstryxTextType.supporting,\n'
      '        color: AstryxTextColor.secondary,\n'
      '        maxLines: 1,\n'
      '      ),\n'
      '    ),\n'
      '    AstryxTableColumn<Expense>(\n'
      '      id: \'amount\',\n'
      '      header: \'Amount\',\n'
      '      width: const AstryxTableColumnWidth.fixed(120),\n'
      '      alignment: AstryxTableAlignment.end,\n'
      '      compare: (a, b) => a.amount.compareTo(b.amount),\n'
      '      cellBuilder: (context, row) =>\n'
      '          AstryxText(_money(row.amount), tabularNumbers: true),\n'
      '    ),\n'
      '  ];\n'
      '\n'
      '  @override\n'
      '  Widget build(BuildContext context) {\n'
      '    final groups = _groups;\n'
      '\n'
      '    return AstryxVStack(\n'
      '      gap: AstryxSpacingToken.spacing4,\n'
      '      align: AstryxStackAlign.stretch,\n'
      '      children: <Widget>[\n'
      '        AstryxHStack(\n'
      '          gap: AstryxSpacingToken.spacing3,\n'
      '          justify: AstryxStackJustify.between,\n'
      '          mainAxisSize: MainAxisSize.max,\n'
      '          wrap: true,\n'
      '          runGap: AstryxSpacingToken.spacing2,\n'
      '          children: <Widget>[\n'
      '            AstryxVStack(\n'
      '              gap: AstryxSpacingToken.spacing1,\n'
      '              children: <Widget>[\n'
      '                const AstryxHeading(\'Expenses, August\', level: 1),\n'
      '                AstryxText(\n'
      '                  \'\${_all.length} lines · \${_money(_total)}\',\n'
      '                  type: AstryxTextType.supporting,\n'
      '                  color: AstryxTextColor.secondary,\n'
      '                ),\n'
      '              ],\n'
      '            ),\n'
      '            AstryxSegmentedControl<String>(\n'
      '              label: \'Group by\',\n'
      '              value: _groupBy,\n'
      '              size: AstryxButtonSize.sm,\n'
      '              onChanged: (value) => setState(() => _groupBy = value),\n'
      '              segments: const <AstryxSegment<String>>[\n'
      '                AstryxSegment(value: \'team\', label: \'Team\'),\n'
      '                AstryxSegment(value: \'status\', label: \'Status\'),\n'
      '              ],\n'
      '            ),\n'
      '          ],\n'
      '        ),\n'
      '        if (_selected.isNotEmpty)\n'
      '          AstryxBanner(\n'
      '            title: \'\${_selected.length} selected\',\n'
      '            announce: false,\n'
      '            actions: <Widget>[\n'
      '              AstryxButton(\n'
      '                label: \'Approve\',\n'
      '                variant: AstryxButtonVariant.primary,\n'
      '                size: AstryxButtonSize.sm,\n'
      '                onPressed: () => setState(() => _selected = <Object>{}),\n'
      '              ),\n'
      '              AstryxButton(\n'
      '                label: \'Clear\',\n'
      '                size: AstryxButtonSize.sm,\n'
      '                onPressed: () => setState(() => _selected = <Object>{}),\n'
      '              ),\n'
      '            ],\n'
      '          ),\n'
      '        // One collapsible per group, and one table inside each. The group is a\n'
      '        // *disclosure* rather than a row, which is why it can hold a subtotal\n'
      '        // and a count without either of them pretending to be data.\n'
      '        AstryxCollapsibleGroup(\n'
      '          children: <AstryxCollapsible>[\n'
      '            for (final group in groups)\n'
      '              AstryxCollapsible(\n'
      '                title: group.title,\n'
      '                initiallyExpanded: true,\n'
      '                description:\n'
      '                    \'\${group.rows.length} lines · \${_money(group.subtotal)}\',\n'
      '                trailing: AstryxBadge(\n'
      '                  \'\${(group.subtotal / _total * 100).round()}%\',\n'
      '                  semanticsLabel:\n'
      '                      \'\${(group.subtotal / _total * 100).round()} per cent of \'\n'
      '                      \'the total\',\n'
      '                ),\n'
      '                child: AstryxTable<Expense>(\n'
      '                  // Each table is named for its group. Four tables all called\n'
      '                  // "Expenses" is four identical announcements, and a reader\n'
      '                  // who tabs into the third one has no idea which it is.\n'
      '                  label: \'\${group.title} expenses\',\n'
      '                  keyOf: (row) => row.id,\n'
      '                  rowLabelOf: (row) => \'\${row.vendor}, \${_money(row.amount)}\',\n'
      '                  columns: _columns,\n'
      '                  rows: group.rows,\n'
      '                  density: AstryxTableDensity.compact,\n'
      '                  // Shared, so a sort press in one group reorders all of them\n'
      '                  // — which is the behaviour a single grouped table would have.\n'
      '                  sort: _sort,\n'
      '                  onSortChanged: (sort) => setState(() => _sort = sort),\n'
      '                  selectionMode: AstryxTableSelectionMode.multiple,\n'
      '                  selected: _selected,\n'
      '                  onSelectionChanged: (value) => setState(() {\n'
      '                    // The set is the whole screen\'s, so a group\'s "select all"\n'
      '                    // has to add its own keys without dropping anyone else\'s.\n'
      '                    final keys = group.rows.map((row) => row.id).toSet();\n'
      '                    _selected = <Object>{\n'
      '                      ..._selected.where((key) => !keys.contains(key)),\n'
      '                      ...value.where(keys.contains),\n'
      '                    };\n'
      '                  }),\n'
      '                ),\n'
      '              ),\n'
      '          ],\n'
      '        ),\n'
      '        AstryxCard(\n'
      '          variant: AstryxCardVariant.muted,\n'
      '          padding: AstryxSpacingToken.spacing3,\n'
      '          child: AstryxHStack(\n'
      '            gap: AstryxSpacingToken.spacing3,\n'
      '            justify: AstryxStackJustify.between,\n'
      '            mainAxisSize: MainAxisSize.max,\n'
      '            children: <Widget>[\n'
      '              const AstryxText(\'Total\', type: AstryxTextType.label),\n'
      '              AstryxText(\n'
      '                _money(_total),\n'
      '                type: AstryxTextType.label,\n'
      '                tabularNumbers: true,\n'
      '              ),\n'
      '            ],\n'
      '          ),\n'
      '        ),\n'
      '      ],\n'
      '    );\n'
      '  }\n'
      '}\n'
      '\n'
      '/// Pence to pounds, grouped in threes.\n'
      'String _money(int value) {\n'
      '  final units = (value / 100).floor().toString();\n'
      '  final grouped = StringBuffer();\n'
      '  for (var i = 0; i < units.length; i++) {\n'
      '    if (i > 0 && (units.length - i) % 3 == 0) grouped.write(\',\');\n'
      '    grouped.write(units[i]);\n'
      '  }\n'
      '  return \'£\$grouped.\${(value % 100).toString().padLeft(2, \'0\')}\';\n'
      '}\n',
  // examples/template_heatmap_examples.dart
  'template_table_page_heatmap_status':
      '/// One service, and its p95 latency in each region.\n'
      'typedef ServiceLatency = ({\n'
      '  String service,\n'
      '  String owner,\n'
      '  Map<String, int> byRegion,\n'
      '  String status,\n'
      '});\n'
      '\n'
      'class HeatmapStatusTablePageTemplate extends StatefulWidget {\n'
      '  const HeatmapStatusTablePageTemplate({super.key});\n'
      '\n'
      '  @override\n'
      '  State<HeatmapStatusTablePageTemplate> createState() =>\n'
      '      _HeatmapStatusTablePageTemplateState();\n'
      '}\n'
      '\n'
      'class _HeatmapStatusTablePageTemplateState\n'
      '    extends State<HeatmapStatusTablePageTemplate> {\n'
      '  static const List<String> _regions = <String>[\n'
      '    \'eu-west\',\n'
      '    \'eu-north\',\n'
      '    \'us-east\',\n'
      '    \'us-west\',\n'
      '    \'ap-south\',\n'
      '  ];\n'
      '\n'
      '  static const List<ServiceLatency> _all = <ServiceLatency>[\n'
      '    (\n'
      '      service: \'scheduler\',\n'
      '      owner: \'Platform\',\n'
      '      status: \'Breaching\',\n'
      '      byRegion: <String, int>{\n'
      '        \'eu-west\': 412,\n'
      '        \'eu-north\': 388,\n'
      '        \'us-east\': 902,\n'
      '        \'us-west\': 741,\n'
      '        \'ap-south\': 1180,\n'
      '      },\n'
      '    ),\n'
      '    (\n'
      '      service: \'edge\',\n'
      '      owner: \'Platform\',\n'
      '      status: \'At risk\',\n'
      '      byRegion: <String, int>{\n'
      '        \'eu-west\': 88,\n'
      '        \'eu-north\': 94,\n'
      '        \'us-east\': 121,\n'
      '        \'us-west\': 486,\n'
      '        \'ap-south\': 512,\n'
      '      },\n'
      '    ),\n'
      '    (\n'
      '      service: \'artifacts\',\n'
      '      owner: \'Delivery\',\n'
      '      status: \'Healthy\',\n'
      '      byRegion: <String, int>{\n'
      '        \'eu-west\': 142,\n'
      '        \'eu-north\': 138,\n'
      '        \'us-east\': 166,\n'
      '        \'us-west\': 174,\n'
      '        \'ap-south\': 231,\n'
      '      },\n'
      '    ),\n'
      '    (\n'
      '      service: \'metrics\',\n'
      '      owner: \'Observability\',\n'
      '      status: \'At risk\',\n'
      '      byRegion: <String, int>{\n'
      '        \'eu-west\': 264,\n'
      '        \'eu-north\': 271,\n'
      '        \'us-east\': 298,\n'
      '        \'us-west\': 312,\n'
      '        \'ap-south\': 640,\n'
      '      },\n'
      '    ),\n'
      '    (\n'
      '      service: \'registry\',\n'
      '      owner: \'Delivery\',\n'
      '      status: \'Healthy\',\n'
      '      byRegion: <String, int>{\n'
      '        \'eu-west\': 61,\n'
      '        \'eu-north\': 58,\n'
      '        \'us-east\': 74,\n'
      '        \'us-west\': 79,\n'
      '        \'ap-south\': 96,\n'
      '      },\n'
      '    ),\n'
      '    (\n'
      '      service: \'billing\',\n'
      '      owner: \'Commerce\',\n'
      '      status: \'Healthy\',\n'
      '      byRegion: <String, int>{\n'
      '        \'eu-west\': 104,\n'
      '        \'eu-north\': 111,\n'
      '        \'us-east\': 98,\n'
      '        \'us-west\': 122,\n'
      '        \'ap-south\': 148,\n'
      '      },\n'
      '    ),\n'
      '    (\n'
      '      service: \'search\',\n'
      '      owner: \'Discovery\',\n'
      '      status: \'Breaching\',\n'
      '      byRegion: <String, int>{\n'
      '        \'eu-west\': 520,\n'
      '        \'eu-north\': 498,\n'
      '        \'us-east\': 610,\n'
      '        \'us-west\': 588,\n'
      '        \'ap-south\': 860,\n'
      '      },\n'
      '    ),\n'
      '  ];\n'
      '\n'
      '  String _owner = \'All\';\n'
      '  int _page = 1;\n'
      '  static const int _pageSize = 4;\n'
      '\n'
      '  List<ServiceLatency> get _matches => _owner == \'All\'\n'
      '      ? _all\n'
      '      : _all.where((row) => row.owner == _owner).toList();\n'
      '\n'
      '  List<ServiceLatency> get _rows {\n'
      '    final matches = _matches;\n'
      '    final start = (_page - 1) * _pageSize;\n'
      '    if (start >= matches.length) return const <ServiceLatency>[];\n'
      '    final end = start + _pageSize;\n'
      '    return matches.sublist(start, end > matches.length ? matches.length : end);\n'
      '  }\n'
      '\n'
      '  /// The scale spans the **whole grid**, not the page and not the row.\n'
      '  ///\n'
      '  /// A ramp recomputed per page would recolour every cell when the reader\n'
      '  /// turned it — the same 412 ms would be pale on one page and saturated on\n'
      '  /// the next, which makes the colour a fact about the page rather than about\n'
      '  /// the number.\n'
      '  static final int _worst = _all\n'
      '      .expand((row) => row.byRegion.values)\n'
      '      .reduce((a, b) => a > b ? a : b);\n'
      '\n'
      '  double _intensity(int value) => value / _worst;\n'
      '\n'
      '  void _refilter(VoidCallback change) => setState(() {\n'
      '    change();\n'
      '    _page = 1;\n'
      '  });\n'
      '\n'
      '  @override\n'
      '  Widget build(BuildContext context) {\n'
      '    final matches = _matches;\n'
      '    final rows = _rows;\n'
      '    final pages = (matches.length / _pageSize).ceil().clamp(1, 999);\n'
      '\n'
      '    return SizedBox(\n'
      '      height: 620,\n'
      '      child: AstryxLayout(\n'
      '        scrollable: false,\n'
      '        header: AstryxVStack(\n'
      '          gap: AstryxSpacingToken.spacing3,\n'
      '          align: AstryxStackAlign.stretch,\n'
      '          children: <Widget>[\n'
      '            AstryxHStack(\n'
      '              gap: AstryxSpacingToken.spacing3,\n'
      '              justify: AstryxStackJustify.between,\n'
      '              mainAxisSize: MainAxisSize.max,\n'
      '              wrap: true,\n'
      '              runGap: AstryxSpacingToken.spacing2,\n'
      '              children: <Widget>[\n'
      '                AstryxVStack(\n'
      '                  gap: AstryxSpacingToken.spacing1,\n'
      '                  children: <Widget>[\n'
      '                    const AstryxHeading(\'p95 latency by region\', level: 1),\n'
      '                    AstryxText(\n'
      '                      \'\${matches.length} services · milliseconds\',\n'
      '                      type: AstryxTextType.supporting,\n'
      '                      color: AstryxTextColor.secondary,\n'
      '                    ),\n'
      '                  ],\n'
      '                ),\n'
      '                AstryxSegmentedControl<String>(\n'
      '                  label: \'Owner\',\n'
      '                  value: _owner,\n'
      '                  size: AstryxButtonSize.sm,\n'
      '                  onChanged: (value) => _refilter(() => _owner = value),\n'
      '                  segments: const <AstryxSegment<String>>[\n'
      '                    AstryxSegment(value: \'All\', label: \'All\'),\n'
      '                    AstryxSegment(value: \'Platform\', label: \'Platform\'),\n'
      '                    AstryxSegment(value: \'Delivery\', label: \'Delivery\'),\n'
      '                  ],\n'
      '                ),\n'
      '              ],\n'
      '            ),\n'
      '            // The legend is not optional decoration. Without it the ramp is a\n'
      '            // set of colours with no stated direction, and a reader has to\n'
      '            // infer from the numbers what the colours were supposed to add.\n'
      '            HeatLegend(\n'
      '              low: \'fastest\',\n'
      '              high: \'slowest (\$_worst ms)\',\n'
      '              tint: AstryxColorToken.error,\n'
      '            ),\n'
      '          ],\n'
      '        ),\n'
      '        footer: AstryxHStack(\n'
      '          gap: AstryxSpacingToken.spacing3,\n'
      '          justify: AstryxStackJustify.between,\n'
      '          mainAxisSize: MainAxisSize.max,\n'
      '          wrap: true,\n'
      '          runGap: AstryxSpacingToken.spacing2,\n'
      '          children: <Widget>[\n'
      '            AstryxText(\n'
      '              \'\${rows.length} of \${matches.length} services\',\n'
      '              type: AstryxTextType.supporting,\n'
      '              color: AstryxTextColor.secondary,\n'
      '              tabularNumbers: true,\n'
      '            ),\n'
      '            AstryxPagination(\n'
      '              page: _page,\n'
      '              pageCount: pages,\n'
      '              onPageChanged: (page) => setState(() => _page = page),\n'
      '            ),\n'
      '          ],\n'
      '        ),\n'
      '        child: AstryxTable<ServiceLatency>(\n'
      '          label: \'p95 latency by service and region\',\n'
      '          keyOf: (row) => row.service,\n'
      '          rowLabelOf: (row) => row.service,\n'
      '          density: AstryxTableDensity.compact,\n'
      '          minWidth: 720,\n'
      '          columns: <AstryxTableColumn<ServiceLatency>>[\n'
      '            AstryxTableColumn<ServiceLatency>(\n'
      '              id: \'service\',\n'
      '              header: \'Service\',\n'
      '              width: const AstryxTableColumnWidth.fixed(150),\n'
      '              cellBuilder: (context, row) => AstryxVStack(\n'
      '                gap: AstryxSpacingToken.spacing0_5,\n'
      '                children: <Widget>[\n'
      '                  AstryxText(row.service, type: AstryxTextType.code),\n'
      '                  AstryxText(\n'
      '                    row.owner,\n'
      '                    type: AstryxTextType.supporting,\n'
      '                    color: AstryxTextColor.secondary,\n'
      '                    maxLines: 1,\n'
      '                  ),\n'
      '                ],\n'
      '              ),\n'
      '            ),\n'
      '            for (final region in _regions)\n'
      '              AstryxTableColumn<ServiceLatency>(\n'
      '                id: region,\n'
      '                header: region,\n'
      '                width: const AstryxTableColumnWidth.fixed(96),\n'
      '                alignment: AstryxTableAlignment.end,\n'
      '                compare: (a, b) =>\n'
      '                    a.byRegion[region]!.compareTo(b.byRegion[region]!),\n'
      '                cellBuilder: (context, row) => HeatCell(\n'
      '                  text: \'\${row.byRegion[region]}\',\n'
      '                  intensity: _intensity(row.byRegion[region]!),\n'
      '                  tint: AstryxColorToken.error,\n'
      '                  onTint: AstryxColorToken.onError,\n'
      '                  semanticsLabel:\n'
      '                      \'\${row.byRegion[region]} milliseconds in \$region\',\n'
      '                ),\n'
      '              ),\n'
      '            AstryxTableColumn<ServiceLatency>(\n'
      '              id: \'status\',\n'
      '              header: \'Objective\',\n'
      '              width: const AstryxTableColumnWidth.fixed(130),\n'
      '              cellBuilder: (context, row) => switch (row.status) {\n'
      '                // The status column is *semantic*, and it is a badge rather\n'
      '                // than a heat cell: "breaching" is a threshold somebody\n'
      '                // agreed, not a position on a ramp. Two different kinds of\n'
      '                // colour on one screen have to look like two different kinds.\n'
      '                \'Breaching\' => const AstryxBadge(\n'
      '                  \'Breaching\',\n'
      '                  variant: AstryxBadgeVariant.error,\n'
      '                  icon: AstryxIcon(AstryxIconName.error),\n'
      '                ),\n'
      '                \'At risk\' => const AstryxBadge(\n'
      '                  \'At risk\',\n'
      '                  variant: AstryxBadgeVariant.warning,\n'
      '                  icon: AstryxIcon(AstryxIconName.warning),\n'
      '                ),\n'
      '                _ => const AstryxBadge(\n'
      '                  \'Healthy\',\n'
      '                  variant: AstryxBadgeVariant.success,\n'
      '                  icon: AstryxIcon(AstryxIconName.success),\n'
      '                ),\n'
      '              },\n'
      '            ),\n'
      '          ],\n'
      '          rows: rows,\n'
      '        ),\n'
      '      ),\n'
      '    );\n'
      '  }\n'
      '}\n',
  // examples/template_heatmap_examples.dart
  'template_table_page_shoe_store_heatmap':
      '/// One shoe, and how many pairs went in each size.\n'
      'typedef Style = ({\n'
      '  String name,\n'
      '  String range,\n'
      '  Map<String, int> bySize,\n'
      '  int stock,\n'
      '});\n'
      '\n'
      'class ShoeStoreHeatmapTemplate extends StatefulWidget {\n'
      '  const ShoeStoreHeatmapTemplate({super.key});\n'
      '\n'
      '  @override\n'
      '  State<ShoeStoreHeatmapTemplate> createState() =>\n'
      '      _ShoeStoreHeatmapTemplateState();\n'
      '}\n'
      '\n'
      'class _ShoeStoreHeatmapTemplateState extends State<ShoeStoreHeatmapTemplate> {\n'
      '  static const List<String> _sizes = <String>[\'6\', \'7\', \'8\', \'9\', \'10\', \'11\'];\n'
      '\n'
      '  static const List<Style> _all = <Style>[\n'
      '    (\n'
      '      name: \'Trail Runner GTX\',\n'
      '      range: \'Trail\',\n'
      '      stock: 412,\n'
      '      bySize: <String, int>{\n'
      '        \'6\': 18,\n'
      '        \'7\': 46,\n'
      '        \'8\': 92,\n'
      '        \'9\': 141,\n'
      '        \'10\': 118,\n'
      '        \'11\': 54,\n'
      '      },\n'
      '    ),\n'
      '    (\n'
      '      name: \'Fell Shoe 3\',\n'
      '      range: \'Trail\',\n'
      '      stock: 96,\n'
      '      bySize: <String, int>{\n'
      '        \'6\': 11,\n'
      '        \'7\': 28,\n'
      '        \'8\': 61,\n'
      '        \'9\': 88,\n'
      '        \'10\': 74,\n'
      '        \'11\': 31,\n'
      '      },\n'
      '    ),\n'
      '    (\n'
      '      name: \'Approach Mid\',\n'
      '      range: \'Hiking\',\n'
      '      stock: 12,\n'
      '      bySize: <String, int>{\n'
      '        \'6\': 6,\n'
      '        \'7\': 19,\n'
      '        \'8\': 44,\n'
      '        \'9\': 52,\n'
      '        \'10\': 48,\n'
      '        \'11\': 22,\n'
      '      },\n'
      '    ),\n'
      '    (\n'
      '      name: \'Road Tempo\',\n'
      '      range: \'Road\',\n'
      '      stock: 288,\n'
      '      bySize: <String, int>{\n'
      '        \'6\': 24,\n'
      '        \'7\': 58,\n'
      '        \'8\': 104,\n'
      '        \'9\': 162,\n'
      '        \'10\': 131,\n'
      '        \'11\': 47,\n'
      '      },\n'
      '    ),\n'
      '    (\n'
      '      name: \'City Knit\',\n'
      '      range: \'Road\',\n'
      '      stock: 0,\n'
      '      bySize: <String, int>{\n'
      '        \'6\': 31,\n'
      '        \'7\': 64,\n'
      '        \'8\': 88,\n'
      '        \'9\': 96,\n'
      '        \'10\': 71,\n'
      '        \'11\': 26,\n'
      '      },\n'
      '    ),\n'
      '    (\n'
      '      name: \'Summit Boot\',\n'
      '      range: \'Hiking\',\n'
      '      stock: 54,\n'
      '      bySize: <String, int>{\n'
      '        \'6\': 4,\n'
      '        \'7\': 12,\n'
      '        \'8\': 33,\n'
      '        \'9\': 41,\n'
      '        \'10\': 39,\n'
      '        \'11\': 26,\n'
      '      },\n'
      '    ),\n'
      '  ];\n'
      '\n'
      '  String _range = \'All\';\n'
      '  int _page = 1;\n'
      '  static const int _pageSize = 4;\n'
      '\n'
      '  List<Style> get _matches => _range == \'All\'\n'
      '      ? _all\n'
      '      : _all.where((row) => row.range == _range).toList();\n'
      '\n'
      '  List<Style> get _rows {\n'
      '    final matches = _matches;\n'
      '    final start = (_page - 1) * _pageSize;\n'
      '    if (start >= matches.length) return const <Style>[];\n'
      '    final end = start + _pageSize;\n'
      '    return matches.sublist(start, end > matches.length ? matches.length : end);\n'
      '  }\n'
      '\n'
      '  /// The busiest cell in the whole grid, so the ramp means the same thing on\n'
      '  /// every page and under every filter.\n'
      '  static final int _best = _all\n'
      '      .expand((row) => row.bySize.values)\n'
      '      .reduce((a, b) => a > b ? a : b);\n'
      '\n'
      '  /// Which size sold most, across everything shown. The point of the screen.\n'
      '  String get _peakSize {\n'
      '    final totals = <String, int>{};\n'
      '    for (final row in _matches) {\n'
      '      for (final entry in row.bySize.entries) {\n'
      '        totals[entry.key] = (totals[entry.key] ?? 0) + entry.value;\n'
      '      }\n'
      '    }\n'
      '    if (totals.isEmpty) return \'—\';\n'
      '    final ranked = totals.entries.toList()\n'
      '      ..sort((a, b) => b.value.compareTo(a.value));\n'
      '    return \'UK \${ranked.first.key}\';\n'
      '  }\n'
      '\n'
      '  void _refilter(VoidCallback change) => setState(() {\n'
      '    change();\n'
      '    _page = 1;\n'
      '  });\n'
      '\n'
      '  @override\n'
      '  Widget build(BuildContext context) {\n'
      '    final matches = _matches;\n'
      '    final rows = _rows;\n'
      '    final pages = (matches.length / _pageSize).ceil().clamp(1, 999);\n'
      '\n'
      '    return SizedBox(\n'
      '      height: 620,\n'
      '      child: AstryxLayout(\n'
      '        scrollable: false,\n'
      '        header: AstryxVStack(\n'
      '          gap: AstryxSpacingToken.spacing3,\n'
      '          align: AstryxStackAlign.stretch,\n'
      '          children: <Widget>[\n'
      '            AstryxHStack(\n'
      '              gap: AstryxSpacingToken.spacing3,\n'
      '              justify: AstryxStackJustify.between,\n'
      '              mainAxisSize: MainAxisSize.max,\n'
      '              wrap: true,\n'
      '              runGap: AstryxSpacingToken.spacing2,\n'
      '              children: <Widget>[\n'
      '                AstryxVStack(\n'
      '                  gap: AstryxSpacingToken.spacing1,\n'
      '                  children: <Widget>[\n'
      '                    const AstryxHeading(\'Pairs sold by size\', level: 1),\n'
      '                    // The conclusion, in words, above the grid. A heatmap is\n'
      '                    // how a reader checks an answer; it is a poor way to be\n'
      '                    // told one.\n'
      '                    AstryxText(\n'
      '                      \'Busiest size: \$_peakSize · \${matches.length} styles\',\n'
      '                      type: AstryxTextType.supporting,\n'
      '                      color: AstryxTextColor.secondary,\n'
      '                    ),\n'
      '                  ],\n'
      '                ),\n'
      '                AstryxSegmentedControl<String>(\n'
      '                  label: \'Range\',\n'
      '                  value: _range,\n'
      '                  size: AstryxButtonSize.sm,\n'
      '                  onChanged: (value) => _refilter(() => _range = value),\n'
      '                  segments: const <AstryxSegment<String>>[\n'
      '                    AstryxSegment(value: \'All\', label: \'All\'),\n'
      '                    AstryxSegment(value: \'Road\', label: \'Road\'),\n'
      '                    AstryxSegment(value: \'Trail\', label: \'Trail\'),\n'
      '                    AstryxSegment(value: \'Hiking\', label: \'Hiking\'),\n'
      '                  ],\n'
      '                ),\n'
      '              ],\n'
      '            ),\n'
      '            // Sales rise toward `success`, and latency rose toward `error` on\n'
      '            // the [HeatmapStatusTablePageTemplate]. Same ramp, opposite\n'
      '            // meaning — which is exactly why the legend has to say which end\n'
      '            // is which rather than leaving the hue to imply it.\n'
      '            HeatLegend(\n'
      '              low: \'fewest\',\n'
      '              high: \'most (\$_best pairs)\',\n'
      '              tint: AstryxColorToken.success,\n'
      '            ),\n'
      '          ],\n'
      '        ),\n'
      '        footer: AstryxHStack(\n'
      '          gap: AstryxSpacingToken.spacing3,\n'
      '          justify: AstryxStackJustify.between,\n'
      '          mainAxisSize: MainAxisSize.max,\n'
      '          wrap: true,\n'
      '          runGap: AstryxSpacingToken.spacing2,\n'
      '          children: <Widget>[\n'
      '            AstryxText(\n'
      '              \'\${rows.length} of \${matches.length} styles\',\n'
      '              type: AstryxTextType.supporting,\n'
      '              color: AstryxTextColor.secondary,\n'
      '              tabularNumbers: true,\n'
      '            ),\n'
      '            AstryxPagination(\n'
      '              page: _page,\n'
      '              pageCount: pages,\n'
      '              onPageChanged: (page) => setState(() => _page = page),\n'
      '            ),\n'
      '          ],\n'
      '        ),\n'
      '        child: AstryxTable<Style>(\n'
      '          label: \'Pairs sold by style and size\',\n'
      '          keyOf: (row) => row.name,\n'
      '          rowLabelOf: (row) => row.name,\n'
      '          density: AstryxTableDensity.compact,\n'
      '          minWidth: 760,\n'
      '          columns: <AstryxTableColumn<Style>>[\n'
      '            AstryxTableColumn<Style>(\n'
      '              id: \'style\',\n'
      '              header: \'Style\',\n'
      '              width: const AstryxTableColumnWidth.fixed(170),\n'
      '              cellBuilder: (context, row) => AstryxVStack(\n'
      '                gap: AstryxSpacingToken.spacing0_5,\n'
      '                children: <Widget>[\n'
      '                  AstryxText(row.name, maxLines: 1),\n'
      '                  AstryxText(\n'
      '                    row.range,\n'
      '                    type: AstryxTextType.supporting,\n'
      '                    color: AstryxTextColor.secondary,\n'
      '                    maxLines: 1,\n'
      '                  ),\n'
      '                ],\n'
      '              ),\n'
      '            ),\n'
      '            for (final size in _sizes)\n'
      '              AstryxTableColumn<Style>(\n'
      '                id: \'size_\$size\',\n'
      '                header: \'UK \$size\',\n'
      '                width: const AstryxTableColumnWidth.fixed(78),\n'
      '                alignment: AstryxTableAlignment.end,\n'
      '                compare: (a, b) => a.bySize[size]!.compareTo(b.bySize[size]!),\n'
      '                cellBuilder: (context, row) => HeatCell(\n'
      '                  text: \'\${row.bySize[size]}\',\n'
      '                  intensity: row.bySize[size]! / _best,\n'
      '                  tint: AstryxColorToken.success,\n'
      '                  onTint: AstryxColorToken.onSuccess,\n'
      '                  semanticsLabel: \'\${row.bySize[size]} pairs in UK \$size\',\n'
      '                ),\n'
      '              ),\n'
      '            AstryxTableColumn<Style>(\n'
      '              id: \'stock\',\n'
      '              header: \'Stock\',\n'
      '              width: const AstryxTableColumnWidth.fixed(130),\n'
      '              compare: (a, b) => a.stock.compareTo(b.stock),\n'
      '              cellBuilder: (context, row) => switch (row.stock) {\n'
      '                0 => const AstryxBadge(\n'
      '                  \'Out of stock\',\n'
      '                  variant: AstryxBadgeVariant.error,\n'
      '                  icon: AstryxIcon(AstryxIconName.error),\n'
      '                ),\n'
      '                < 50 => AstryxBadge(\n'
      '                  \'\${row.stock} left\',\n'
      '                  variant: AstryxBadgeVariant.warning,\n'
      '                  icon: const AstryxIcon(AstryxIconName.warning),\n'
      '                ),\n'
      '                _ => AstryxBadge(\n'
      '                  \'\${row.stock} in stock\',\n'
      '                  variant: AstryxBadgeVariant.success,\n'
      '                  icon: const AstryxIcon(AstryxIconName.success),\n'
      '                ),\n'
      '              },\n'
      '            ),\n'
      '          ],\n'
      '          rows: rows,\n'
      '        ),\n'
      '      ),\n'
      '    );\n'
      '  }\n'
      '}\n',
  // examples/template_login_examples.dart
  'template_login':
      'class LoginTemplate extends StatefulWidget {\n'
      '  const LoginTemplate({super.key});\n'
      '\n'
      '  @override\n'
      '  State<LoginTemplate> createState() => _LoginTemplateState();\n'
      '}\n'
      '\n'
      'class _LoginTemplateState extends State<LoginTemplate> {\n'
      '  final TextEditingController _email = TextEditingController();\n'
      '  final TextEditingController _password = TextEditingController();\n'
      '\n'
      '  /// True once the user has tried to submit. Until then, nothing is red: a form\n'
      '  /// that scolds you for fields you have not reached yet is hostile.\n'
      '  bool _submitted = false;\n'
      '  bool _submitting = false;\n'
      '  bool _rejected = false;\n'
      '  bool _remember = true;\n'
      '\n'
      '  @override\n'
      '  void dispose() {\n'
      '    _email.dispose();\n'
      '    _password.dispose();\n'
      '    super.dispose();\n'
      '  }\n'
      '\n'
      '  AstryxFieldStatus? get _emailStatus {\n'
      '    if (!_submitted) return null;\n'
      '    if (_email.text.trim().isEmpty) {\n'
      '      return const AstryxFieldStatus.error(\'Enter your email address\');\n'
      '    }\n'
      '    if (!looksLikeEmail(_email.text)) {\n'
      '      return const AstryxFieldStatus.error(\'That is not an email address\');\n'
      '    }\n'
      '    return null;\n'
      '  }\n'
      '\n'
      '  AstryxFieldStatus? get _passwordStatus {\n'
      '    if (!_submitted || _password.text.isNotEmpty) return null;\n'
      '    return const AstryxFieldStatus.error(\'Enter your password\');\n'
      '  }\n'
      '\n'
      '  Future<void> _submit() async {\n'
      '    setState(() {\n'
      '      _submitted = true;\n'
      '      _rejected = false;\n'
      '    });\n'
      '    if (_emailStatus != null || _passwordStatus != null) return;\n'
      '\n'
      '    setState(() => _submitting = true);\n'
      '    await Future<void>.delayed(const Duration(milliseconds: 900));\n'
      '    if (!mounted) return;\n'
      '    // The template\'s job is the shape of the screen, not authentication: this\n'
      '    // stands in for the request, and always fails, so the error state is\n'
      '    // reachable in the preview.\n'
      '    setState(() {\n'
      '      _submitting = false;\n'
      '      _rejected = true;\n'
      '    });\n'
      '  }\n'
      '\n'
      '  @override\n'
      '  Widget build(BuildContext context) {\n'
      '    return AstryxCenter(\n'
      '      maxWidth: 380,\n'
      '      paddingBlock: AstryxSpacingToken.spacing8,\n'
      '      child: AstryxVStack(\n'
      '        gap: AstryxSpacingToken.spacing5,\n'
      '        align: AstryxStackAlign.stretch,\n'
      '        children: <Widget>[\n'
      '          const AstryxVStack(\n'
      '            gap: AstryxSpacingToken.spacing2,\n'
      '            align: AstryxStackAlign.stretch,\n'
      '            children: <Widget>[\n'
      '              AstryxHeading(\'Sign in\', level: 1),\n'
      '              AstryxText(\n'
      '                \'Use the account your workspace was created with.\',\n'
      '                color: AstryxTextColor.secondary,\n'
      '              ),\n'
      '            ],\n'
      '          ),\n'
      '          // The failure goes in a banner, not a toast: the user has to act on\n'
      '          // it, and it belongs beside the fields it is about.\n'
      '          if (_rejected)\n'
      '            const AstryxBanner(\n'
      '              status: AstryxBannerStatus.error,\n'
      '              title: \'That email and password do not match\',\n'
      '              description: \'Check the password, or reset it below.\',\n'
      '            ),\n'
      '          AstryxTextInput(\n'
      '            label: \'Email\',\n'
      '            controller: _email,\n'
      '            required: true,\n'
      '            enabled: !_submitting,\n'
      '            status: _emailStatus,\n'
      '            placeholder: \'you@example.com\',\n'
      '            keyboardType: TextInputType.emailAddress,\n'
      '            textInputAction: TextInputAction.next,\n'
      '            autofillHints: const <String>[AutofillHints.email],\n'
      '            onChanged: (_) => setState(() {}),\n'
      '          ),\n'
      '          AstryxTextInput(\n'
      '            label: \'Password\',\n'
      '            controller: _password,\n'
      '            required: true,\n'
      '            enabled: !_submitting,\n'
      '            status: _passwordStatus,\n'
      '            obscureText: true,\n'
      '            textInputAction: TextInputAction.done,\n'
      '            autofillHints: const <String>[AutofillHints.password],\n'
      '            onChanged: (_) => setState(() {}),\n'
      '            onSubmitted: (_) => _submit(),\n'
      '          ),\n'
      '          AstryxHStack(\n'
      '            gap: AstryxSpacingToken.spacing2,\n'
      '            justify: AstryxStackJustify.between,\n'
      '            mainAxisSize: MainAxisSize.max,\n'
      '            children: <Widget>[\n'
      '              // A checkbox, not a switch: it applies when the form is\n'
      '              // submitted, not the moment it is ticked. `Flexible`, because\n'
      '              // the label has to be allowed to wrap on a narrow screen rather\n'
      '              // than push the link off the edge.\n'
      '              Flexible(\n'
      '                child: AstryxCheckbox(\n'
      '                  label: \'Keep me signed in\',\n'
      '                  size: AstryxToggleSize.sm,\n'
      '                  value: _remember,\n'
      '                  onChanged: (value) => setState(() => _remember = value),\n'
      '                ),\n'
      '              ),\n'
      '              AstryxButton(\n'
      '                label: \'Forgot password?\',\n'
      '                variant: AstryxButtonVariant.ghost,\n'
      '                size: AstryxButtonSize.sm,\n'
      '                onPressed: () {},\n'
      '              ),\n'
      '            ],\n'
      '          ),\n'
      '          AstryxButton(\n'
      '            label: \'Sign in\',\n'
      '            variant: AstryxButtonVariant.primary,\n'
      '            loading: _submitting,\n'
      '            onPressed: _submit,\n'
      '          ),\n'
      '          AstryxHStack(\n'
      '            gap: AstryxSpacingToken.spacing1,\n'
      '            wrap: true,\n'
      '            justify: AstryxStackJustify.center,\n'
      '            children: <Widget>[\n'
      '              const AstryxText(\n'
      '                \'No account?\',\n'
      '                type: AstryxTextType.supporting,\n'
      '                color: AstryxTextColor.secondary,\n'
      '              ),\n'
      '              AstryxButton(\n'
      '                label: \'Request access\',\n'
      '                variant: AstryxButtonVariant.ghost,\n'
      '                size: AstryxButtonSize.sm,\n'
      '                onPressed: () {},\n'
      '              ),\n'
      '            ],\n'
      '          ),\n'
      '        ],\n'
      '      ),\n'
      '    );\n'
      '  }\n'
      '}\n',
  // examples/template_login_examples.dart
  'template_login_card':
      'class LoginCardTemplate extends StatefulWidget {\n'
      '  const LoginCardTemplate({super.key});\n'
      '\n'
      '  @override\n'
      '  State<LoginCardTemplate> createState() => _LoginCardTemplateState();\n'
      '}\n'
      '\n'
      'class _LoginCardTemplateState extends State<LoginCardTemplate> {\n'
      '  final TextEditingController _email = TextEditingController();\n'
      '  final TextEditingController _password = TextEditingController();\n'
      '  bool _submitting = false;\n'
      '\n'
      '  @override\n'
      '  void dispose() {\n'
      '    _email.dispose();\n'
      '    _password.dispose();\n'
      '    super.dispose();\n'
      '  }\n'
      '\n'
      '  Future<void> _submit() async {\n'
      '    setState(() => _submitting = true);\n'
      '    await Future<void>.delayed(const Duration(milliseconds: 900));\n'
      '    if (mounted) setState(() => _submitting = false);\n'
      '  }\n'
      '\n'
      '  @override\n'
      '  Widget build(BuildContext context) {\n'
      '    // The card\'s three slots carry the three parts of the screen: who this is\n'
      '    // for, what to fill in, what to press. `padding` is both the inset and the\n'
      '    // gap between them, so the rhythm cannot drift.\n'
      '    return AstryxCenter(\n'
      '      paddingBlock: AstryxSpacingToken.spacing8,\n'
      '      child: AstryxCard(\n'
      '        width: 380,\n'
      '        elevation: AstryxElevation.low,\n'
      '        padding: AstryxSpacingToken.spacing5,\n'
      '        header: const AstryxHStack(\n'
      '          justify: AstryxStackJustify.between,\n'
      '          align: AstryxStackAlign.start,\n'
      '          mainAxisSize: MainAxisSize.max,\n'
      '          children: <Widget>[\n'
      '            Flexible(\n'
      '              child: AstryxVStack(\n'
      '                gap: AstryxSpacingToken.spacing1,\n'
      '                children: <Widget>[\n'
      '                  AstryxHeading(\'Sign in to Atlas\'),\n'
      '                  AstryxText(\n'
      '                    \'Internal tools for the platform team.\',\n'
      '                    type: AstryxTextType.supporting,\n'
      '                    color: AstryxTextColor.secondary,\n'
      '                  ),\n'
      '                ],\n'
      '              ),\n'
      '            ),\n'
      '            AstryxBadge(\'Staging\', variant: AstryxBadgeVariant.warning),\n'
      '          ],\n'
      '        ),\n'
      '        footer: AstryxVStack(\n'
      '          gap: AstryxSpacingToken.spacing3,\n'
      '          align: AstryxStackAlign.stretch,\n'
      '          children: <Widget>[\n'
      '            AstryxButton(\n'
      '              label: \'Sign in\',\n'
      '              variant: AstryxButtonVariant.primary,\n'
      '              loading: _submitting,\n'
      '              onPressed: _submit,\n'
      '            ),\n'
      '            const AstryxText(\n'
      '              \'By signing in you accept the acceptable-use policy.\',\n'
      '              type: AstryxTextType.supporting,\n'
      '              color: AstryxTextColor.secondary,\n'
      '              justify: AstryxTextJustify.center,\n'
      '            ),\n'
      '          ],\n'
      '        ),\n'
      '        child: AstryxVStack(\n'
      '          gap: AstryxSpacingToken.spacing4,\n'
      '          align: AstryxStackAlign.stretch,\n'
      '          children: <Widget>[\n'
      '            AstryxTextInput(\n'
      '              label: \'Email\',\n'
      '              controller: _email,\n'
      '              required: true,\n'
      '              enabled: !_submitting,\n'
      '              placeholder: \'you@example.com\',\n'
      '              keyboardType: TextInputType.emailAddress,\n'
      '              autofillHints: const <String>[AutofillHints.email],\n'
      '            ),\n'
      '            AstryxTextInput(\n'
      '              label: \'Password\',\n'
      '              controller: _password,\n'
      '              required: true,\n'
      '              enabled: !_submitting,\n'
      '              obscureText: true,\n'
      '              autofillHints: const <String>[AutofillHints.password],\n'
      '              onSubmitted: (_) => _submit(),\n'
      '            ),\n'
      '          ],\n'
      '        ),\n'
      '      ),\n'
      '    );\n'
      '  }\n'
      '}\n',
  // examples/template_login_examples.dart
  'template_login_sso':
      'class LoginSsoTemplate extends StatefulWidget {\n'
      '  const LoginSsoTemplate({super.key});\n'
      '\n'
      '  @override\n'
      '  State<LoginSsoTemplate> createState() => _LoginSsoTemplateState();\n'
      '}\n'
      '\n'
      'class _LoginSsoTemplateState extends State<LoginSsoTemplate> {\n'
      '  final TextEditingController _email = TextEditingController();\n'
      '\n'
      '  /// Which provider is being redirected to, if any. One at a time: a second\n'
      '  /// press while a redirect is in flight is a bug, not a feature.\n'
      '  String? _redirecting;\n'
      '\n'
      '  @override\n'
      '  void dispose() {\n'
      '    _email.dispose();\n'
      '    super.dispose();\n'
      '  }\n'
      '\n'
      '  Future<void> _redirect(String provider) async {\n'
      '    setState(() => _redirecting = provider);\n'
      '    await Future<void>.delayed(const Duration(milliseconds: 900));\n'
      '    if (mounted) setState(() => _redirecting = null);\n'
      '  }\n'
      '\n'
      '  @override\n'
      '  Widget build(BuildContext context) {\n'
      '    const providers = <String>[\'Okta\', \'Google Workspace\', \'Microsoft Entra\'];\n'
      '\n'
      '    return AstryxCenter(\n'
      '      maxWidth: 380,\n'
      '      paddingBlock: AstryxSpacingToken.spacing8,\n'
      '      child: AstryxVStack(\n'
      '        gap: AstryxSpacingToken.spacing5,\n'
      '        align: AstryxStackAlign.stretch,\n'
      '        children: <Widget>[\n'
      '          const AstryxVStack(\n'
      '            gap: AstryxSpacingToken.spacing2,\n'
      '            align: AstryxStackAlign.stretch,\n'
      '            children: <Widget>[\n'
      '              AstryxHeading(\'Continue to Atlas\', level: 1),\n'
      '              AstryxText(\n'
      '                \'Single sign-on is how most people get in.\',\n'
      '                color: AstryxTextColor.secondary,\n'
      '              ),\n'
      '            ],\n'
      '          ),\n'
      '          // Each provider is its own button, stacked and stretched. The\n'
      '          // trailing icon says "this leaves the page", which is the one thing\n'
      '          // an SSO button has to promise.\n'
      '          AstryxVStack(\n'
      '            gap: AstryxSpacingToken.spacing2,\n'
      '            align: AstryxStackAlign.stretch,\n'
      '            children: <Widget>[\n'
      '              for (final provider in providers)\n'
      '                AstryxButton(\n'
      '                  label: \'Continue with \$provider\',\n'
      '                  loading: _redirecting == provider,\n'
      '                  enabled: _redirecting == null || _redirecting == provider,\n'
      '                  trailing: const AstryxIcon(\n'
      '                    AstryxIconName.externalLink,\n'
      '                    size: AstryxIconSize.sm,\n'
      '                  ),\n'
      '                  onPressed: () => _redirect(provider),\n'
      '                ),\n'
      '            ],\n'
      '          ),\n'
      '          // A labelled divider is the whole "or" affordance — no extra text\n'
      '          // widget, no hand-spaced rules either side of it.\n'
      '          const AstryxDivider(label: \'or use your email\'),\n'
      '          AstryxTextInput(\n'
      '            label: \'Work email\',\n'
      '            controller: _email,\n'
      '            required: true,\n'
      '            enabled: _redirecting == null,\n'
      '            placeholder: \'you@example.com\',\n'
      '            description: \'We will email you a sign-in link.\',\n'
      '            keyboardType: TextInputType.emailAddress,\n'
      '            autofillHints: const <String>[AutofillHints.email],\n'
      '            onChanged: (_) => setState(() {}),\n'
      '          ),\n'
      '          AstryxButton(\n'
      '            label: \'Email me a link\',\n'
      '            variant: AstryxButtonVariant.primary,\n'
      '            enabled: _redirecting == null && looksLikeEmail(_email.text),\n'
      '            onPressed: () {},\n'
      '          ),\n'
      '        ],\n'
      '      ),\n'
      '    );\n'
      '  }\n'
      '}\n',
  // examples/template_login_examples.dart
  'template_login_split':
      'class LoginSplitTemplate extends StatelessWidget {\n'
      '  const LoginSplitTemplate({super.key});\n'
      '\n'
      '  /// Below this the split cannot hold: 340 for the form leaves the panel less\n'
      '  /// room than one line of its heading needs.\n'
      '  static const double _splitMinWidth = 560;\n'
      '\n'
      '  @override\n'
      '  Widget build(BuildContext context) {\n'
      '    final form = AstryxCenter(\n'
      '      paddingInline: AstryxSpacingToken.spacing6,\n'
      '      child: AstryxVStack(\n'
      '        gap: AstryxSpacingToken.spacing4,\n'
      '        align: AstryxStackAlign.stretch,\n'
      '        children: <Widget>[\n'
      '          const AstryxHeading(\'Sign in\', level: 1),\n'
      '          const AstryxTextInput(\n'
      '            label: \'Email\',\n'
      '            required: true,\n'
      '            placeholder: \'you@example.com\',\n'
      '            keyboardType: TextInputType.emailAddress,\n'
      '          ),\n'
      '          const AstryxTextInput(\n'
      '            label: \'Password\',\n'
      '            required: true,\n'
      '            obscureText: true,\n'
      '          ),\n'
      '          AstryxButton(\n'
      '            label: \'Sign in\',\n'
      '            variant: AstryxButtonVariant.primary,\n'
      '            onPressed: () {},\n'
      '          ),\n'
      '        ],\n'
      '      ),\n'
      '    );\n'
      '\n'
      '    // Two columns of one height: the form keeps its measure and the panel takes\n'
      '    // the rest, so the split holds at every width down to `_splitMinWidth`.\n'
      '    // Below that there is no split — the panel goes above the form, because a\n'
      '    // 120-wide column of prose is not a panel, it is a stripe.\n'
      '    return LayoutBuilder(\n'
      '      builder: (context, constraints) => constraints.maxWidth < _splitMinWidth\n'
      '          ? AstryxVStack(\n'
      '              align: AstryxStackAlign.stretch,\n'
      '              children: <Widget>[\n'
      '                const _SplitPanel(),\n'
      '                Padding(\n'
      '                  padding: EdgeInsets.symmetric(\n'
      '                    vertical: AstryxTheme.of(\n'
      '                      context,\n'
      '                    ).spacing(AstryxSpacingToken.spacing6),\n'
      '                  ),\n'
      '                  child: form,\n'
      '                ),\n'
      '              ],\n'
      '            )\n'
      '          : SizedBox(\n'
      '              height: 460,\n'
      '              child: AstryxHStack(\n'
      '                align: AstryxStackAlign.stretch,\n'
      '                mainAxisSize: MainAxisSize.max,\n'
      '                children: <Widget>[\n'
      '                  const Expanded(child: _SplitPanel()),\n'
      '                  SizedBox(width: 340, child: form),\n'
      '                ],\n'
      '              ),\n'
      '            ),\n'
      '    );\n'
      '  }\n'
      '}\n',
  // examples/template_media_examples.dart
  'template_gallery_hero':
      'class GalleryHeroTemplate extends StatefulWidget {\n'
      '  const GalleryHeroTemplate({super.key});\n'
      '\n'
      '  @override\n'
      '  State<GalleryHeroTemplate> createState() => _GalleryHeroTemplateState();\n'
      '}\n'
      '\n'
      'class _GalleryHeroTemplateState extends State<GalleryHeroTemplate> {\n'
      '  static const List<Shot> _shots = <Shot>[\n'
      '    (\n'
      '      name: \'The rack view\',\n'
      '      caption: \'Every machine in a region, and what it is doing right now.\',\n'
      '      ratio: 16 / 9,\n'
      '    ),\n'
      '    (\n'
      '      name: \'The deploy timeline\',\n'
      '      caption: \'One row per service, one column per minute.\',\n'
      '      ratio: 16 / 9,\n'
      '    ),\n'
      '    (\n'
      '      name: \'The incident console\',\n'
      '      caption: \'Severity, the people on it, and the last thing that changed.\',\n'
      '      ratio: 16 / 9,\n'
      '    ),\n'
      '  ];\n'
      '\n'
      '  int _index = 0;\n'
      '\n'
      '  @override\n'
      '  Widget build(BuildContext context) {\n'
      '    // A hero is a claim and one action. The media underneath it is *evidence*\n'
      '    // for the claim, which is why it is a strip the reader can page rather\n'
      '    // than a wall they have to scan.\n'
      '    return AstryxVStack(\n'
      '      gap: AstryxSpacingToken.spacing8,\n'
      '      align: AstryxStackAlign.stretch,\n'
      '      children: <Widget>[\n'
      '        AstryxCenter(\n'
      '          maxWidth: 620,\n'
      '          padding: AstryxSpacingToken.spacing0,\n'
      '          child: AstryxVStack(\n'
      '            gap: AstryxSpacingToken.spacing4,\n'
      '            align: AstryxStackAlign.center,\n'
      '            children: <Widget>[\n'
      '              const AstryxBadge(\n'
      '                \'Atlas 4\',\n'
      '                variant: AstryxBadgeVariant.info,\n'
      '                icon: AstryxIcon(AstryxIconName.info),\n'
      '              ),\n'
      '              const AstryxHeading(\n'
      '                \'See the whole fleet at once\',\n'
      '                level: 1,\n'
      '                type: AstryxHeadingType.display2,\n'
      '                justify: AstryxTextJustify.center,\n'
      '              ),\n'
      '              const AstryxText(\n'
      '                \'Every deploy, every incident and every machine on one screen \'\n'
      '                \'— and the same screen on a phone at three in the morning.\',\n'
      '                type: AstryxTextType.large,\n'
      '                color: AstryxTextColor.secondary,\n'
      '                justify: AstryxTextJustify.center,\n'
      '              ),\n'
      '              AstryxHStack(\n'
      '                gap: AstryxSpacingToken.spacing3,\n'
      '                wrap: true,\n'
      '                runGap: AstryxSpacingToken.spacing2,\n'
      '                justify: AstryxStackJustify.center,\n'
      '                children: <Widget>[\n'
      '                  AstryxButton(\n'
      '                    label: \'Start free\',\n'
      '                    variant: AstryxButtonVariant.primary,\n'
      '                    size: AstryxButtonSize.lg,\n'
      '                    onPressed: () {},\n'
      '                  ),\n'
      '                  AstryxButton(\n'
      '                    label: \'Watch the tour\',\n'
      '                    size: AstryxButtonSize.lg,\n'
      '                    trailing: const AstryxIcon(\n'
      '                      AstryxIconName.externalLink,\n'
      '                      size: AstryxIconSize.sm,\n'
      '                    ),\n'
      '                    onPressed: () {},\n'
      '                  ),\n'
      '                ],\n'
      '              ),\n'
      '            ],\n'
      '          ),\n'
      '        ),\n'
      '        // The strip is one tab stop with its own arrow keys and its own "2 of\n'
      '        // 3" readout, so the position is never something the reader has to\n'
      '        // infer from how far a scrollbar has moved.\n'
      '        AstryxCarousel(\n'
      '          label: \'Product screens\',\n'
      '          height: 260,\n'
      '          viewportFraction: 0.86,\n'
      '          onIndexChanged: (index) => setState(() => _index = index),\n'
      '          items: <Widget>[\n'
      '            for (final shot in _shots) _HeroPanel(shot: shot),\n'
      '          ],\n'
      '        ),\n'
      '        // The caption is on the page, not over the picture. A hero\'s\n'
      '        // supporting line is content, and content behind a scrim is content\n'
      '        // somebody decided was decoration.\n'
      '        AstryxCenter(\n'
      '          maxWidth: 620,\n'
      '          padding: AstryxSpacingToken.spacing0,\n'
      '          child: AstryxVStack(\n'
      '            gap: AstryxSpacingToken.spacing1,\n'
      '            align: AstryxStackAlign.center,\n'
      '            children: <Widget>[\n'
      '              AstryxText(\n'
      '                _shots[_index].name,\n'
      '                type: AstryxTextType.label,\n'
      '                justify: AstryxTextJustify.center,\n'
      '              ),\n'
      '              AstryxText(\n'
      '                _shots[_index].caption,\n'
      '                type: AstryxTextType.supporting,\n'
      '                color: AstryxTextColor.secondary,\n'
      '                justify: AstryxTextJustify.center,\n'
      '              ),\n'
      '            ],\n'
      '          ),\n'
      '        ),\n'
      '      ],\n'
      '    );\n'
      '  }\n'
      '}\n'
      '\n'
      '/// One panel of the hero strip: a picture, and its name over it.\n'
      'class _HeroPanel extends StatelessWidget {\n'
      '  const _HeroPanel({required this.shot});\n'
      '\n'
      '  final Shot shot;\n'
      '\n'
      '  @override\n'
      '  Widget build(BuildContext context) {\n'
      '    final theme = AstryxTheme.of(context);\n'
      '\n'
      '    return Padding(\n'
      '      padding: EdgeInsets.symmetric(\n'
      '        horizontal: theme.spacing(AstryxSpacingToken.spacing2),\n'
      '      ),\n'
      '      child: ClipRRect(\n'
      '        borderRadius: theme.borderRadius(AstryxRadiusToken.container),\n'
      '        child: Stack(\n'
      '          fit: StackFit.expand,\n'
      '          children: <Widget>[\n'
      '            AstryxAspectRatio(\n'
      '              ratio: shot.ratio,\n'
      '              background: AstryxColorToken.backgroundInverted,\n'
      '              semanticsLabel: shot.name,\n'
      '              child: const Center(\n'
      '                child: AstryxMediaTheme(\n'
      '                  scrim: AstryxMediaScrim.none,\n'
      '                  padding: AstryxSpacingToken.spacing0,\n'
      '                  child: AstryxIcon(\n'
      '                    AstryxIconName.viewColumns,\n'
      '                    size: AstryxIconSize.lg,\n'
      '                  ),\n'
      '                ),\n'
      '              ),\n'
      '            ),\n'
      '            Positioned.directional(\n'
      '              textDirection: Directionality.of(context),\n'
      '              start: 0,\n'
      '              end: 0,\n'
      '              bottom: 0,\n'
      '              child: AstryxMediaTheme(\n'
      '                child: AstryxText(\n'
      '                  shot.name,\n'
      '                  color: AstryxTextColor.inherit,\n'
      '                  maxLines: 1,\n'
      '                ),\n'
      '              ),\n'
      '            ),\n'
      '          ],\n'
      '        ),\n'
      '      ),\n'
      '    );\n'
      '  }\n'
      '}\n',
  // examples/template_media_examples.dart
  'template_mixed_gallery':
      'class MixedGalleryTemplate extends StatefulWidget {\n'
      '  const MixedGalleryTemplate({super.key});\n'
      '\n'
      '  @override\n'
      '  State<MixedGalleryTemplate> createState() => _MixedGalleryTemplateState();\n'
      '}\n'
      '\n'
      'class _MixedGalleryTemplateState extends State<MixedGalleryTemplate> {\n'
      '  /// The sizes differ because the pictures do.\n'
      '  ///\n'
      '  /// A panorama cropped to a square is a panorama nobody can read, and a\n'
      '  /// portrait letterboxed into a 16:9 tile is mostly ground. Each item carries\n'
      '  /// its own ratio and its own width, and the row wraps around them.\n'
      '  static const List<({Shot shot, double width})> _items =\n'
      '      <({Shot shot, double width})>[\n'
      '        (\n'
      '          shot: (\n'
      '            name: \'Cold aisle, full length\',\n'
      '            caption: \'Panorama · 8064 × 2268\',\n'
      '            ratio: 32 / 9,\n'
      '          ),\n'
      '          width: 420,\n'
      '        ),\n'
      '        (\n'
      '          shot: (\n'
      '            name: \'Rack 14, door open\',\n'
      '            caption: \'Portrait · 3024 × 4032\',\n'
      '            ratio: 3 / 4,\n'
      '          ),\n'
      '          width: 170,\n'
      '        ),\n'
      '        (\n'
      '          shot: (\n'
      '            name: \'Patch panel B\',\n'
      '            caption: \'Square · 3024 × 3024\',\n'
      '            ratio: 1,\n'
      '          ),\n'
      '          width: 200,\n'
      '        ),\n'
      '        (\n'
      '          shot: (\n'
      '            name: \'Generator test\',\n'
      '            caption: \'Video · 1920 × 1080\',\n'
      '            ratio: 16 / 9,\n'
      '          ),\n'
      '          width: 300,\n'
      '        ),\n'
      '        (\n'
      '          shot: (\n'
      '            name: \'Health check log\',\n'
      '            caption: \'Screenshot · 1440 × 900\',\n'
      '            ratio: 8 / 5,\n'
      '          ),\n'
      '          width: 260,\n'
      '        ),\n'
      '      ];\n'
      '\n'
      '  final AstryxOverlayController _viewer = AstryxOverlayController();\n'
      '\n'
      '  int _index = 0;\n'
      '\n'
      '  @override\n'
      '  void dispose() {\n'
      '    _viewer.dispose();\n'
      '    super.dispose();\n'
      '  }\n'
      '\n'
      '  void _open(int index) {\n'
      '    setState(() => _index = index);\n'
      '    _viewer.show();\n'
      '  }\n'
      '\n'
      '  @override\n'
      '  Widget build(BuildContext context) {\n'
      '    return AstryxVStack(\n'
      '      gap: AstryxSpacingToken.spacing4,\n'
      '      align: AstryxStackAlign.stretch,\n'
      '      children: <Widget>[\n'
      '        AstryxHStack(\n'
      '          gap: AstryxSpacingToken.spacing3,\n'
      '          justify: AstryxStackJustify.between,\n'
      '          mainAxisSize: MainAxisSize.max,\n'
      '          children: <Widget>[\n'
      '            const Flexible(child: AstryxHeading(\'Site visit\', level: 1)),\n'
      '            AstryxText(\n'
      '              \'\${_items.length} items\',\n'
      '              type: AstryxTextType.supporting,\n'
      '              color: AstryxTextColor.secondary,\n'
      '            ),\n'
      '          ],\n'
      '        ),\n'
      '        // A wrapping row, not an `AstryxGrid`. A grid gives every cell in a row\n'
      '        // the height of the tallest — which is the whole thing this screen is\n'
      '        // trying not to do, quite apart from the intrinsic measurement a\n'
      '        // pressable tile cannot answer in touch density.\n'
      '        AstryxHStack(\n'
      '          gap: AstryxSpacingToken.spacing3,\n'
      '          wrap: true,\n'
      '          runGap: AstryxSpacingToken.spacing3,\n'
      '          align: AstryxStackAlign.start,\n'
      '          children: <Widget>[\n'
      '            for (var i = 0; i < _items.length; i++)\n'
      '              _MixedTile(\n'
      '                shot: _items[i].shot,\n'
      '                width: _items[i].width,\n'
      '                onPressed: () => _open(i),\n'
      '              ),\n'
      '          ],\n'
      '        ),\n'
      '        AstryxLightbox(\n'
      '          controller: _viewer,\n'
      '          initialIndex: _index,\n'
      '          label: \'Site visit\',\n'
      '          items: <AstryxLightboxItem>[\n'
      '            for (final item in _items)\n'
      '              AstryxLightboxItem(\n'
      '                label: item.shot.name,\n'
      '                caption: \'\${item.shot.name} · \${item.shot.caption}\',\n'
      '                // The viewer shows each item at its own ratio too. A gallery\n'
      '                // that mixes shapes on the wall and squares them in the viewer\n'
      '                // has lied about one of the two.\n'
      '                child: SizedBox(\n'
      '                  width: 640,\n'
      '                  child: AstryxAspectRatio(\n'
      '                    ratio: item.shot.ratio,\n'
      '                    background: AstryxColorToken.backgroundCard,\n'
      '                    child: Center(\n'
      '                      child: AstryxText(\n'
      '                        item.shot.name,\n'
      '                        color: AstryxTextColor.secondary,\n'
      '                      ),\n'
      '                    ),\n'
      '                  ),\n'
      '                ),\n'
      '              ),\n'
      '          ],\n'
      '        ),\n'
      '      ],\n'
      '    );\n'
      '  }\n'
      '}\n'
      '\n'
      '/// One tile, at whatever size and shape its picture asks for.\n'
      'class _MixedTile extends StatelessWidget {\n'
      '  const _MixedTile({\n'
      '    required this.shot,\n'
      '    required this.width,\n'
      '    required this.onPressed,\n'
      '  });\n'
      '\n'
      '  final Shot shot;\n'
      '  final double width;\n'
      '  final VoidCallback onPressed;\n'
      '\n'
      '  @override\n'
      '  Widget build(BuildContext context) {\n'
      '    return SizedBox(\n'
      '      width: width,\n'
      '      child: AstryxCard(\n'
      '        padding: AstryxSpacingToken.spacing2,\n'
      '        semanticsLabel: \'\${shot.name}, \${shot.caption}\',\n'
      '        onPressed: onPressed,\n'
      '        footer: AstryxVStack(\n'
      '          gap: AstryxSpacingToken.spacing0_5,\n'
      '          children: <Widget>[\n'
      '            AstryxText(shot.name, type: AstryxTextType.label, maxLines: 1),\n'
      '            AstryxText(\n'
      '              shot.caption,\n'
      '              type: AstryxTextType.supporting,\n'
      '              color: AstryxTextColor.secondary,\n'
      '              maxLines: 1,\n'
      '            ),\n'
      '          ],\n'
      '        ),\n'
      '        child: AstryxAspectRatio(\n'
      '          ratio: shot.ratio,\n'
      '          child: const Center(\n'
      '            child: AstryxIcon(AstryxIconName.viewColumns),\n'
      '          ),\n'
      '        ),\n'
      '      ),\n'
      '    );\n'
      '  }\n'
      '}\n',
  // examples/template_media_examples.dart
  'template_side_gallery':
      'class SideGalleryTemplate extends StatefulWidget {\n'
      '  const SideGalleryTemplate({super.key});\n'
      '\n'
      '  @override\n'
      '  State<SideGalleryTemplate> createState() => _SideGalleryTemplateState();\n'
      '}\n'
      '\n'
      'class _SideGalleryTemplateState extends State<SideGalleryTemplate> {\n'
      '  static const List<Shot> _shots = <Shot>[\n'
      '    (\n'
      '      name: \'Latency, p95\',\n'
      '      caption: \'Captured 14:02 · scheduler-a\',\n'
      '      ratio: 16 / 9,\n'
      '    ),\n'
      '    (\n'
      '      name: \'Queue depth\',\n'
      '      caption: \'Captured 14:03 · scheduler-a\',\n'
      '      ratio: 16 / 9,\n'
      '    ),\n'
      '    (\n'
      '      name: \'Retries per minute\',\n'
      '      caption: \'Captured 14:06 · scheduler-b\',\n'
      '      ratio: 16 / 9,\n'
      '    ),\n'
      '    (\n'
      '      name: \'Error budget burn\',\n'
      '      caption: \'Captured 14:11 · platform\',\n'
      '      ratio: 16 / 9,\n'
      '    ),\n'
      '  ];\n'
      '\n'
      '  int _index = 1;\n'
      '\n'
      '  @override\n'
      '  Widget build(BuildContext context) {\n'
      '    final shot = _shots[_index];\n'
      '\n'
      '    // One item at a time, with the rest reachable without leaving the screen.\n'
      '    // This is the shape to reach for when the pictures are *evidence* — the\n'
      '    // reader is comparing them against each other rather than browsing.\n'
      '    return AstryxVStack(\n'
      '      gap: AstryxSpacingToken.spacing4,\n'
      '      align: AstryxStackAlign.stretch,\n'
      '      children: <Widget>[\n'
      '        AstryxHStack(\n'
      '          gap: AstryxSpacingToken.spacing3,\n'
      '          justify: AstryxStackJustify.between,\n'
      '          mainAxisSize: MainAxisSize.max,\n'
      '          children: <Widget>[\n'
      '            const Flexible(\n'
      '              child: AstryxHeading(\'Incident 4102 · evidence\', level: 1),\n'
      '            ),\n'
      '            AstryxText(\n'
      '              \'\${_index + 1} of \${_shots.length}\',\n'
      '              type: AstryxTextType.supporting,\n'
      '              color: AstryxTextColor.secondary,\n'
      '              tabularNumbers: true,\n'
      '            ),\n'
      '          ],\n'
      '        ),\n'
      '        LayoutBuilder(\n'
      '          builder: (context, constraints) {\n'
      '            final wide = constraints.maxWidth >= 640;\n'
      '            final strip = _Strip(\n'
      '              shots: _shots,\n'
      '              index: _index,\n'
      '              vertical: wide,\n'
      '              onSelected: (index) => setState(() => _index = index),\n'
      '            );\n'
      '\n'
      '            final viewer = _Viewer(shot: shot);\n'
      '\n'
      '            // The strip runs down the trailing edge when there is room for it\n'
      '            // and across the bottom when there is not. Same widget, same\n'
      '            // selection — only the axis moves.\n'
      '            if (!wide) {\n'
      '              return AstryxVStack(\n'
      '                gap: AstryxSpacingToken.spacing3,\n'
      '                align: AstryxStackAlign.stretch,\n'
      '                children: <Widget>[viewer, strip],\n'
      '              );\n'
      '            }\n'
      '\n'
      '            return AstryxHStack(\n'
      '              gap: AstryxSpacingToken.spacing3,\n'
      '              align: AstryxStackAlign.start,\n'
      '              mainAxisSize: MainAxisSize.max,\n'
      '              children: <Widget>[\n'
      '                Expanded(child: viewer),\n'
      '                SizedBox(width: 132, child: strip),\n'
      '              ],\n'
      '            );\n'
      '          },\n'
      '        ),\n'
      '      ],\n'
      '    );\n'
      '  }\n'
      '}\n'
      '\n'
      '/// The item being looked at, and what is known about it.\n'
      'class _Viewer extends StatelessWidget {\n'
      '  const _Viewer({required this.shot});\n'
      '\n'
      '  final Shot shot;\n'
      '\n'
      '  @override\n'
      '  Widget build(BuildContext context) {\n'
      '    return AstryxCard(\n'
      '      padding: AstryxSpacingToken.spacing3,\n'
      '      footer: AstryxVStack(\n'
      '        gap: AstryxSpacingToken.spacing0_5,\n'
      '        children: <Widget>[\n'
      '          AstryxText(shot.name, type: AstryxTextType.label),\n'
      '          AstryxText(\n'
      '            shot.caption,\n'
      '            type: AstryxTextType.supporting,\n'
      '            color: AstryxTextColor.secondary,\n'
      '          ),\n'
      '        ],\n'
      '      ),\n'
      '      child: AstryxAspectRatio(\n'
      '        ratio: shot.ratio,\n'
      '        semanticsLabel: shot.name,\n'
      '        child: Center(\n'
      '          child: AstryxText(shot.name, color: AstryxTextColor.secondary),\n'
      '        ),\n'
      '      ),\n'
      '    );\n'
      '  }\n'
      '}\n'
      '\n'
      '/// The strip of everything else, in whichever axis fits.\n'
      'class _Strip extends StatelessWidget {\n'
      '  const _Strip({\n'
      '    required this.shots,\n'
      '    required this.index,\n'
      '    required this.vertical,\n'
      '    required this.onSelected,\n'
      '  });\n'
      '\n'
      '  final List<Shot> shots;\n'
      '  final int index;\n'
      '  final bool vertical;\n'
      '  final ValueChanged<int> onSelected;\n'
      '\n'
      '  @override\n'
      '  Widget build(BuildContext context) {\n'
      '    final tiles = <Widget>[\n'
      '      for (var i = 0; i < shots.length; i++)\n'
      '        // `selected` is what marks the current one, and the thumbnail draws it\n'
      '        // as a ring rather than a tint — a tint over a picture is a change to\n'
      '        // the picture.\n'
      '        AstryxThumbnail(\n'
      '          label: shots[i].name,\n'
      '          icon: AstryxIconName.viewColumns,\n'
      '          ratio: 16 / 9,\n'
      '          width: vertical ? 116 : 104,\n'
      '          selected: i == index,\n'
      '          onPressed: () => onSelected(i),\n'
      '        ),\n'
      '    ];\n'
      '\n'
      '    if (vertical) {\n'
      '      return AstryxVStack(\n'
      '        gap: AstryxSpacingToken.spacing2,\n'
      '        align: AstryxStackAlign.stretch,\n'
      '        children: tiles,\n'
      '      );\n'
      '    }\n'
      '\n'
      '    return SingleChildScrollView(\n'
      '      scrollDirection: Axis.horizontal,\n'
      '      child: AstryxHStack(\n'
      '        gap: AstryxSpacingToken.spacing2,\n'
      '        children: tiles,\n'
      '      ),\n'
      '    );\n'
      '  }\n'
      '}\n',
  // examples/template_screen_examples.dart
  'template_centered_hero':
      'class CenteredHeroTemplate extends StatelessWidget {\n'
      '  const CenteredHeroTemplate({super.key});\n'
      '\n'
      '  @override\n'
      '  Widget build(BuildContext context) {\n'
      '    // One measure, one heading, one action. `maxWidth` is what keeps the\n'
      '    // supporting line readable — a hero that runs the full width of a desktop\n'
      '    // window is a paragraph nobody finishes.\n'
      '    return AstryxCenter(\n'
      '      maxWidth: 620,\n'
      '      minHeight: 360,\n'
      '      padding: AstryxSpacingToken.spacing8,\n'
      '      child: AstryxVStack(\n'
      '        gap: AstryxSpacingToken.spacing5,\n'
      '        align: AstryxStackAlign.center,\n'
      '        children: <Widget>[\n'
      '          const AstryxBadge(\n'
      '            \'Now in every region\',\n'
      '            variant: AstryxBadgeVariant.info,\n'
      '            icon: AstryxIcon(AstryxIconName.info),\n'
      '          ),\n'
      '          const AstryxHeading(\n'
      '            \'Every deploy, every incident, one timeline\',\n'
      '            level: 1,\n'
      '            type: AstryxHeadingType.display2,\n'
      '            justify: AstryxTextJustify.center,\n'
      '          ),\n'
      '          const AstryxText(\n'
      '            \'Atlas watches the services you already run and tells you which \'\n'
      '            \'change caused the graph to bend.\',\n'
      '            type: AstryxTextType.large,\n'
      '            color: AstryxTextColor.secondary,\n'
      '            justify: AstryxTextJustify.center,\n'
      '          ),\n'
      '          // One `primary` in the view. The second action is secondary, not a\n'
      '          // second primary: two of them side by side is a question.\n'
      '          AstryxHStack(\n'
      '            gap: AstryxSpacingToken.spacing3,\n'
      '            wrap: true,\n'
      '            runGap: AstryxSpacingToken.spacing2,\n'
      '            justify: AstryxStackJustify.center,\n'
      '            children: <Widget>[\n'
      '              AstryxButton(\n'
      '                label: \'Start free\',\n'
      '                variant: AstryxButtonVariant.primary,\n'
      '                size: AstryxButtonSize.lg,\n'
      '                onPressed: () {},\n'
      '              ),\n'
      '              AstryxButton(\n'
      '                label: \'Read the docs\',\n'
      '                size: AstryxButtonSize.lg,\n'
      '                trailing: const AstryxIcon(\n'
      '                  AstryxIconName.externalLink,\n'
      '                  size: AstryxIconSize.sm,\n'
      '                ),\n'
      '                onPressed: () {},\n'
      '              ),\n'
      '            ],\n'
      '          ),\n'
      '          const AstryxText(\n'
      '            \'No card. Two minutes to the first graph.\',\n'
      '            type: AstryxTextType.supporting,\n'
      '            color: AstryxTextColor.secondary,\n'
      '          ),\n'
      '        ],\n'
      '      ),\n'
      '    );\n'
      '  }\n'
      '}\n',
  // examples/template_screen_examples.dart
  'template_detail_page':
      'class DetailPageTemplate extends StatefulWidget {\n'
      '  const DetailPageTemplate({super.key});\n'
      '\n'
      '  @override\n'
      '  State<DetailPageTemplate> createState() => _DetailPageTemplateState();\n'
      '}\n'
      '\n'
      'class _DetailPageTemplateState extends State<DetailPageTemplate> {\n'
      '  static final Incident _incident = incidents.first;\n'
      '\n'
      '  String _tab = \'overview\';\n'
      '\n'
      '  @override\n'
      '  Widget build(BuildContext context) {\n'
      '    return AstryxVStack(\n'
      '      gap: AstryxSpacingToken.spacing5,\n'
      '      align: AstryxStackAlign.stretch,\n'
      '      children: <Widget>[\n'
      '        // The record\'s identity and its actions, on one line at width and\n'
      '        // wrapping at none. The id is `code`, because it is a thing to be\n'
      '        // copied exactly.\n'
      '        AstryxHStack(\n'
      '          gap: AstryxSpacingToken.spacing4,\n'
      '          justify: AstryxStackJustify.between,\n'
      '          align: AstryxStackAlign.start,\n'
      '          mainAxisSize: MainAxisSize.max,\n'
      '          children: <Widget>[\n'
      '            Flexible(\n'
      '              child: AstryxVStack(\n'
      '                gap: AstryxSpacingToken.spacing2,\n'
      '                children: <Widget>[\n'
      '                  AstryxHStack(\n'
      '                    gap: AstryxSpacingToken.spacing2,\n'
      '                    wrap: true,\n'
      '                    runGap: AstryxSpacingToken.spacing1,\n'
      '                    children: <Widget>[\n'
      '                      AstryxBadge(\n'
      '                        _incident.severityLabel,\n'
      '                        variant: severityVariant(_incident.severity),\n'
      '                        icon: const AstryxIcon(AstryxIconName.warning),\n'
      '                      ),\n'
      '                      const AstryxBadge(\n'
      '                        \'Open\',\n'
      '                        variant: AstryxBadgeVariant.palette(AstryxPalette.red),\n'
      '                      ),\n'
      '                      AstryxText(\n'
      '                        _incident.id,\n'
      '                        type: AstryxTextType.code,\n'
      '                        color: AstryxTextColor.secondary,\n'
      '                      ),\n'
      '                    ],\n'
      '                  ),\n'
      '                  AstryxHeading(_incident.title, level: 1),\n'
      '                  AstryxText(\n'
      '                    \'Opened \${formatMinutes(_incident.minutes)} ago in \'\n'
      '                    \'\${_incident.service} · paging \${_incident.owner}\',\n'
      '                    color: AstryxTextColor.secondary,\n'
      '                  ),\n'
      '                ],\n'
      '              ),\n'
      '            ),\n'
      '            AstryxHStack(\n'
      '              gap: AstryxSpacingToken.spacing2,\n'
      '              children: <Widget>[\n'
      '                AstryxButton(\n'
      '                  label: \'Resolve\',\n'
      '                  variant: AstryxButtonVariant.primary,\n'
      '                  leading: const AstryxIcon(AstryxIconName.check),\n'
      '                  onPressed: () => AstryxToastScope.of(\n'
      '                    context,\n'
      '                  ).show(const AstryxToast(message: \'Incident resolved\')),\n'
      '                ),\n'
      '                AstryxDropdownMenu(\n'
      '                  label: \'Incident actions\',\n'
      '                  width: 220,\n'
      '                  entries: <AstryxMenuEntry>[\n'
      '                    const AstryxMenuSection(\'Share\'),\n'
      '                    AstryxMenuItem(\n'
      '                      label: \'Copy link\',\n'
      '                      icon: const AstryxIcon(AstryxIconName.copy),\n'
      '                      onSelected: () {},\n'
      '                    ),\n'
      '                    AstryxMenuItem(\n'
      '                      label: \'Open the runbook\',\n'
      '                      icon: const AstryxIcon(AstryxIconName.externalLink),\n'
      '                      onSelected: () {},\n'
      '                    ),\n'
      '                    const AstryxMenuDivider(),\n'
      '                    AstryxMenuItem(\n'
      '                      label: \'Delete incident\',\n'
      '                      destructive: true,\n'
      '                      onSelected: () {},\n'
      '                    ),\n'
      '                  ],\n'
      '                  triggerBuilder: (context, controller) => AstryxIconButton(\n'
      '                    icon: AstryxIconName.moreHorizontal,\n'
      '                    label: \'Incident actions\',\n'
      '                    onPressed: controller.toggle,\n'
      '                  ),\n'
      '                ),\n'
      '              ],\n'
      '            ),\n'
      '          ],\n'
      '        ),\n'
      '        const AstryxBanner(\n'
      '          status: AstryxBannerStatus.warning,\n'
      '          title: \'Latency is still above the objective\',\n'
      '          description: \'p95 is 2.4s against a 1.0s target.\',\n'
      '          announce: false,\n'
      '        ),\n'
      '        AstryxTabList<String>(\n'
      '          label: \'Incident sections\',\n'
      '          value: _tab,\n'
      '          onChanged: (value) => setState(() => _tab = value),\n'
      '          tabs: const <AstryxTab<String>>[\n'
      '            AstryxTab(value: \'overview\', label: \'Overview\'),\n'
      '            AstryxTab(\n'
      '              value: \'timeline\',\n'
      '              label: \'Timeline\',\n'
      '              badge: AstryxBadge(\'4\'),\n'
      '            ),\n'
      '            AstryxTab(value: \'notes\', label: \'Notes\'),\n'
      '          ],\n'
      '        ),\n'
      '        switch (_tab) {\n'
      '          \'overview\' => const _IncidentFacts(),\n'
      '          \'timeline\' => const _IncidentTimeline(),\n'
      '          _ => const _IncidentNotes(),\n'
      '        },\n'
      '      ],\n'
      '    );\n'
      '  }\n'
      '}\n',
  // examples/template_screen_examples.dart
  'template_dashboard':
      'class DashboardTemplate extends StatefulWidget {\n'
      '  const DashboardTemplate({super.key});\n'
      '\n'
      '  @override\n'
      '  State<DashboardTemplate> createState() => _DashboardTemplateState();\n'
      '}\n'
      '\n'
      'class _DashboardTemplateState extends State<DashboardTemplate> {\n'
      '  String _range = \'7d\';\n'
      '\n'
      '  @override\n'
      '  Widget build(BuildContext context) {\n'
      '    final open = incidents.where((row) => !row.resolved).toList();\n'
      '\n'
      '    return AstryxVStack(\n'
      '      gap: AstryxSpacingToken.spacing6,\n'
      '      align: AstryxStackAlign.stretch,\n'
      '      children: <Widget>[\n'
      '        // Title and range picker on one line at width, stacked below it when\n'
      '        // there is no room. Not `wrap: true`: a wrapped row hands its children\n'
      '        // unbounded width, so the supporting line would refuse to break and\n'
      '        // overflow instead of moving.\n'
      '        LayoutBuilder(\n'
      '          builder: (context, constraints) {\n'
      '            // A range picker as an attached button group, the selected segment\n'
      '            // taking the louder variant. That is the segmented control until\n'
      '            // `SegmentedControl` is ported.\n'
      '            final picker = AstryxButtonGroup(\n'
      '              size: AstryxButtonSize.sm,\n'
      '              children: <Widget>[\n'
      '                for (final range in const <String>[\'24h\', \'7d\', \'30d\'])\n'
      '                  AstryxButton(\n'
      '                    label: range,\n'
      '                    variant: _range == range\n'
      '                        ? AstryxButtonVariant.primary\n'
      '                        : AstryxButtonVariant.secondary,\n'
      '                    onPressed: () => setState(() => _range = range),\n'
      '                  ),\n'
      '              ],\n'
      '            );\n'
      '\n'
      '            return constraints.maxWidth < 520\n'
      '                ? AstryxVStack(\n'
      '                    gap: AstryxSpacingToken.spacing3,\n'
      '                    children: <Widget>[const _DashboardTitle(), picker],\n'
      '                  )\n'
      '                : AstryxHStack(\n'
      '                    gap: AstryxSpacingToken.spacing4,\n'
      '                    justify: AstryxStackJustify.between,\n'
      '                    mainAxisSize: MainAxisSize.max,\n'
      '                    children: <Widget>[\n'
      '                      const Flexible(child: _DashboardTitle()),\n'
      '                      picker,\n'
      '                    ],\n'
      '                  );\n'
      '          },\n'
      '        ),\n'
      '        // Tiles first, and the column count falls out of the width rather than\n'
      '        // out of a breakpoint table.\n'
      '        const AstryxGrid(\n'
      '          minWidth: 190,\n'
      '          maxColumns: 4,\n'
      '          gap: AstryxSpacingToken.spacing3,\n'
      '          children: <Widget>[\n'
      '            _Tile(\n'
      '              label: \'Availability\',\n'
      '              value: \'99.94%\',\n'
      '              detail: \'Objective 99.90%\',\n'
      '              progress: 0.9994,\n'
      '              variant: AstryxProgressVariant.success,\n'
      '            ),\n'
      '            _Tile(\n'
      '              label: \'p95 latency\',\n'
      '              value: \'318 ms\',\n'
      '              detail: \'Objective 400 ms\',\n'
      '              progress: 0.79,\n'
      '            ),\n'
      '            _Tile(\n'
      '              label: \'Error budget\',\n'
      '              value: \'38% left\',\n'
      '              detail: \'Resets in 12 days\',\n'
      '              progress: 0.38,\n'
      '              variant: AstryxProgressVariant.warning,\n'
      '            ),\n'
      '            _Tile(\n'
      '              label: \'Open incidents\',\n'
      '              value: \'2\',\n'
      '              detail: \'One at Sev-1\',\n'
      '              progress: null,\n'
      '            ),\n'
      '          ],\n'
      '        ),\n'
      '        AstryxVStack(\n'
      '          gap: AstryxSpacingToken.spacing3,\n'
      '          align: AstryxStackAlign.stretch,\n'
      '          children: <Widget>[\n'
      '            AstryxHStack(\n'
      '              gap: AstryxSpacingToken.spacing2,\n'
      '              justify: AstryxStackJustify.between,\n'
      '              mainAxisSize: MainAxisSize.max,\n'
      '              children: <Widget>[\n'
      '                // `Flexible`, so the heading wraps on a narrow screen instead\n'
      '                // of pushing the link past the edge.\n'
      '                const Flexible(child: AstryxHeading(\'Open incidents\')),\n'
      '                AstryxButton(\n'
      '                  label: \'All incidents\',\n'
      '                  variant: AstryxButtonVariant.ghost,\n'
      '                  size: AstryxButtonSize.sm,\n'
      '                  trailing: const AstryxIcon(\n'
      '                    AstryxIconName.chevronRight,\n'
      '                    size: AstryxIconSize.sm,\n'
      '                  ),\n'
      '                  onPressed: () {},\n'
      '                ),\n'
      '              ],\n'
      '            ),\n'
      '            AstryxTable<Incident>(\n'
      '              label: \'Open incidents\',\n'
      '              rows: open,\n'
      '              keyOf: (row) => row.id,\n'
      '              rowLabelOf: (row) => row.title,\n'
      '              emptyState: const AstryxCenter(\n'
      '                minHeight: 160,\n'
      '                child: AstryxVStack(\n'
      '                  gap: AstryxSpacingToken.spacing2,\n'
      '                  align: AstryxStackAlign.center,\n'
      '                  children: <Widget>[\n'
      '                    AstryxIcon(\n'
      '                      AstryxIconName.success,\n'
      '                      size: AstryxIconSize.lg,\n'
      '                      color: AstryxIconColor.success,\n'
      '                    ),\n'
      '                    AstryxHeading(\'Nothing on fire\', level: 4),\n'
      '                    AstryxText(\n'
      '                      \'Every service is inside its objective.\',\n'
      '                      color: AstryxTextColor.secondary,\n'
      '                    ),\n'
      '                  ],\n'
      '                ),\n'
      '              ),\n'
      '              columns: <AstryxTableColumn<Incident>>[\n'
      '                AstryxTableColumn<Incident>(\n'
      '                  id: \'title\',\n'
      '                  header: \'Incident\',\n'
      '                  width: const AstryxTableColumnWidth.flex(1.6),\n'
      '                  cellBuilder: (context, row) =>\n'
      '                      AstryxText(row.title, maxLines: 1),\n'
      '                ),\n'
      '                AstryxTableColumn<Incident>(\n'
      '                  id: \'severity\',\n'
      '                  header: \'Severity\',\n'
      '                  width: const AstryxTableColumnWidth.intrinsic(min: 96),\n'
      '                  cellBuilder: (context, row) => AstryxBadge(\n'
      '                    row.severityLabel,\n'
      '                    variant: severityVariant(row.severity),\n'
      '                  ),\n'
      '                ),\n'
      '                AstryxTableColumn<Incident>(\n'
      '                  id: \'owner\',\n'
      '                  header: \'On call\',\n'
      '                  cellBuilder: (context, row) => AstryxText(row.owner),\n'
      '                ),\n'
      '                AstryxTableColumn<Incident>(\n'
      '                  id: \'age\',\n'
      '                  header: \'Age\',\n'
      '                  width: const AstryxTableColumnWidth.fixed(80),\n'
      '                  alignment: AstryxTableAlignment.end,\n'
      '                  cellBuilder: (context, row) => AstryxText(\n'
      '                    formatMinutes(row.minutes),\n'
      '                    tabularNumbers: true,\n'
      '                  ),\n'
      '                ),\n'
      '              ],\n'
      '            ),\n'
      '          ],\n'
      '        ),\n'
      '      ],\n'
      '    );\n'
      '  }\n'
      '}\n',
  // examples/template_screen_examples.dart
  'template_table':
      'class TableTemplate extends StatefulWidget {\n'
      '  const TableTemplate({super.key});\n'
      '\n'
      '  @override\n'
      '  State<TableTemplate> createState() => _TableTemplateState();\n'
      '}\n'
      '\n'
      'class _TableTemplateState extends State<TableTemplate> {\n'
      '  final TextEditingController _query = TextEditingController();\n'
      '\n'
      '  AstryxTableSort? _sort = const AstryxTableSort(\n'
      '    \'severity\',\n'
      '    AstryxSortDirection.ascending,\n'
      '  );\n'
      '  Set<Object> _selected = <Object>{};\n'
      '  String _status = \'all\';\n'
      '\n'
      '  @override\n'
      '  void dispose() {\n'
      '    _query.dispose();\n'
      '    super.dispose();\n'
      '  }\n'
      '\n'
      '  /// Filtering happens here, not in the table: `rows` is documented as already\n'
      '  /// filtered, and a table that filtered its own rows could not tell the\n'
      '  /// difference between "no matches" and "no data".\n'
      '  List<Incident> get _rows {\n'
      '    final query = _query.text.trim().toLowerCase();\n'
      '    return incidents.where((row) {\n'
      '      final matchesStatus = switch (_status) {\n'
      '        \'open\' => !row.resolved,\n'
      '        \'resolved\' => row.resolved,\n'
      '        _ => true,\n'
      '      };\n'
      '      final matchesQuery =\n'
      '          query.isEmpty ||\n'
      '          row.title.toLowerCase().contains(query) ||\n'
      '          row.service.toLowerCase().contains(query) ||\n'
      '          row.owner.toLowerCase().contains(query);\n'
      '      return matchesStatus && matchesQuery;\n'
      '    }).toList();\n'
      '  }\n'
      '\n'
      '  @override\n'
      '  Widget build(BuildContext context) {\n'
      '    final rows = _rows;\n'
      '\n'
      '    return AstryxVStack(\n'
      '      gap: AstryxSpacingToken.spacing4,\n'
      '      align: AstryxStackAlign.stretch,\n'
      '      children: <Widget>[\n'
      '        AstryxHStack(\n'
      '          gap: AstryxSpacingToken.spacing4,\n'
      '          justify: AstryxStackJustify.between,\n'
      '          mainAxisSize: MainAxisSize.max,\n'
      '          children: <Widget>[\n'
      '            const Flexible(child: AstryxHeading(\'Incidents\', level: 1)),\n'
      '            AstryxButton(\n'
      '              label: \'Declare incident\',\n'
      '              variant: AstryxButtonVariant.primary,\n'
      '              onPressed: () {},\n'
      '            ),\n'
      '          ],\n'
      '        ),\n'
      '        // The toolbar: search, a filter in a popover, and a column menu. All\n'
      '        // three are always visible — none of them is behind hover.\n'
      '        AstryxHStack(\n'
      '          gap: AstryxSpacingToken.spacing3,\n'
      '          wrap: true,\n'
      '          runGap: AstryxSpacingToken.spacing2,\n'
      '          mainAxisSize: MainAxisSize.max,\n'
      '          children: <Widget>[\n'
      '            SizedBox(\n'
      '              width: 260,\n'
      '              child: AstryxTextInput(\n'
      '                label: \'Search incidents\',\n'
      '                labelHidden: true,\n'
      '                controller: _query,\n'
      '                placeholder: \'Search title, service or owner\',\n'
      '                leading: const AstryxIcon(AstryxIconName.search),\n'
      '                showClear: true,\n'
      '                size: AstryxInputSize.sm,\n'
      '                onChanged: (_) => setState(() {}),\n'
      '              ),\n'
      '            ),\n'
      '            AstryxPopover(\n'
      '              label: \'Filter incidents\',\n'
      '              width: 240,\n'
      '              content: AstryxVStack(\n'
      '                gap: AstryxSpacingToken.spacing4,\n'
      '                align: AstryxStackAlign.stretch,\n'
      '                children: <Widget>[\n'
      '                  AstryxRadioList<String>(\n'
      '                    label: \'Status\',\n'
      '                    value: _status,\n'
      '                    size: AstryxToggleSize.sm,\n'
      '                    onChanged: (value) => setState(() => _status = value),\n'
      '                    options: const <AstryxRadioOption<String>>[\n'
      '                      AstryxRadioOption(value: \'all\', label: \'Everything\'),\n'
      '                      AstryxRadioOption(value: \'open\', label: \'Open only\'),\n'
      '                      AstryxRadioOption(\n'
      '                        value: \'resolved\',\n'
      '                        label: \'Resolved only\',\n'
      '                      ),\n'
      '                    ],\n'
      '                  ),\n'
      '                ],\n'
      '              ),\n'
      '              triggerBuilder: (context, controller) => AstryxButton(\n'
      '                label: _status == \'all\' ? \'Filter\' : \'Filter: \$_status\',\n'
      '                size: AstryxButtonSize.sm,\n'
      '                leading: const AstryxIcon(\n'
      '                  AstryxIconName.funnel,\n'
      '                  size: AstryxIconSize.sm,\n'
      '                ),\n'
      '                onPressed: controller.toggle,\n'
      '              ),\n'
      '            ),\n'
      '            AstryxDropdownMenu(\n'
      '              label: \'Table options\',\n'
      '              width: 200,\n'
      '              entries: <AstryxMenuEntry>[\n'
      '                const AstryxMenuSection(\'Rows\'),\n'
      '                AstryxMenuItem(\n'
      '                  label: \'Export as CSV\',\n'
      '                  icon: const AstryxIcon(AstryxIconName.copy),\n'
      '                  onSelected: () {},\n'
      '                ),\n'
      '                AstryxMenuItem(\n'
      '                  label: \'Subscribe to this view\',\n'
      '                  onSelected: () {},\n'
      '                ),\n'
      '              ],\n'
      '              triggerBuilder: (context, controller) => AstryxIconButton(\n'
      '                icon: AstryxIconName.viewColumns,\n'
      '                label: \'Table options\',\n'
      '                tooltip: \'Table options\',\n'
      '                size: AstryxButtonSize.sm,\n'
      '                onPressed: controller.toggle,\n'
      '              ),\n'
      '            ),\n'
      '          ],\n'
      '        ),\n'
      '        // The selection bar appears once something is selected and says how\n'
      '        // many, because "Delete" with no count is a question the user cannot\n'
      '        // answer.\n'
      '        if (_selected.isNotEmpty)\n'
      '          AstryxBanner(\n'
      '            title: \'\${_selected.length} selected\',\n'
      '            announce: false,\n'
      '            actions: <Widget>[\n'
      '              AstryxButton(\n'
      '                label: \'Resolve\',\n'
      '                size: AstryxButtonSize.sm,\n'
      '                onPressed: () => setState(_selected.clear),\n'
      '              ),\n'
      '              AstryxButton(\n'
      '                label: \'Clear\',\n'
      '                variant: AstryxButtonVariant.ghost,\n'
      '                size: AstryxButtonSize.sm,\n'
      '                onPressed: () => setState(_selected.clear),\n'
      '              ),\n'
      '            ],\n'
      '          ),\n'
      '        AstryxTable<Incident>(\n'
      '          label: \'Incidents\',\n'
      '          rows: rows,\n'
      '          keyOf: (row) => row.id,\n'
      '          rowLabelOf: (row) => row.title,\n'
      '          selectionMode: AstryxTableSelectionMode.multiple,\n'
      '          selected: _selected,\n'
      '          onSelectionChanged: (value) => setState(() => _selected = value),\n'
      '          sort: _sort,\n'
      '          onSortChanged: (sort) => setState(() => _sort = sort),\n'
      '          striped: true,\n'
      '          maxHeight: 320,\n'
      '          emptyState: AstryxCenter(\n'
      '            minHeight: 180,\n'
      '            child: AstryxVStack(\n'
      '              gap: AstryxSpacingToken.spacing3,\n'
      '              align: AstryxStackAlign.center,\n'
      '              children: <Widget>[\n'
      '                const AstryxIcon(\n'
      '                  AstryxIconName.search,\n'
      '                  size: AstryxIconSize.lg,\n'
      '                  color: AstryxIconColor.secondary,\n'
      '                ),\n'
      '                const AstryxHeading(\'No incidents match\', level: 4),\n'
      '                const AstryxText(\n'
      '                  \'Every filter is still applied.\',\n'
      '                  color: AstryxTextColor.secondary,\n'
      '                ),\n'
      '                AstryxButton(\n'
      '                  label: \'Clear filters\',\n'
      '                  onPressed: () => setState(() {\n'
      '                    _query.clear();\n'
      '                    _status = \'all\';\n'
      '                  }),\n'
      '                ),\n'
      '              ],\n'
      '            ),\n'
      '          ),\n'
      '          rowActionsBuilder: (context, row) => AstryxDropdownMenu(\n'
      '            width: 200,\n'
      '            entries: <AstryxMenuEntry>[\n'
      '              AstryxMenuItem(label: \'Open \${row.id}\', onSelected: () {}),\n'
      '              AstryxMenuItem(label: \'Reassign\', onSelected: () {}),\n'
      '              const AstryxMenuDivider(),\n'
      '              AstryxMenuItem(\n'
      '                label: \'Delete\',\n'
      '                destructive: true,\n'
      '                onSelected: () {},\n'
      '              ),\n'
      '            ],\n'
      '            triggerBuilder: (context, controller) => AstryxIconButton(\n'
      '              icon: AstryxIconName.moreHorizontal,\n'
      '              label: \'Actions for \${row.title}\',\n'
      '              variant: AstryxButtonVariant.ghost,\n'
      '              size: AstryxButtonSize.sm,\n'
      '              onPressed: controller.toggle,\n'
      '            ),\n'
      '          ),\n'
      '          columns: <AstryxTableColumn<Incident>>[\n'
      '            AstryxTableColumn<Incident>(\n'
      '              id: \'title\',\n'
      '              header: \'Incident\',\n'
      '              width: const AstryxTableColumnWidth.flex(1.8),\n'
      '              compare: (a, b) => a.title.compareTo(b.title),\n'
      '              cellBuilder: (context, row) => AstryxVStack(\n'
      '                gap: AstryxSpacingToken.spacing0_5,\n'
      '                children: <Widget>[\n'
      '                  AstryxText(row.title, maxLines: 1),\n'
      '                  AstryxText(\n'
      '                    row.service,\n'
      '                    type: AstryxTextType.supporting,\n'
      '                    color: AstryxTextColor.secondary,\n'
      '                  ),\n'
      '                ],\n'
      '              ),\n'
      '            ),\n'
      '            AstryxTableColumn<Incident>(\n'
      '              id: \'severity\',\n'
      '              header: \'Severity\',\n'
      '              width: const AstryxTableColumnWidth.intrinsic(min: 100),\n'
      '              // Sorting on the number, showing the label: "Sev-10" would sort\n'
      '              // between "Sev-1" and "Sev-2" as a string.\n'
      '              compare: (a, b) => a.severity.compareTo(b.severity),\n'
      '              cellBuilder: (context, row) => AstryxBadge(\n'
      '                row.severityLabel,\n'
      '                variant: severityVariant(row.severity),\n'
      '              ),\n'
      '            ),\n'
      '            AstryxTableColumn<Incident>(\n'
      '              id: \'status\',\n'
      '              header: \'Status\',\n'
      '              width: const AstryxTableColumnWidth.intrinsic(min: 96),\n'
      '              cellBuilder: (context, row) => AstryxBadge(\n'
      '                row.resolved ? \'Resolved\' : \'Open\',\n'
      '                variant: row.resolved\n'
      '                    ? AstryxBadgeVariant.success\n'
      '                    : AstryxBadgeVariant.warning,\n'
      '                icon: AstryxIcon(\n'
      '                  row.resolved\n'
      '                      ? AstryxIconName.success\n'
      '                      : AstryxIconName.warning,\n'
      '                ),\n'
      '              ),\n'
      '            ),\n'
      '            AstryxTableColumn<Incident>(\n'
      '              id: \'age\',\n'
      '              header: \'Age\',\n'
      '              width: const AstryxTableColumnWidth.fixed(80),\n'
      '              alignment: AstryxTableAlignment.end,\n'
      '              headerTooltip: \'Time since the alert fired\',\n'
      '              compare: (a, b) => a.minutes.compareTo(b.minutes),\n'
      '              cellBuilder: (context, row) =>\n'
      '                  AstryxText(formatMinutes(row.minutes), tabularNumbers: true),\n'
      '            ),\n'
      '          ],\n'
      '        ),\n'
      '        AstryxText(\n'
      '          \'\${rows.length} of \${incidents.length} incidents\'\n'
      '          \'\${_sort == null ? \'\' : \' · sorted by \${_sort!.columnId}\'}\',\n'
      '          type: AstryxTextType.supporting,\n'
      '          color: AstryxTextColor.secondary,\n'
      '        ),\n'
      '      ],\n'
      '    );\n'
      '  }\n'
      '}\n',
  // examples/template_screen_examples.dart
  'template_theme_showcase':
      'class ThemeShowcaseTemplate extends StatefulWidget {\n'
      '  const ThemeShowcaseTemplate({super.key});\n'
      '\n'
      '  @override\n'
      '  State<ThemeShowcaseTemplate> createState() => _ThemeShowcaseTemplateState();\n'
      '}\n'
      '\n'
      'class _ThemeShowcaseTemplateState extends State<ThemeShowcaseTemplate> {\n'
      '  final AstryxDialogController _dialog = AstryxDialogController();\n'
      '\n'
      '  bool _switched = true;\n'
      '  bool _checked = true;\n'
      '  String _tab = \'live\';\n'
      '  String? _selected = \'eu\';\n'
      '  String _radio = \'balanced\';\n'
      '\n'
      '  @override\n'
      '  void dispose() {\n'
      '    _dialog.dispose();\n'
      '    super.dispose();\n'
      '  }\n'
      '\n'
      '  @override\n'
      '  Widget build(BuildContext context) {\n'
      '    // One screen holding one of everything, so a theme can be judged rather\n'
      '    // than imagined. Change the theme in the picker above and every colour,\n'
      '    // radius, weight and duration on this page moves with it.\n'
      '    //\n'
      '    // Two columns of cards rather than an `AstryxGrid`: a grid gives every cell\n'
      '    // in a row the height of the tallest, which needs an intrinsic measurement\n'
      '    // that a wrapped row of buttons cannot supply. Columns of independent cards\n'
      '    // are also the better shape here — these sections have nothing to line up.\n'
      '    return AstryxVStack(\n'
      '      gap: AstryxSpacingToken.spacing5,\n'
      '      align: AstryxStackAlign.stretch,\n'
      '      children: <Widget>[\n'
      '        LayoutBuilder(\n'
      '          builder: (context, constraints) => constraints.maxWidth < 640\n'
      '              ? AstryxVStack(\n'
      '                  gap: AstryxSpacingToken.spacing4,\n'
      '                  align: AstryxStackAlign.stretch,\n'
      '                  children: <Widget>[\n'
      '                    _actions(),\n'
      '                    _forms(),\n'
      '                    _status(),\n'
      '                    _overlays(context),\n'
      '                  ],\n'
      '                )\n'
      '              : AstryxHStack(\n'
      '                  gap: AstryxSpacingToken.spacing4,\n'
      '                  align: AstryxStackAlign.start,\n'
      '                  mainAxisSize: MainAxisSize.max,\n'
      '                  children: <Widget>[\n'
      '                    Expanded(\n'
      '                      child: AstryxVStack(\n'
      '                        gap: AstryxSpacingToken.spacing4,\n'
      '                        align: AstryxStackAlign.stretch,\n'
      '                        children: <Widget>[_actions(), _status()],\n'
      '                      ),\n'
      '                    ),\n'
      '                    Expanded(\n'
      '                      child: AstryxVStack(\n'
      '                        gap: AstryxSpacingToken.spacing4,\n'
      '                        align: AstryxStackAlign.stretch,\n'
      '                        children: <Widget>[_forms(), _overlays(context)],\n'
      '                      ),\n'
      '                    ),\n'
      '                  ],\n'
      '                ),\n'
      '        ),\n'
      '        _panel(),\n'
      '      ],\n'
      '    );\n'
      '  }\n'
      '\n'
      '  /// Every button variant, and the two sizes of icon button.\n'
      '  Widget _actions() {\n'
      '    return AstryxCard(\n'
      '      header: const AstryxHeading(\'Actions\', level: 3),\n'
      '      child: AstryxVStack(\n'
      '        gap: AstryxSpacingToken.spacing3,\n'
      '        align: AstryxStackAlign.stretch,\n'
      '        children: <Widget>[\n'
      '          AstryxHStack(\n'
      '            gap: AstryxSpacingToken.spacing2,\n'
      '            wrap: true,\n'
      '            runGap: AstryxSpacingToken.spacing2,\n'
      '            children: <Widget>[\n'
      '              AstryxButton(\n'
      '                label: \'Primary\',\n'
      '                variant: AstryxButtonVariant.primary,\n'
      '                onPressed: () {},\n'
      '              ),\n'
      '              AstryxButton(label: \'Secondary\', onPressed: () {}),\n'
      '              AstryxButton(\n'
      '                label: \'Ghost\',\n'
      '                variant: AstryxButtonVariant.ghost,\n'
      '                onPressed: () {},\n'
      '              ),\n'
      '              AstryxButton(\n'
      '                label: \'Destructive\',\n'
      '                variant: AstryxButtonVariant.destructive,\n'
      '                onPressed: () {},\n'
      '              ),\n'
      '              AstryxButton(label: \'Disabled\', enabled: false, onPressed: () {}),\n'
      '            ],\n'
      '          ),\n'
      '          AstryxHStack(\n'
      '            gap: AstryxSpacingToken.spacing2,\n'
      '            wrap: true,\n'
      '            runGap: AstryxSpacingToken.spacing2,\n'
      '            children: <Widget>[\n'
      '              AstryxIconButton(\n'
      '                icon: AstryxIconName.search,\n'
      '                label: \'Search\',\n'
      '                tooltip: \'Search\',\n'
      '                onPressed: () {},\n'
      '              ),\n'
      '              AstryxIconButton(\n'
      '                icon: AstryxIconName.funnel,\n'
      '                label: \'Filter\',\n'
      '                variant: AstryxButtonVariant.ghost,\n'
      '                onPressed: () {},\n'
      '              ),\n'
      '              AstryxButton(label: \'Loading\', loading: true, onPressed: () {}),\n'
      '            ],\n'
      '          ),\n'
      '          AstryxButtonGroup(\n'
      '            size: AstryxButtonSize.sm,\n'
      '            children: <Widget>[\n'
      '              AstryxButton(label: \'Day\', onPressed: () {}),\n'
      '              AstryxButton(\n'
      '                label: \'Week\',\n'
      '                variant: AstryxButtonVariant.primary,\n'
      '                onPressed: () {},\n'
      '              ),\n'
      '              AstryxButton(label: \'Month\', onPressed: () {}),\n'
      '            ],\n'
      '          ),\n'
      '        ],\n'
      '      ),\n'
      '    );\n'
      '  }\n'
      '\n'
      '  /// One of every input, including a validated one.\n'
      '  Widget _forms() {\n'
      '    return AstryxCard(\n'
      '      header: const AstryxHeading(\'Forms\', level: 3),\n'
      '      child: AstryxVStack(\n'
      '        gap: AstryxSpacingToken.spacing3,\n'
      '        align: AstryxStackAlign.stretch,\n'
      '        children: <Widget>[\n'
      '          const AstryxTextInput(\n'
      '            label: \'Workspace\',\n'
      '            placeholder: \'Atlas\',\n'
      '            status: AstryxFieldStatus.success(\'Available\'),\n'
      '          ),\n'
      '          AstryxSelector<String>(\n'
      '            label: \'Region\',\n'
      '            value: _selected,\n'
      '            onChanged: (value) => setState(() => _selected = value),\n'
      '            options: const <AstryxSelectorEntry<String>>[\n'
      '              AstryxSelectorOption(value: \'eu\', label: \'Frankfurt\'),\n'
      '              AstryxSelectorOption(value: \'us\', label: \'Virginia\'),\n'
      '            ],\n'
      '          ),\n'
      '          AstryxSwitch(\n'
      '            label: \'Notifications\',\n'
      '            value: _switched,\n'
      '            labelPosition: AstryxToggleLabelPosition.start,\n'
      '            labelSpacing: AstryxToggleLabelSpacing.spread,\n'
      '            onChanged: (value) => setState(() => _switched = value),\n'
      '          ),\n'
      '          AstryxCheckbox(\n'
      '            label: \'Include archived\',\n'
      '            value: _checked,\n'
      '            onChanged: (value) => setState(() => _checked = value),\n'
      '          ),\n'
      '          AstryxRadioList<String>(\n'
      '            label: \'Density\',\n'
      '            value: _radio,\n'
      '            orientation: AstryxRadioListOrientation.horizontal,\n'
      '            onChanged: (value) => setState(() => _radio = value),\n'
      '            options: const <AstryxRadioOption<String>>[\n'
      '              AstryxRadioOption(value: \'compact\', label: \'Compact\'),\n'
      '              AstryxRadioOption(value: \'balanced\', label: \'Balanced\'),\n'
      '            ],\n'
      '          ),\n'
      '        ],\n'
      '      ),\n'
      '    );\n'
      '  }\n'
      '\n'
      '  /// The badges, the bar, the spinner and the skeleton.\n'
      '  Widget _status() {\n'
      '    return const AstryxCard(\n'
      '      header: AstryxHeading(\'Status\', level: 3),\n'
      '      child: AstryxVStack(\n'
      '        gap: AstryxSpacingToken.spacing3,\n'
      '        align: AstryxStackAlign.stretch,\n'
      '        children: <Widget>[\n'
      '          AstryxHStack(\n'
      '            gap: AstryxSpacingToken.spacing2,\n'
      '            wrap: true,\n'
      '            runGap: AstryxSpacingToken.spacing2,\n'
      '            children: <Widget>[\n'
      '              AstryxBadge(\'neutral\'),\n'
      '              AstryxBadge(\'info\', variant: AstryxBadgeVariant.info),\n'
      '              AstryxBadge(\'success\', variant: AstryxBadgeVariant.success),\n'
      '              AstryxBadge(\'warning\', variant: AstryxBadgeVariant.warning),\n'
      '              AstryxBadge(\'error\', variant: AstryxBadgeVariant.error),\n'
      '            ],\n'
      '          ),\n'
      '          AstryxBanner(\n'
      '            title: \'Rebuilding the search index\',\n'
      '            description: \'Results may be incomplete for a few minutes.\',\n'
      '            announce: false,\n'
      '          ),\n'
      '          AstryxProgressBar(\n'
      '            label: \'Rebuilding index\',\n'
      '            value: 0.62,\n'
      '            showValueLabel: true,\n'
      '          ),\n'
      '          AstryxHStack(\n'
      '            gap: AstryxSpacingToken.spacing2,\n'
      '            children: <Widget>[\n'
      '              AstryxSpinner(label: \'Loading\'),\n'
      '              AstryxText(\'Loading…\', color: AstryxTextColor.secondary),\n'
      '            ],\n'
      '          ),\n'
      '          AstryxSkeleton.text(),\n'
      '          AstryxSkeleton.text(widthFactor: 0.6),\n'
      '        ],\n'
      '      ),\n'
      '    );\n'
      '  }\n'
      '\n'
      '  /// Every overlay, each behind its own trigger.\n'
      '  Widget _overlays(BuildContext context) {\n'
      '    return AstryxCard(\n'
      '      header: const AstryxHeading(\'Overlays\', level: 3),\n'
      '      child: AstryxVStack(\n'
      '        gap: AstryxSpacingToken.spacing3,\n'
      '        align: AstryxStackAlign.stretch,\n'
      '        children: <Widget>[\n'
      '          AstryxHStack(\n'
      '            gap: AstryxSpacingToken.spacing2,\n'
      '            wrap: true,\n'
      '            runGap: AstryxSpacingToken.spacing2,\n'
      '            children: <Widget>[\n'
      '              AstryxPopover(\n'
      '                label: \'Details\',\n'
      '                width: 220,\n'
      '                content: const AstryxText(\n'
      '                  \'A floating panel, with focus trapped inside it until it \'\n'
      '                  \'closes.\',\n'
      '                ),\n'
      '                triggerBuilder: (context, controller) => AstryxButton(\n'
      '                  label: \'Popover\',\n'
      '                  size: AstryxButtonSize.sm,\n'
      '                  onPressed: controller.toggle,\n'
      '                ),\n'
      '              ),\n'
      '              AstryxDropdownMenu(\n'
      '                label: \'Menu\',\n'
      '                width: 180,\n'
      '                entries: <AstryxMenuEntry>[\n'
      '                  AstryxMenuItem(label: \'Rename\', onSelected: () {}),\n'
      '                  AstryxMenuItem(\n'
      '                    label: \'Delete\',\n'
      '                    destructive: true,\n'
      '                    onSelected: () {},\n'
      '                  ),\n'
      '                ],\n'
      '                triggerBuilder: (context, controller) => AstryxButton(\n'
      '                  label: \'Menu\',\n'
      '                  size: AstryxButtonSize.sm,\n'
      '                  onPressed: controller.toggle,\n'
      '                ),\n'
      '              ),\n'
      '              AstryxTooltip(\n'
      '                message: \'The same information, for a pointer\',\n'
      '                child: AstryxButton(\n'
      '                  label: \'Tooltip\',\n'
      '                  size: AstryxButtonSize.sm,\n'
      '                  onPressed: () {},\n'
      '                ),\n'
      '              ),\n'
      '              AstryxButton(\n'
      '                label: \'Toast\',\n'
      '                size: AstryxButtonSize.sm,\n'
      '                onPressed: () => AstryxToastScope.of(\n'
      '                  context,\n'
      '                ).show(const AstryxToast(message: \'Saved to your views\')),\n'
      '              ),\n'
      '              AstryxButton(\n'
      '                label: \'Dialog\',\n'
      '                size: AstryxButtonSize.sm,\n'
      '                onPressed: _dialog.show,\n'
      '              ),\n'
      '            ],\n'
      '          ),\n'
      '          AstryxDialog(\n'
      '            controller: _dialog,\n'
      '            title: \'A modal\',\n'
      '            description: \'Focus is trapped until it closes.\',\n'
      '            footer: AstryxHStack(\n'
      '              gap: AstryxSpacingToken.spacing2,\n'
      '              justify: AstryxStackJustify.end,\n'
      '              mainAxisSize: MainAxisSize.max,\n'
      '              children: <Widget>[\n'
      '                AstryxButton(label: \'Close\', onPressed: _dialog.hide),\n'
      '              ],\n'
      '            ),\n'
      '            child: const AstryxText(\n'
      '              \'Every radius, shadow and duration here comes from the theme in \'\n'
      '              \'scope.\',\n'
      '            ),\n'
      '          ),\n'
      '        ],\n'
      '      ),\n'
      '    );\n'
      '  }\n'
      '\n'
      '  /// A table and a type specimen, behind a tab strip.\n'
      '  Widget _panel() {\n'
      '    return AstryxCard(\n'
      '      header: AstryxTabList<String>(\n'
      '        label: \'Showcase sections\',\n'
      '        value: _tab,\n'
      '        onChanged: (value) => setState(() => _tab = value),\n'
      '        tabs: const <AstryxTab<String>>[\n'
      '          AstryxTab(value: \'live\', label: \'Incidents\'),\n'
      '          AstryxTab(value: \'typography\', label: \'Typography\'),\n'
      '        ],\n'
      '      ),\n'
      '      child: _tab == \'live\'\n'
      '          ? AstryxTable<Incident>(\n'
      '              label: \'Incidents\',\n'
      '              rows: incidents,\n'
      '              keyOf: (row) => row.id,\n'
      '              striped: true,\n'
      '              maxHeight: 220,\n'
      '              columns: <AstryxTableColumn<Incident>>[\n'
      '                AstryxTableColumn<Incident>(\n'
      '                  id: \'title\',\n'
      '                  header: \'Incident\',\n'
      '                  cellBuilder: (context, row) =>\n'
      '                      AstryxText(row.title, maxLines: 1),\n'
      '                ),\n'
      '                AstryxTableColumn<Incident>(\n'
      '                  id: \'severity\',\n'
      '                  header: \'Severity\',\n'
      '                  width: const AstryxTableColumnWidth.intrinsic(min: 96),\n'
      '                  cellBuilder: (context, row) => AstryxBadge(\n'
      '                    row.severityLabel,\n'
      '                    variant: severityVariant(row.severity),\n'
      '                  ),\n'
      '                ),\n'
      '              ],\n'
      '            )\n'
      '          : const AstryxVStack(\n'
      '              gap: AstryxSpacingToken.spacing2,\n'
      '              align: AstryxStackAlign.stretch,\n'
      '              children: <Widget>[\n'
      '                AstryxHeading(\'Heading level 2\'),\n'
      '                AstryxHeading(\'Heading level 4\', level: 4),\n'
      '                AstryxText(\n'
      '                  \'Body text, which is what most of a tool is made of.\',\n'
      '                ),\n'
      '                AstryxText(\n'
      '                  \'Supporting text, for the line under the thing.\',\n'
      '                  type: AstryxTextType.supporting,\n'
      '                  color: AstryxTextColor.secondary,\n'
      '                ),\n'
      '                AstryxText(\'const AstryxText(…)\', type: AstryxTextType.code),\n'
      '              ],\n'
      '            ),\n'
      '    );\n'
      '  }\n'
      '}\n',
  // examples/template_settings_examples.dart
  'template_settings':
      'class SettingsTemplate extends StatefulWidget {\n'
      '  const SettingsTemplate({super.key});\n'
      '\n'
      '  @override\n'
      '  State<SettingsTemplate> createState() => _SettingsTemplateState();\n'
      '}\n'
      '\n'
      'class _SettingsTemplateState extends State<SettingsTemplate> {\n'
      '  final Set<String> _on = <String>{\'mentions\', \'incidents\'};\n'
      '  final AstryxDialogController _leave = AstryxDialogController();\n'
      '\n'
      '  String? _theme = \'system\';\n'
      '  String? _startPage = \'dashboard\';\n'
      '\n'
      '  @override\n'
      '  void dispose() {\n'
      '    _leave.dispose();\n'
      '    super.dispose();\n'
      '  }\n'
      '\n'
      '  /// Applies a switch immediately, and says so. A setting that takes effect\n'
      '  /// silently and a setting that failed to save look identical.\n'
      '  void _toggle(String id, String label, bool value) {\n'
      '    setState(() {\n'
      '      if (value) {\n'
      '        _on.add(id);\n'
      '      } else {\n'
      '        _on.remove(id);\n'
      '      }\n'
      '    });\n'
      '    AstryxToastScope.of(context).show(\n'
      '      AstryxToast(message: \'\$label \${value ? \'on\' : \'off\'}\'),\n'
      '    );\n'
      '  }\n'
      '\n'
      '  @override\n'
      '  Widget build(BuildContext context) {\n'
      '    return AstryxVStack(\n'
      '      gap: AstryxSpacingToken.spacing6,\n'
      '      align: AstryxStackAlign.stretch,\n'
      '      children: <Widget>[\n'
      '        const AstryxVStack(\n'
      '          gap: AstryxSpacingToken.spacing1,\n'
      '          children: <Widget>[\n'
      '            AstryxHeading(\'Settings\', level: 1),\n'
      '            AstryxText(\n'
      '              \'Yours only. Workspace-wide settings live under Admin.\',\n'
      '              color: AstryxTextColor.secondary,\n'
      '            ),\n'
      '          ],\n'
      '        ),\n'
      '        // Notifications are switches: each one is in force the moment it moves,\n'
      '        // and there is no Save button on the screen to suggest otherwise.\n'
      '        AstryxCard(\n'
      '          header: const _SectionHeader(\n'
      '            title: \'Notifications\',\n'
      '            description: \'Applied as you change them.\',\n'
      '          ),\n'
      '          child: AstryxVStack(\n'
      '            gap: AstryxSpacingToken.spacing3,\n'
      '            align: AstryxStackAlign.stretch,\n'
      '            children: <Widget>[\n'
      '              for (final row in const <List<String>>[\n'
      '                <String>[\'mentions\', \'Mentions\', \'When someone @s you\'],\n'
      '                <String>[\'incidents\', \'Incidents\', \'Sev-1 and Sev-2 only\'],\n'
      '                <String>[\'digest\', \'Weekly digest\', \'Mondays, 9am\'],\n'
      '                <String>[\'marketing\', \'Product news\', \'About once a month\'],\n'
      '              ]) ...<Widget>[\n'
      '                if (row.first != \'mentions\') const AstryxDivider(),\n'
      '                AstryxSwitch(\n'
      '                  label: row[1],\n'
      '                  description: row[2],\n'
      '                  value: _on.contains(row.first),\n'
      '                  labelPosition: AstryxToggleLabelPosition.start,\n'
      '                  labelSpacing: AstryxToggleLabelSpacing.spread,\n'
      '                  onChanged: (value) => _toggle(row.first, row[1], value),\n'
      '                ),\n'
      '              ],\n'
      '            ],\n'
      '          ),\n'
      '        ),\n'
      '        AstryxCard(\n'
      '          header: const _SectionHeader(\n'
      '            title: \'Appearance\',\n'
      '            description: \'Stored on this device.\',\n'
      '          ),\n'
      '          child: AstryxVStack(\n'
      '            gap: AstryxSpacingToken.spacing4,\n'
      '            align: AstryxStackAlign.stretch,\n'
      '            children: <Widget>[\n'
      '              AstryxSelector<String>(\n'
      '                label: \'Colour mode\',\n'
      '                value: _theme,\n'
      '                onChanged: (value) => setState(() => _theme = value),\n'
      '                options: const <AstryxSelectorEntry<String>>[\n'
      '                  AstryxSelectorOption(\n'
      '                    value: \'system\',\n'
      '                    label: \'Match the system\',\n'
      '                    description: \'Follows your OS setting as it changes\',\n'
      '                  ),\n'
      '                  AstryxSelectorOption(value: \'light\', label: \'Light\'),\n'
      '                  AstryxSelectorOption(value: \'dark\', label: \'Dark\'),\n'
      '                ],\n'
      '              ),\n'
      '              AstryxSelector<String>(\n'
      '                label: \'Open on\',\n'
      '                value: _startPage,\n'
      '                onChanged: (value) => setState(() => _startPage = value),\n'
      '                options: const <AstryxSelectorEntry<String>>[\n'
      '                  AstryxSelectorOption(\n'
      '                    value: \'dashboard\',\n'
      '                    label: \'Dashboard\',\n'
      '                  ),\n'
      '                  AstryxSelectorOption(value: \'incidents\', label: \'Incidents\'),\n'
      '                  AstryxSelectorOption(value: \'projects\', label: \'Projects\'),\n'
      '                ],\n'
      '              ),\n'
      '            ],\n'
      '          ),\n'
      '        ),\n'
      '        // The destructive section is last, is bordered in its own right, and\n'
      '        // goes through a dialog. The button alone is not the confirmation.\n'
      '        AstryxCard(\n'
      '          variant: const AstryxCardVariant.palette(AstryxPalette.red),\n'
      '          header: const _SectionHeader(\n'
      '            title: \'Leave workspace\',\n'
      '            description: \'You will lose access to Atlas immediately.\',\n'
      '          ),\n'
      '          child: AstryxHStack(\n'
      '            gap: AstryxSpacingToken.spacing3,\n'
      '            children: <Widget>[\n'
      '              AstryxButton(\n'
      '                label: \'Leave Atlas\',\n'
      '                variant: AstryxButtonVariant.destructive,\n'
      '                onPressed: _leave.show,\n'
      '              ),\n'
      '              AstryxDialog(\n'
      '                controller: _leave,\n'
      '                title: \'Leave Atlas?\',\n'
      '                description: \'An admin has to invite you back.\',\n'
      '                footer: AstryxHStack(\n'
      '                  gap: AstryxSpacingToken.spacing2,\n'
      '                  justify: AstryxStackJustify.end,\n'
      '                  mainAxisSize: MainAxisSize.max,\n'
      '                  children: <Widget>[\n'
      '                    AstryxButton(label: \'Stay\', onPressed: _leave.hide),\n'
      '                    AstryxButton(\n'
      '                      label: \'Leave\',\n'
      '                      variant: AstryxButtonVariant.destructive,\n'
      '                      onPressed: _leave.hide,\n'
      '                    ),\n'
      '                  ],\n'
      '                ),\n'
      '                child: const AstryxText(\n'
      '                  \'Your drafts and saved views are deleted after 30 days. \'\n'
      '                  \'Anything you published stays with the workspace.\',\n'
      '                ),\n'
      '              ),\n'
      '            ],\n'
      '          ),\n'
      '        ),\n'
      '      ],\n'
      '    );\n'
      '  }\n'
      '}\n',
  // examples/template_settings_examples.dart
  'template_settings_dialog':
      'class SettingsDialogTemplate extends StatefulWidget {\n'
      '  const SettingsDialogTemplate({super.key});\n'
      '\n'
      '  @override\n'
      '  State<SettingsDialogTemplate> createState() => _SettingsDialogTemplateState();\n'
      '}\n'
      '\n'
      'class _SettingsDialogTemplateState extends State<SettingsDialogTemplate> {\n'
      '  final AstryxDialogController _controller = AstryxDialogController();\n'
      '  final TextEditingController _name = TextEditingController(text: \'Ada\');\n'
      '\n'
      '  /// The dialog\'s own navigation. A tab list reports a value and owns no panel,\n'
      '  /// so the section on screen is this field and nothing else.\n'
      '  String _section = \'profile\';\n'
      '  bool _compact = false;\n'
      '  final Set<String> _on = <String>{\'mentions\'};\n'
      '\n'
      '  @override\n'
      '  void dispose() {\n'
      '    _controller.dispose();\n'
      '    _name.dispose();\n'
      '    super.dispose();\n'
      '  }\n'
      '\n'
      '  @override\n'
      '  Widget build(BuildContext context) {\n'
      '    return AstryxHStack(\n'
      '      gap: AstryxSpacingToken.spacing3,\n'
      '      children: <Widget>[\n'
      '        AstryxButton(\n'
      '          label: \'Open settings\',\n'
      '          leading: const AstryxIcon(AstryxIconName.wrench),\n'
      '          onPressed: _controller.show,\n'
      '        ),\n'
      '        AstryxDialog(\n'
      '          controller: _controller,\n'
      '          title: \'Settings\',\n'
      '          width: 520,\n'
      '          footer: AstryxHStack(\n'
      '            gap: AstryxSpacingToken.spacing2,\n'
      '            justify: AstryxStackJustify.end,\n'
      '            mainAxisSize: MainAxisSize.max,\n'
      '            children: <Widget>[\n'
      '              AstryxButton(label: \'Close\', onPressed: _controller.hide),\n'
      '            ],\n'
      '          ),\n'
      '          child: AstryxVStack(\n'
      '            gap: AstryxSpacingToken.spacing5,\n'
      '            align: AstryxStackAlign.stretch,\n'
      '            children: <Widget>[\n'
      '              AstryxTabList<String>(\n'
      '                label: \'Settings sections\',\n'
      '                value: _section,\n'
      '                onChanged: (value) => setState(() => _section = value),\n'
      '                tabs: const <AstryxTab<String>>[\n'
      '                  AstryxTab(value: \'profile\', label: \'Profile\'),\n'
      '                  AstryxTab(value: \'notifications\', label: \'Notifications\'),\n'
      '                  AstryxTab(value: \'advanced\', label: \'Advanced\'),\n'
      '                ],\n'
      '              ),\n'
      '              switch (_section) {\n'
      '                \'profile\' => AstryxVStack(\n'
      '                  gap: AstryxSpacingToken.spacing4,\n'
      '                  align: AstryxStackAlign.stretch,\n'
      '                  children: <Widget>[\n'
      '                    AstryxTextInput(\n'
      '                      label: \'Display name\',\n'
      '                      controller: _name,\n'
      '                      required: true,\n'
      '                    ),\n'
      '                    const AstryxTextInput(\n'
      '                      label: \'Email\',\n'
      '                      readOnly: true,\n'
      '                      // Read-only, not disabled: the value matters, it is just\n'
      '                      // not yours to change here.\n'
      '                      description: \'Managed by your identity provider.\',\n'
      '                      placeholder: \'ada@example.com\',\n'
      '                    ),\n'
      '                  ],\n'
      '                ),\n'
      '                \'notifications\' => AstryxVStack(\n'
      '                  gap: AstryxSpacingToken.spacing3,\n'
      '                  align: AstryxStackAlign.stretch,\n'
      '                  children: <Widget>[\n'
      '                    for (final row in const <List<String>>[\n'
      '                      <String>[\'mentions\', \'Mentions\'],\n'
      '                      <String>[\'replies\', \'Replies to my comments\'],\n'
      '                      <String>[\'deploys\', \'Deploy failures\'],\n'
      '                    ])\n'
      '                      AstryxSwitch(\n'
      '                        label: row[1],\n'
      '                        value: _on.contains(row.first),\n'
      '                        labelPosition: AstryxToggleLabelPosition.start,\n'
      '                        labelSpacing: AstryxToggleLabelSpacing.spread,\n'
      '                        onChanged: (value) => setState(() {\n'
      '                          if (value) {\n'
      '                            _on.add(row.first);\n'
      '                          } else {\n'
      '                            _on.remove(row.first);\n'
      '                          }\n'
      '                        }),\n'
      '                      ),\n'
      '                  ],\n'
      '                ),\n'
      '                _ => AstryxVStack(\n'
      '                  gap: AstryxSpacingToken.spacing4,\n'
      '                  align: AstryxStackAlign.stretch,\n'
      '                  children: <Widget>[\n'
      '                    AstryxSwitch(\n'
      '                      label: \'Compact tables\',\n'
      '                      description: \'More rows, less room in each.\',\n'
      '                      value: _compact,\n'
      '                      labelPosition: AstryxToggleLabelPosition.start,\n'
      '                      labelSpacing: AstryxToggleLabelSpacing.spread,\n'
      '                      onChanged: (value) => setState(() => _compact = value),\n'
      '                    ),\n'
      '                    const AstryxBanner(\n'
      '                      title: \'Changes here apply immediately\',\n'
      '                      description: \'There is no Save button, by design.\',\n'
      '                      announce: false,\n'
      '                    ),\n'
      '                  ],\n'
      '                ),\n'
      '              },\n'
      '            ],\n'
      '          ),\n'
      '        ),\n'
      '      ],\n'
      '    );\n'
      '  }\n'
      '}\n',
  // examples/template_settings_examples.dart
  'template_settings_sidebar':
      'class SettingsSidebarTemplate extends StatefulWidget {\n'
      '  const SettingsSidebarTemplate({super.key});\n'
      '\n'
      '  @override\n'
      '  State<SettingsSidebarTemplate> createState() =>\n'
      '      _SettingsSidebarTemplateState();\n'
      '}\n'
      '\n'
      'class _SettingsSidebarTemplateState extends State<SettingsSidebarTemplate> {\n'
      '  /// The sections, as navigation rather than as headings on one long page.\n'
      '  ///\n'
      '  /// Past about four sections a settings page stops being scannable, and the\n'
      '  /// reader is scrolling to find out what exists. A rail answers that question\n'
      '  /// without scrolling anything.\n'
      '  static const List<AstryxNavEntry> _sections = <AstryxNavEntry>[\n'
      '    AstryxNavSection(\n'
      '      label: \'You\',\n'
      '      items: <AstryxNavItem>[\n'
      '        AstryxNavItem(\n'
      '          id: \'profile\',\n'
      '          label: \'Profile\',\n'
      '          icon: AstryxNavIcon(AstryxIcon(AstryxIconName.check)),\n'
      '        ),\n'
      '        AstryxNavItem(\n'
      '          id: \'notifications\',\n'
      '          label: \'Notifications\',\n'
      '          icon: AstryxNavIcon(AstryxIcon(AstryxIconName.info)),\n'
      '          trailing: AstryxBadge(\'2\'),\n'
      '        ),\n'
      '        AstryxNavItem(\n'
      '          id: \'appearance\',\n'
      '          label: \'Appearance\',\n'
      '          icon: AstryxNavIcon(AstryxIcon(AstryxIconName.viewColumns)),\n'
      '        ),\n'
      '      ],\n'
      '    ),\n'
      '    AstryxNavSection(\n'
      '      label: \'Workspace\',\n'
      '      items: <AstryxNavItem>[\n'
      '        AstryxNavItem(\n'
      '          id: \'members\',\n'
      '          label: \'Members\',\n'
      '          icon: AstryxNavIcon(AstryxIcon(AstryxIconName.checkDouble)),\n'
      '        ),\n'
      '        AstryxNavItem(\n'
      '          id: \'security\',\n'
      '          label: \'Security\',\n'
      '          icon: AstryxNavIcon(AstryxIcon(AstryxIconName.eyeSlash)),\n'
      '        ),\n'
      '      ],\n'
      '    ),\n'
      '    AstryxNavDivider(),\n'
      '    AstryxNavItem(\n'
      '      id: \'danger\',\n'
      '      label: \'Delete workspace\',\n'
      '      icon: AstryxNavIcon(AstryxIcon(AstryxIconName.warning)),\n'
      '    ),\n'
      '  ];\n'
      '\n'
      '  static const Map<String, ({String title, String description})> _headings =\n'
      '      <String, ({String title, String description})>{\n'
      '        \'profile\': (\n'
      '          title: \'Profile\',\n'
      '          description: \'How you appear to everyone else in the workspace.\',\n'
      '        ),\n'
      '        \'notifications\': (\n'
      '          title: \'Notifications\',\n'
      '          description: \'What reaches you, and how loudly.\',\n'
      '        ),\n'
      '        \'appearance\': (\n'
      '          title: \'Appearance\',\n'
      '          description: \'Yours only. Nobody else sees these.\',\n'
      '        ),\n'
      '        \'members\': (\n'
      '          title: \'Members\',\n'
      '          description: \'Who is in this workspace, and what they may do.\',\n'
      '        ),\n'
      '        \'security\': (\n'
      '          title: \'Security\',\n'
      '          description: \'Sign-in, sessions and tokens.\',\n'
      '        ),\n'
      '        \'danger\': (\n'
      '          title: \'Delete workspace\',\n'
      '          description: \'Everything in it goes, thirty days later.\',\n'
      '        ),\n'
      '      };\n'
      '\n'
      '  final Set<String> _on = <String>{\'mentions\', \'incidents\', \'digest\'};\n'
      '  final AstryxDialogController _confirm = AstryxDialogController();\n'
      '\n'
      '  String _section = \'notifications\';\n'
      '  String? _theme = \'system\';\n'
      '\n'
      '  @override\n'
      '  void dispose() {\n'
      '    _confirm.dispose();\n'
      '    super.dispose();\n'
      '  }\n'
      '\n'
      '  /// Every control here applies the moment it moves, so every one of them\n'
      '  /// confirms. There is no Save button anywhere on this screen — adding one\n'
      '  /// would make every switch a lie.\n'
      '  void _toggle(String id, String label, {required bool value}) {\n'
      '    setState(() {\n'
      '      if (value) {\n'
      '        _on.add(id);\n'
      '      } else {\n'
      '        _on.remove(id);\n'
      '      }\n'
      '    });\n'
      '    AstryxToastScope.of(context).show(\n'
      '      AstryxToast(message: \'\$label \${value ? \'on\' : \'off\'}\'),\n'
      '    );\n'
      '  }\n'
      '\n'
      '  @override\n'
      '  Widget build(BuildContext context) {\n'
      '    final heading = _headings[_section]!;\n'
      '\n'
      '    // The rail sits in the *shell* rather than in the layout\'s `panel`. Two\n'
      '    // reasons, and the second is the one that matters on a phone: a panel is\n'
      '    // wrapped in a scroll view, so it is handed an unbounded height — and an\n'
      '    // `AstryxSideNav` pins its own footer with an `Expanded`, which cannot be\n'
      '    // laid out against one. And a shell already knows what to do when there is\n'
      '    // no room beside the content: the rail moves into a drawer, with the\n'
      '    // focus trap, the Escape key and the return of focus that a hand-rolled\n'
      '    // `Row` never gets around to.\n'
      '    return SizedBox(\n'
      '      height: 620,\n'
      '      child: AstryxAppShell(\n'
      '        compactBelow: 640,\n'
      '        sidebarWidth: 232,\n'
      '        navLabel: \'Settings sections\',\n'
      '        header: _SettingsBar(title: heading.title),\n'
      '        // A rail of sections, not a tab strip: these are *places* in a\n'
      '        // settings area rather than views of one thing, and there are\n'
      '        // more of them than a strip can hold without scrolling sideways.\n'
      '        sidebar: AstryxSideNav(\n'
      '          label: \'Settings sections\',\n'
      '          entries: _sections,\n'
      '          selectedId: _section,\n'
      '          onSelected: (id) {\n'
      '            setState(() => _section = id);\n'
      '            // Choosing a section in the drawer is the end of what the drawer\n'
      '            // was opened for. Leaving it up would hide the answer.\n'
      '            AstryxAppShell.of(context).controller.hide();\n'
      '          },\n'
      '        ),\n'
      '        child: AstryxLayout(\n'
      '          maxContentWidth: 620,\n'
      '          header: AstryxVStack(\n'
      '            gap: AstryxSpacingToken.spacing1,\n'
      '            children: <Widget>[\n'
      '              AstryxHeading(heading.title, level: 1),\n'
      '              AstryxText(\n'
      '                heading.description,\n'
      '                type: AstryxTextType.supporting,\n'
      '                color: AstryxTextColor.secondary,\n'
      '              ),\n'
      '            ],\n'
      '          ),\n'
      '          child: switch (_section) {\n'
      '            \'notifications\' => _notifications(),\n'
      '            \'appearance\' => _appearance(),\n'
      '            \'danger\' => _danger(context),\n'
      '            _ => _placeholder(heading.title),\n'
      '          },\n'
      '        ),\n'
      '      ),\n'
      '    );\n'
      '  }\n'
      '\n'
      '  Widget _notifications() {\n'
      '    return AstryxCard(\n'
      '      padding: AstryxSpacingToken.spacing0,\n'
      '      child: AstryxVStack(\n'
      '        gap: AstryxSpacingToken.spacing0,\n'
      '        align: AstryxStackAlign.stretch,\n'
      '        children: <Widget>[\n'
      '          for (final row in const <List<String>>[\n'
      '            <String>[\'mentions\', \'Mentions\', \'When someone @s you\'],\n'
      '            <String>[\n'
      '              \'incidents\',\n'
      '              \'Incidents\',\n'
      '              \'Every Sev-1, however it was raised\',\n'
      '            ],\n'
      '            <String>[\'digest\', \'Weekly digest\', \'Monday morning, once\'],\n'
      '            <String>[\'marketing\', \'Product news\', \'Roughly monthly\'],\n'
      '          ])\n'
      '            Padding(\n'
      '              padding: const EdgeInsets.all(16),\n'
      '              child: AstryxSwitch(\n'
      '                label: row[1],\n'
      '                description: row[2],\n'
      '                value: _on.contains(row[0]),\n'
      '                labelPosition: AstryxToggleLabelPosition.start,\n'
      '                labelSpacing: AstryxToggleLabelSpacing.spread,\n'
      '                onChanged: (value) => _toggle(row[0], row[1], value: value),\n'
      '              ),\n'
      '            ),\n'
      '        ],\n'
      '      ),\n'
      '    );\n'
      '  }\n'
      '\n'
      '  Widget _appearance() {\n'
      '    return AstryxCard(\n'
      '      child: AstryxSelector<String>(\n'
      '        label: \'Theme\',\n'
      '        description: \'Applies as soon as it is chosen.\',\n'
      '        value: _theme,\n'
      '        onChanged: (value) => setState(() => _theme = value),\n'
      '        options: const <AstryxSelectorOption<String>>[\n'
      '          AstryxSelectorOption(value: \'system\', label: \'Match the system\'),\n'
      '          AstryxSelectorOption(value: \'light\', label: \'Light\'),\n'
      '          AstryxSelectorOption(value: \'dark\', label: \'Dark\'),\n'
      '        ],\n'
      '      ),\n'
      '    );\n'
      '  }\n'
      '\n'
      '  /// The destructive section is a destination of its own here, rather than the\n'
      '  /// bottom of a long page — which is the one thing a sidebar changes about\n'
      '  /// the [SettingsTemplate] shape.\n'
      '  Widget _danger(BuildContext context) {\n'
      '    return AstryxVStack(\n'
      '      gap: AstryxSpacingToken.spacing3,\n'
      '      align: AstryxStackAlign.stretch,\n'
      '      children: <Widget>[\n'
      '        const AstryxBanner(\n'
      '          status: AstryxBannerStatus.warning,\n'
      '          title: \'This cannot be undone after thirty days\',\n'
      '          description:\n'
      '              \'Drafts, saved views and every uploaded asset go with the \'\n'
      '              \'workspace.\',\n'
      '          announce: false,\n'
      '        ),\n'
      '        AstryxCard(\n'
      '          variant: const AstryxCardVariant.palette(AstryxPalette.red),\n'
      '          child: AstryxHStack(\n'
      '            gap: AstryxSpacingToken.spacing3,\n'
      '            justify: AstryxStackJustify.between,\n'
      '            mainAxisSize: MainAxisSize.max,\n'
      '            children: <Widget>[\n'
      '              const Flexible(\n'
      '                child: AstryxText(\n'
      '                  \'Deleting removes the workspace for all eleven members.\',\n'
      '                ),\n'
      '              ),\n'
      '              AstryxButton(\n'
      '                label: \'Delete workspace\',\n'
      '                variant: AstryxButtonVariant.destructive,\n'
      '                onPressed: _confirm.show,\n'
      '              ),\n'
      '            ],\n'
      '          ),\n'
      '        ),\n'
      '        // The button is not the confirmation; the dialog is, and it states\n'
      '        // what is actually lost rather than asking "are you sure?".\n'
      '        AstryxAlertDialog(\n'
      '          controller: _confirm,\n'
      '          title: \'Delete this workspace?\',\n'
      '          description:\n'
      '              \'Eleven members lose access immediately. Everything in the \'\n'
      '              \'workspace is deleted permanently after thirty days.\',\n'
      '          confirmLabel: \'Delete workspace\',\n'
      '          destructive: true,\n'
      '          onConfirm: () => AstryxToastScope.of(context).show(\n'
      '            const AstryxToast(message: \'Workspace scheduled for deletion\'),\n'
      '          ),\n'
      '        ),\n'
      '      ],\n'
      '    );\n'
      '  }\n'
      '\n'
      '  Widget _placeholder(String title) {\n'
      '    return AstryxCard(\n'
      '      child: AstryxText(\n'
      '        \'The \$title section would go here. It is one field of state and a \'\n'
      '        \'`switch` expression away — which is exactly what makes a settings \'\n'
      '        \'area with a rail no harder than one without.\',\n'
      '      ),\n'
      '    );\n'
      '  }\n'
      '}\n'
      '\n'
      '/// The bar above the settings area.\n'
      '///\n'
      '/// Its only job on a wide window is to say where you are. Its job on a narrow\n'
      '/// one is to be the way back to the rail, which has moved into a drawer.\n'
      'class _SettingsBar extends StatelessWidget {\n'
      '  const _SettingsBar({required this.title});\n'
      '\n'
      '  /// The open section, so the bar still says where you are once the rail is\n'
      '  /// behind a button and the selected row is out of sight.\n'
      '  final String title;\n'
      '\n'
      '  @override\n'
      '  Widget build(BuildContext context) {\n'
      '    // The shell knows where the navigation went. A header cannot decide\n'
      '    // whether to draw a menu button without that, which is why it asks rather\n'
      '    // than measuring the window a second time.\n'
      '    final shell = AstryxAppShell.of(context);\n'
      '\n'
      '    return Padding(\n'
      '      padding: const EdgeInsetsDirectional.symmetric(\n'
      '        horizontal: 12,\n'
      '        vertical: 8,\n'
      '      ),\n'
      '      child: AstryxHStack(\n'
      '        gap: AstryxSpacingToken.spacing2,\n'
      '        mainAxisSize: MainAxisSize.max,\n'
      '        children: <Widget>[\n'
      '          if (shell.compact)\n'
      '            const AstryxMobileNavToggle(\n'
      '              label: \'Open the settings sections\',\n'
      '              size: AstryxButtonSize.sm,\n'
      '            ),\n'
      '          const AstryxText(\'Settings\', type: AstryxTextType.label),\n'
      '          if (shell.compact) ...<Widget>[\n'
      '            const AstryxText(\'/\', color: AstryxTextColor.secondary),\n'
      '            Flexible(\n'
      '              child: AstryxText(\n'
      '                title,\n'
      '                color: AstryxTextColor.secondary,\n'
      '                maxLines: 1,\n'
      '              ),\n'
      '            ),\n'
      '          ],\n'
      '        ],\n'
      '      ),\n'
      '    );\n'
      '  }\n'
      '}\n',
  // examples/template_shell_examples.dart
  'template_shell_nav':
      'class ShellNavTemplate extends StatefulWidget {\n'
      '  const ShellNavTemplate({super.key});\n'
      '\n'
      '  @override\n'
      '  State<ShellNavTemplate> createState() => _ShellNavTemplateState();\n'
      '}\n'
      '\n'
      'class _ShellNavTemplateState extends State<ShellNavTemplate> {\n'
      '  /// One list of destinations. The rail and the bar are containers for it.\n'
      '  static const List<AstryxNavEntry> _sections = <AstryxNavEntry>[\n'
      '    AstryxNavItem(\n'
      '      id: \'deploys\',\n'
      '      label: \'Deploys\',\n'
      '      icon: AstryxNavIcon(AstryxIcon(AstryxIconName.arrowUp)),\n'
      '      trailing: AstryxBadge(\'3\'),\n'
      '    ),\n'
      '    AstryxNavItem(\n'
      '      id: \'incidents\',\n'
      '      label: \'Incidents\',\n'
      '      icon: AstryxNavIcon(AstryxIcon(AstryxIconName.warning)),\n'
      '    ),\n'
      '    AstryxNavItem(\n'
      '      id: \'services\',\n'
      '      label: \'Services\',\n'
      '      icon: AstryxNavIcon(AstryxIcon(AstryxIconName.viewColumns)),\n'
      '    ),\n'
      '    AstryxNavDivider(),\n'
      '    AstryxNavSection(\n'
      '      label: \'Workspace\',\n'
      '      items: <AstryxNavItem>[\n'
      '        AstryxNavItem(\n'
      '          id: \'members\',\n'
      '          label: \'Members\',\n'
      '          icon: AstryxNavIcon(AstryxIcon(AstryxIconName.check)),\n'
      '        ),\n'
      '        AstryxNavItem(\n'
      '          id: \'billing\',\n'
      '          label: \'Billing\',\n'
      '          icon: AstryxNavIcon(AstryxIcon(AstryxIconName.clock)),\n'
      '        ),\n'
      '      ],\n'
      '    ),\n'
      '  ];\n'
      '\n'
      '  static const Map<String, String> _titles = <String, String>{\n'
      '    \'deploys\': \'Deploys\',\n'
      '    \'incidents\': \'Incidents\',\n'
      '    \'services\': \'Services\',\n'
      '    \'members\': \'Members\',\n'
      '    \'billing\': \'Billing\',\n'
      '  };\n'
      '\n'
      '  String _section = \'deploys\';\n'
      '  bool _collapsed = false;\n'
      '\n'
      '  @override\n'
      '  Widget build(BuildContext context) {\n'
      '    // Two bars and one content column. The shell decides whether the rail sits\n'
      '    // beside the content or behind a drawer; nothing inside has to know, and\n'
      '    // the header asks when it needs to.\n'
      '    return SizedBox(\n'
      '      height: 520,\n'
      '      child: AstryxAppShell(\n'
      '        compactBelow: 720,\n'
      '        navLabel: \'Sections\',\n'
      '        sidebarWidth: _collapsed ? 72 : 248,\n'
      '        header: _ShellBar(section: _titles[_section]!),\n'
      '        sidebar: AstryxSideNav(\n'
      '          label: \'Sections\',\n'
      '          entries: _sections,\n'
      '          selectedId: _section,\n'
      '          onSelected: (id) => setState(() => _section = id),\n'
      '          collapsed: _collapsed,\n'
      '          onCollapsedChanged: (value) => setState(() => _collapsed = value),\n'
      '          header: AstryxNavHeadingMenu(\n'
      '            label: \'Acme Corp\',\n'
      '            description: \'Production\',\n'
      '            collapsed: _collapsed,\n'
      '            leading: const AstryxNavIcon(\n'
      '              AstryxIcon(AstryxIconName.viewColumns),\n'
      '            ),\n'
      '            entries: <AstryxMenuEntry>[\n'
      '              AstryxMenuItem(label: \'Acme Corp\', onSelected: () {}),\n'
      '              AstryxMenuItem(label: \'Globex\', onSelected: () {}),\n'
      '              const AstryxMenuDivider(),\n'
      '              AstryxMenuItem(label: \'New workspace\', onSelected: () {}),\n'
      '            ],\n'
      '          ),\n'
      '          footer: AstryxItem(\n'
      '            label: \'Ada Lovelace\',\n'
      '            description: _collapsed ? null : \'ada@acme.example\',\n'
      '            leading: const AstryxAvatar(\n'
      '              name: \'Ada Lovelace\',\n'
      '              size: AstryxAvatarSize.sm,\n'
      '            ),\n'
      '            onPressed: () {},\n'
      '          ),\n'
      '        ),\n'
      '        child: AstryxLayout(\n'
      '          header: AstryxVStack(\n'
      '            gap: AstryxSpacingToken.spacing2,\n'
      '            align: AstryxStackAlign.stretch,\n'
      '            children: <Widget>[\n'
      '              AstryxBreadcrumbs(\n'
      '                label: \'You are here\',\n'
      '                items: <AstryxBreadcrumb>[\n'
      '                  AstryxBreadcrumb(label: \'Acme Corp\', onPressed: () {}),\n'
      '                  AstryxBreadcrumb(label: \'Production\', onPressed: () {}),\n'
      '                  AstryxBreadcrumb(label: _titles[_section]!),\n'
      '                ],\n'
      '              ),\n'
      '              AstryxHStack(\n'
      '                gap: AstryxSpacingToken.spacing3,\n'
      '                justify: AstryxStackJustify.between,\n'
      '                mainAxisSize: MainAxisSize.max,\n'
      '                children: <Widget>[\n'
      '                  Flexible(child: AstryxHeading(_titles[_section]!, level: 1)),\n'
      '                  AstryxButton(\n'
      '                    label: \'New deploy\',\n'
      '                    variant: AstryxButtonVariant.primary,\n'
      '                    size: AstryxButtonSize.sm,\n'
      '                    onPressed: () {},\n'
      '                  ),\n'
      '                ],\n'
      '              ),\n'
      '            ],\n'
      '          ),\n'
      '          child: AstryxVStack(\n'
      '            gap: AstryxSpacingToken.spacing4,\n'
      '            align: AstryxStackAlign.stretch,\n'
      '            children: <Widget>[\n'
      '              const AstryxText(\n'
      '                \'Narrow the window past 720 logical pixels and the rail moves \'\n'
      '                \'behind the drawer the menu button opens. Widen it and it \'\n'
      '                \'comes back — the content column is the only thing that \'\n'
      '                \'changes width.\',\n'
      '              ),\n'
      '              for (var i = 0; i < 6; i++)\n'
      '                AstryxCard(\n'
      '                  child: AstryxHStack(\n'
      '                    gap: AstryxSpacingToken.spacing3,\n'
      '                    justify: AstryxStackJustify.between,\n'
      '                    mainAxisSize: MainAxisSize.max,\n'
      '                    children: <Widget>[\n'
      '                      Flexible(\n'
      '                        child: AstryxVStack(\n'
      '                          gap: AstryxSpacingToken.spacing0_5,\n'
      '                          children: <Widget>[\n'
      '                            AstryxText(\n'
      '                              \'\${_titles[_section]} #\${412 - i}\',\n'
      '                              type: AstryxTextType.label,\n'
      '                            ),\n'
      '                            const AstryxText(\n'
      '                              \'main · 11 minutes\',\n'
      '                              type: AstryxTextType.supporting,\n'
      '                              color: AstryxTextColor.secondary,\n'
      '                            ),\n'
      '                          ],\n'
      '                        ),\n'
      '                      ),\n'
      '                      AstryxBadge(\n'
      '                        i == 0 ? \'Live\' : \'Superseded\',\n'
      '                        variant: i == 0\n'
      '                            ? AstryxBadgeVariant.success\n'
      '                            : AstryxBadgeVariant.neutral,\n'
      '                        icon: AstryxIcon(\n'
      '                          i == 0\n'
      '                              ? AstryxIconName.success\n'
      '                              : AstryxIconName.clock,\n'
      '                        ),\n'
      '                      ),\n'
      '                    ],\n'
      '                  ),\n'
      '                ),\n'
      '            ],\n'
      '          ),\n'
      '        ),\n'
      '      ),\n'
      '    );\n'
      '  }\n'
      '}\n'
      '\n'
      '/// The bar across the whole window: identity, global actions, account.\n'
      '///\n'
      '/// It is an `AstryxTopNav` rather than a hand-built row because the tabs in it\n'
      '/// are destinations — and a bar of destinations owns arrow-key traversal, a\n'
      '/// selected state and the overflow behaviour that comes with it.\n'
      'class _ShellBar extends StatelessWidget {\n'
      '  const _ShellBar({required this.section});\n'
      '\n'
      '  final String section;\n'
      '\n'
      '  @override\n'
      '  Widget build(BuildContext context) {\n'
      '    // The shell knows where the navigation went. A header cannot decide whether\n'
      '    // to draw a menu button without that, which is why it asks rather than\n'
      '    // measuring the window a second time.\n'
      '    final shell = AstryxAppShell.of(context);\n'
      '\n'
      '    return AstryxTopNav(\n'
      '      leading: AstryxHStack(\n'
      '        gap: AstryxSpacingToken.spacing2,\n'
      '        children: <Widget>[\n'
      '          if (shell.compact)\n'
      '            AstryxIconButton(\n'
      '              icon: AstryxIconName.menu,\n'
      '              label: \'Open navigation\',\n'
      '              variant: AstryxButtonVariant.ghost,\n'
      '              size: AstryxButtonSize.sm,\n'
      '              onPressed: shell.controller.toggle,\n'
      '            ),\n'
      '          const AstryxText(\'Atlas\', type: AstryxTextType.label),\n'
      '        ],\n'
      '      ),\n'
      '      entries: <AstryxNavEntry>[\n'
      '        const AstryxNavItem(id: \'app\', label: \'Application\'),\n'
      '        AstryxNavItem(\n'
      '          id: \'docs\',\n'
      '          label: \'Docs\',\n'
      '          panel: AstryxCard(\n'
      '            child: AstryxVStack(\n'
      '              gap: AstryxSpacingToken.spacing2,\n'
      '              align: AstryxStackAlign.stretch,\n'
      '              children: <Widget>[\n'
      '                const AstryxHeading(\'Guides\', level: 3),\n'
      '                AstryxItem(label: \'Getting started\', onPressed: () {}),\n'
      '                AstryxItem(label: \'Deploy pipelines\', onPressed: () {}),\n'
      '                AstryxItem(label: \'On-call rotations\', onPressed: () {}),\n'
      '              ],\n'
      '            ),\n'
      '          ),\n'
      '        ),\n'
      '        const AstryxNavItem(id: \'status\', label: \'Status\'),\n'
      '      ],\n'
      '      selectedId: \'app\',\n'
      '      onSelected: (_) {},\n'
      '      actions: <Widget>[\n'
      '        AstryxIconButton(\n'
      '          icon: AstryxIconName.search,\n'
      '          label: \'Search\',\n'
      '          tooltip: \'Search\',\n'
      '          variant: AstryxButtonVariant.ghost,\n'
      '          size: AstryxButtonSize.sm,\n'
      '          onPressed: () {},\n'
      '        ),\n'
      '        AstryxDropdownMenu(\n'
      '          label: \'Account\',\n'
      '          width: 200,\n'
      '          entries: <AstryxMenuEntry>[\n'
      '            const AstryxMenuSection(\'ada@acme.example\'),\n'
      '            AstryxMenuItem(label: \'Preferences\', onSelected: () {}),\n'
      '            AstryxMenuItem(label: \'Sign out\', onSelected: () {}),\n'
      '          ],\n'
      '          triggerBuilder: (context, controller) => AstryxAvatar(\n'
      '            name: \'Ada Lovelace\',\n'
      '            size: AstryxAvatarSize.sm,\n'
      '            semanticsLabel: \'Account — Ada Lovelace\',\n'
      '            onPressed: controller.toggle,\n'
      '          ),\n'
      '        ),\n'
      '      ],\n'
      '    );\n'
      '  }\n'
      '}\n',
  // examples/template_shell_examples.dart
  'template_documentation':
      'class DocumentationTemplate extends StatefulWidget {\n'
      '  const DocumentationTemplate({super.key});\n'
      '\n'
      '  @override\n'
      '  State<DocumentationTemplate> createState() => _DocumentationTemplateState();\n'
      '}\n'
      '\n'
      'class _DocumentationTemplateState extends State<DocumentationTemplate> {\n'
      '  /// One heading per section, in the order they appear on the page.\n'
      '  static const List<({String id, String title, String body})> _sections =\n'
      '      <({String id, String title, String body})>[\n'
      '        (\n'
      '          id: \'install\',\n'
      '          title: \'Install\',\n'
      '          body:\n'
      '              \'Add the package, then wrap the application once. Everything \'\n'
      '              \'else — the theme, the icons, the localisations, the toast host \'\n'
      '              \'— is installed by that one widget.\',\n'
      '        ),\n'
      '        (\n'
      '          id: \'configure\',\n'
      '          title: \'Configure\',\n'
      '          body:\n'
      '              \'A pipeline is a file in the repository, not a form in a web \'\n'
      '              \'application. The file is the source of truth and the screen is \'\n'
      '              \'a view of it, which is why every field here is read-only until \'\n'
      '              \'you take the lock.\',\n'
      '        ),\n'
      '        (\n'
      '          id: \'deploy\',\n'
      '          title: \'Deploy\',\n'
      '          body:\n'
      '              \'A deploy is a request to make the cluster match a commit. It \'\n'
      '              \'is not a script, and nothing about it is ordered by the time \'\n'
      '              \'you pressed the button.\',\n'
      '        ),\n'
      '        (\n'
      '          id: \'rollback\',\n'
      '          title: \'Roll back\',\n'
      '          body:\n'
      '              \'Rolling back is a deploy of the previous commit, which is why \'\n'
      '              \'there is no separate rollback screen: the thing you already \'\n'
      '              \'know how to watch is the thing that runs.\',\n'
      '        ),\n'
      '      ];\n'
      '\n'
      '  /// The scroll view the anchors live in, and the one the outline tracks.\n'
      '  final ScrollController _scroll = ScrollController();\n'
      '\n'
      '  /// A key on each section\'s heading, so the outline has somewhere to scroll.\n'
      '  final Map<String, GlobalKey> _anchors = <String, GlobalKey>{\n'
      '    for (final section in _sections) section.id: GlobalKey(),\n'
      '  };\n'
      '\n'
      '  String _page = \'deploys\';\n'
      '\n'
      '  @override\n'
      '  void dispose() {\n'
      '    _scroll.dispose();\n'
      '    super.dispose();\n'
      '  }\n'
      '\n'
      '  @override\n'
      '  Widget build(BuildContext context) {\n'
      '    // Three columns: the rail says where you are in the site, the outline says\n'
      '    // where you are on the page, and the body is the only one that scrolls\n'
      '    // under either of them.\n'
      '    return SizedBox(\n'
      '      height: 520,\n'
      '      child: AstryxAppShell(\n'
      '        compactBelow: 840,\n'
      '        navLabel: \'Documentation\',\n'
      '        sidebarWidth: 232,\n'
      '        header: const _DocsBar(),\n'
      '        sidebar: AstryxSideNav(\n'
      '          label: \'Documentation\',\n'
      '          selectedId: _page,\n'
      '          onSelected: (id) => setState(() => _page = id),\n'
      '          entries: const <AstryxNavEntry>[\n'
      '            AstryxNavSection(\n'
      '              label: \'Getting started\',\n'
      '              items: <AstryxNavItem>[\n'
      '                AstryxNavItem(id: \'install\', label: \'Installation\'),\n'
      '                AstryxNavItem(id: \'concepts\', label: \'Concepts\'),\n'
      '              ],\n'
      '            ),\n'
      '            AstryxNavSection(\n'
      '              label: \'Guides\',\n'
      '              items: <AstryxNavItem>[\n'
      '                AstryxNavItem(id: \'deploys\', label: \'Deploys\'),\n'
      '                AstryxNavItem(id: \'rollbacks\', label: \'Rollbacks\'),\n'
      '                AstryxNavItem(id: \'oncall\', label: \'On-call\'),\n'
      '              ],\n'
      '            ),\n'
      '          ],\n'
      '        ),\n'
      '        child: AstryxLayout(\n'
      '          // The outline needs the body\'s scroll position, and the body\'s\n'
      '          // scroll view belongs to the layout — so the controller is handed in\n'
      '          // rather than invented here.\n'
      '          scrollController: _scroll,\n'
      '          maxContentWidth: 720,\n'
      '          panelWidth: 200,\n'
      '          header: AstryxBreadcrumbs(\n'
      '            label: \'You are here\',\n'
      '            items: <AstryxBreadcrumb>[\n'
      '              AstryxBreadcrumb(label: \'Docs\', onPressed: () {}),\n'
      '              AstryxBreadcrumb(label: \'Guides\', onPressed: () {}),\n'
      '              const AstryxBreadcrumb(label: \'Deploys\'),\n'
      '            ],\n'
      '          ),\n'
      '          panel: AstryxOutline(\n'
      '            label: \'On this page\',\n'
      '            controller: _scroll,\n'
      '            entries: <AstryxOutlineEntry>[\n'
      '              for (final section in _sections)\n'
      '                AstryxOutlineEntry(\n'
      '                  id: section.id,\n'
      '                  label: section.title,\n'
      '                  anchor: _anchors[section.id],\n'
      '                ),\n'
      '            ],\n'
      '          ),\n'
      '          footer: AstryxHStack(\n'
      '            gap: AstryxSpacingToken.spacing3,\n'
      '            justify: AstryxStackJustify.between,\n'
      '            mainAxisSize: MainAxisSize.max,\n'
      '            // Two pagers whose labels are page titles, and page titles are as\n'
      '            // long as they are. Narrow, they take a line each — the chevrons\n'
      '            // still say which way each one goes.\n'
      '            wrap: true,\n'
      '            runGap: AstryxSpacingToken.spacing2,\n'
      '            children: <Widget>[\n'
      '              AstryxButton(\n'
      '                label: \'Concepts\',\n'
      '                variant: AstryxButtonVariant.ghost,\n'
      '                size: AstryxButtonSize.sm,\n'
      '                leading: const AstryxIcon(\n'
      '                  AstryxIconName.chevronLeft,\n'
      '                  size: AstryxIconSize.sm,\n'
      '                ),\n'
      '                onPressed: () {},\n'
      '              ),\n'
      '              AstryxButton(\n'
      '                label: \'Rollbacks\',\n'
      '                variant: AstryxButtonVariant.ghost,\n'
      '                size: AstryxButtonSize.sm,\n'
      '                trailing: const AstryxIcon(\n'
      '                  AstryxIconName.chevronRight,\n'
      '                  size: AstryxIconSize.sm,\n'
      '                ),\n'
      '                onPressed: () {},\n'
      '              ),\n'
      '            ],\n'
      '          ),\n'
      '          child: AstryxVStack(\n'
      '            gap: AstryxSpacingToken.spacing6,\n'
      '            align: AstryxStackAlign.stretch,\n'
      '            children: <Widget>[\n'
      '              const AstryxVStack(\n'
      '                gap: AstryxSpacingToken.spacing3,\n'
      '                align: AstryxStackAlign.stretch,\n'
      '                children: <Widget>[\n'
      '                  AstryxHeading(\'Deploys\', level: 1),\n'
      '                  AstryxText(\n'
      '                    \'What a deploy is, how to start one, and what to do when \'\n'
      '                    \'it goes wrong.\',\n'
      '                    type: AstryxTextType.large,\n'
      '                    color: AstryxTextColor.secondary,\n'
      '                  ),\n'
      '                ],\n'
      '              ),\n'
      '              const AstryxBanner(\n'
      '                title: \'This guide covers Atlas 4\',\n'
      '                description: \'Atlas 3 pipelines are configured in the console.\',\n'
      '                announce: false,\n'
      '              ),\n'
      '              for (final section in _sections)\n'
      '                AstryxSection(\n'
      '                  title: section.title,\n'
      '                  headerKey: _anchors[section.id],\n'
      '                  child: AstryxVStack(\n'
      '                    gap: AstryxSpacingToken.spacing3,\n'
      '                    align: AstryxStackAlign.stretch,\n'
      '                    children: <Widget>[\n'
      '                      AstryxText(section.body),\n'
      '                      if (section.id == \'install\')\n'
      '                        const AstryxCodeBlock(\n'
      '                          \'dart pub add astryx_ui\',\n'
      '                          language: \'bash\',\n'
      '                        )\n'
      '                      else\n'
      '                        Text.rich(\n'
      '                          TextSpan(\n'
      '                            children: <InlineSpan>[\n'
      '                              const TextSpan(text: \'Run \'),\n'
      '                              AstryxCode.span(\'atlas \${section.id}\'),\n'
      '                              const TextSpan(text: \', or see \'),\n'
      '                              AstryxLink.span(\n'
      '                                \'the reference\',\n'
      '                                onPressed: () {},\n'
      '                              ),\n'
      '                              const TextSpan(text: \' for every flag.\'),\n'
      '                            ],\n'
      '                          ),\n'
      '                        ),\n'
      '                    ],\n'
      '                  ),\n'
      '                ),\n'
      '            ],\n'
      '          ),\n'
      '        ),\n'
      '      ),\n'
      '    );\n'
      '  }\n'
      '}\n'
      '\n'
      '/// The bar above a documentation site: identity, search, version.\n'
      'class _DocsBar extends StatelessWidget {\n'
      '  const _DocsBar();\n'
      '\n'
      '  @override\n'
      '  Widget build(BuildContext context) {\n'
      '    final shell = AstryxAppShell.of(context);\n'
      '\n'
      '    return Padding(\n'
      '      padding: const EdgeInsetsDirectional.symmetric(\n'
      '        horizontal: 12,\n'
      '        vertical: 8,\n'
      '      ),\n'
      '      child: AstryxHStack(\n'
      '        gap: AstryxSpacingToken.spacing3,\n'
      '        mainAxisSize: MainAxisSize.max,\n'
      '        children: <Widget>[\n'
      '          if (shell.compact)\n'
      '            AstryxIconButton(\n'
      '              icon: AstryxIconName.menu,\n'
      '              label: \'Open documentation navigation\',\n'
      '              variant: AstryxButtonVariant.ghost,\n'
      '              size: AstryxButtonSize.sm,\n'
      '              onPressed: shell.controller.toggle,\n'
      '            ),\n'
      '          const Flexible(\n'
      '            child: AstryxText(\n'
      '              \'Atlas docs\',\n'
      '              type: AstryxTextType.label,\n'
      '              maxLines: 1,\n'
      '            ),\n'
      '          ),\n'
      '          const Spacer(),\n'
      '          // A phone has no keyboard to press ⌘K on and no room for the cap\n'
      '          // that says so, so the search collapses to its glyph. The name it is\n'
      '          // announced by does not collapse with it — an icon button with no\n'
      '          // label is a button screen readers call "button".\n'
      '          if (shell.compact)\n'
      '            AstryxIconButton(\n'
      '              icon: AstryxIconName.search,\n'
      '              label: \'Search the documentation\',\n'
      '              tooltip: \'Search\',\n'
      '              variant: AstryxButtonVariant.ghost,\n'
      '              size: AstryxButtonSize.sm,\n'
      '              onPressed: () {},\n'
      '            )\n'
      '          else ...<Widget>[\n'
      '            AstryxButton(\n'
      '              label: \'Search\',\n'
      '              size: AstryxButtonSize.sm,\n'
      '              leading: const AstryxIcon(\n'
      '                AstryxIconName.search,\n'
      '                size: AstryxIconSize.sm,\n'
      '              ),\n'
      '              // `mod` is ⌘ on a Mac and Ctrl everywhere else, and the cap says\n'
      '              // whichever one this platform actually listens for.\n'
      '              trailing: const AstryxKbd.hotkey(\n'
      '                AstryxHotkey.mod(LogicalKeyboardKey.keyK),\n'
      '                size: AstryxKbdSize.sm,\n'
      '              ),\n'
      '              onPressed: () {},\n'
      '            ),\n'
      '            const AstryxBadge(\'v4.2\'),\n'
      '          ],\n'
      '        ],\n'
      '      ),\n'
      '    );\n'
      '  }\n'
      '}\n',
  // examples/template_shell_variant_examples.dart
  'template_shell_side_nav':
      'class ShellSideNavTemplate extends StatefulWidget {\n'
      '  const ShellSideNavTemplate({super.key});\n'
      '\n'
      '  @override\n'
      '  State<ShellSideNavTemplate> createState() => _ShellSideNavTemplateState();\n'
      '}\n'
      '\n'
      'class _ShellSideNavTemplateState extends State<ShellSideNavTemplate> {\n'
      '  /// Every destination in the product, down one column.\n'
      '  ///\n'
      '  /// A rail is the right container when the list is long enough to need\n'
      '  /// headings, or deep enough to need indenting — both of which a bar has no\n'
      '  /// room for. `children` here are indented rows; on an `AstryxTopNav` the same\n'
      '  /// list would be a menu.\n'
      '  static const List<AstryxNavEntry> _entries = <AstryxNavEntry>[\n'
      '    AstryxNavItem(\n'
      '      id: \'overview\',\n'
      '      label: \'Overview\',\n'
      '      icon: AstryxNavIcon(AstryxIcon(AstryxIconName.viewColumns)),\n'
      '    ),\n'
      '    AstryxNavItem(\n'
      '      id: \'runs\',\n'
      '      label: \'Runs\',\n'
      '      icon: AstryxNavIcon(AstryxIcon(AstryxIconName.arrowUp)),\n'
      '      trailing: AstryxBadge(\'12\'),\n'
      '      children: <AstryxNavItem>[\n'
      '        AstryxNavItem(id: \'runs_queued\', label: \'Queued\'),\n'
      '        AstryxNavItem(id: \'runs_failed\', label: \'Failed\'),\n'
      '      ],\n'
      '    ),\n'
      '    AstryxNavItem(\n'
      '      id: \'artifacts\',\n'
      '      label: \'Artifacts\',\n'
      '      icon: AstryxNavIcon(AstryxIcon(AstryxIconName.copy)),\n'
      '    ),\n'
      '    AstryxNavDivider(),\n'
      '    AstryxNavSection(\n'
      '      label: \'Configuration\',\n'
      '      items: <AstryxNavItem>[\n'
      '        AstryxNavItem(\n'
      '          id: \'triggers\',\n'
      '          label: \'Triggers\',\n'
      '          icon: AstryxNavIcon(AstryxIcon(AstryxIconName.clock)),\n'
      '        ),\n'
      '        AstryxNavItem(\n'
      '          id: \'secrets\',\n'
      '          label: \'Secrets\',\n'
      '          icon: AstryxNavIcon(AstryxIcon(AstryxIconName.eyeSlash)),\n'
      '        ),\n'
      '      ],\n'
      '    ),\n'
      '  ];\n'
      '\n'
      '  static const Map<String, String> _titles = <String, String>{\n'
      '    \'overview\': \'Overview\',\n'
      '    \'runs\': \'Runs\',\n'
      '    \'runs_queued\': \'Queued runs\',\n'
      '    \'runs_failed\': \'Failed runs\',\n'
      '    \'artifacts\': \'Artifacts\',\n'
      '    \'triggers\': \'Triggers\',\n'
      '    \'secrets\': \'Secrets\',\n'
      '  };\n'
      '\n'
      '  String _section = \'runs\';\n'
      '  bool _collapsed = false;\n'
      '\n'
      '  @override\n'
      '  Widget build(BuildContext context) {\n'
      '    final title = _titles[_section]!;\n'
      '\n'
      '    // No `header:` on the shell at all. Everything a bar would have carried is\n'
      '    // in the rail — identity at the top, the account at the bottom — because a\n'
      '    // full-width band holding only a logo is a band spent on nothing.\n'
      '    return SizedBox(\n'
      '      height: 520,\n'
      '      child: AstryxAppShell(\n'
      '        compactBelow: 680,\n'
      '        navLabel: \'Sections\',\n'
      '        sidebarWidth: _collapsed ? 72 : 244,\n'
      '        sidebar: AstryxSideNav(\n'
      '          label: \'Sections\',\n'
      '          entries: _entries,\n'
      '          selectedId: _section,\n'
      '          onSelected: (id) => setState(() => _section = id),\n'
      '          collapsed: _collapsed,\n'
      '          onCollapsedChanged: (value) => setState(() => _collapsed = value),\n'
      '          header: AstryxNavHeadingMenu(\n'
      '            label: \'Foundry\',\n'
      '            description: \'acme/platform\',\n'
      '            collapsed: _collapsed,\n'
      '            leading: const AstryxNavIcon(AstryxIcon(AstryxIconName.wrench)),\n'
      '            entries: <AstryxMenuEntry>[\n'
      '              AstryxMenuItem(label: \'acme/platform\', onSelected: () {}),\n'
      '              AstryxMenuItem(label: \'acme/website\', onSelected: () {}),\n'
      '              const AstryxMenuDivider(),\n'
      '              AstryxMenuItem(label: \'New project\', onSelected: () {}),\n'
      '            ],\n'
      '          ),\n'
      '          footer: AstryxItem(\n'
      '            label: \'Grace Hopper\',\n'
      '            description: _collapsed ? null : \'grace@acme.example\',\n'
      '            leading: const AstryxAvatar(\n'
      '              name: \'Grace Hopper\',\n'
      '              size: AstryxAvatarSize.sm,\n'
      '            ),\n'
      '            onPressed: () {},\n'
      '          ),\n'
      '        ),\n'
      '        child: AstryxLayout(\n'
      '          header: _PageHeader(title: title),\n'
      '          child: AstryxVStack(\n'
      '            gap: AstryxSpacingToken.spacing3,\n'
      '            align: AstryxStackAlign.stretch,\n'
      '            children: <Widget>[\n'
      '              const AstryxText(\n'
      '                \'One bar, and it is vertical. Collapse the rail with the \'\n'
      '                \'control below the account row, or narrow the window past 680 \'\n'
      '                \'logical pixels to send it behind the drawer the menu button \'\n'
      '                \'in this page header opens.\',\n'
      '              ),\n'
      '              for (var i = 0; i < 7; i++)\n'
      '                AstryxCard(\n'
      '                  padding: AstryxSpacingToken.spacing3,\n'
      '                  child: AstryxHStack(\n'
      '                    gap: AstryxSpacingToken.spacing3,\n'
      '                    justify: AstryxStackJustify.between,\n'
      '                    mainAxisSize: MainAxisSize.max,\n'
      '                    children: <Widget>[\n'
      '                      Flexible(\n'
      '                        child: AstryxText(\n'
      '                          \'\$title · job \${920 - i}\',\n'
      '                          maxLines: 1,\n'
      '                        ),\n'
      '                      ),\n'
      '                      AstryxBadge(\n'
      '                        i.isEven ? \'Passed\' : \'Queued\',\n'
      '                        variant: i.isEven\n'
      '                            ? AstryxBadgeVariant.success\n'
      '                            : AstryxBadgeVariant.neutral,\n'
      '                        icon: AstryxIcon(\n'
      '                          i.isEven\n'
      '                              ? AstryxIconName.success\n'
      '                              : AstryxIconName.clock,\n'
      '                        ),\n'
      '                      ),\n'
      '                    ],\n'
      '                  ),\n'
      '                ),\n'
      '            ],\n'
      '          ),\n'
      '        ),\n'
      '      ),\n'
      '    );\n'
      '  }\n'
      '}\n'
      '\n'
      '/// The page\'s own header — which is where the drawer toggle has to live when\n'
      '/// the shell has no header of its own.\n'
      'class _PageHeader extends StatelessWidget {\n'
      '  const _PageHeader({required this.title});\n'
      '\n'
      '  final String title;\n'
      '\n'
      '  @override\n'
      '  Widget build(BuildContext context) {\n'
      '    // `AstryxMobileNavToggle` with no `controller` reaches for the enclosing\n'
      '    // shell\'s, so this row does not have to know that a drawer exists — only\n'
      '    // that the shell is compact, which is the shell\'s answer to give.\n'
      '    final shell = AstryxAppShell.of(context);\n'
      '\n'
      '    return AstryxHStack(\n'
      '      gap: AstryxSpacingToken.spacing3,\n'
      '      justify: AstryxStackJustify.between,\n'
      '      mainAxisSize: MainAxisSize.max,\n'
      '      children: <Widget>[\n'
      '        Flexible(\n'
      '          child: AstryxHStack(\n'
      '            gap: AstryxSpacingToken.spacing2,\n'
      '            children: <Widget>[\n'
      '              if (shell.compact)\n'
      '                const AstryxMobileNavToggle(\n'
      '                  label: \'Open navigation\',\n'
      '                  size: AstryxButtonSize.sm,\n'
      '                ),\n'
      '              Flexible(child: AstryxHeading(title, level: 1)),\n'
      '            ],\n'
      '          ),\n'
      '        ),\n'
      '        AstryxButton(\n'
      '          label: \'Run pipeline\',\n'
      '          variant: AstryxButtonVariant.primary,\n'
      '          size: AstryxButtonSize.sm,\n'
      '          onPressed: () {},\n'
      '        ),\n'
      '      ],\n'
      '    );\n'
      '  }\n'
      '}\n',
  // examples/template_shell_variant_examples.dart
  'template_shell_top_nav':
      'class ShellTopNavTemplate extends StatefulWidget {\n'
      '  const ShellTopNavTemplate({super.key});\n'
      '\n'
      '  @override\n'
      '  State<ShellTopNavTemplate> createState() => _ShellTopNavTemplateState();\n'
      '}\n'
      '\n'
      'class _ShellTopNavTemplateState extends State<ShellTopNavTemplate> {\n'
      '  /// The same entry type as the rail, laid along a row.\n'
      '  ///\n'
      '  /// A section becomes a *menu* here rather than a heading: a bar has no room\n'
      '  /// for a label over a group, and a menu is exactly what holds one.\n'
      '  static const List<AstryxNavEntry> _entries = <AstryxNavEntry>[\n'
      '    AstryxNavItem(id: \'inbox\', label: \'Inbox\', trailing: AstryxBadge(\'4\')),\n'
      '    AstryxNavItem(id: \'reports\', label: \'Reports\'),\n'
      '    AstryxNavSection(\n'
      '      label: \'Admin\',\n'
      '      items: <AstryxNavItem>[\n'
      '        AstryxNavItem(id: \'members\', label: \'Members\'),\n'
      '        AstryxNavItem(id: \'audit\', label: \'Audit log\'),\n'
      '        AstryxNavItem(id: \'billing\', label: \'Billing\'),\n'
      '      ],\n'
      '    ),\n'
      '  ];\n'
      '\n'
      '  static const Map<String, String> _titles = <String, String>{\n'
      '    \'inbox\': \'Inbox\',\n'
      '    \'reports\': \'Reports\',\n'
      '    \'members\': \'Members\',\n'
      '    \'audit\': \'Audit log\',\n'
      '    \'billing\': \'Billing\',\n'
      '  };\n'
      '\n'
      '  String _section = \'inbox\';\n'
      '\n'
      '  @override\n'
      '  Widget build(BuildContext context) {\n'
      '    final title = _titles[_section] ?? \'Inbox\';\n'
      '\n'
      '    // No `sidebar:`, so there is no drawer and `compactBelow` has nothing to\n'
      '    // do — the bar scrolls its own destinations sideways when the window is\n'
      '    // too narrow for them, and the actions stay pinned at the trailing edge.\n'
      '    return SizedBox(\n'
      '      height: 480,\n'
      '      child: AstryxAppShell(\n'
      '        header: AstryxTopNav(\n'
      '          label: \'Areas\',\n'
      '          leading: const AstryxHStack(\n'
      '            gap: AstryxSpacingToken.spacing2,\n'
      '            children: <Widget>[\n'
      '              AstryxNavIcon(AstryxIcon(AstryxIconName.checkDouble)),\n'
      '              AstryxText(\'Ledger\', type: AstryxTextType.label),\n'
      '            ],\n'
      '          ),\n'
      '          entries: _entries,\n'
      '          selectedId: _section,\n'
      '          onSelected: (id) => setState(() => _section = id),\n'
      '          actions: <Widget>[\n'
      '            AstryxIconButton(\n'
      '              icon: AstryxIconName.search,\n'
      '              label: \'Search\',\n'
      '              tooltip: \'Search\',\n'
      '              variant: AstryxButtonVariant.ghost,\n'
      '              size: AstryxButtonSize.sm,\n'
      '              onPressed: () {},\n'
      '            ),\n'
      '            AstryxDropdownMenu(\n'
      '              label: \'Account\',\n'
      '              width: 220,\n'
      '              entries: <AstryxMenuEntry>[\n'
      '                const AstryxMenuSection(\'grace@acme.example\'),\n'
      '                AstryxMenuItem(label: \'Preferences\', onSelected: () {}),\n'
      '                AstryxMenuItem(label: \'Sign out\', onSelected: () {}),\n'
      '              ],\n'
      '              triggerBuilder: (context, controller) => AstryxAvatar(\n'
      '                name: \'Grace Hopper\',\n'
      '                size: AstryxAvatarSize.sm,\n'
      '                semanticsLabel: \'Account — Grace Hopper\',\n'
      '                onPressed: controller.toggle,\n'
      '              ),\n'
      '            ),\n'
      '          ],\n'
      '        ),\n'
      '        child: AstryxLayout(\n'
      '          maxContentWidth: 900,\n'
      '          header: AstryxHStack(\n'
      '            gap: AstryxSpacingToken.spacing3,\n'
      '            justify: AstryxStackJustify.between,\n'
      '            mainAxisSize: MainAxisSize.max,\n'
      '            children: <Widget>[\n'
      '              Flexible(child: AstryxHeading(title, level: 1)),\n'
      '              AstryxButton(\n'
      '                label: \'New entry\',\n'
      '                variant: AstryxButtonVariant.primary,\n'
      '                size: AstryxButtonSize.sm,\n'
      '                onPressed: () {},\n'
      '              ),\n'
      '            ],\n'
      '          ),\n'
      '          child: AstryxVStack(\n'
      '            gap: AstryxSpacingToken.spacing4,\n'
      '            align: AstryxStackAlign.stretch,\n'
      '            children: <Widget>[\n'
      '              const AstryxText(\n'
      '                \'Five destinations and no rail. Narrow the window and the bar \'\n'
      '                \'scrolls its destinations rather than dropping them: nothing \'\n'
      '                \'moves behind a drawer, because there is no drawer to move it \'\n'
      '                \'into.\',\n'
      '              ),\n'
      '              // A second level of navigation, inside the page rather than\n'
      '              // beside it. This is the affordance a rail would have carried,\n'
      '              // and it is a tab strip because these are views of one thing\n'
      '              // rather than places in the product.\n'
      '              AstryxTabList<String>(\n'
      '                label: \'\$title views\',\n'
      '                value: \'open\',\n'
      '                onChanged: (_) {},\n'
      '                tabs: const <AstryxTab<String>>[\n'
      '                  AstryxTab(value: \'open\', label: \'Open\'),\n'
      '                  AstryxTab(\n'
      '                    value: \'waiting\',\n'
      '                    label: \'Waiting\',\n'
      '                    badge: AstryxBadge(\'2\'),\n'
      '                  ),\n'
      '                  AstryxTab(value: \'done\', label: \'Done\'),\n'
      '                ],\n'
      '              ),\n'
      '              AstryxList(\n'
      '                label: title,\n'
      '                showDividers: true,\n'
      '                children: <Widget>[\n'
      '                  for (final entry in const <List<String>>[\n'
      '                    <String>[\'Invoice 8841\', \'Northwind · £4,800.00\'],\n'
      '                    <String>[\'Invoice 8840\', \'Contoso · £192.00\'],\n'
      '                    <String>[\'Invoice 8839\', \'Initech · £1,250.00\'],\n'
      '                    <String>[\'Invoice 8838\', \'Umbrella · £640.00\'],\n'
      '                  ])\n'
      '                    AstryxItem(\n'
      '                      label: entry[0],\n'
      '                      description: entry[1],\n'
      '                      leading: const AstryxIcon(AstryxIconName.copy),\n'
      '                      trailing: const AstryxIcon(AstryxIconName.chevronRight),\n'
      '                      onPressed: () {},\n'
      '                    ),\n'
      '                ],\n'
      '              ),\n'
      '            ],\n'
      '          ),\n'
      '        ),\n'
      '      ),\n'
      '    );\n'
      '  }\n'
      '}\n',
  // examples/template_split_examples.dart
  'template_library':
      '/// One asset in the library.\n'
      'typedef Asset = ({\n'
      '  String id,\n'
      '  String name,\n'
      '  String collection,\n'
      '  String kind,\n'
      '  String size,\n'
      '  String added,\n'
      '});\n'
      '\n'
      'class LibraryTemplate extends StatefulWidget {\n'
      '  const LibraryTemplate({super.key});\n'
      '\n'
      '  @override\n'
      '  State<LibraryTemplate> createState() => _LibraryTemplateState();\n'
      '}\n'
      '\n'
      'class _LibraryTemplateState extends State<LibraryTemplate> {\n'
      '  static const List<Asset> _assets = <Asset>[\n'
      '    (\n'
      '      id: \'a1\',\n'
      '      name: \'Runbook cover\',\n'
      '      collection: \'Brand\',\n'
      '      kind: \'Image\',\n'
      '      size: \'2.4 MB\',\n'
      '      added: \'11 minutes ago\',\n'
      '    ),\n'
      '    (\n'
      '      id: \'a2\',\n'
      '      name: \'Wordmark, dark\',\n'
      '      collection: \'Brand\',\n'
      '      kind: \'Vector\',\n'
      '      size: \'18 kB\',\n'
      '      added: \'Yesterday\',\n'
      '    ),\n'
      '    (\n'
      '      id: \'a3\',\n'
      '      name: \'Incident 4102 timeline\',\n'
      '      collection: \'Incidents\',\n'
      '      kind: \'Image\',\n'
      '      size: \'5.1 MB\',\n'
      '      added: \'2 days ago\',\n'
      '    ),\n'
      '    (\n'
      '      id: \'a4\',\n'
      '      name: \'Scheduler diagram\',\n'
      '      collection: \'Architecture\',\n'
      '      kind: \'Vector\',\n'
      '      size: \'96 kB\',\n'
      '      added: \'2 days ago\',\n'
      '    ),\n'
      '    (\n'
      '      id: \'a5\',\n'
      '      name: \'Fleet map\',\n'
      '      collection: \'Architecture\',\n'
      '      kind: \'Image\',\n'
      '      size: \'3.8 MB\',\n'
      '      added: \'Last week\',\n'
      '    ),\n'
      '    (\n'
      '      id: \'a6\',\n'
      '      name: \'On-call rota, Q3\',\n'
      '      collection: \'Operations\',\n'
      '      kind: \'Document\',\n'
      '      size: \'212 kB\',\n'
      '      added: \'Last week\',\n'
      '    ),\n'
      '    (\n'
      '      id: \'a7\',\n'
      '      name: \'Post-mortem template\',\n'
      '      collection: \'Operations\',\n'
      '      kind: \'Document\',\n'
      '      size: \'44 kB\',\n'
      '      added: \'Last month\',\n'
      '    ),\n'
      '  ];\n'
      '\n'
      '  final TextEditingController _query = TextEditingController();\n'
      '\n'
      '  Set<String> _kinds = <String>{};\n'
      '  String _collection = \'All\';\n'
      '  String _view = \'grid\';\n'
      '  final Set<Object> _selected = <Object>{};\n'
      '\n'
      '  @override\n'
      '  void initState() {\n'
      '    super.initState();\n'
      '    _query.addListener(() => setState(() {}));\n'
      '  }\n'
      '\n'
      '  @override\n'
      '  void dispose() {\n'
      '    _query.dispose();\n'
      '    super.dispose();\n'
      '  }\n'
      '\n'
      '  /// Narrowed in the caller, so an empty result can say which of the two\n'
      '  /// nothings it is: nothing matched, or nothing here yet.\n'
      '  List<Asset> get _shown {\n'
      '    final text = _query.text.trim().toLowerCase();\n'
      '    return _assets\n'
      '        .where(\n'
      '          (asset) =>\n'
      '              (_collection == \'All\' || asset.collection == _collection) &&\n'
      '              (_kinds.isEmpty || _kinds.contains(asset.kind)) &&\n'
      '              (text.isEmpty || asset.name.toLowerCase().contains(text)),\n'
      '        )\n'
      '        .toList();\n'
      '  }\n'
      '\n'
      '  /// How many assets a collection holds, for the count beside its row.\n'
      '  int _countIn(String collection) => collection == \'All\'\n'
      '      ? _assets.length\n'
      '      : _assets.where((asset) => asset.collection == collection).length;\n'
      '\n'
      '  void _toggle(String id, {required bool selected}) => setState(() {\n'
      '    if (selected) {\n'
      '      _selected.add(id);\n'
      '    } else {\n'
      '      _selected.remove(id);\n'
      '    }\n'
      '  });\n'
      '\n'
      '  @override\n'
      '  Widget build(BuildContext context) {\n'
      '    final shown = _shown;\n'
      '\n'
      '    return SizedBox(\n'
      '      height: 620,\n'
      '      child: AstryxLayout(\n'
      '        panelSide: AstryxLayoutPanelSide.start,\n'
      '        panelWidth: 210,\n'
      '        header: AstryxVStack(\n'
      '          gap: AstryxSpacingToken.spacing3,\n'
      '          align: AstryxStackAlign.stretch,\n'
      '          children: <Widget>[\n'
      '            AstryxHStack(\n'
      '              gap: AstryxSpacingToken.spacing3,\n'
      '              justify: AstryxStackJustify.between,\n'
      '              mainAxisSize: MainAxisSize.max,\n'
      '              wrap: true,\n'
      '              runGap: AstryxSpacingToken.spacing2,\n'
      '              children: <Widget>[\n'
      '                AstryxVStack(\n'
      '                  gap: AstryxSpacingToken.spacing1,\n'
      '                  children: <Widget>[\n'
      '                    const AstryxHeading(\'Library\', level: 1),\n'
      '                    AstryxText(\n'
      '                      \'\${shown.length} of \${_assets.length} assets\',\n'
      '                      type: AstryxTextType.supporting,\n'
      '                      color: AstryxTextColor.secondary,\n'
      '                    ),\n'
      '                  ],\n'
      '                ),\n'
      '                AstryxHStack(\n'
      '                  gap: AstryxSpacingToken.spacing2,\n'
      '                  children: <Widget>[\n'
      '                    SizedBox(\n'
      '                      width: 200,\n'
      '                      child: AstryxTextInput(\n'
      '                        controller: _query,\n'
      '                        label: \'Search the library\',\n'
      '                        labelHidden: true,\n'
      '                        placeholder: \'Search\',\n'
      '                        showClear: true,\n'
      '                        size: AstryxInputSize.sm,\n'
      '                        leading: const AstryxIcon(\n'
      '                          AstryxIconName.search,\n'
      '                          size: AstryxIconSize.sm,\n'
      '                        ),\n'
      '                      ),\n'
      '                    ),\n'
      '                    // Two ways of looking at one set, so a segmented control:\n'
      '                    // it announces itself as a radio group, and the arrows\n'
      '                    // both move and choose.\n'
      '                    AstryxSegmentedControl<String>(\n'
      '                      label: \'View\',\n'
      '                      value: _view,\n'
      '                      size: AstryxButtonSize.sm,\n'
      '                      onChanged: (value) => setState(() => _view = value),\n'
      '                      segments: const <AstryxSegment<String>>[\n'
      '                        AstryxSegment(\n'
      '                          value: \'grid\',\n'
      '                          label: \'Grid\',\n'
      '                          labelHidden: true,\n'
      '                          icon: AstryxIcon(AstryxIconName.viewColumns),\n'
      '                        ),\n'
      '                        AstryxSegment(\n'
      '                          value: \'list\',\n'
      '                          label: \'List\',\n'
      '                          labelHidden: true,\n'
      '                          icon: AstryxIcon(AstryxIconName.menu),\n'
      '                        ),\n'
      '                      ],\n'
      '                    ),\n'
      '                  ],\n'
      '                ),\n'
      '              ],\n'
      '            ),\n'
      '            // The selection bar appears only once something is ticked, and it\n'
      '            // says how many. "Delete" with no count is a question nobody can\n'
      '            // answer.\n'
      '            if (_selected.isNotEmpty)\n'
      '              AstryxBanner(\n'
      '                title: \'\${_selected.length} selected\',\n'
      '                announce: false,\n'
      '                actions: <Widget>[\n'
      '                  AstryxButton(\n'
      '                    label: \'Download\',\n'
      '                    size: AstryxButtonSize.sm,\n'
      '                    onPressed: () {},\n'
      '                  ),\n'
      '                  AstryxButton(\n'
      '                    label: \'Remove\',\n'
      '                    variant: AstryxButtonVariant.destructive,\n'
      '                    size: AstryxButtonSize.sm,\n'
      '                    onPressed: () => setState(_selected.clear),\n'
      '                  ),\n'
      '                ],\n'
      '              ),\n'
      '          ],\n'
      '        ),\n'
      '        panel: AstryxVStack(\n'
      '          gap: AstryxSpacingToken.spacing5,\n'
      '          align: AstryxStackAlign.stretch,\n'
      '          children: <Widget>[\n'
      '            AstryxSection(\n'
      '              title: \'Collections\',\n'
      '              level: 2,\n'
      '              child: AstryxList(\n'
      '                label: \'Collections\',\n'
      '                density: AstryxItemDensity.compact,\n'
      '                children: <Widget>[\n'
      '                  for (final collection in const <String>[\n'
      '                    \'All\',\n'
      '                    \'Brand\',\n'
      '                    \'Incidents\',\n'
      '                    \'Architecture\',\n'
      '                    \'Operations\',\n'
      '                  ])\n'
      '                    AstryxItem(\n'
      '                      label: collection,\n'
      '                      selected: _collection == collection,\n'
      '                      trailing: AstryxText(\n'
      '                        \'\${_countIn(collection)}\',\n'
      '                        type: AstryxTextType.supporting,\n'
      '                        color: AstryxTextColor.secondary,\n'
      '                      ),\n'
      '                      onPressed: () => setState(() => _collection = collection),\n'
      '                    ),\n'
      '                ],\n'
      '              ),\n'
      '            ),\n'
      '            const AstryxDivider(),\n'
      '            AstryxCheckboxList<String>(\n'
      '              label: \'Kind\',\n'
      '              values: _kinds,\n'
      '              onChanged: (values) => setState(() => _kinds = values),\n'
      '              options: const <AstryxCheckboxOption<String>>[\n'
      '                AstryxCheckboxOption(value: \'Image\', label: \'Image\'),\n'
      '                AstryxCheckboxOption(value: \'Vector\', label: \'Vector\'),\n'
      '                AstryxCheckboxOption(value: \'Document\', label: \'Document\'),\n'
      '              ],\n'
      '            ),\n'
      '          ],\n'
      '        ),\n'
      '        child: shown.isEmpty\n'
      '            ? AstryxEmptyState(\n'
      '                title: \'Nothing matches\',\n'
      '                description:\n'
      '                    \'Seven assets are still here; the filters are what is \'\n'
      '                    \'hiding them.\',\n'
      '                icon: const AstryxIcon(\n'
      '                  AstryxIconName.funnel,\n'
      '                  size: AstryxIconSize.lg,\n'
      '                ),\n'
      '                actions: <Widget>[\n'
      '                  AstryxButton(\n'
      '                    label: \'Clear filters\',\n'
      '                    variant: AstryxButtonVariant.primary,\n'
      '                    onPressed: () => setState(() {\n'
      '                      _kinds = <String>{};\n'
      '                      _collection = \'All\';\n'
      '                      _query.clear();\n'
      '                    }),\n'
      '                  ),\n'
      '                ],\n'
      '              )\n'
      '            : _view == \'grid\'\n'
      '            ? _grid(shown)\n'
      '            : _list(shown),\n'
      '      ),\n'
      '    );\n'
      '  }\n'
      '\n'
      '  /// The wall: a selectable card per asset.\n'
      '  ///\n'
      '  /// `AstryxSelectableCard` rather than a pressable card with a checkbox on\n'
      '  /// it: this is a *control* that reports a selection, and it announces itself\n'
      '  /// as a checkbox rather than as a button that happens to tick something.\n'
      '  Widget _grid(List<Asset> shown) {\n'
      '    return AstryxHStack(\n'
      '      gap: AstryxSpacingToken.spacing3,\n'
      '      wrap: true,\n'
      '      runGap: AstryxSpacingToken.spacing3,\n'
      '      align: AstryxStackAlign.start,\n'
      '      children: <Widget>[\n'
      '        for (final asset in shown)\n'
      '          SizedBox(\n'
      '            width: 200,\n'
      '            child: AstryxSelectableCard(\n'
      '              label: asset.name,\n'
      '              semanticsHint: \'\${asset.kind}, \${asset.size}\',\n'
      '              selected: _selected.contains(asset.id),\n'
      '              padding: AstryxSpacingToken.spacing3,\n'
      '              onSelectedChanged: (value) => _toggle(asset.id, selected: value),\n'
      '              child: AstryxVStack(\n'
      '                gap: AstryxSpacingToken.spacing2,\n'
      '                align: AstryxStackAlign.stretch,\n'
      '                children: <Widget>[\n'
      '                  AstryxAspectRatio(\n'
      '                    ratio: 4 / 3,\n'
      '                    semanticsLabel: asset.name,\n'
      '                    child: const Center(\n'
      '                      child: AstryxIcon(AstryxIconName.viewColumns),\n'
      '                    ),\n'
      '                  ),\n'
      '                  AstryxText(\n'
      '                    asset.name,\n'
      '                    type: AstryxTextType.label,\n'
      '                    maxLines: 1,\n'
      '                  ),\n'
      '                  AstryxText(\n'
      '                    \'\${asset.kind} · \${asset.size}\',\n'
      '                    type: AstryxTextType.supporting,\n'
      '                    color: AstryxTextColor.secondary,\n'
      '                    maxLines: 1,\n'
      '                  ),\n'
      '                ],\n'
      '              ),\n'
      '            ),\n'
      '          ),\n'
      '      ],\n'
      '    );\n'
      '  }\n'
      '\n'
      '  /// The same set, and the same selection, as rows.\n'
      '  Widget _list(List<Asset> shown) {\n'
      '    return AstryxTable<Asset>(\n'
      '      label: \'Assets\',\n'
      '      keyOf: (row) => row.id,\n'
      '      rowLabelOf: (row) => row.name,\n'
      '      density: AstryxTableDensity.compact,\n'
      '      selectionMode: AstryxTableSelectionMode.multiple,\n'
      '      selected: _selected,\n'
      '      onSelectionChanged: (value) => setState(() {\n'
      '        _selected\n'
      '          ..clear()\n'
      '          ..addAll(value);\n'
      '      }),\n'
      '      columns: <AstryxTableColumn<Asset>>[\n'
      '        AstryxTableColumn<Asset>(\n'
      '          id: \'name\',\n'
      '          header: \'Name\',\n'
      '          compare: (a, b) => a.name.compareTo(b.name),\n'
      '          cellBuilder: (context, row) => AstryxText(row.name, maxLines: 1),\n'
      '        ),\n'
      '        AstryxTableColumn<Asset>(\n'
      '          id: \'collection\',\n'
      '          header: \'Collection\',\n'
      '          width: const AstryxTableColumnWidth.fixed(130),\n'
      '          cellBuilder: (context, row) => AstryxBadge(row.collection),\n'
      '        ),\n'
      '        AstryxTableColumn<Asset>(\n'
      '          id: \'kind\',\n'
      '          header: \'Kind\',\n'
      '          width: const AstryxTableColumnWidth.fixed(100),\n'
      '          cellBuilder: (context, row) => AstryxText(row.kind, maxLines: 1),\n'
      '        ),\n'
      '        AstryxTableColumn<Asset>(\n'
      '          id: \'added\',\n'
      '          header: \'Added\',\n'
      '          width: const AstryxTableColumnWidth.fixed(130),\n'
      '          cellBuilder: (context, row) => AstryxText(\n'
      '            row.added,\n'
      '            type: AstryxTextType.supporting,\n'
      '            color: AstryxTextColor.secondary,\n'
      '            maxLines: 1,\n'
      '          ),\n'
      '        ),\n'
      '      ],\n'
      '      rows: shown,\n'
      '    );\n'
      '  }\n'
      '}\n',
  // examples/template_split_examples.dart
  'template_messaging_shell':
      '/// One conversation in the list.\n'
      'typedef Thread = ({\n'
      '  String id,\n'
      '  String name,\n'
      '  String preview,\n'
      '  int unread,\n'
      '  bool online,\n'
      '});\n'
      '\n'
      '/// One message in a thread.\n'
      'typedef Line = ({bool mine, String text, String at});\n'
      '\n'
      'class MessagingShellTemplate extends StatefulWidget {\n'
      '  const MessagingShellTemplate({super.key});\n'
      '\n'
      '  @override\n'
      '  State<MessagingShellTemplate> createState() => _MessagingShellTemplateState();\n'
      '}\n'
      '\n'
      'class _MessagingShellTemplateState extends State<MessagingShellTemplate> {\n'
      '  static const List<Thread> _threads = <Thread>[\n'
      '    (\n'
      '      id: \'sre\',\n'
      '      name: \'Ada Lovelace\',\n'
      '      preview: \'The bind is still taking 40 seconds.\',\n'
      '      unread: 2,\n'
      '      online: true,\n'
      '    ),\n'
      '    (\n'
      '      id: \'grace\',\n'
      '      name: \'Grace Hopper\',\n'
      '      preview: \'Merged — thanks for the review.\',\n'
      '      unread: 0,\n'
      '      online: true,\n'
      '    ),\n'
      '    (\n'
      '      id: \'oncall\',\n'
      '      name: \'On-call, Europe\',\n'
      '      preview: \'Rota swapped for Thursday.\',\n'
      '      unread: 5,\n'
      '      online: false,\n'
      '    ),\n'
      '    (\n'
      '      id: \'alan\',\n'
      '      name: \'Alan Turing\',\n'
      '      preview: \'Can you look at 4102 when you get a minute?\',\n'
      '      unread: 0,\n'
      '      online: false,\n'
      '    ),\n'
      '  ];\n'
      '\n'
      '  static const Map<String, List<Line>> _messages = <String, List<Line>>{\n'
      '    \'sre\': <Line>[\n'
      '      (\n'
      '        mine: false,\n'
      '        text: \'The 14:02 deploy rolled back again.\',\n'
      '        at: \'13:58\',\n'
      '      ),\n'
      '      (\n'
      '        mine: true,\n'
      '        text: \'Health check or the migration?\',\n'
      '        at: \'14:01\',\n'
      '      ),\n'
      '      (\n'
      '        mine: false,\n'
      '        text:\n'
      '            \'Health check. The bind is still taking 40 seconds and the check \'\n'
      '            \'gives up at 30.\',\n'
      '        at: \'14:03\',\n'
      '      ),\n'
      '    ],\n'
      '    \'grace\': <Line>[\n'
      '      (mine: false, text: \'Merged — thanks for the review.\', at: \'09:12\'),\n'
      '    ],\n'
      '    \'oncall\': <Line>[\n'
      '      (mine: false, text: \'Rota swapped for Thursday.\', at: \'Yesterday\'),\n'
      '    ],\n'
      '    \'alan\': <Line>[\n'
      '      (\n'
      '        mine: false,\n'
      '        text: \'Can you look at 4102 when you get a minute?\',\n'
      '        at: \'Monday\',\n'
      '      ),\n'
      '    ],\n'
      '  };\n'
      '\n'
      '  final TextEditingController _draft = TextEditingController();\n'
      '  final List<Line> _extra = <Line>[];\n'
      '\n'
      '  String _thread = \'sre\';\n'
      '\n'
      '  @override\n'
      '  void dispose() {\n'
      '    _draft.dispose();\n'
      '    super.dispose();\n'
      '  }\n'
      '\n'
      '  Thread get _open => _threads.firstWhere((t) => t.id == _thread);\n'
      '\n'
      '  List<Line> get _lines => <Line>[\n'
      '    ..._messages[_thread] ?? const <Line>[],\n'
      '    if (_thread == \'sre\') ..._extra,\n'
      '  ];\n'
      '\n'
      '  void _send(String text) {\n'
      '    if (text.trim().isEmpty) return;\n'
      '    setState(() {\n'
      '      _extra.add((mine: true, text: text.trim(), at: \'now\'));\n'
      '      _thread = \'sre\';\n'
      '      _draft.clear();\n'
      '    });\n'
      '  }\n'
      '\n'
      '  @override\n'
      '  Widget build(BuildContext context) {\n'
      '    final open = _open;\n'
      '\n'
      '    // `scrollable: false`, because the transcript scrolls itself and the list\n'
      '    // in the panel scrolls itself. The layout is a frame here, not a scroller.\n'
      '    return SizedBox(\n'
      '      height: 560,\n'
      '      child: AstryxLayout(\n'
      '        scrollable: false,\n'
      '        padding: AstryxSpacingToken.spacing0,\n'
      '        panelSide: AstryxLayoutPanelSide.start,\n'
      '        panelWidth: 260,\n'
      '        panel: _ThreadList(\n'
      '          threads: _threads,\n'
      '          selected: _thread,\n'
      '          onSelected: (id) => setState(() => _thread = id),\n'
      '        ),\n'
      '        child: AstryxChatLayout(\n'
      '          maxWidth: 640,\n'
      '          header: AstryxHStack(\n'
      '            gap: AstryxSpacingToken.spacing3,\n'
      '            justify: AstryxStackJustify.between,\n'
      '            mainAxisSize: MainAxisSize.max,\n'
      '            children: <Widget>[\n'
      '              Flexible(\n'
      '                child: AstryxHStack(\n'
      '                  gap: AstryxSpacingToken.spacing2,\n'
      '                  children: <Widget>[\n'
      '                    AstryxAvatar(\n'
      '                      name: open.name,\n'
      '                      size: AstryxAvatarSize.sm,\n'
      '                      status: open.online\n'
      '                          ? AstryxStatusDotVariant.success\n'
      '                          : AstryxStatusDotVariant.neutral,\n'
      '                      statusLabel: open.online ? \'Online\' : \'Away\',\n'
      '                    ),\n'
      '                    Flexible(child: AstryxHeading(open.name, level: 1)),\n'
      '                  ],\n'
      '                ),\n'
      '              ),\n'
      '              AstryxMoreMenu(\n'
      '                label: \'Conversation actions\',\n'
      '                entries: <AstryxMenuEntry>[\n'
      '                  AstryxMenuItem(\n'
      '                    label: \'Search this thread\',\n'
      '                    onSelected: () {},\n'
      '                  ),\n'
      '                  AstryxMenuItem(label: \'Mute\', onSelected: () {}),\n'
      '                  const AstryxMenuDivider(),\n'
      '                  AstryxMenuItem(\n'
      '                    label: \'Leave conversation\',\n'
      '                    destructive: true,\n'
      '                    onSelected: () {},\n'
      '                  ),\n'
      '                ],\n'
      '              ),\n'
      '            ],\n'
      '          ),\n'
      '          messages: <Widget>[\n'
      '            for (final line in _lines)\n'
      '              // `AstryxChatRole` is about which side of the transcript a turn\n'
      '              // sits on, not about who is a machine: `user` is whoever is\n'
      '              // composing, and everything else is the other side.\n'
      '              AstryxChatMessage(\n'
      '                role: line.mine\n'
      '                    ? AstryxChatRole.user\n'
      '                    : AstryxChatRole.assistant,\n'
      '                author: line.mine ? \'You\' : open.name,\n'
      '                leading: line.mine\n'
      '                    ? null\n'
      '                    : AstryxAvatar(name: open.name, size: AstryxAvatarSize.sm),\n'
      '                timestamp: AstryxText(\n'
      '                  line.at,\n'
      '                  type: AstryxTextType.supporting,\n'
      '                  color: AstryxTextColor.secondary,\n'
      '                ),\n'
      '                // Plain text, always. Rendering what somebody typed changes\n'
      '                // what they said — and in a person-to-person thread there is\n'
      '                // no markdown to render in the first place.\n'
      '                child: AstryxText(line.text),\n'
      '              ),\n'
      '          ],\n'
      '          composer: AstryxChatComposer(\n'
      '            controller: _draft,\n'
      '            placeholder: \'Message \${open.name}\',\n'
      '            label: \'Message \${open.name}\',\n'
      '            onSubmit: _send,\n'
      '            leading: <Widget>[\n'
      '              AstryxIconButton(\n'
      '                icon: AstryxIconName.copy,\n'
      '                label: \'Attach a file\',\n'
      '                variant: AstryxButtonVariant.ghost,\n'
      '                onPressed: () {},\n'
      '              ),\n'
      '            ],\n'
      '          ),\n'
      '        ),\n'
      '      ),\n'
      '    );\n'
      '  }\n'
      '}\n'
      '\n'
      '/// The conversations, newest first, with what is unread on each.\n'
      'class _ThreadList extends StatelessWidget {\n'
      '  const _ThreadList({\n'
      '    required this.threads,\n'
      '    required this.selected,\n'
      '    required this.onSelected,\n'
      '  });\n'
      '\n'
      '  final List<Thread> threads;\n'
      '  final String selected;\n'
      '  final ValueChanged<String> onSelected;\n'
      '\n'
      '  @override\n'
      '  Widget build(BuildContext context) {\n'
      '    // No `Expanded` and no scroller of its own: `AstryxLayout` wraps a panel\n'
      '    // in a `SingleChildScrollView`, so the panel is handed an unbounded\n'
      '    // height and anything that wants to fill it cannot be laid out.\n'
      '    return AstryxVStack(\n'
      '      gap: AstryxSpacingToken.spacing0,\n'
      '      align: AstryxStackAlign.stretch,\n'
      '      children: <Widget>[\n'
      '        Padding(\n'
      '          padding: const EdgeInsets.all(12),\n'
      '          child: AstryxHStack(\n'
      '            gap: AstryxSpacingToken.spacing2,\n'
      '            justify: AstryxStackJustify.between,\n'
      '            mainAxisSize: MainAxisSize.max,\n'
      '            children: <Widget>[\n'
      '              const AstryxHeading(\'Messages\'),\n'
      '              AstryxIconButton(\n'
      '                icon: AstryxIconName.copy,\n'
      '                label: \'New conversation\',\n'
      '                tooltip: \'New conversation\',\n'
      '                variant: AstryxButtonVariant.ghost,\n'
      '                size: AstryxButtonSize.sm,\n'
      '                onPressed: () {},\n'
      '              ),\n'
      '            ],\n'
      '          ),\n'
      '        ),\n'
      '        const AstryxDivider(),\n'
      '        AstryxList(\n'
      '          label: \'Conversations\',\n'
      '          children: <Widget>[\n'
      '            for (final thread in threads)\n'
      '              AstryxItem(\n'
      '                label: thread.name,\n'
      '                description: thread.preview,\n'
      '                selected: thread.id == selected,\n'
      '                leading: AstryxAvatar(\n'
      '                  name: thread.name,\n'
      '                  size: AstryxAvatarSize.sm,\n'
      '                  status: thread.online ? AstryxStatusDotVariant.success : null,\n'
      '                  statusLabel: thread.online ? \'Online\' : null,\n'
      '                ),\n'
      '                // The count is the badge *and* the announcement: "2" on\n'
      '                // its own beside a name is a number about nothing.\n'
      '                trailing: thread.unread == 0\n'
      '                    ? null\n'
      '                    : AstryxBadge(\n'
      '                        \'\${thread.unread}\',\n'
      '                        variant: AstryxBadgeVariant.info,\n'
      '                        semanticsLabel: \'\${thread.unread} unread messages\',\n'
      '                      ),\n'
      '                onPressed: () => onSelected(thread.id),\n'
      '              ),\n'
      '          ],\n'
      '        ),\n'
      '      ],\n'
      '    );\n'
      '  }\n'
      '}\n',
  // examples/template_table_page_examples.dart
  'template_table_page':
      '/// One row of the table.\n'
      'class Run {\n'
      '  const Run({\n'
      '    required this.id,\n'
      '    required this.pipeline,\n'
      '    required this.branch,\n'
      '    required this.owner,\n'
      '    required this.seconds,\n'
      '    required this.state,\n'
      '  });\n'
      '\n'
      '  final String id;\n'
      '  final String pipeline;\n'
      '  final String branch;\n'
      '  final String owner;\n'
      '  final int seconds;\n'
      '\n'
      '  /// `passed`, `failed` or `running`.\n'
      '  final String state;\n'
      '}\n'
      '\n'
      '/// Forty-two rows, which is the whole point: three pages of fourteen.\n'
      '///\n'
      '/// Generated rather than typed out, and deterministic — an example that\n'
      '/// shuffles itself is an example whose screenshot cannot be trusted.\n'
      'final List<Run> runs = <Run>[\n'
      '  for (var i = 0; i < 42; i++)\n'
      '    Run(\n'
      '      id: \'r-\${4200 - i}\',\n'
      '      pipeline: const <String>[\n'
      '        \'payments-api\',\n'
      '        \'events\',\n'
      '        \'edge\',\n'
      '        \'reports\',\n'
      '      ][i % 4],\n'
      '      branch: i.isEven ? \'main\' : \'release/4.2\',\n'
      '      owner: const <String>[\n'
      '        \'Ada Lovelace\',\n'
      '        \'Alan Turing\',\n'
      '        \'Grace Hopper\',\n'
      '        \'Katherine Johnson\',\n'
      '      ][i % 4],\n'
      '      seconds: 40 + (i * 37) % 900,\n'
      '      state: switch (i % 7) {\n'
      '        0 => \'failed\',\n'
      '        1 => \'running\',\n'
      '        _ => \'passed\',\n'
      '      },\n'
      '    ),\n'
      '];\n'
      '\n'
      'class TablePageTemplate extends StatefulWidget {\n'
      '  const TablePageTemplate({super.key});\n'
      '\n'
      '  @override\n'
      '  State<TablePageTemplate> createState() => _TablePageTemplateState();\n'
      '}\n'
      '\n'
      'class _TablePageTemplateState extends State<TablePageTemplate> {\n'
      '  static const List<int> _pageSizes = <int>[7, 14, 28];\n'
      '\n'
      '  final TextEditingController _query = TextEditingController();\n'
      '\n'
      '  AstryxTableSort? _sort;\n'
      '  String _state = \'all\';\n'
      '  int _pageSize = 14;\n'
      '  int _page = 1;\n'
      '\n'
      '  @override\n'
      '  void dispose() {\n'
      '    _query.dispose();\n'
      '    super.dispose();\n'
      '  }\n'
      '\n'
      '  /// Every row that survives the filters, in whatever order sorting asked for.\n'
      '  ///\n'
      '  /// Filtering *and* sorting happen here, not in the table. That is not a\n'
      '  /// preference: a page is a window onto the sorted set, so the sort has to be\n'
      '  /// applied before the window is cut — a table sorting the fourteen rows it\n'
      '  /// was handed would sort one page at a time.\n'
      '  List<Run> get _matches {\n'
      '    final query = _query.text.trim().toLowerCase();\n'
      '    final rows =\n'
      '        runs.where((row) {\n'
      '          final matchesState = _state == \'all\' || row.state == _state;\n'
      '          final matchesQuery =\n'
      '              query.isEmpty ||\n'
      '              row.id.contains(query) ||\n'
      '              row.pipeline.contains(query) ||\n'
      '              row.branch.contains(query) ||\n'
      '              row.owner.toLowerCase().contains(query);\n'
      '          return matchesState && matchesQuery;\n'
      '        }).toList();\n'
      '\n'
      '    final sort = _sort;\n'
      '    if (sort != null) {\n'
      '      final compare = switch (sort.columnId) {\n'
      '        \'run\' => (Run a, Run b) => a.id.compareTo(b.id),\n'
      '        \'duration\' => (Run a, Run b) => a.seconds.compareTo(b.seconds),\n'
      '        \'owner\' => (Run a, Run b) => a.owner.compareTo(b.owner),\n'
      '        _ => null,\n'
      '      };\n'
      '      if (compare != null) {\n'
      '        rows.sort(\n'
      '          sort.direction == AstryxSortDirection.ascending\n'
      '              ? compare\n'
      '              : (a, b) => compare(b, a),\n'
      '        );\n'
      '      }\n'
      '    }\n'
      '\n'
      '    return rows;\n'
      '  }\n'
      '\n'
      '  int get _pageCount => (_matches.length / _pageSize).ceil().clamp(1, 999);\n'
      '\n'
      '  /// The rows this page shows.\n'
      '  List<Run> get _rows {\n'
      '    final matches = _matches;\n'
      '    final start = (_page - 1) * _pageSize;\n'
      '    if (start >= matches.length) return const <Run>[];\n'
      '    final end = start + _pageSize;\n'
      '    return matches.sublist(start, end > matches.length ? matches.length : end);\n'
      '  }\n'
      '\n'
      '  /// Any change to the filters puts the reader back on page one.\n'
      '  ///\n'
      '  /// Leaving them on page three of a set that now has two is how a filter\n'
      '  /// produces an empty screen that looks like a bug.\n'
      '  void _refilter(VoidCallback change) => setState(() {\n'
      '    change();\n'
      '    _page = 1;\n'
      '  });\n'
      '\n'
      '  @override\n'
      '  Widget build(BuildContext context) {\n'
      '    final matches = _matches;\n'
      '    final rows = _rows;\n'
      '    final first = matches.isEmpty ? 0 : (_page - 1) * _pageSize + 1;\n'
      '    final last = first + rows.length - (rows.isEmpty ? 0 : 1);\n'
      '\n'
      '    return SizedBox(\n'
      '      height: 620,\n'
      '      child: AstryxLayout(\n'
      '        // The table scrolls its own body under a pinned header row, so the page\n'
      '        // must not scroll as well — two scroll views inside one another is one\n'
      '        // too many.\n'
      '        scrollable: false,\n'
      '        header: AstryxVStack(\n'
      '          gap: AstryxSpacingToken.spacing3,\n'
      '          align: AstryxStackAlign.stretch,\n'
      '          children: <Widget>[\n'
      '            AstryxHStack(\n'
      '              gap: AstryxSpacingToken.spacing3,\n'
      '              justify: AstryxStackJustify.between,\n'
      '              mainAxisSize: MainAxisSize.max,\n'
      '              children: <Widget>[\n'
      '                const Flexible(child: AstryxHeading(\'Pipeline runs\', level: 1)),\n'
      '                AstryxButton(\n'
      '                  label: \'Run pipeline\',\n'
      '                  variant: AstryxButtonVariant.primary,\n'
      '                  size: AstryxButtonSize.sm,\n'
      '                  onPressed: () {},\n'
      '                ),\n'
      '              ],\n'
      '            ),\n'
      '            AstryxHStack(\n'
      '              gap: AstryxSpacingToken.spacing3,\n'
      '              wrap: true,\n'
      '              runGap: AstryxSpacingToken.spacing2,\n'
      '              mainAxisSize: MainAxisSize.max,\n'
      '              children: <Widget>[\n'
      '                SizedBox(\n'
      '                  width: 240,\n'
      '                  child: AstryxTextInput(\n'
      '                    label: \'Search runs\',\n'
      '                    labelHidden: true,\n'
      '                    controller: _query,\n'
      '                    placeholder: \'Run, pipeline, branch or owner\',\n'
      '                    leading: const AstryxIcon(AstryxIconName.search),\n'
      '                    showClear: true,\n'
      '                    size: AstryxInputSize.sm,\n'
      '                    onChanged: (_) => _refilter(() {}),\n'
      '                  ),\n'
      '                ),\n'
      '                // A segmented control rather than a menu: three states, all\n'
      '                // worth seeing at once, and the applied one is visible without\n'
      '                // opening anything.\n'
      '                AstryxSegmentedControl<String>(\n'
      '                  label: \'State\',\n'
      '                  value: _state,\n'
      '                  size: AstryxButtonSize.sm,\n'
      '                  onChanged: (value) => _refilter(() => _state = value),\n'
      '                  segments: const <AstryxSegment<String>>[\n'
      '                    AstryxSegment(value: \'all\', label: \'All\'),\n'
      '                    AstryxSegment(value: \'passed\', label: \'Passed\'),\n'
      '                    AstryxSegment(value: \'failed\', label: \'Failed\'),\n'
      '                  ],\n'
      '                ),\n'
      '                // No `Spacer` in a wrapping row: `wrap: true` lays the children\n'
      '                // out as a `Wrap`, and a `Spacer` is a `Flex` child.\n'
      '                AstryxText(\n'
      '                  \'\${matches.length} of \${runs.length} runs\',\n'
      '                  type: AstryxTextType.supporting,\n'
      '                  color: AstryxTextColor.secondary,\n'
      '                ),\n'
      '              ],\n'
      '            ),\n'
      '          ],\n'
      '        ),\n'
      '        footer: AstryxHStack(\n'
      '          gap: AstryxSpacingToken.spacing4,\n'
      '          wrap: true,\n'
      '          runGap: AstryxSpacingToken.spacing2,\n'
      '          justify: AstryxStackJustify.between,\n'
      '          mainAxisSize: MainAxisSize.max,\n'
      '          children: <Widget>[\n'
      '            // The range, not just the page number: "1–14 of 38" is the sentence\n'
      '            // that tells a reader how much they have not seen.\n'
      '            AstryxText(\n'
      '              matches.isEmpty ? \'Nothing to show\' : \'\$first–\$last of \'\n'
      '                  \'\${matches.length}\',\n'
      '              type: AstryxTextType.supporting,\n'
      '              color: AstryxTextColor.secondary,\n'
      '            ),\n'
      '            AstryxHStack(\n'
      '              gap: AstryxSpacingToken.spacing3,\n'
      '              // The page size and the pager are 330 logical pixels between\n'
      '              // them, which is a phone with nothing left over. They take a\n'
      '              // line each rather than the pager losing its last page button.\n'
      '              wrap: true,\n'
      '              runGap: AstryxSpacingToken.spacing2,\n'
      '              children: <Widget>[\n'
      '                AstryxSelector<int>(\n'
      '                  label: \'Rows per page\',\n'
      '                  labelHidden: true,\n'
      '                  value: _pageSize,\n'
      '                  width: 132,\n'
      '                  size: AstryxInputSize.sm,\n'
      '                  onChanged: (value) => _refilter(\n'
      '                    () => _pageSize = value ?? _pageSize,\n'
      '                  ),\n'
      '                  options: <AstryxSelectorOption<int>>[\n'
      '                    for (final size in _pageSizes)\n'
      '                      AstryxSelectorOption<int>(\n'
      '                        value: size,\n'
      '                        label: \'\$size per page\',\n'
      '                      ),\n'
      '                  ],\n'
      '                ),\n'
      '                AstryxPagination(\n'
      '                  label: \'Runs\',\n'
      '                  page: _page,\n'
      '                  pageCount: _pageCount,\n'
      '                  onPageChanged: (page) => setState(() => _page = page),\n'
      '                ),\n'
      '              ],\n'
      '            ),\n'
      '          ],\n'
      '        ),\n'
      '        child: AstryxTable<Run>(\n'
      '          label: \'Pipeline runs\',\n'
      '          rows: rows,\n'
      '          keyOf: (row) => row.id,\n'
      '          rowLabelOf: (row) => \'\${row.id} — \${row.pipeline}\',\n'
      '          sort: _sort,\n'
      '          // Sorting is a change to the whole set, so it resets the page too.\n'
      '          onSortChanged: (sort) => _refilter(() => _sort = sort),\n'
      '          striped: true,\n'
      '          emptyState: AstryxCenter(\n'
      '            minHeight: 220,\n'
      '            child: AstryxVStack(\n'
      '              gap: AstryxSpacingToken.spacing3,\n'
      '              align: AstryxStackAlign.center,\n'
      '              children: <Widget>[\n'
      '                const AstryxIcon(\n'
      '                  AstryxIconName.search,\n'
      '                  size: AstryxIconSize.lg,\n'
      '                  color: AstryxIconColor.secondary,\n'
      '                ),\n'
      '                const AstryxHeading(\'No runs match\', level: 4),\n'
      '                const AstryxText(\n'
      '                  \'Every filter is still applied.\',\n'
      '                  color: AstryxTextColor.secondary,\n'
      '                ),\n'
      '                AstryxButton(\n'
      '                  label: \'Clear filters\',\n'
      '                  onPressed: () => _refilter(() {\n'
      '                    _query.clear();\n'
      '                    _state = \'all\';\n'
      '                  }),\n'
      '                ),\n'
      '              ],\n'
      '            ),\n'
      '          ),\n'
      '          rowActionsBuilder: (context, row) => AstryxIconButton(\n'
      '            icon: AstryxIconName.externalLink,\n'
      '            label: \'Open \${row.id}\',\n'
      '            variant: AstryxButtonVariant.ghost,\n'
      '            size: AstryxButtonSize.sm,\n'
      '            onPressed: () {},\n'
      '          ),\n'
      '          columns: <AstryxTableColumn<Run>>[\n'
      '            AstryxTableColumn<Run>(\n'
      '              id: \'run\',\n'
      '              header: \'Run\',\n'
      '              width: const AstryxTableColumnWidth.intrinsic(min: 96),\n'
      '              compare: (a, b) => a.id.compareTo(b.id),\n'
      '              cellBuilder: (context, row) =>\n'
      '                  AstryxCode(row.id, semanticsLabel: \'Run \${row.id}\'),\n'
      '            ),\n'
      '            AstryxTableColumn<Run>(\n'
      '              id: \'pipeline\',\n'
      '              header: \'Pipeline\',\n'
      '              width: const AstryxTableColumnWidth.flex(1.4),\n'
      '              cellBuilder: (context, row) => AstryxVStack(\n'
      '                gap: AstryxSpacingToken.spacing0_5,\n'
      '                children: <Widget>[\n'
      '                  AstryxText(row.pipeline, maxLines: 1),\n'
      '                  AstryxText(\n'
      '                    row.branch,\n'
      '                    type: AstryxTextType.supporting,\n'
      '                    color: AstryxTextColor.secondary,\n'
      '                    maxLines: 1,\n'
      '                  ),\n'
      '                ],\n'
      '              ),\n'
      '            ),\n'
      '            AstryxTableColumn<Run>(\n'
      '              id: \'state\',\n'
      '              header: \'State\',\n'
      '              width: const AstryxTableColumnWidth.intrinsic(min: 104),\n'
      '              cellBuilder: (context, row) => switch (row.state) {\n'
      '                \'failed\' => const AstryxBadge(\n'
      '                  \'Failed\',\n'
      '                  variant: AstryxBadgeVariant.error,\n'
      '                  icon: AstryxIcon(AstryxIconName.error),\n'
      '                ),\n'
      '                \'running\' => const AstryxBadge(\n'
      '                  \'Running\',\n'
      '                  variant: AstryxBadgeVariant.info,\n'
      '                  icon: AstryxIcon(AstryxIconName.clock),\n'
      '                ),\n'
      '                _ => const AstryxBadge(\n'
      '                  \'Passed\',\n'
      '                  variant: AstryxBadgeVariant.success,\n'
      '                  icon: AstryxIcon(AstryxIconName.success),\n'
      '                ),\n'
      '              },\n'
      '            ),\n'
      '            AstryxTableColumn<Run>(\n'
      '              id: \'owner\',\n'
      '              header: \'Owner\',\n'
      '              compare: (a, b) => a.owner.compareTo(b.owner),\n'
      '              cellBuilder: (context, row) => AstryxHStack(\n'
      '                gap: AstryxSpacingToken.spacing2,\n'
      '                children: <Widget>[\n'
      '                  AstryxAvatar(name: row.owner, size: AstryxAvatarSize.xs),\n'
      '                  Flexible(child: AstryxText(row.owner, maxLines: 1)),\n'
      '                ],\n'
      '              ),\n'
      '            ),\n'
      '            AstryxTableColumn<Run>(\n'
      '              id: \'duration\',\n'
      '              header: \'Duration\',\n'
      '              width: const AstryxTableColumnWidth.fixed(96),\n'
      '              alignment: AstryxTableAlignment.end,\n'
      '              compare: (a, b) => a.seconds.compareTo(b.seconds),\n'
      '              cellBuilder: (context, row) => AstryxText(\n'
      '                \'\${(row.seconds / 60).floor()}m \${row.seconds % 60}s\',\n'
      '                tabularNumbers: true,\n'
      '              ),\n'
      '            ),\n'
      '          ],\n'
      '        ),\n'
      '      ),\n'
      '    );\n'
      '  }\n'
      '}\n',
  // examples/template_workspace_examples.dart
  'template_editor':
      'class EditorTemplate extends StatefulWidget {\n'
      '  const EditorTemplate({super.key});\n'
      '\n'
      '  @override\n'
      '  State<EditorTemplate> createState() => _EditorTemplateState();\n'
      '}\n'
      '\n'
      'class _EditorTemplateState extends State<EditorTemplate> {\n'
      '  final TextEditingController _title = TextEditingController(\n'
      '    text: \'Rolling back a deploy\',\n'
      '  );\n'
      '\n'
      '  final TextEditingController _body = TextEditingController(\n'
      '    text:\n'
      '        \'# Rolling back\\n\\n\'\n'
      '        \'A rollback is a deploy of the previous commit. There is no separate \'\n'
      '        \'rollback screen, because the thing you already know how to watch is \'\n'
      '        \'the thing that runs.\\n\\n\'\n'
      '        \'Select a phrase and press **Bold** in the toolbar above.\',\n'
      '  );\n'
      '\n'
      '  /// Whether the canvas shows the source or the rendered result.\n'
      '  String _mode = \'write\';\n'
      '\n'
      '  bool _dirty = false;\n'
      '  String _status = \'draft\';\n'
      '  final Set<String> _tags = <String>{\'deploys\'};\n'
      '\n'
      '  @override\n'
      '  void initState() {\n'
      '    super.initState();\n'
      '    _title.addListener(_touch);\n'
      '    _body.addListener(_touch);\n'
      '  }\n'
      '\n'
      '  @override\n'
      '  void dispose() {\n'
      '    _title.dispose();\n'
      '    _body.dispose();\n'
      '    super.dispose();\n'
      '  }\n'
      '\n'
      '  void _touch() {\n'
      '    if (!_dirty) setState(() => _dirty = true);\n'
      '  }\n'
      '\n'
      '  /// Wraps the selection in [marker], leaving the caret after it.\n'
      '  ///\n'
      '  /// This is the whole of what a toolbar can honestly do over a plain text\n'
      '  /// field: the package ships no rich-text editing controller, so the document\n'
      '  /// is its own markup and the buttons are edits to it rather than styling\n'
      '  /// applied to a hidden model.\n'
      '  void _wrap(String marker) {\n'
      '    final value = _body.value;\n'
      '    final selection = value.selection;\n'
      '    if (!selection.isValid) return;\n'
      '\n'
      '    final replaced = \'\$marker\${selection.textInside(value.text)}\$marker\';\n'
      '    _body.value = value.copyWith(\n'
      '      text:\n'
      '          selection.textBefore(value.text) +\n'
      '          replaced +\n'
      '          selection.textAfter(value.text),\n'
      '      selection: TextSelection.collapsed(\n'
      '        offset: selection.start + replaced.length,\n'
      '      ),\n'
      '      composing: TextRange.empty,\n'
      '    );\n'
      '  }\n'
      '\n'
      '  /// How many words the draft has, for the footer.\n'
      '  int get _words =>\n'
      '      _body.text.split(RegExp(r\'\\s+\')).where((word) => word.isNotEmpty).length;\n'
      '\n'
      '  @override\n'
      '  Widget build(BuildContext context) {\n'
      '    // `scrollable: false`: the canvas scrolls itself, and a scroll view inside\n'
      '    // a scroll view measures unbounded — which is a layout assertion rather\n'
      '    // than a subtle bug.\n'
      '    return LayoutBuilder(\n'
      '      builder: (context, constraints) {\n'
      '        // The same width the layout\'s own panel makes its mind up at, so the\n'
      '        // frame and the panel change together rather than one at a time.\n'
      '        final compact = constraints.maxWidth < 640;\n'
      '\n'
      '        return SizedBox(\n'
      '          // A header that has wrapped onto three lines and a panel that has\n'
      '          // become a band above the canvas both cost height the wide frame\n'
      '          // never had to find. Bands do not shrink, so the frame grows.\n'
      '          height: compact ? 720 : 560,\n'
      '          child: _layout(context, compact: compact),\n'
      '        );\n'
      '      },\n'
      '    );\n'
      '  }\n'
      '\n'
      '  Widget _layout(BuildContext context, {required bool compact}) {\n'
      '    return AstryxLayout(\n'
      '      scrollable: false,\n'
      '      panelWidth: 260,\n'
      '      panelLabel: \'Document\',\n'
      '      header: AstryxVStack(\n'
      '        gap: AstryxSpacingToken.spacing3,\n'
      '        align: AstryxStackAlign.stretch,\n'
      '        children: <Widget>[\n'
      '          AstryxHStack(\n'
      '            gap: AstryxSpacingToken.spacing3,\n'
      '            justify: AstryxStackJustify.between,\n'
      '            mainAxisSize: MainAxisSize.max,\n'
      '            children: <Widget>[\n'
      '              Flexible(\n'
      '                child: AstryxTextInput(\n'
      '                  controller: _title,\n'
      '                  label: \'Title\',\n'
      '                  labelHidden: true,\n'
      '                  size: AstryxInputSize.lg,\n'
      '                  placeholder: \'Untitled\',\n'
      '                ),\n'
      '              ),\n'
      '              AstryxBadge(\n'
      '                _dirty ? \'Unsaved changes\' : \'Saved\',\n'
      '                variant: _dirty\n'
      '                    ? AstryxBadgeVariant.warning\n'
      '                    : AstryxBadgeVariant.success,\n'
      '                icon: AstryxIcon(\n'
      '                  _dirty ? AstryxIconName.warning : AstryxIconName.success,\n'
      '                ),\n'
      '              ),\n'
      '            ],\n'
      '          ),\n'
      '          AstryxHStack(\n'
      '            gap: AstryxSpacingToken.spacing3,\n'
      '            justify: AstryxStackJustify.between,\n'
      '            mainAxisSize: MainAxisSize.max,\n'
      '            wrap: true,\n'
      '            runGap: AstryxSpacingToken.spacing2,\n'
      '            children: <Widget>[\n'
      '              // One tab stop for the whole band, however many controls sit\n'
      '              // in it. Tab reaches the toolbar and leaves it; the arrows\n'
      '              // move inside.\n'
      '              AstryxToolbar(\n'
      '                label: \'Formatting\',\n'
      '                children: <Widget>[\n'
      '                  for (final mark in const <List<String>>[\n'
      '                    <String>[\'Bold\', \'**\'],\n'
      '                    <String>[\'Italic\', \'_\'],\n'
      '                    <String>[\'Code\', \'`\'],\n'
      '                  ])\n'
      '                    AstryxButton(\n'
      '                      label: mark[0],\n'
      '                      size: AstryxButtonSize.sm,\n'
      '                      variant: AstryxButtonVariant.ghost,\n'
      '                      enabled: _mode == \'write\',\n'
      '                      onPressed: () => _wrap(mark[1]),\n'
      '                    ),\n'
      '                  const AstryxToolbarDivider(),\n'
      '                  AstryxMoreMenu(\n'
      '                    label: \'More formatting\',\n'
      '                    enabled: _mode == \'write\',\n'
      '                    entries: <AstryxMenuEntry>[\n'
      '                      AstryxMenuItem(\n'
      '                        label: \'Strikethrough\',\n'
      '                        onSelected: () => _wrap(\'~~\'),\n'
      '                      ),\n'
      '                      AstryxMenuItem(\n'
      '                        label: \'Quote\',\n'
      '                        onSelected: () => _wrap(\'\\n> \'),\n'
      '                      ),\n'
      '                    ],\n'
      '                  ),\n'
      '                ],\n'
      '              ),\n'
      '              AstryxSegmentedControl<String>(\n'
      '                label: \'Canvas\',\n'
      '                value: _mode,\n'
      '                size: AstryxButtonSize.sm,\n'
      '                onChanged: (value) => setState(() => _mode = value),\n'
      '                segments: const <AstryxSegment<String>>[\n'
      '                  AstryxSegment(value: \'write\', label: \'Write\'),\n'
      '                  AstryxSegment(value: \'preview\', label: \'Preview\'),\n'
      '                ],\n'
      '              ),\n'
      '            ],\n'
      '          ),\n'
      '        ],\n'
      '      ),\n'
      '      panel: AstryxVStack(\n'
      '        gap: AstryxSpacingToken.spacing5,\n'
      '        align: AstryxStackAlign.stretch,\n'
      '        children: <Widget>[\n'
      '          AstryxSection(\n'
      '            title: \'Document\',\n'
      '            level: 2,\n'
      '            child: AstryxVStack(\n'
      '              gap: AstryxSpacingToken.spacing3,\n'
      '              align: AstryxStackAlign.stretch,\n'
      '              children: <Widget>[\n'
      '                AstryxSelector<String>(\n'
      '                  label: \'Status\',\n'
      '                  value: _status,\n'
      '                  onChanged: (value) => setState(() {\n'
      '                    _status = value ?? _status;\n'
      '                    _dirty = true;\n'
      '                  }),\n'
      '                  options: const <AstryxSelectorOption<String>>[\n'
      '                    AstryxSelectorOption(value: \'draft\', label: \'Draft\'),\n'
      '                    AstryxSelectorOption(value: \'review\', label: \'In review\'),\n'
      '                    AstryxSelectorOption(\n'
      '                      value: \'published\',\n'
      '                      label: \'Published\',\n'
      '                    ),\n'
      '                  ],\n'
      '                ),\n'
      '                AstryxCheckboxList(\n'
      '                  label: \'Tags\',\n'
      '                  values: _tags,\n'
      '                  onChanged: (values) => setState(() {\n'
      '                    _tags\n'
      '                      ..clear()\n'
      '                      ..addAll(values);\n'
      '                    _dirty = true;\n'
      '                  }),\n'
      '                  options: const <AstryxCheckboxOption<String>>[\n'
      '                    AstryxCheckboxOption(value: \'deploys\', label: \'Deploys\'),\n'
      '                    AstryxCheckboxOption(value: \'oncall\', label: \'On-call\'),\n'
      '                    AstryxCheckboxOption(\n'
      '                      value: \'runbook\',\n'
      '                      label: \'Runbook\',\n'
      '                    ),\n'
      '                  ],\n'
      '                ),\n'
      '              ],\n'
      '            ),\n'
      '          ),\n'
      '          const AstryxDivider(),\n'
      '          AstryxSection(\n'
      '            title: \'History\',\n'
      '            level: 2,\n'
      '            child: AstryxMetadataList(\n'
      '              items: <AstryxMetadataItem>[\n'
      '                AstryxMetadataItem.text(\n'
      '                  label: \'Created\',\n'
      '                  value: \'12 March, by Grace Hopper\',\n'
      '                ),\n'
      '                AstryxMetadataItem.text(\n'
      '                  label: \'Last edited\',\n'
      '                  value: \'4 minutes ago, by you\',\n'
      '                ),\n'
      '                AstryxMetadataItem.text(label: \'Revisions\', value: \'31\'),\n'
      '              ],\n'
      '            ),\n'
      '          ),\n'
      '        ],\n'
      '      ),\n'
      '      footer: AstryxHStack(\n'
      '        gap: AstryxSpacingToken.spacing3,\n'
      '        justify: AstryxStackJustify.between,\n'
      '        mainAxisSize: MainAxisSize.max,\n'
      '        // The count and the two actions take a line each rather than the\n'
      '        // count being pushed off the start of the band.\n'
      '        wrap: true,\n'
      '        runGap: AstryxSpacingToken.spacing2,\n'
      '        children: <Widget>[\n'
      '          AstryxText(\n'
      '            \'\$_words words\',\n'
      '            type: AstryxTextType.supporting,\n'
      '            color: AstryxTextColor.secondary,\n'
      '          ),\n'
      '          AstryxHStack(\n'
      '            gap: AstryxSpacingToken.spacing2,\n'
      '            children: <Widget>[\n'
      '              AstryxButton(\n'
      '                label: \'Discard\',\n'
      '                size: AstryxButtonSize.sm,\n'
      '                enabled: _dirty,\n'
      '                onPressed: () => setState(() => _dirty = false),\n'
      '              ),\n'
      '              AstryxButton(\n'
      '                label: \'Save\',\n'
      '                variant: AstryxButtonVariant.primary,\n'
      '                size: AstryxButtonSize.sm,\n'
      '                enabled: _dirty,\n'
      '                onPressed: () => setState(() => _dirty = false),\n'
      '              ),\n'
      '            ],\n'
      '          ),\n'
      '        ],\n'
      '      ),\n'
      '      // The canvas, and the only thing on the screen that scrolls — in both\n'
      '      // modes, and for the same reason. `minLines` becomes a minimum in\n'
      '      // *pixels* once it has been measured, and it wins against the frame: a\n'
      '      // field asking for twelve lines inside a band with room for nine\n'
      '      // overflows rather than shrinking. Given a scroll view it keeps the\n'
      '      // height it asked for and the reader gets at the rest by scrolling.\n'
      '      child: SingleChildScrollView(\n'
      '        child: _mode == \'write\'\n'
      '            ? AstryxTextArea(\n'
      '                controller: _body,\n'
      '                label: \'Document body\',\n'
      '                labelHidden: true,\n'
      '                // Fewer lines on a phone all the same: a canvas that opens\n'
      '                // taller than the window it is in has put the Save button\n'
      '                // behind a scroll nobody was told about.\n'
      '                minLines: compact ? 6 : 12,\n'
      '                maxLines: 40,\n'
      '              )\n'
      '            : AstryxMarkdown(_body.text),\n'
      '      ),\n'
      '    );\n'
      '  }\n'
      '}\n',
  // examples/template_workspace_examples.dart
  'template_file_explorer':
      '/// One file in the listing.\n'
      'typedef ExplorerFile = ({String name, String kind, String size, String edited});\n'
      '\n'
      'class FileExplorerTemplate extends StatefulWidget {\n'
      '  const FileExplorerTemplate({super.key});\n'
      '\n'
      '  @override\n'
      '  State<FileExplorerTemplate> createState() => _FileExplorerTemplateState();\n'
      '}\n'
      '\n'
      'class _FileExplorerTemplateState extends State<FileExplorerTemplate> {\n'
      '  static const List<AstryxTreeNode> _folders = <AstryxTreeNode>[\n'
      '    AstryxTreeNode(\n'
      '      id: \'workspace\',\n'
      '      label: \'Workspace\',\n'
      '      leading: AstryxIcon(AstryxIconName.viewColumns),\n'
      '      children: <AstryxTreeNode>[\n'
      '        AstryxTreeNode(\n'
      '          id: \'runbooks\',\n'
      '          label: \'Runbooks\',\n'
      '          children: <AstryxTreeNode>[\n'
      '            AstryxTreeNode(id: \'runbooks_deploys\', label: \'Deploys\'),\n'
      '            AstryxTreeNode(id: \'runbooks_oncall\', label: \'On-call\'),\n'
      '          ],\n'
      '        ),\n'
      '        AstryxTreeNode(\n'
      '          id: \'postmortems\',\n'
      '          label: \'Post-mortems\',\n'
      '          trailing: AstryxBadge(\'4\'),\n'
      '        ),\n'
      '        AstryxTreeNode(id: \'archive\', label: \'Archive\', enabled: false),\n'
      '      ],\n'
      '    ),\n'
      '    AstryxTreeNode(\n'
      '      id: \'shared\',\n'
      '      label: \'Shared with me\',\n'
      '      leading: AstryxIcon(AstryxIconName.checkDouble),\n'
      '      children: <AstryxTreeNode>[\n'
      '        AstryxTreeNode(id: \'shared_sre\', label: \'SRE\'),\n'
      '        AstryxTreeNode(id: \'shared_security\', label: \'Security\'),\n'
      '      ],\n'
      '    ),\n'
      '  ];\n'
      '\n'
      '  static const Map<String, List<ExplorerFile>> _contents =\n'
      '      <String, List<ExplorerFile>>{\n'
      '        \'runbooks_deploys\': <ExplorerFile>[\n'
      '          (\n'
      '            name: \'rollback.md\',\n'
      '            kind: \'Markdown\',\n'
      '            size: \'4.2 kB\',\n'
      '            edited: \'11 minutes ago\',\n'
      '          ),\n'
      '          (\n'
      '            name: \'canary.md\',\n'
      '            kind: \'Markdown\',\n'
      '            size: \'8.9 kB\',\n'
      '            edited: \'Yesterday\',\n'
      '          ),\n'
      '          (\n'
      '            name: \'pipeline.yaml\',\n'
      '            kind: \'YAML\',\n'
      '            size: \'1.1 kB\',\n'
      '            edited: \'3 days ago\',\n'
      '          ),\n'
      '        ],\n'
      '        \'runbooks_oncall\': <ExplorerFile>[\n'
      '          (\n'
      '            name: \'escalation.md\',\n'
      '            kind: \'Markdown\',\n'
      '            size: \'2.4 kB\',\n'
      '            edited: \'Last week\',\n'
      '          ),\n'
      '          (\n'
      '            name: \'rota-2026.csv\',\n'
      '            kind: \'CSV\',\n'
      '            size: \'19 kB\',\n'
      '            edited: \'Last week\',\n'
      '          ),\n'
      '        ],\n'
      '        \'postmortems\': <ExplorerFile>[\n'
      '          (\n'
      '            name: \'4102-latency.md\',\n'
      '            kind: \'Markdown\',\n'
      '            size: \'22 kB\',\n'
      '            edited: \'2 hours ago\',\n'
      '          ),\n'
      '        ],\n'
      '      };\n'
      '\n'
      '  static const Map<String, String> _names = <String, String>{\n'
      '    \'workspace\': \'Workspace\',\n'
      '    \'runbooks\': \'Runbooks\',\n'
      '    \'runbooks_deploys\': \'Deploys\',\n'
      '    \'runbooks_oncall\': \'On-call\',\n'
      '    \'postmortems\': \'Post-mortems\',\n'
      '    \'shared\': \'Shared with me\',\n'
      '    \'shared_sre\': \'SRE\',\n'
      '    \'shared_security\': \'Security\',\n'
      '  };\n'
      '\n'
      '  String _folder = \'runbooks_deploys\';\n'
      '  Set<Object> _selected = <Object>{};\n'
      '\n'
      '  List<ExplorerFile> get _files => _contents[_folder] ?? const <ExplorerFile>[];\n'
      '\n'
      '  @override\n'
      '  Widget build(BuildContext context) {\n'
      '    final files = _files;\n'
      '\n'
      '    return SizedBox(\n'
      '      height: 520,\n'
      '      child: AstryxLayout(\n'
      '        scrollable: false,\n'
      '        // The tree is at the reading-start edge, because it is where the\n'
      '        // reader came *from* rather than what they are looking at.\n'
      '        panelSide: AstryxLayoutPanelSide.start,\n'
      '        panelWidth: 240,\n'
      '        header: AstryxHStack(\n'
      '          gap: AstryxSpacingToken.spacing3,\n'
      '          justify: AstryxStackJustify.between,\n'
      '          mainAxisSize: MainAxisSize.max,\n'
      '          wrap: true,\n'
      '          runGap: AstryxSpacingToken.spacing2,\n'
      '          children: <Widget>[\n'
      '            AstryxVStack(\n'
      '              gap: AstryxSpacingToken.spacing1,\n'
      '              children: <Widget>[\n'
      '                AstryxHeading(_names[_folder] ?? \'Files\', level: 1),\n'
      '                AstryxText(\n'
      '                  \'\${files.length} items\',\n'
      '                  type: AstryxTextType.supporting,\n'
      '                  color: AstryxTextColor.secondary,\n'
      '                ),\n'
      '              ],\n'
      '            ),\n'
      '            AstryxButton(\n'
      '              label: \'Upload\',\n'
      '              variant: AstryxButtonVariant.primary,\n'
      '              size: AstryxButtonSize.sm,\n'
      '              onPressed: () {},\n'
      '            ),\n'
      '          ],\n'
      '        ),\n'
      '        // The tree is one tab stop and the arrows do the rest: Right opens a\n'
      '        // branch and steps into it, Left closes it and steps out.\n'
      '        panel: AstryxTreeList(\n'
      '          label: \'Folders\',\n'
      '          nodes: _folders,\n'
      '          initiallyExpanded: const <String>{\'workspace\', \'runbooks\'},\n'
      '          density: AstryxItemDensity.compact,\n'
      '          selected: _folder,\n'
      '          onSelectedChanged: (id) => setState(() {\n'
      '            _folder = id;\n'
      '            _selected = <Object>{};\n'
      '          }),\n'
      '        ),\n'
      '        child: AstryxTable<ExplorerFile>(\n'
      '          label: \'Files in \${_names[_folder]}\',\n'
      '          keyOf: (row) => row.name,\n'
      '          rowLabelOf: (row) => row.name,\n'
      '          density: AstryxTableDensity.compact,\n'
      '          selectionMode: AstryxTableSelectionMode.multiple,\n'
      '          selected: _selected,\n'
      '          onSelectionChanged: (value) => setState(() => _selected = value),\n'
      '          onRowPressed: (_) {},\n'
      '          maxHeight: 340,\n'
      '          emptyState: AstryxEmptyState(\n'
      '            title: \'Nothing in this folder\',\n'
      '            description: \'Drop a file here, or pick another folder.\',\n'
      '            size: AstryxEmptyStateSize.compact,\n'
      '            actions: <Widget>[\n'
      '              AstryxButton(\n'
      '                label: \'Upload\',\n'
      '                size: AstryxButtonSize.sm,\n'
      '                onPressed: () {},\n'
      '              ),\n'
      '            ],\n'
      '          ),\n'
      '          columns: <AstryxTableColumn<ExplorerFile>>[\n'
      '            AstryxTableColumn<ExplorerFile>(\n'
      '              id: \'name\',\n'
      '              header: \'Name\',\n'
      '              compare: (a, b) => a.name.compareTo(b.name),\n'
      '              cellBuilder: (context, row) => AstryxHStack(\n'
      '                gap: AstryxSpacingToken.spacing2,\n'
      '                children: <Widget>[\n'
      '                  const AstryxIcon(AstryxIconName.copy),\n'
      '                  Flexible(child: AstryxText(row.name, maxLines: 1)),\n'
      '                ],\n'
      '              ),\n'
      '            ),\n'
      '            AstryxTableColumn<ExplorerFile>(\n'
      '              id: \'kind\',\n'
      '              header: \'Kind\',\n'
      '              width: const AstryxTableColumnWidth.fixed(110),\n'
      '              cellBuilder: (context, row) => AstryxBadge(row.kind),\n'
      '            ),\n'
      '            AstryxTableColumn<ExplorerFile>(\n'
      '              id: \'size\',\n'
      '              header: \'Size\',\n'
      '              width: const AstryxTableColumnWidth.fixed(90),\n'
      '              alignment: AstryxTableAlignment.end,\n'
      '              cellBuilder: (context, row) =>\n'
      '                  AstryxText(row.size, tabularNumbers: true, maxLines: 1),\n'
      '            ),\n'
      '            AstryxTableColumn<ExplorerFile>(\n'
      '              id: \'edited\',\n'
      '              header: \'Edited\',\n'
      '              width: const AstryxTableColumnWidth.fixed(130),\n'
      '              cellBuilder: (context, row) => AstryxText(\n'
      '                row.edited,\n'
      '                type: AstryxTextType.supporting,\n'
      '                color: AstryxTextColor.secondary,\n'
      '                maxLines: 1,\n'
      '              ),\n'
      '            ),\n'
      '          ],\n'
      '          rows: files,\n'
      '          // Always visible, never on hover: touch has no hover, and the\n'
      '          // density system suppresses hover styling there.\n'
      '          rowActionsBuilder: (context, row) => AstryxMoreMenu(\n'
      '            label: \'Actions for \${row.name}\',\n'
      '            entries: <AstryxMenuEntry>[\n'
      '              AstryxMenuItem(label: \'Rename\', onSelected: () {}),\n'
      '              AstryxMenuItem(label: \'Download\', onSelected: () {}),\n'
      '              const AstryxMenuDivider(),\n'
      '              AstryxMenuItem(\n'
      '                label: \'Delete\',\n'
      '                destructive: true,\n'
      '                onSelected: () {},\n'
      '              ),\n'
      '            ],\n'
      '          ),\n'
      '        ),\n'
      '      ),\n'
      '    );\n'
      '  }\n'
      '}\n',
  // examples/template_workspace_examples.dart
  'template_ide':
      'class IdeTemplate extends StatefulWidget {\n'
      '  const IdeTemplate({super.key});\n'
      '\n'
      '  @override\n'
      '  State<IdeTemplate> createState() => _IdeTemplateState();\n'
      '}\n'
      '\n'
      'class _IdeTemplateState extends State<IdeTemplate> {\n'
      '  static const List<AstryxTreeNode> _nodes = <AstryxTreeNode>[\n'
      '    AstryxTreeNode(\n'
      '      id: \'lib\',\n'
      '      label: \'lib\',\n'
      '      children: <AstryxTreeNode>[\n'
      '        AstryxTreeNode(\n'
      '          id: \'components\',\n'
      '          label: \'components\',\n'
      '          children: <AstryxTreeNode>[\n'
      '            AstryxTreeNode(id: \'card.dart\', label: \'card.dart\'),\n'
      '            AstryxTreeNode(\n'
      '              id: \'table.dart\',\n'
      '              label: \'table.dart\',\n'
      '              trailing: AstryxStatusDot(\n'
      '                AstryxStatusDotVariant.warning,\n'
      '                label: \'2 problems\',\n'
      '              ),\n'
      '            ),\n'
      '          ],\n'
      '        ),\n'
      '        AstryxTreeNode(id: \'astryx_ui.dart\', label: \'astryx_ui.dart\'),\n'
      '      ],\n'
      '    ),\n'
      '    AstryxTreeNode(\n'
      '      id: \'test\',\n'
      '      label: \'test\',\n'
      '      children: <AstryxTreeNode>[\n'
      '        AstryxTreeNode(id: \'table_test.dart\', label: \'table_test.dart\'),\n'
      '      ],\n'
      '    ),\n'
      '  ];\n'
      '\n'
      '  static const Map<String, String> _sources = <String, String>{\n'
      '    \'card.dart\': \'\'\'\n'
      'class AstryxCard extends StatelessWidget {\n'
      '  const AstryxCard({\n'
      '    required this.child,\n'
      '    this.header,\n'
      '    this.footer,\n'
      '    this.onPressed,\n'
      '  });\n'
      '\n'
      '  /// A non-null [onPressed] makes the whole card a button.\n'
      '  final VoidCallback? onPressed;\n'
      '}\'\'\',\n'
      '    \'table.dart\': \'\'\'\n'
      '/// A column is sortable when — and only when — it has a [compare].\n'
      'class AstryxTableColumn<T> {\n'
      '  const AstryxTableColumn({\n'
      '    required this.id,\n'
      '    required this.header,\n'
      '    required this.cellBuilder,\n'
      '    this.compare,\n'
      '  });\n'
      '\n'
      '  final int Function(T a, T b)? compare;\n'
      '}\'\'\',\n'
      '    \'table_test.dart\': \'\'\'\n'
      'void main() {\n'
      '  testWidgets(\'a column without compare is not sortable\', (tester) async {\n'
      '    await tester.pumpWidget(const _Harness());\n'
      '    expect(find.byIcon(AstryxIconName.arrowsUpDown), findsNothing);\n'
      '  });\n'
      '}\'\'\',\n'
      '  };\n'
      '\n'
      '  /// The files with an editor open, in the order they were opened.\n'
      '  final List<String> _open = <String>[\'card.dart\', \'table.dart\'];\n'
      '\n'
      '  String _file = \'table.dart\';\n'
      '  String _drawer = \'problems\';\n'
      '\n'
      '  /// The two regions the reader may resize.\n'
      '  ///\n'
      '  /// A handle reports a size; the caller is what remembers it.\n'
      '  double _treeWidth = 200;\n'
      '  double _drawerHeight = 132;\n'
      '\n'
      '  @override\n'
      '  Widget build(BuildContext context) {\n'
      '    // A bare `Column`, not an `AstryxCard`. A card sizes itself to its body,\n'
      '    // so it hands that body an unbounded height — and every region here is an\n'
      '    // `Expanded` or a fixed band measured against the frame. The bounded\n'
      '    // `SizedBox` is what the whole layout is built against.\n'
      '    //\n'
      '    // The `LayoutBuilder` is what decides whether there are three regions or\n'
      '    // one. A resizable tree needs a window to be resized *within*: at 390\n'
      '    // logical pixels the handle\'s own minimum of 140 is more than a third of\n'
      '    // the screen, and what is left is not a narrow editor but no editor.\n'
      '    return LayoutBuilder(\n'
      '      builder: (context, constraints) {\n'
      '        final compact = constraints.maxWidth < 640;\n'
      '\n'
      '        return SizedBox(\n'
      '          // The bands do not shrink — a tab strip and a status bar cost what\n'
      '          // they cost — so a narrow frame is a taller one rather than an\n'
      '          // overflowing one.\n'
      '          height: compact ? 620 : 520,\n'
      '          child: Column(\n'
      '            crossAxisAlignment: CrossAxisAlignment.stretch,\n'
      '            children: <Widget>[\n'
      '              // Narrow, the tree is a disclosure above the editor rather than a\n'
      '              // column beside it: the same nodes, the same selection, and the\n'
      '              // editor keeps the whole width once a file is chosen.\n'
      '              if (compact) ...<Widget>[\n'
      '                AstryxCollapsible(\n'
      '                  title: \'Explorer\',\n'
      '                  child: ConstrainedBox(\n'
      '                    constraints: const BoxConstraints(maxHeight: 180),\n'
      '                    child: SingleChildScrollView(child: _tree(context)),\n'
      '                  ),\n'
      '                ),\n'
      '                const AstryxDivider(),\n'
      '                Expanded(child: _editor(context)),\n'
      '              ] else\n'
      '                Expanded(\n'
      '                  child: Row(\n'
      '                    crossAxisAlignment: CrossAxisAlignment.stretch,\n'
      '                    children: <Widget>[\n'
      '                      SizedBox(\n'
      '                        width: _treeWidth,\n'
      '                        child: AstryxVStack(\n'
      '                          gap: AstryxSpacingToken.spacing0,\n'
      '                          align: AstryxStackAlign.stretch,\n'
      '                          children: <Widget>[\n'
      '                            const Padding(\n'
      '                              padding: EdgeInsets.all(8),\n'
      '                              child: AstryxText(\n'
      '                                \'Explorer\',\n'
      '                                type: AstryxTextType.supporting,\n'
      '                                color: AstryxTextColor.secondary,\n'
      '                              ),\n'
      '                            ),\n'
      '                            Expanded(\n'
      '                              child: SingleChildScrollView(\n'
      '                                child: _tree(context),\n'
      '                              ),\n'
      '                            ),\n'
      '                          ],\n'
      '                        ),\n'
      '                      ),\n'
      '                      // Tab reaches the handle and the arrows move it. A\n'
      '                      // divider only a pointer can drag is a layout only some\n'
      '                      // people can use, which is the part hand-rolled\n'
      '                      // splitters always miss.\n'
      '                      AstryxResizeHandle(\n'
      '                        label: \'Resize the file tree\',\n'
      '                        size: _treeWidth,\n'
      '                        min: 140,\n'
      '                        max: 320,\n'
      '                        onResize: (width) => setState(() => _treeWidth = width),\n'
      '                      ),\n'
      '                      Expanded(child: _editor(context)),\n'
      '                    ],\n'
      '                  ),\n'
      '                ),\n'
      '              // Nothing to drag on a touch screen with no pointer to spare, so\n'
      '              // narrow the drawer is a fixed band and the handle goes away\n'
      '              // rather than becoming a control that cannot be used.\n'
      '              if (!compact)\n'
      '                AstryxResizeHandle(\n'
      '                  label: \'Resize the panel\',\n'
      '                  edge: AstryxResizeEdge.bottom,\n'
      '                  size: _drawerHeight,\n'
      '                  min: 80,\n'
      '                  max: 260,\n'
      '                  onResize: (height) => setState(() => _drawerHeight = height),\n'
      '                )\n'
      '              else\n'
      '                const AstryxDivider(),\n'
      '              SizedBox(\n'
      '                height: compact ? 132 : _drawerHeight,\n'
      '                child: _panel(context),\n'
      '              ),\n'
      '              const AstryxDivider(),\n'
      '              _statusBar(context, compact: compact),\n'
      '            ],\n'
      '          ),\n'
      '        );\n'
      '      },\n'
      '    );\n'
      '  }\n'
      '\n'
      '  /// The file tree, shared by the column and the disclosure.\n'
      '  Widget _tree(BuildContext context) => AstryxTreeList(\n'
      '    label: \'Files\',\n'
      '    nodes: _nodes,\n'
      '    initiallyExpanded: const <String>{\'lib\', \'components\'},\n'
      '    density: AstryxItemDensity.compact,\n'
      '    selected: _file,\n'
      '    onSelectedChanged: _openFile,\n'
      '  );\n'
      '\n'
      '  /// Opens [id] in a tab, if it is a file rather than a folder.\n'
      '  void _openFile(String id) {\n'
      '    if (!_sources.containsKey(id)) return;\n'
      '    setState(() {\n'
      '      if (!_open.contains(id)) _open.add(id);\n'
      '      _file = id;\n'
      '    });\n'
      '  }\n'
      '\n'
      '  /// The tab strip and the surface under it.\n'
      '  Widget _editor(BuildContext context) {\n'
      '    return AstryxVStack(\n'
      '      gap: AstryxSpacingToken.spacing0,\n'
      '      align: AstryxStackAlign.stretch,\n'
      '      children: <Widget>[\n'
      '        // The strip reports a value and owns no panel, so which file is showing\n'
      '        // is one field of state — and closing a tab is a list edit, not a\n'
      '        // panel-stack surgery.\n'
      '        AstryxHStack(\n'
      '          gap: AstryxSpacingToken.spacing1,\n'
      '          mainAxisSize: MainAxisSize.max,\n'
      '          children: <Widget>[\n'
      '            Flexible(\n'
      '              child: AstryxTabList<String>(\n'
      '                label: \'Open files\',\n'
      '                value: _file,\n'
      '                size: AstryxTabSize.sm,\n'
      '                onChanged: (value) => setState(() => _file = value),\n'
      '                tabs: <AstryxTab<String>>[\n'
      '                  for (final file in _open) AstryxTab(value: file, label: file),\n'
      '                ],\n'
      '              ),\n'
      '            ),\n'
      '            AstryxMoreMenu(\n'
      '              label: \'Editor actions\',\n'
      '              entries: <AstryxMenuEntry>[\n'
      '                AstryxMenuItem(\n'
      '                  label: \'Close \$_file\',\n'
      '                  onSelected: () => setState(() {\n'
      '                    _open.remove(_file);\n'
      '                    _file = _open.isEmpty ? \'\' : _open.last;\n'
      '                  }),\n'
      '                ),\n'
      '                AstryxMenuItem(\n'
      '                  label: \'Close all\',\n'
      '                  onSelected: () => setState(() {\n'
      '                    _open.clear();\n'
      '                    _file = \'\';\n'
      '                  }),\n'
      '                ),\n'
      '              ],\n'
      '            ),\n'
      '          ],\n'
      '        ),\n'
      '        // The surface scrolls rather than being squeezed: a code block handed a\n'
      '        // tight height has nowhere to put the lines that do not fit.\n'
      '        Expanded(\n'
      '          child: SingleChildScrollView(\n'
      '            padding: const EdgeInsets.all(8),\n'
      '            child: _open.isEmpty\n'
      '                ? const AstryxEmptyState(\n'
      '                    title: \'No file open\',\n'
      '                    description: \'Choose one from the tree on the left.\',\n'
      '                    size: AstryxEmptyStateSize.compact,\n'
      '                  )\n'
      '                : AstryxCodeBlock(\n'
      '                    _sources[_file] ?? \'\',\n'
      '                    language: \'dart\',\n'
      '                    showLineNumbers: true,\n'
      '                  ),\n'
      '          ),\n'
      '        ),\n'
      '      ],\n'
      '    );\n'
      '  }\n'
      '\n'
      '  /// The drawer under the editor: problems, or the run log.\n'
      '  Widget _panel(BuildContext context) {\n'
      '    return AstryxVStack(\n'
      '      gap: AstryxSpacingToken.spacing0,\n'
      '      align: AstryxStackAlign.stretch,\n'
      '      children: <Widget>[\n'
      '        AstryxTabList<String>(\n'
      '          label: \'Panel\',\n'
      '          value: _drawer,\n'
      '          size: AstryxTabSize.sm,\n'
      '          onChanged: (value) => setState(() => _drawer = value),\n'
      '          tabs: const <AstryxTab<String>>[\n'
      '            AstryxTab(\n'
      '              value: \'problems\',\n'
      '              label: \'Problems\',\n'
      '              badge: AstryxBadge(\'2\'),\n'
      '            ),\n'
      '            AstryxTab(value: \'output\', label: \'Output\'),\n'
      '          ],\n'
      '        ),\n'
      '        Expanded(\n'
      '          child: SingleChildScrollView(\n'
      '            padding: const EdgeInsets.all(8),\n'
      '            child: _drawer == \'problems\'\n'
      '                ? AstryxList(\n'
      '                    label: \'Problems\',\n'
      '                    density: AstryxItemDensity.compact,\n'
      '                    children: <Widget>[\n'
      '                      for (final problem in const <List<String>>[\n'
      '                        <String>[\n'
      '                          \'table.dart:41\',\n'
      '                          \'Unused import: dart:math\',\n'
      '                        ],\n'
      '                        <String>[\n'
      '                          \'table.dart:88\',\n'
      '                          \'compare is null, so this column is not sortable\',\n'
      '                        ],\n'
      '                      ])\n'
      '                        AstryxItem(\n'
      '                          label: problem[1],\n'
      '                          description: problem[0],\n'
      '                          leading: const AstryxIcon(\n'
      '                            AstryxIconName.warning,\n'
      '                            color: AstryxIconColor.warning,\n'
      '                          ),\n'
      '                          onPressed: () {},\n'
      '                        ),\n'
      '                    ],\n'
      '                  )\n'
      '                : const AstryxCodeBlock(\n'
      '                    \'\\\$ dart test\\n\'\n'
      '                    \'00:02 +14: All tests passed!\',\n'
      '                    showCopy: false,\n'
      '                  ),\n'
      '          ),\n'
      '        ),\n'
      '      ],\n'
      '    );\n'
      '  }\n'
      '\n'
      '  /// The band along the bottom: branch, problems, and where the caret is.\n'
      '  ///\n'
      '  /// Narrow, the caret position goes rather than being squeezed: it is the one\n'
      '  /// item here a reader can get from the editor itself, and a status bar that\n'
      '  /// wraps onto two lines has stopped being a band.\n'
      '  Widget _statusBar(BuildContext context, {required bool compact}) {\n'
      '    return Padding(\n'
      '      padding: const EdgeInsets.symmetric(horizontal: 12, vertical: 6),\n'
      '      child: AstryxHStack(\n'
      '        gap: compact\n'
      '            ? AstryxSpacingToken.spacing3\n'
      '            : AstryxSpacingToken.spacing4,\n'
      '        mainAxisSize: MainAxisSize.max,\n'
      '        children: <Widget>[\n'
      '          const AstryxStatusDot(\n'
      '            AstryxStatusDotVariant.success,\n'
      '            label: \'Analyser is clean\',\n'
      '          ),\n'
      '          const Flexible(\n'
      '            child: AstryxText(\n'
      '              \'main\',\n'
      '              type: AstryxTextType.supporting,\n'
      '              color: AstryxTextColor.secondary,\n'
      '              maxLines: 1,\n'
      '            ),\n'
      '          ),\n'
      '          const Spacer(),\n'
      '          if (!compact)\n'
      '            const AstryxText(\n'
      '              \'Ln 41, Col 12\',\n'
      '              type: AstryxTextType.supporting,\n'
      '              color: AstryxTextColor.secondary,\n'
      '              tabularNumbers: true,\n'
      '            ),\n'
      '          AstryxText(\n'
      '            _file.isEmpty ? \'—\' : \'Dart\',\n'
      '            type: AstryxTextType.supporting,\n'
      '            color: AstryxTextColor.secondary,\n'
      '          ),\n'
      '        ],\n'
      '      ),\n'
      '    );\n'
      '  }\n'
      '}\n',
  // examples/text_area_examples.dart
  'text_area_demo':
      'class TextAreaDemoExample extends StatelessWidget {\n'
      '  const TextAreaDemoExample({super.key});\n'
