  // examples/text_area_examples.dart
  'text_area_lines':
      'class TextAreaLinesExample extends StatelessWidget {\n'
      '  const TextAreaLinesExample({super.key});\n'
      '\n'
      '  @override\n'
      '  Widget build(BuildContext context) {\n'
      '    // The field grows from `minLines` and stops at `maxLines`, then scrolls.\n'
      '    return const SizedBox(\n'
      '      width: 380,\n'
      '      child: AstryxVStack(\n'
      '        gap: AstryxSpacingToken.spacing3,\n'
      '        align: AstryxStackAlign.stretch,\n'
      '        children: <Widget>[\n'
      '          AstryxTextArea(\n'
      '            label: \'Two to four lines\',\n'
      '            minLines: 2,\n'
      '            maxLines: 4,\n'
      '            placeholder: \'Type until it stops growing…\',\n'
      '          ),\n'
      '          AstryxTextArea(\n'
      '            label: \'Fixed at four\',\n'
      '            minLines: 4,\n'
      '            maxLines: 4,\n'
      '          ),\n'
      '        ],\n'
      '      ),\n'
      '    );\n'
      '  }\n'
      '}\n',
  // examples/text_area_examples.dart
  'text_area_counted':
      'class TextAreaCountedExample extends StatefulWidget {\n'
      '  const TextAreaCountedExample({super.key});\n'
      '\n'
      '  @override\n'
      '  State<TextAreaCountedExample> createState() => _TextAreaCountedExampleState();\n'
      '}\n'
      '\n'
      'class _TextAreaCountedExampleState extends State<TextAreaCountedExample> {\n'
      '  static const int _limit = 140;\n'
      '  final TextEditingController _controller = TextEditingController();\n'
      '\n'
      '  @override\n'
      '  void dispose() {\n'
      '    _controller.dispose();\n'
      '    super.dispose();\n'
      '  }\n'
      '\n'
      '  @override\n'
      '  Widget build(BuildContext context) {\n'
      '    final remaining = _limit - _controller.text.length;\n'
      '\n'
      '    return SizedBox(\n'
      '      width: 380,\n'
      '      child: AstryxTextArea(\n'
      '        label: \'Status message\',\n'
      '        controller: _controller,\n'
      '        maxLength: _limit,\n'
      '        minLines: 2,\n'
      '        maxLines: 4,\n'
      '        description: \'\$remaining characters left\',\n'
      '        status: remaining <= 20\n'
      '            ? const AstryxFieldStatus.warning(\'Nearly at the limit\')\n'
      '            : null,\n'
      '        onChanged: (_) => setState(() {}),\n'
      '      ),\n'
      '    );\n'
      '  }\n'
      '}\n',
  // examples/text_examples.dart
  'text_demo':
      'class TextDemoExample extends StatelessWidget {\n'
      '  const TextDemoExample({super.key});\n'
      '\n'
