  // examples/themes_examples.dart
  'themes_gallery':
      'class ThemesGalleryExample extends StatelessWidget {\n'
      '  const ThemesGalleryExample({super.key});\n'
      '\n'
      '  @override\n'
      '  Widget build(BuildContext context) {\n'
      '    return AstryxGrid(\n'
      '      minWidth: 210,\n'
      '      gap: AstryxSpacingToken.spacing3,\n'
      '      children: <Widget>[\n'
      '        for (final (name, theme) in galleryThemes)\n'
      '          AstryxThemeProvider(\n'
      '            theme: theme,\n'
      '            // Each cell paints its own page background rather than borrowing\n'
      '            // the site\'s: `--color-background-body` is the first thing that\n'
      '            // separates one theme from the next, and a gallery that hides it\n'
      '            // would be comparing seven cards on one page.\n'
      '            child: Builder(\n'
      '              builder: (context) {\n'
      '                final t = AstryxTheme.of(context);\n'
      '\n'
      '                return DecoratedBox(\n'
      '                  decoration: BoxDecoration(\n'
      '                    color: t.color(AstryxColorToken.backgroundBody),\n'
      '                    borderRadius: t.borderRadius(AstryxRadiusToken.container),\n'
      '                    border: Border.all(\n'
      '                      color: t.color(AstryxColorToken.border),\n'
      '                    ),\n'
      '                  ),\n'
      '                  child: Padding(\n'
      '                    padding: EdgeInsets.all(\n'
      '                      t.spacing(AstryxSpacingToken.spacing3),\n'
      '                    ),\n'
      '                    child: AstryxVStack(\n'
      '                      gap: AstryxSpacingToken.spacing2,\n'
      '                      align: AstryxStackAlign.stretch,\n'
      '                      children: <Widget>[\n'
      '                        AstryxHeading(name, level: 4),\n'
      '                        const AstryxText(\n'
      '                          \'Body copy, on the page.\',\n'
      '                          type: AstryxTextType.supporting,\n'
      '                          color: AstryxTextColor.secondary,\n'
      '                        ),\n'
      '                        AstryxButton(\n'
      '                          label: \'Primary\',\n'
      '                          variant: AstryxButtonVariant.primary,\n'
      '                          size: AstryxButtonSize.sm,\n'
      '                          onPressed: () {},\n'
      '                        ),\n'
      '                      ],\n'
      '                    ),\n'
      '                  ),\n'
      '                );\n'
      '              },\n'
      '            ),\n'
      '          ),\n'
      '      ],\n'
      '    );\n'
      '  }\n'
      '}\n',
  // examples/themes_examples.dart
  'themes_light_dark':
      'class ThemesLightDarkExample extends StatelessWidget {\n'
      '  const ThemesLightDarkExample({super.key});\n'
      '\n'
      '  @override\n'
      '  Widget build(BuildContext context) {\n'
      '    return AstryxGrid(\n'
      '      minWidth: 190,\n'
      '      gap: AstryxSpacingToken.spacing3,\n'
      '      children: <Widget>[\n'
      '        for (final (name, theme) in galleryThemes)\n'
      '          AstryxVStack(\n'
      '            gap: AstryxSpacingToken.spacing1,\n'
      '            align: AstryxStackAlign.stretch,\n'
      '            children: <Widget>[\n'
      '              AstryxText(name, type: AstryxTextType.label),\n'
      '              // A colour token is not a colour: it is a `light-dark()` pair,\n'
      '              // and the mode picks a half. Both halves come from the one\n'
      '              // definition — dark mode is not a second theme to maintain.\n'
      '              for (final mode in <AstryxColorMode>[\n'
      '                AstryxColorMode.light,\n'
      '                AstryxColorMode.dark,\n'
      '              ])\n'
      '                AstryxThemeProvider(\n'
      '                  theme: theme,\n'
      '                  mode: mode,\n'
      '                  child: Builder(\n'
      '                    builder: (context) {\n'
      '                      final t = AstryxTheme.of(context);\n'
      '\n'
      '                      return DecoratedBox(\n'
      '                        decoration: BoxDecoration(\n'
      '                          color: t.color(AstryxColorToken.backgroundBody),\n'
      '                          border: Border.all(\n'
      '                            color: t.color(AstryxColorToken.border),\n'
      '                          ),\n'
      '                        ),\n'
      '                        child: Padding(\n'
      '                          padding: EdgeInsets.all(\n'
      '                            t.spacing(AstryxSpacingToken.spacing2),\n'
      '                          ),\n'
      '                          child: AstryxHStack(\n'
      '                            gap: AstryxSpacingToken.spacing2,\n'
      '                            children: <Widget>[\n'
      '                              DecoratedBox(\n'
      '                                decoration: BoxDecoration(\n'
      '                                  color: t.color(AstryxColorToken.accent),\n'
      '                                  borderRadius: t.borderRadius(\n'
      '                                    AstryxRadiusToken.inner,\n'
      '                                  ),\n'
      '                                ),\n'
      '                                child: const SizedBox(width: 18, height: 18),\n'
      '                              ),\n'
      '                              AstryxText(\n'
      '                                mode.name,\n'
      '                                type: AstryxTextType.supporting,\n'
      '                              ),\n'
      '                            ],\n'
      '                          ),\n'
      '                        ),\n'
      '                      );\n'
      '                    },\n'
      '                  ),\n'
      '                ),\n'
      '            ],\n'
      '          ),\n'
      '      ],\n'
      '    );\n'
      '  }\n'
      '}\n',
  // examples/themes_examples.dart
  'themes_swatches':
      'class ThemesSwatchesExample extends StatelessWidget {\n'
      '  const ThemesSwatchesExample({super.key});\n'
      '\n'
      '  @override\n'
      '  Widget build(BuildContext context) {\n'
      '    return AstryxVStack(\n'
      '      gap: AstryxSpacingToken.spacing2,\n'
      '      align: AstryxStackAlign.stretch,\n'
      '      children: <Widget>[\n'
      '        for (final (name, theme) in galleryThemes)\n'
      '          Row(\n'
      '            children: <Widget>[\n'
      '              SizedBox(\n'
      '                width: 84,\n'
      '                child: AstryxText(\n'
      '                  name,\n'
      '                  type: AstryxTextType.code,\n'
      '                  color: AstryxTextColor.secondary,\n'
      '                  maxLines: 1,\n'
      '                ),\n'
      '              ),\n'
      '              // The swatches resolve inside the theme they belong to. Reading a\n'
      '              // token is the only way to sample one: the values live in the\n'
      '              // resolved token set, not in a constant anybody can import.\n'
      '              Expanded(\n'
      '                child: AstryxThemeProvider(\n'
      '                  theme: theme,\n'
      '                  child: Builder(\n'
      '                    builder: (context) {\n'
      '                      final t = AstryxTheme.of(context);\n'
      '\n'
      '                      return Row(\n'
      '                        children: <Widget>[\n'
      '                          for (final token in gallerySwatchTokens)\n'
      '                            Expanded(\n'
      '                              child: Padding(\n'
      '                                padding: const EdgeInsets.only(right: 4),\n'
      '                                child: DecoratedBox(\n'
      '                                  decoration: BoxDecoration(\n'
      '                                    color: t.color(token),\n'
      '                                    borderRadius: t.borderRadius(\n'
      '                                      AstryxRadiusToken.inner,\n'
      '                                    ),\n'
      '                                    border: Border.all(\n'
      '                                      color: t.color(AstryxColorToken.border),\n'
      '                                    ),\n'
      '                                  ),\n'
      '                                  child: const SizedBox(height: 24),\n'
      '                                ),\n'
      '                              ),\n'
      '                            ),\n'
      '                        ],\n'
      '                      );\n'
      '                    },\n'
      '                  ),\n'
      '                ),\n'
      '              ),\n'
      '            ],\n'
      '          ),\n'
      '      ],\n'
      '    );\n'
      '  }\n'
      '}\n',
  // examples/themes_examples.dart
  'themes_components':
      'class ThemesComponentsExample extends StatelessWidget {\n'
