  // examples/theming_examples.dart
  'theming_tokens':
      'class ThemingTokensExample extends StatelessWidget {\n'
      '  const ThemingTokensExample({super.key});\n'
      '\n'
      '  /// The tokens a page reaches for most often. There are 100-odd in total.\n'
      '  static const List<AstryxColorToken> _tokens = <AstryxColorToken>[\n'
      '    AstryxColorToken.accent,\n'
      '    AstryxColorToken.accentMuted,\n'
      '    AstryxColorToken.backgroundBody,\n'
      '    AstryxColorToken.backgroundSurface,\n'
      '    AstryxColorToken.backgroundCard,\n'
      '    AstryxColorToken.backgroundMuted,\n'
      '    AstryxColorToken.border,\n'
      '    AstryxColorToken.borderEmphasized,\n'
      '    AstryxColorToken.success,\n'
      '    AstryxColorToken.warning,\n'
      '    AstryxColorToken.error,\n'
      '    AstryxColorToken.backgroundInverted,\n'
      '  ];\n'
      '\n'
      '  @override\n'
      '  Widget build(BuildContext context) {\n'
      '    final theme = AstryxTheme.of(context);\n'
      '\n'
      '    return AstryxGrid(\n'
      '      minWidth: 180,\n'
      '      gap: AstryxSpacingToken.spacing2,\n'
      '      children: <Widget>[\n'
      '        for (final token in _tokens)\n'
      '          AstryxHStack(\n'
      '            gap: AstryxSpacingToken.spacing2,\n'
      '            children: <Widget>[\n'
      '              DecoratedBox(\n'
      '                decoration: BoxDecoration(\n'
      '                  color: theme.color(token),\n'
      '                  borderRadius: theme.borderRadius(AstryxRadiusToken.inner),\n'
      '                  border: Border.all(\n'
      '                    color: theme.color(AstryxColorToken.border),\n'
      '                  ),\n'
      '                ),\n'
      '                child: const SizedBox(width: 24, height: 24),\n'
      '              ),\n'
      '              Flexible(\n'
      '                child: AstryxText(\n'
      '                  token.name,\n'
      '                  type: AstryxTextType.supporting,\n'
      '                  color: AstryxTextColor.secondary,\n'
      '                  maxLines: 1,\n'
      '                ),\n'
      '              ),\n'
      '            ],\n'
      '          ),\n'
      '      ],\n'
      '    );\n'
      '  }\n'
      '}\n',
