  'time_input_demo':
      'class TimeInputDemoExample extends StatefulWidget {\n'
      '  const TimeInputDemoExample({super.key});\n'
      '\n'
      '  @override\n'
      '  State<TimeInputDemoExample> createState() => _TimeInputDemoExampleState();\n'
      '}\n'
      '\n'
      'class _TimeInputDemoExampleState extends State<TimeInputDemoExample> {\n'
      '  AstryxTime? _at = const AstryxTime(hour: 9, minute: 30);\n'
      '\n'
      '  @override\n'
      '  Widget build(BuildContext context) {\n'
      '    // `0930`, `9:30`, `9.30` and `9:30 am` all commit half past nine. The arrow\n'
      '    // keys move the value; both clocks are accepted whichever one is shown.\n'
      '    return SizedBox(\n'
      '      width: 220,\n'
      '      child: AstryxTimeInput(\n'
      '        label: \'Starts at\',\n'
      '        description: \'Arrow keys step by 15 minutes.\',\n'
      '        value: _at,\n'
      '        stepMinutes: 15,\n'
      '        onChanged: (time) => setState(() => _at = time),\n'
      '      ),\n'
      '    );\n'
      '  }\n'
      '}\n',
  // examples/time_input_examples.dart
  'time_input_bounds':
      'class TimeInputBoundsExample extends StatefulWidget {\n'
      '  const TimeInputBoundsExample({super.key});\n'
      '\n'
      '  @override\n'
      '  State<TimeInputBoundsExample> createState() => _TimeInputBoundsExampleState();\n'
      '}\n'
      '\n'
      'class _TimeInputBoundsExampleState extends State<TimeInputBoundsExample> {\n'
      '  AstryxTime? _open = const AstryxTime(hour: 9, minute: 0);\n'
      '  AstryxTime? _close = const AstryxTime(hour: 17, minute: 30);\n'
      '\n'
      '  @override\n'
      '  Widget build(BuildContext context) {\n'
      '    // On a twelve-hour clock, and bounded: a step that would leave the window\n'
      '    // is refused rather than wrapped round midnight.\n'
      '    return AstryxHStack(\n'
      '      gap: AstryxSpacingToken.spacing3,\n'
      '      align: AstryxStackAlign.start,\n'
      '      children: <Widget>[\n'
      '        SizedBox(\n'
      '          width: 180,\n'
      '          child: AstryxTimeInput(\n'
      '            label: \'Opens\',\n'
      '            value: _open,\n'
      '            format: AstryxTimeFormat.h12,\n'
      '            earliest: const AstryxTime(hour: 6, minute: 0),\n'
      '            latest: AstryxTime.noon,\n'
      '            stepMinutes: 30,\n'
      '            onChanged: (time) => setState(() => _open = time),\n'
      '          ),\n'
      '        ),\n'
      '        SizedBox(\n'
      '          width: 180,\n'
      '          child: AstryxTimeInput(\n'
      '            label: \'Closes\',\n'
      '            value: _close,\n'
      '            format: AstryxTimeFormat.h12,\n'
      '            earliest: AstryxTime.noon,\n'
      '            latest: const AstryxTime(hour: 23, minute: 30),\n'
      '            stepMinutes: 30,\n'
      '            onChanged: (time) => setState(() => _close = time),\n'
      '          ),\n'
      '        ),\n'
      '      ],\n'
      '    );\n'
      '  }\n'
      '}\n',
  // examples/timestamp_examples.dart
  'timestamp_demo':
      'class TimestampDemoExample extends StatelessWidget {\n'
      '  const TimestampDemoExample({super.key});\n'
      '\n'
      '  @override\n'
      '  Widget build(BuildContext context) {\n'
      '    final now = DateTime.now();\n'
      '\n'
      '    // Relative, and re-rendered as it ages: "just now" becomes "5 minutes ago"\n'
      '    // without the caller rebuilding anything. Past a week it writes the date\n'
      '    // instead, because "43 days ago" is arithmetic nobody asked for.\n'
      '    return AstryxMetadataList(\n'
      '      items: <AstryxMetadataItem>[\n'
      '        AstryxMetadataItem(\n'
      '          label: \'Deployed\',\n'
      '          value: AstryxTimestamp(now.subtract(const Duration(seconds: 20))),\n'
      '        ),\n'
      '        AstryxMetadataItem(\n'
      '          label: \'Last error\',\n'
      '          value: AstryxTimestamp(now.subtract(const Duration(minutes: 42))),\n'
      '        ),\n'
      '        AstryxMetadataItem(\n'
      '          label: \'Created\',\n'
      '          value: AstryxTimestamp(now.subtract(const Duration(days: 3))),\n'
      '        ),\n'
      '        AstryxMetadataItem(\n'
      '          label: \'Certificate issued\',\n'
      '          value: AstryxTimestamp(now.subtract(const Duration(days: 40))),\n'
      '        ),\n'
      '        AstryxMetadataItem(\n'
      '          label: \'Next run\',\n'
      '          value: AstryxTimestamp(now.add(const Duration(hours: 6))),\n'
      '        ),\n'
      '      ],\n'
      '    );\n'
      '  }\n'
      '}\n',
  // examples/timestamp_examples.dart
  'timestamp_formats':
      'class TimestampFormatsExample extends StatelessWidget {\n'
      '  const TimestampFormatsExample({super.key});\n'
      '\n'
      '  @override\n'
      '  Widget build(BuildContext context) {\n'
      '    final at = DateTime.now().subtract(const Duration(hours: 5));\n'
      '\n'
      '    // The absolute formats are for a column that has to line up, or a record\n'
      '    // where the exact instant is the point rather than its age.\n'
      '    return AstryxVStack(\n'
      '      gap: AstryxSpacingToken.spacing2,\n'
      '      children: <Widget>[\n'
      '        AstryxTimestamp(at),\n'
      '        AstryxTimestamp(at, format: AstryxTimestampFormat.time),\n'
      '        AstryxTimestamp(at, format: AstryxTimestampFormat.date),\n'
      '        AstryxTimestamp(\n'
      '          at,\n'
      '          format: AstryxTimestampFormat.dateTime,\n'
      '          timeFormat: AstryxTimeFormat.h12,\n'
      '          type: AstryxTextType.supporting,\n'
      '          color: AstryxTextColor.secondary,\n'
      '        ),\n'
      '      ],\n'
      '    );\n'
      '  }\n'
      '}\n',
